            'allOf item' => [['type' => 'array', 'items' => ['allOf' => [$ref]]], $strings, '{"f":[["a"]]}', '{"f":[[1]]}'],
            'sibling maxItems' => [[...$ref, 'maxItems' => 1], $strings, '{"f":["a"]}', '{"f":["a","b"]}'],
