    /**
     * A REQUIRED property that is nullable through a `$ref` — `oneOf: [$ref, {type: null}]`, the only way
     * a document can say "this nested object may be null".
     *
     * The keyword matrix cannot host it: its probes are scalars, and the nullability of a `$ref` is not
     * visible in the property's constraint map at all — there is no `type` there to carry a `null` member.
     * Reading it instead off `$property['nullable']` is wrong for the opposite reason: the walker sets that
     * flag for every OPTIONAL property, so it cannot be trusted unless the property is required.
     *
     * Which is exactly the case this pins, and it is not hypothetical: laravel-data mode needs the answer
     * for its property TYPE (`Child|null` versus `Child`, where a wrong answer is a TypeError on a payload
     * the schema allows), and the fix moved laravel mode's emitted rules too — `['present']` became
     * `['present', 'nullable']`.
     */
    public function testARequiredPropertyNullableThroughARefIsAcceptedAsNullInEveryMode(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['child'],
                        'properties' => [
                            'child' => [
                                'oneOf' => [
                                    ['$ref' => '#/components/schemas/Child'],
                                    ['type' => 'null'],
                                ],
                            ],
                        ],
                    ],
                    'Child' => [
                        'type' => 'object',
                        'required' => ['id'],
                        'properties' => ['id' => ['type' => 'integer', 'minimum' => 5]],
                    ],
                ],
            ],
        ];

        // `null` is what the schema allows; an object missing the child's own required key is not.
        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, 'nullable ref', '{"child":null}', '{"child":{}}'),
            context: 'required property nullable through a $ref',
        );
    }

    /**
     * A schema that refers to itself, enforced at EVERY depth in every mode.
     *
     * The other two get this for free: Symfony cascades through `#[Assert\Valid]` into each nested DTO's
     * own constraints, and the runtime validator walks the schema it holds in memory. Laravel mode has one
     * flat rule map and one emitted schema literal, and a recursive schema has no finite inline form — so
     * the walk used to stop at the first turn of the cycle. Measured then: a CHILD violating `minimum: 1`
     * was accepted while the identical violation at the root was reported, and `laravelNestedRules()`
     * emitted no `children.*.id` path to cover it either. Nothing reported it at all.
     *
     * Now the fold is emitted once and re-entered through a marker, so this walks as deep as the payload.
     */
    #[DataProvider('recursiveDepthProvider')]
    public function testARecursiveSchemaIsEnforcedAtEveryDepthInEveryMode(string $key, string $invalidJson): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['f'],
                        'properties' => ['f' => ['$ref' => '#/components/schemas/TreeNode']],
                    ],
                    'TreeNode' => [
                        'type' => 'object',
                        'required' => ['id'],
                        'properties' => [
                            'id' => ['type' => 'integer', 'minimum' => 1],
                            'label' => ['type' => 'string', 'not' => ['const' => 'forbidden']],
                            'parent' => ['$ref' => '#/components/schemas/TreeNode'],
                            'children' => [
                                'type' => 'array',
                                'items' => ['$ref' => '#/components/schemas/TreeNode'],
                            ],
                        ],
                    ],
                ],
            ],
        ];

        $valid = '{"f":{"id":1,"label":"ok","children":[{"id":2}]}}';

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, 'rec ' . $key, $valid, $invalidJson),
            context: 'recursive ' . $key,
        );
    }

    /**
     * @return array<string, array{0: string, 1: string}>
     */
    public static function recursiveDepthProvider(): array
    {
        $cases = [
            // A keyword the rules DO express, at each depth — this is the half that went missing.
            'root minimum' => '{"f":{"id":0}}',
            'child minimum' => '{"f":{"id":1,"children":[{"id":0}]}}',
            'grandchild minimum' => '{"f":{"id":1,"children":[{"id":2,"children":[{"id":0}]}]}}',
            'parent minimum' => '{"f":{"id":1,"parent":{"id":0}}}',
            'grandparent minimum' => '{"f":{"id":1,"parent":{"id":2,"parent":{"id":0}}}}',
            // A keyword no rule can express, which was already right and must stay right.
            'root not' => '{"f":{"id":1,"label":"forbidden"}}',
            'child not' => '{"f":{"id":1,"children":[{"id":2,"label":"forbidden"}]}}',
            'grandchild not' => '{"f":{"id":1,"children":[{"id":2,"children":[{"id":3,"label":"forbidden"}]}]}}',
            'child required' => '{"f":{"id":1,"children":[{"label":"x"}]}}',
            'grandchild required' => '{"f":{"id":1,"children":[{"id":2,"children":[{"label":"x"}]}]}}',
        ];

        $provided = [];
        foreach ($cases as $key => $invalidJson) {
            $provided[$key] = [$key, $invalidJson];
        }

        return $provided;
    }

    /**
     * A union branch `{type: object, allOf: [{$ref: Teal}]}` is typed as `Teal` — no class of its own is
     * written for it — yet runtime and Symfony read the `type: object` beside the reference as a sibling
     * that the branch's own class checks, and kept that sibling alone: any object matched the branch, and
     * the `oneOf` refused every valid value of its other branch as matching twice. A bare `$ref` (`pear`)
     * always kept the class check; a reference beside keys of its own (`fig`) is a class of its own.
     */
    public function testARefBranchBesideANonNarrowingSiblingIsStillThatClass(): void
    {
        $ref = ['$ref' => '#/components/schemas/Teal'];
        $stoat = ['type' => 'object', 'properties' => ['stoat' => ['type' => 'integer']]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Teal' => ['type' => 'object', 'properties' => ['marten' => ['type' => 'integer']], 'required' => ['marten']],
                'Probe' => ['type' => 'object', 'properties' => [
                    'kiwi' => ['oneOf' => [$stoat, ['type' => 'object', 'allOf' => [$ref]]]],
                    'pear' => ['oneOf' => [$stoat, $ref]],
                    'fig' => ['oneOf' => [
                        ['type' => 'object', 'properties' => ['stoat' => ['type' => 'integer']], 'required' => ['stoat']],
                        ['allOf' => [$ref, ['properties' => ['lynx' => ['type' => 'string']], 'required' => ['lynx']]]],
                    ]],
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'ref branch beside a non-narrowing sibling',
                payloads: [
                    '{"kiwi":{"stoat":9}}' => true,
                    '{"kiwi":{"marten":1}}' => false,
                    '{"kiwi":{"marten":1,"stoat":9}}' => false,
                    '{"kiwi":{"stoat":"x"}}' => false,
                    '{"pear":{"stoat":9}}' => true,
                    '{"pear":{"marten":1,"stoat":9}}' => false,
                    '{"fig":{"stoat":9}}' => true,
                    '{"fig":{"marten":1,"lynx":"a"}}' => true,
                    '{"fig":{"marten":1,"lynx":"a","stoat":9}}' => false,
                    '{"fig":{"lynx":"a"}}' => false,
                ],
                // Symfony's serializer builds ONE member of the class union, and the validator judges
                // the object it was handed: a second match is not seen, and a payload only a later
                // member accepts depends on the serializer release (README.support-matrix.md).
                diverging: ['symfony' => [
                    '{"kiwi":{"marten":1}}' => null,
                    '{"kiwi":{"marten":1,"stoat":9}}' => null,
                    '{"pear":{"marten":1,"stoat":9}}' => null,
                    '{"fig":{"marten":1,"lynx":"a"}}' => null,
                    '{"fig":{"marten":1,"lynx":"a","stoat":9}}' => null,
                ]],
            ),
        );
    }

    /**
     * A `$ref` to a union COMPONENT (`Shape: {anyOf: [$ref Circle, $ref Square]}`) as one branch of a
     * wider union. Laravel and laravel-data spelled such a branch as nothing, so the whole union was
     * pruned and the rules said only `sometimes`: `{"newt": 5}` reached the constructor (a TypeError,
     * laravel) or was written back as `"5"` (laravel-data), and a value two `oneOf` members match
     * (`toad`, `pair`) went through. laravel-data also never built such a member — the array reached the
     * constructor, or `Shape::from()` was called on the interface — and beside a scalar a discriminated
     * morph base (`Pet|string`) died in laravel-data's own `DataMorphClassResolver` on the string.
     * The bare `$ref` (`fern`), a list of the same union (`list`), the union written inline (`inl`) and
     * the component beside null (`nul`) are the neighbours that already worked. `{"pair": {"radius":
     * "x"}}` is valid: Square has no required key and allows the extra one.
     */
    public function testARefToAUnionComponentAsOneBranchOfAWiderUnionIsChecked(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $integerField = static fn(string $name, bool $required): array => [
            'type' => 'object',
            'properties' => [$name => ['type' => 'integer']],
        ] + ($required ? ['required' => [$name]] : []);
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Circle' => $integerField('radius', false),
                'Square' => $integerField('side', false),
                'Shape' => ['anyOf' => [$ref('Circle'), $ref('Square')]],
                'Disc' => $integerField('radius', true),
                'Tile' => $integerField('side', true),
                'Form' => ['oneOf' => [$ref('Disc'), $ref('Tile')]],
                'Cat' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'lives' => ['type' => 'integer']], 'required' => ['kind']],
                'Dog' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'bark' => ['type' => 'string']], 'required' => ['kind']],
                'Pet' => [
                    'oneOf' => [$ref('Cat'), $ref('Dog')],
                    'discriminator' => [
                        'propertyName' => 'kind',
                        'mapping' => ['cat' => '#/components/schemas/Cat', 'dog' => '#/components/schemas/Dog'],
                    ],
                ],
                'Hue' => ['type' => 'string', 'enum' => ['red', 'teal']],
                'Probe' => ['type' => 'object', 'properties' => [
                    'newt' => ['oneOf' => [$ref('Shape'), ['type' => 'string']]],
                    'moth' => ['anyOf' => [$ref('Shape'), ['type' => 'string']]],
                    'toad' => ['oneOf' => [$ref('Form'), ['type' => 'integer']]],
                    'pair' => ['oneOf' => [$ref('Shape'), $ref('Disc')]],
                    'pet' => ['oneOf' => [$ref('Pet'), ['type' => 'string']]],
                    'tint' => ['oneOf' => [$ref('Pet'), $ref('Hue')]],
                    'fern' => $ref('Shape'),
                    'list' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Shape'), ['type' => 'string']]]],
                    'inl' => ['oneOf' => [['anyOf' => [$ref('Circle'), $ref('Square')]], ['type' => 'string']]],
                    'nul' => ['oneOf' => [$ref('Shape'), ['type' => 'null']]],
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'ref to a union component as a union branch',
                payloads: [
                    '{"newt":{"radius":1}}' => true,
                    '{"newt":{"side":2}}' => true,
                    '{"newt":"x"}' => true,
                    '{"newt":5}' => false,
                    '{"newt":{"radius":"x","side":"y"}}' => false,
                    '{"moth":{"radius":1}}' => true,
                    '{"moth":"x"}' => true,
                    '{"moth":5}' => false,
                    '{"toad":{"radius":1}}' => true,
                    '{"toad":3}' => true,
                    '{"toad":{"radius":1,"side":2}}' => false,
                    '{"toad":{}}' => false,
                    '{"toad":{"radius":"x"}}' => false,
                    '{"pair":{"side":2}}' => true,
                    '{"pair":{"radius":"x"}}' => true,
                    '{"pair":{"radius":1}}' => false,
                    '{"pair":5}' => false,
                    '{"pair":{"radius":"x","side":"y"}}' => false,
                    '{"pet":"s"}' => true,
                    '{"pet":{"kind":"cat","lives":9}}' => true,
                    '{"pet":{"kind":"dog","bark":"w"}}' => true,
                    '{"pet":5}' => false,
                    '{"pet":{"kind":"cat","lives":"x"}}' => false,
                    '{"pet":{"kind":"dog","bark":5}}' => false,
                    '{"pet":{"kind":"zzz"}}' => false,
                    '{"tint":"red"}' => true,
                    '{"tint":{"kind":"cat","lives":9}}' => true,
                    '{"tint":"x"}' => false,
                    '{"tint":{"kind":"zzz"}}' => false,
                    '{"fern":{"radius":1}}' => true,
                    '{"fern":5}' => false,
                    '{"list":[{"radius":1},"s"]}' => true,
                    '{"list":[5]}' => false,
                    '{"list":[{"radius":"x","side":"y"}]}' => false,
                    '{"inl":{"side":2}}' => true,
                    '{"inl":"s"}' => true,
                    '{"inl":5}' => false,
                    '{"nul":null}' => true,
                    '{"nul":{"radius":1}}' => true,
                    '{"nul":5}' => false,
                ],
                diverging: [
                    // Outside the Laravel modes this test is about, and unasserted here: Symfony's
                    // serializer builds ONE member of the class union, which depends on the serializer
                    // release (README.support-matrix.md).
                    'symfony' => [
                        '{"pair":{"side":2}}' => null,
                        '{"pair":{"radius":"x"}}' => null,
                    ],
                ],
            ),
        );
    }

    /**
     * A discriminated `oneOf` nested as one member of a wider union beside a scalar, reached through
     * `allOf` with one `$ref`, whose member requires nothing and declares the discriminator as an EMPTY
     * schema (`kind: {}`). An object without `kind` matches that member alone, and the emitted
     * interpreter then looked for the tag: `property_exists()` answered for the member's PRIVATE
     * `$kind`, and Symfony died reading it ("Cannot access private property"). The tag is looked up
     * among the properties the interpreter may read now. Whether an object the untyped member accepts
     * but its tag does not route there is valid differs by reading (JSON Schema `oneOf` or the OpenAPI
     * discriminator), so those payloads are unasserted — but none may crash. The same union by a bare
     * `$ref` (`bare`) is the neighbour.
     */
    public function testANestedDiscriminatedUnionWithAnUntypedTagIsCheckedInEveryMode(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Hexa' => ['type' => 'object', 'properties' => [
                    'kind' => [],
                    'size' => ['type' => 'integer', 'minimum' => 5, 'exclusiveMinimum' => true],
                    'solid' => ['type' => 'boolean'],
                ]],
                'Disc' => ['type' => 'object', 'required' => ['kind', 'radius', 'depth']],
                'Figure' => ['oneOf' => [
                    ['type' => 'string', 'maxLength' => 0],
                    [
                        'oneOf' => [$ref('Hexa'), $ref('Disc')],
                        'discriminator' => [
                            'propertyName' => 'kind',
                            'mapping' => ['hexagon' => '#/components/schemas/Hexa', 'circle' => '#/components/schemas/Disc'],
                        ],
                    ],
                ]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'plover' => ['allOf' => [$ref('Figure')]],
                    'bare' => $ref('Figure'),
                ]],
            ]],
        ];

        $payloads = [];
        $unasserted = [];
        foreach (['plover', 'bare'] as $property) {
            $payloads += [
                sprintf('{"%s":{"kind":"hexagon","size":6,"solid":true}}', $property) => true,
                sprintf('{"%s":{"kind":"hexagon","size":5}}', $property) => false,
                sprintf('{"%s":""}', $property) => true,
                sprintf('{"%s":"x"}', $property) => false,
                sprintf('{"%s":5}', $property) => false,
            ];
            foreach (['{"solid":true}', '{"size":7,"solid":true}', '{"kind":"circle","radius":1}', '{"kind":"zzz"}'] as $object) {
                $json = sprintf('{"%s":%s}', $property, $object);
                $payloads[$json] = false;
                $unasserted[$json] = null;
            }
        }
        $diverging = [];
        foreach (GenerationMode::cases() as $mode) {
            $diverging[$mode->value] = $unasserted;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'nested discriminated union untyped tag', payloads: $payloads, diverging: $diverging),
        );
    }

    /**
     * A union COMPONENT whose first member is itself a `oneOf` of scalars — one of them a 3.1 `$ref`
     * with an `enum` and a bound beside it — and whose other members are classes. The `$ref` with
     * siblings was not read as a scalar, so the component became a union interface of its classes
     * alone: runtime tried to build every class from `-3.5`, yii3 refused it as "must be an object",
     * the Laravel modes as "must be an array". Its scalar members make it a value union now, inlined
     * where it is used. The annotated `$ref` (`kiwi`), the bare one (`bare`) and the same union written
     * flat on the property (`flat`) answer alike.
     */
    public function testScalarMembersOfANestedOneOfBesideClassesAreAccepted(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Amount' => ['type' => 'number'],
                'Flag' => ['type' => 'boolean'],
                'Badge' => [
                    'type' => 'object',
                    'properties' => [
                        'label' => ['type' => 'string', 'maxLength' => 4],
                        'shiny' => ['type' => 'boolean'],
                        'weight' => ['type' => 'number', 'maximum' => 5.5],
                    ],
                    'required' => ['label', 'shiny', 'weight'],
                ],
                'Token' => ['oneOf' => [
                    ['oneOf' => [
                        $ref('Amount') + ['enum' => [-5, -3.5], 'exclusiveMinimum' => -5.5],
                        ['type' => 'boolean'],
                        ['type' => 'string', 'format' => 'uuid'],
                    ]],
                    [
                        'type' => 'object',
                        'properties' => [
                            'stamp' => ['type' => 'string', 'format' => 'date-time'],
                            'flag' => ['allOf' => [$ref('Flag')]],
                        ],
                        'required' => ['stamp', 'flag'],
                        'additionalProperties' => false,
                    ],
                    $ref('Badge'),
                ]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'kiwi' => $ref('Token') + ['title' => 'Union', 'deprecated' => false],
                    'bare' => $ref('Token'),
                    'flat' => ['oneOf' => [
                        $ref('Amount') + ['enum' => [-5, -3.5], 'exclusiveMinimum' => -5.5],
                        ['type' => 'boolean'],
                        ['type' => 'string', 'format' => 'uuid'],
                        $ref('Badge'),
                    ]],
                ]],
            ]],
        ];

        $payloads = [];
        foreach (['kiwi', 'bare'] as $property) {
            $payloads += [
                sprintf('{"%s":-3.5}', $property) => true,
                sprintf('{"%s":-5}', $property) => true,
                sprintf('{"%s":true}', $property) => true,
                sprintf('{"%s":"6f1c1b3e-6a7e-4b8e-9c3e-2f4f5a6b7c8d"}', $property) => true,
                sprintf('{"%s":{"stamp":"2024-01-02T03:04:05Z","flag":true}}', $property) => true,
                sprintf('{"%s":{"label":"ab","shiny":true,"weight":1}}', $property) => true,
                sprintf('{"%s":-4}', $property) => false,
                sprintf('{"%s":"x"}', $property) => false,
                sprintf('{"%s":{"label":"abcdef","shiny":true,"weight":1}}', $property) => false,
                sprintf('{"%s":{"stamp":"2024-01-02T03:04:05Z"}}', $property) => false,
            ];
        }
        $payloads += [
            '{"flat":-3.5}' => true,
            '{"flat":true}' => true,
            '{"flat":{"label":"ab","shiny":true,"weight":1}}' => true,
            '{"flat":-4}' => false,
            '{"flat":"x"}' => false,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'scalar members of a nested oneOf beside classes',
                payloads: $payloads,
                diverging: [
                    // Inlined where it is used, the union is a union of classes written on the property:
                    // Symfony's serializer builds the member whose class name sorts first
                    // (README.support-matrix.md), and that is `Badge`, not the inline object.
                    'symfony' => [
                        '{"kiwi":{"stamp":"2024-01-02T03:04:05Z","flag":true}}' => null,
                        '{"bare":{"stamp":"2024-01-02T03:04:05Z","flag":true}}' => null,
                    ],
                ],
            ),
        );
    }

    /**
     * A `$ref` to a union COMPONENT beside a scalar, inside `items` or `additionalProperties`. Symfony
     * spelled that branch as "is a Shape", but the container stays an untyped `array`: the serializer
     * never builds the item, so every object item was refused under `oneOf` and waved through under
     * `anyOf`, a wrong member body of a discriminated union (`tagged`) included. The neighbours are
     * pinned by `testUnionComponentNeighboursInsideAContainerAreChecked()`.
     */
    public function testAUnionComponentBesideAScalarInsideAContainerIsChecked(): void
    {
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: self::containedUnionComponentSpec(),
                key: 'union component beside a scalar in a container',
                payloads: [
                    '{"list":[{"radius":1},"s"]}' => true,
                    '{"list":[{"radius":1}]}' => true,
                    '{"list":[{"side":2}]}' => true,
                    '{"list":[5]}' => false,
                    '{"list":[{"radius":"x"}]}' => false,
                    '{"list":[{}]}' => false,
                    '{"tagged":[{"kind":"c","radius":1},"s"]}' => true,
                    '{"tagged":[{"kind":"s","side":2}]}' => true,
                    '{"tagged":[{"kind":"c","radius":"a"}]}' => false,
                    '{"tagged":[{"kind":"zzz"}]}' => false,
                    '{"tagged":[5]}' => false,
                    '{"bag":{"a":{"radius":1},"b":3}}' => true,
                    '{"bag":{"a":{"kind":"x"}}}' => false,
                    '{"bag":{"a":"s"}}' => false,
                    '{"mix":[{"kind":"s","side":2}]}' => true,
                    '{"mix":[{"kind":"s","side":"x"}]}' => false,
                    '{"mix":["s"]}' => false,
                    '{"deep":[[{"kind":"c","radius":1},"s"]]}' => true,
                    '{"deep":[[{"kind":"c","radius":"a"}]]}' => false,
                    '{"either":[{"kind":"s","side":2},"s"]}' => true,
                    '{"either":7}' => true,
                    '{"either":[{"kind":"s","side":"x"}]}' => false,
                ],
            ),
        );
    }

    /**
     * The neighbours of `testAUnionComponentBesideAScalarInsideAContainerIsChecked()` that already
     * worked: the union component beside only null in `items`, a plain class beside a string in `items`,
     * and a typed list of the union.
     */
    public function testUnionComponentNeighboursInsideAContainerAreChecked(): void
    {
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: self::containedUnionComponentSpec(),
                key: 'union component neighbours in a container',
                payloads: [
                    '{"plain":[{"radius":1},null]}' => true,
                    '{"plain":[{"radius":"x"}]}' => false,
                    '{"plain":["s"]}' => false,
                    '{"roster":[{"radius":1},"s"]}' => true,
                    '{"roster":[{"radius":"x"}]}' => false,
                    '{"roster":[5]}' => false,
                    '{"shapes":[{"side":2}]}' => true,
                    '{"shapes":[{"side":"x"}]}' => false,
                    '{"shapes":["s"]}' => false,
                ],
            ),
        );
    }

    /**
     * @return array<string, mixed>
     */
    private static function containedUnionComponentSpec(): array
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $integerField = static fn(string $name): array => [
            'type' => 'object',
            'required' => [$name],
            'properties' => [$name => ['type' => 'integer']],
        ];
        $tagged = static fn(string $name): array => [
            'type' => 'object',
            'required' => ['kind', $name],
            'properties' => ['kind' => ['type' => 'string'], $name => ['type' => 'integer']],
        ];

        return [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Circle' => $integerField('radius'),
                'Square' => $integerField('side'),
                'Shape' => ['oneOf' => [$ref('Circle'), $ref('Square')]],
                'Disc' => $tagged('radius'),
                'Tile' => $tagged('side'),
                'Tagged' => [
                    'oneOf' => [$ref('Disc'), $ref('Tile')],
                    'discriminator' => [
                        'propertyName' => 'kind',
                        'mapping' => ['c' => '#/components/schemas/Disc', 's' => '#/components/schemas/Tile'],
                    ],
                ],
                'Probe' => ['type' => 'object', 'properties' => [
                    'list' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Shape'), ['type' => 'string']]]],
                    'tagged' => ['type' => 'array', 'items' => ['anyOf' => [$ref('Tagged'), ['type' => 'string']]]],
                    'bag' => ['type' => 'object', 'additionalProperties' => ['anyOf' => [$ref('Shape'), ['type' => 'integer']]]],
                    'plain' => ['type' => 'array', 'items' => ['anyOf' => [$ref('Shape'), ['type' => 'null']]]],
                    'roster' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Circle'), ['type' => 'string']]]],
                    'shapes' => ['type' => 'array', 'items' => $ref('Shape')],
                    'mix' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Tagged'), $ref('Circle')]]],
                    'deep' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => ['anyOf' => [$ref('Tagged'), ['type' => 'string']]]]],
                    'either' => ['oneOf' => [
                        ['type' => 'array', 'items' => ['anyOf' => [$ref('Tagged'), ['type' => 'string']]]],
                        ['type' => 'integer'],
                    ]],
                ]],
            ]],
        ];
    }

    /**
     * A tuple whose `items` is a `$ref` to a union COMPONENT, under `anyOf` beside null. Symfony typed
     * the property `?array<Coral>` off `items` alone, so the serializer built the tuple's leading
     * integer as a Coral too and refused `[5]` as "Type property kind not found". The neighbours (the
     * same tuple as a plain `type: array` or `type: [array, null]`, and items of a union without a
     * discriminator) are pinned in the same table.
     */
    public function testATupleOfAUnionComponentBesideNullKeepsItsLeadingPositions(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $tuple = static fn(string $item): array => [
            'type' => 'array',
            'prefixItems' => [['type' => 'integer']],
            'items' => $ref($item),
        ];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'tuple of a union', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => [
                'Probe' => [
                    'type' => 'object',
                    'properties' => [
                        'lemur' => ['anyOf' => [$tuple('Coral'), ['type' => 'null']]],
                        'otter' => ['type' => ['array', 'null']] + $tuple('Coral'),
                        'heron' => $tuple('Coral'),
                        'swan' => ['anyOf' => [$tuple('Mauve'), ['type' => 'null']]],
                    ],
                ],
                'Ochre' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']]],
                'Teal' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'gecko' => ['type' => 'string']]],
                'Coral' => ['anyOf' => [$ref('Ochre'), $ref('Teal')], 'discriminator' => ['propertyName' => 'kind']],
                'Mauve' => ['anyOf' => [$ref('Ochre'), $ref('Teal')]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'tuple of a union component beside null',
                payloads: [
                    '{"lemur":[5]}' => true,
                    '{"lemur":[-28]}' => true,
                    '{"lemur":[1,{"kind":"Teal"}]}' => true,
                    '{"lemur":null}' => true,
                    '{"lemur":["x"]}' => false,
                    '{"otter":[5]}' => true,
                    '{"otter":[1,{"kind":"Teal"}]}' => true,
                    '{"otter":["x"]}' => false,
                    '{"heron":[5]}' => true,
                    '{"heron":[1,{"kind":"Teal"}]}' => true,
                    '{"heron":["x"]}' => false,
                    '{"swan":[5]}' => true,
                    '{"swan":null}' => true,
                    '{"swan":["x"]}' => false,
                ],
            ),
        );
    }

    /**
     * `format: date` on a property, a list item, a map value, a nested object, a nullable property and
     * a union member. Symfony typed it `DateTimeImmutable` and let the serializer parse it with
     * `new DateTimeImmutable($data)`, which takes any phrase PHP understands: `"x"` became today,
     * `"tomorrow"` and a full date-time passed. The neighbours (a valid date written back unchanged,
     * `format: time`) are pinned beside them.
     */
    public function testAFormatDateIsParsedStrictly(): void
    {
        $date = ['type' => 'string', 'format' => 'date'];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'strict date', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => [
                'Probe' => [
                    'type' => 'object',
                    'properties' => [
                        'day' => $date,
                        'maybe' => ['type' => ['string', 'null'], 'format' => 'date'],
                        'days' => ['type' => 'array', 'items' => $date],
                        'dayMap' => ['type' => 'object', 'additionalProperties' => $date],
                        'nested' => ['type' => 'object', 'properties' => ['day' => $date]],
                        'either' => ['oneOf' => [$date, ['type' => 'integer']]],
                        'hour' => ['type' => 'string', 'format' => 'time'],
                    ],
                ],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'strict format date',
                payloads: [
                    '{"day":"2020-01-02"}' => true,
                    '{"day":"x"}' => false,
                    '{"day":"tomorrow"}' => false,
                    '{"day":"2020-01-02T10:00:00Z"}' => false,
                    '{"maybe":"2020-01-02"}' => true,
                    '{"maybe":null}' => true,
                    '{"maybe":"x"}' => false,
                    '{"days":["2020-01-02"]}' => true,
                    '{"days":["x"]}' => false,
                    '{"dayMap":{"a":"2020-01-02"}}' => true,
                    '{"dayMap":{"a":"x"}}' => false,
                    '{"nested":{"day":"2020-01-02"}}' => true,
                    '{"nested":{"day":"x"}}' => false,
                    '{"either":"2020-01-02"}' => true,
                    '{"either":5}' => true,
                    '{"either":"x"}' => false,
                    '{"hour":"10:00:00Z"}' => true,
                    '{"hour":"x"}' => false,
                ],
            ),
        );
    }

    /**
     * Shapes the Symfony and yii3 renderers each got wrong in one spelling while the plain one worked: a
     * date a lenient reader took, a union member the strict date reading or a list never reached, a
     * number list refusing an integer, an email checked more loosely in a union branch, a class the PHP
     * type folded into `array`, a discriminated union nested in a union, and a `$ref` with a sibling
     * keyword dropping its member's `allOf`.
     *
     * @param array<string, mixed> $properties the Probe component's properties
     * @param array<string, array<string, mixed>> $components
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging
     */
    #[DataProvider('rendererSpellingProvider')]
    public function testEachSpellingOfAShapeIsJudgedAsThePlainOne(
        array $properties,
        array $components,
        array $payloads,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => ['Probe' => ['type' => 'object', 'properties' => $properties]] + $components],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'renderer spelling ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return array<string, array{0: array<string, mixed>, 1: array<string, array<string, mixed>>, 2: array<string, bool>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function rendererSpellingProvider(): array
    {
        $date = ['type' => 'string', 'format' => 'date'];
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $kindObject = ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']], 'required' => ['kind']];
        $shape = static fn(string $kind): array => [
            'type' => 'object',
            'properties' => ['kind' => ['type' => 'string', 'enum' => [$kind]]],
            'required' => ['kind'],
        ];
        // Symfony reads the date with `!Y-m-d`, and PHP takes a one-digit month or day there before any
        // generated constraint sees the string (README.support-matrix, the impossible calendar date row).
        $oneDigitInSymfony = static fn(array $payloads): array => ['symfony' => array_fill_keys($payloads, true)];

        return [
            'a one-digit month or day for format: date however spelled' => [
                [
                    'plover' => $date,
                    'heron' => ['type' => 'array', 'items' => $date],
                    'llama' => ['allOf' => [['format' => 'date'], ['type' => 'string']]],
                ],
                [],
                [
                    '{"plover":"2020-01-02"}' => true,
                    '{"plover":"2020-1-2"}' => false,
                    '{"plover":"2020-01-2"}' => false,
                    '{"heron":["2020-01-02"]}' => true,
                    '{"heron":["2020-1-2"]}' => false,
                    '{"llama":"2020-01-02"}' => true,
                    '{"llama":"2020-1-2"}' => false,
                ],
                $oneDigitInSymfony(['{"plover":"2020-1-2"}', '{"plover":"2020-01-2"}', '{"heron":["2020-1-2"]}', '{"llama":"2020-1-2"}']),
            ],
            'format: date as a union member beside a list or an integer enum' => [
                [
                    'badger' => ['anyOf' => [$date, ['type' => 'array']]],
                    'newt' => ['oneOf' => [['type' => 'integer', 'enum' => [2]], $date]],
                ],
                [],
                [
                    '{"badger":"2020-01-02"}' => true,
                    '{"badger":[1]}' => true,
                    '{"badger":"2020-1-2"}' => false,
                    '{"badger":"+1 day"}' => false,
                    '{"badger":"x"}' => false,
                    '{"newt":2}' => true,
                    '{"newt":"2020-01-02"}' => true,
                    '{"newt":"2020-1-2"}' => false,
                    '{"newt":"@0"}' => false,
                    '{"newt":"x"}' => false,
                ],
                $oneDigitInSymfony(['{"badger":"2020-1-2"}', '{"newt":"2020-1-2"}']),
            ],
            'a $ref to a list component of format: date' => [
                ['robin' => $ref('Saffron')],
                ['Saffron' => ['type' => 'array', 'items' => $date]],
                ['{"robin":["2020-01-02"]}' => true, '{"robin":["@0"]}' => false, '{"robin":["x"]}' => false],
            ],
            'a list beside one class that requires a key' => [
                [
                    'wren' => ['oneOf' => [$kindObject, ['type' => 'array']]],
                    'robin' => ['oneOf' => [$kindObject, ['type' => 'string'], ['type' => 'array']]],
                ],
                [],
                [
                    '{"wren":[1]}' => true,
                    '{"wren":[]}' => true,
                    '{"wren":{"kind":"a"}}' => true,
                    '{"wren":{"kind":5}}' => false,
                    '{"wren":5}' => false,
                    '{"robin":[false]}' => true,
                    '{"robin":"s"}' => true,
                    '{"robin":{"kind":"a"}}' => true,
                    '{"robin":{"kind":5}}' => false,
                ],
            ],
            'a list beside two classes' => [
                [
                    'vole' => ['anyOf' => [
                        ['type' => 'object', 'properties' => ['quokka' => ['type' => 'string']]],
                        ['type' => 'array', 'maxItems' => 1, 'items' => ['type' => 'integer']],
                        ['type' => 'object', 'properties' => ['plover' => ['type' => 'string']]],
                    ]],
                    // Pinned: one class beside the list was always right.
                    'wolf' => ['anyOf' => [
                        ['type' => 'object', 'properties' => ['quokka' => ['type' => 'string']]],
                        ['type' => 'array', 'maxItems' => 1, 'items' => ['type' => 'integer']],
                    ]],
                ],
                [],
                [
                    '{"vole":[1]}' => true,
                    '{"vole":{"quokka":"a"}}' => true,
                    '{"vole":{"plover":"b"}}' => true,
                    '{"vole":["g","g"]}' => false,
                    '{"vole":[null]}' => false,
                    '{"vole":[[2]]}' => false,
                    '{"vole":[{"quokka":5}]}' => false,
                    '{"vole":[1,2]}' => false,
                    '{"wolf":[1]}' => true,
                    '{"wolf":{"quokka":"a"}}' => true,
                    '{"wolf":["g"]}' => false,
                    '{"wolf":[1,2]}' => false,
                ],
            ],
            'a list of numbers as a union branch' => [
                [
                    'urchin' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'number']], ['type' => 'null']]],
                    'newt' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'number']], ['type' => 'boolean']]],
                    // Pinned: the plain list took an integer item.
                    'heron' => ['type' => 'array', 'items' => ['type' => 'number']],
                ],
                [],
                [
                    '{"urchin":[-34]}' => true,
                    '{"urchin":[1.5]}' => true,
                    '{"urchin":null}' => true,
                    '{"urchin":["1"]}' => false,
                    '{"urchin":[true]}' => false,
                    '{"newt":[5]}' => true,
                    '{"newt":true}' => true,
                    '{"newt":["x"]}' => false,
                    // An object is no list, whatever its values: `Type('array')` took both.
                    '{"urchin":{"zz":1}}' => false,
                    '{"newt":{"zz":1.5}}' => false,
                    '{"heron":[5]}' => true,
                    '{"heron":["5"]}' => false,
                ],
                // laravel-data casts a numeric string (README.support-matrix, the numeric string row).
                ['laravel-data' => ['{"heron":["5"]}' => null]],
            ],
            'format: email as a union branch' => [
                [
                    'urchin' => ['anyOf' => [['type' => 'boolean'], ['type' => 'string', 'format' => 'email']]],
                    'mail' => ['type' => 'string', 'format' => 'email'],
                ],
                [],
                [
                    '{"urchin":"a@example.com"}' => true,
                    '{"urchin":true}' => true,
                    '{"urchin":"a.@example.com"}' => false,
                    '{"urchin":"a..b@example.com"}' => false,
                    '{"mail":"a@example.com"}' => true,
                    '{"mail":"a.@example.com"}' => false,
                ],
            ],
            'a $ref class the PHP type folds into array' => [
                ['raven' => ['oneOf' => [['enum' => ['green']], $ref('Umber'), ['type' => 'object', 'required' => ['bison']]]]],
                ['Umber' => ['type' => 'object', 'properties' => ['plover' => ['type' => 'integer']]]],
                [
                    '{"raven":{"plover":65}}' => true,
                    '{"raven":"green"}' => true,
                    '{"raven":"blue"}' => false,
                    '{"raven":{"plover":"x"}}' => false,
                ],
            ],
            'a discriminated union nested in a union' => [
                ['koala' => ['oneOf' => [
                    [
                        'oneOf' => [$ref('Circle'), $ref('Square')],
                        'discriminator' => [
                            'propertyName' => 'kind',
                            'mapping' => ['circle' => '#/components/schemas/Circle', 'square' => '#/components/schemas/Square'],
                        ],
                    ],
                    ['type' => 'string'],
                ]]],
                ['Circle' => $shape('circle'), 'Square' => $shape('square')],
                [
                    '{"koala":{"kind":"square"}}' => true,
                    '{"koala":{"kind":"circle"}}' => true,
                    '{"koala":"x"}' => true,
                    '{"koala":{"kind":"oval"}}' => false,
                ],
            ],
            'a $ref with a sibling to a union whose object member is an allOf' => [
                ['quokka' => $ref('Teal') + ['description' => 'd']],
                ['Teal' => ['oneOf' => [
                    ['type' => 'object', 'allOf' => [['type' => 'object', 'properties' => ['crane' => ['type' => 'integer']]]]],
                    ['type' => 'array'],
                ]]],
                [
                    '{"quokka":{"crane":1}}' => true,
                    '{"quokka":[1]}' => true,
                    '{"quokka":{"crane":null}}' => false,
                    '{"quokka":{"crane":"x"}}' => false,
                ],
            ],
        ];
    }

    /**
     * A property, or a map value, typed with a union INTERFACE whose "is that class" branches the
     * generator writes one level down: under `allOf`, or as the inner `anyOf` of a `oneOf`/`anyOf`
     * branch beside null. Runtime read the members only off the direct branches of a top-level union,
     * found none, and refused every object as "Unsupported type" (a map value as "unknown type"). The
     * neighbours that already worked are pinned by `testUnionInterfaceNeighboursOfANestedSpellingAreBuilt()`.
     */
    public function testAUnionInterfaceSpelledOneLevelDownIsBuilt(): void
    {
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: self::nestedUnionInterfaceSpec(),
                key: 'union interface spelled one level down',
                payloads: [
                    '{"nul":{"radius":1}}' => true,
                    '{"nul":{"side":2}}' => true,
                    '{"nul":{"radius":"x","side":"y"}}' => false,
                    '{"any":{"side":2}}' => true,
                    '{"any":{"radius":"x","side":"y"}}' => false,
                    '{"dove":{"radius":1}}' => true,
                    '{"dove":{"side":2}}' => true,
                    '{"dove":{"radius":"x","side":"y"}}' => false,
                    '{"wrap":{"radius":1}}' => true,
                    '{"wrap":{"radius":"x","side":"y"}}' => false,
                    '{"herd":{"a":{"side":1}}}' => true,
                    '{"herd":{"a":{"side":1},"b":{"radius":2}}}' => true,
                    '{"herd":{"a":{"radius":"x","side":"y"}}}' => false,
                    '{"herd":{"a":5}}' => false,
                ],
            ),
        );
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: self::nestedUnionInterfaceSpec(required: true),
                key: 'required union interface beside null',
                payloads: [
                    '{"req":{"radius":1}}' => true,
                    '{"req":null}' => true,
                    '{"req":{"radius":"x","side":"y"}}' => false,
                    '{"req":5}' => false,
                    '{}' => false,
                ],
            ),
        );
    }

    /**
     * OpenAPI 3.0: `{oneOf: [$ref Shape], nullable: true}` and `{allOf: [$ref Shape], nullable: true}`
     * are typed `?Shape`. Runtime could build neither from an object (the members sit one level down),
     * and it refused null for the `allOf` spelling: the `nullable` beside it short-circuited only the
     * checks of its own level, and the `allOf` branch, handed the null, said "must be Circle".
     */
    public function testANullableUnionInterfaceOfOpenApi30IsBuiltAndAcceptsNull(): void
    {
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: self::nestedUnionInterfaceSpec30(),
                key: 'nullable union interface of 3.0',
                payloads: [
                    '{"wren":{"radius":1}}' => true,
                    '{"wren":{"side":2}}' => true,
                    '{"wren":{"radius":"x","side":"y"}}' => false,
                    '{"lark":{"radius":1}}' => true,
                    '{"lark":{"side":2}}' => true,
                    '{"lark":null}' => true,
                    '{"lark":{"radius":"x","side":"y"}}' => false,
                    '{"lark":5}' => false,
                    '{"dove":{"radius":1}}' => true,
                    '{"dove":5}' => false,
                ],
            ),
        );
    }

    /**
     * The neighbours of the nested spellings, which already worked: a bare `$ref` to the union, one with
     * a `description` beside it, a list of `allOf: [$ref Shape]` items, a list and a map of `oneOf:
     * [Shape, null]`, a union of the component with a string and null, and the 3.0 nullable spellings
     * that accepted null.
     */
    public function testUnionInterfaceNeighboursOfANestedSpellingAreBuilt(): void
    {
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: self::nestedUnionInterfaceSpec(),
                key: 'neighbours of a nested union interface',
                payloads: [
                    '{"nul":null}' => true,
                    '{"any":null}' => true,
                    '{"wrap":null}' => true,
                    '{"plain":{"radius":1}}' => true,
                    '{"plain":5}' => false,
                    '{"owl":{"side":2}}' => true,
                    '{"owl":5}' => false,
                    '{"flock":[{"radius":1}]}' => true,
                    '{"flock":[5]}' => false,
                    '{"arr":[{"radius":1},null]}' => true,
                    '{"arr":[5]}' => false,
                    '{"tri":{"radius":1}}' => true,
                    '{"tri":"s"}' => true,
                    '{"tri":null}' => true,
                    '{"tri":5}' => false,
                    '{"map":{"a":{"side":1},"b":null}}' => true,
                    '{"map":{"a":5}}' => false,
                ],
                diverging: [
                    // Outside the runtime mode this test is about, and unasserted here: Symfony leaves the
                    // items of the untyped `flock` list unchecked.
                    'symfony' => ['{"flock":[5]}' => null],
                ],
            ),
        );
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: self::nestedUnionInterfaceSpec30(),
                key: 'neighbours of a nullable union interface of 3.0',
                payloads: [
                    '{"wren":null}' => true,
                    '{"kite":null}' => true,
                    '{"kite":{"side":1}}' => true,
                    '{"kite":5}' => false,
                    '{"hawk":null}' => true,
                    '{"hawk":{"radius":1}}' => true,
                    '{"hawk":{"radius":"x"}}' => false,
                ],
            ),
        );
    }

    /**
     * Runtime refuses a value no member accepts as a member mismatch, not as a type it cannot build.
     */
    public function testRuntimeRefusesAScalarForANestedUnionInterfaceAsAMemberMismatch(): void
    {
        $fqcn = $this->generate(
            spec: self::nestedUnionInterfaceSpec(),
            namespace: $this->namespaceFor(GenerationMode::Runtime, 'nested union interface message'),
            mode: GenerationMode::Runtime->value,
        );
        foreach (['{"nul":5}', '{"dove":5}', '{"any":5}', '{"wrap":5}'] as $json) {
            $outcome = $this->payloadOutcome(GenerationMode::Runtime, $fqcn, $json);
            $this->assertSame(PayloadVerdict::Refused, $outcome->verdict, $json . ': ' . $outcome->detail);
            $this->assertStringNotContainsString('Unsupported type', $outcome->detail, $json);
            $this->assertStringContainsString('Circle', $outcome->detail, $json);
        }
    }

    /**
     * @return array<string, mixed>
     */
    private static function nestedUnionInterfaceSpec(bool $required = false): array
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $null = ['type' => 'null'];
        $properties = $required
            ? ['req' => ['oneOf' => [$ref('Shape'), $null]]]
            : [
                'nul' => ['oneOf' => [$ref('Shape'), $null]],
                'any' => ['anyOf' => [$ref('Shape'), $null]],
                'dove' => ['allOf' => [$ref('Shape')]],
                'wrap' => ['anyOf' => [['allOf' => [$ref('Shape')]], $null]],
                'herd' => ['type' => 'object', 'additionalProperties' => ['allOf' => [$ref('Shape')]]],
                'plain' => $ref('Shape'),
                'owl' => [...$ref('Shape'), 'description' => 'A shape.'],
                'flock' => ['type' => 'array', 'items' => ['allOf' => [$ref('Shape')]]],
                'arr' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Shape'), $null]]],
                'tri' => ['oneOf' => [$ref('Shape'), ['type' => 'string'], $null]],
                'map' => ['type' => 'object', 'additionalProperties' => ['oneOf' => [$ref('Shape'), $null]]],
            ];

        return [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Circle' => ['type' => 'object', 'properties' => ['radius' => ['type' => 'integer']]],
                'Square' => ['type' => 'object', 'properties' => ['side' => ['type' => 'integer']]],
                'Shape' => ['anyOf' => [$ref('Circle'), $ref('Square')]],
                'Probe' => ['type' => 'object', 'properties' => $properties] + ($required ? ['required' => ['req']] : []),
            ]],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function nestedUnionInterfaceSpec30(): array
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];

        return [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Circle' => ['type' => 'object', 'properties' => ['radius' => ['type' => 'integer']]],
                'Square' => ['type' => 'object', 'properties' => ['side' => ['type' => 'integer']]],
                'Shape' => ['anyOf' => [$ref('Circle'), $ref('Square')]],
                'Nshape' => ['anyOf' => [$ref('Circle'), $ref('Square')], 'nullable' => true],
                'Probe' => ['type' => 'object', 'properties' => [
                    'wren' => ['oneOf' => [$ref('Shape')], 'nullable' => true],
                    'lark' => ['allOf' => [$ref('Shape')], 'nullable' => true],
                    'dove' => ['allOf' => [$ref('Shape')]],
                    'kite' => $ref('Nshape'),
                    'hawk' => ['allOf' => [$ref('Circle')], 'nullable' => true],
                ]],
            ]],
        ];
    }

    /**
     * A union branch `{allOf: [{$ref: Teal}]}` is Teal wrapped: typed `Teal` and checked as "is a Teal",
     * as a bare `$ref` is. Runtime read the wrapper as a branch of no class, so the inline object beside
     * it was never marked as its own class either, and its open spelling matched the built Teal: a
     * payload only Teal accepts (`stoat` is no integer) was refused as matching two `oneOf` branches.
     * The payloads both branches accept stay refused, and `anyOf` (`elk`) always agreed.
     */
    public function testAnAllOfWrappedRefBranchLetsTheInlineObjectBesideItBeItsOwnClass(): void
    {
        $wrapped = ['allOf' => [['$ref' => '#/components/schemas/Teal']]];
        $stoat = ['type' => 'object', 'properties' => ['stoat' => ['type' => 'integer']]];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Teal' => ['type' => 'object', 'properties' => ['marten' => ['type' => 'integer']], 'required' => ['marten']],
                'Probe' => ['type' => 'object', 'properties' => [
                    'fox' => ['oneOf' => [$stoat, $wrapped]],
                    'owl' => ['oneOf' => [$stoat + ['required' => ['stoat']], $wrapped]],
                    'elk' => ['anyOf' => [$stoat, $wrapped]],
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'allOf-wrapped ref branch beside an inline object',
                payloads: [
                    '{"fox":{"marten":1,"stoat":"x"}}' => true,
                    '{"fox":{"stoat":1}}' => true,
                    '{"fox":{"marten":1}}' => false,
                    '{"fox":{"stoat":"x"}}' => false,
                    '{"owl":{"marten":1,"stoat":"x"}}' => true,
                    '{"owl":{"marten":1}}' => true,
                    '{"owl":{"marten":1,"stoat":1}}' => false,
                    '{"owl":{"stoat":"x"}}' => false,
                    '{"elk":{"marten":1,"stoat":"x"}}' => true,
                    '{"elk":{"marten":1}}' => true,
                    '{"elk":{"stoat":"x"}}' => false,
                ],
                // Symfony's serializer builds ONE member of the class union, and the validator judges
                // the object it was handed: a second match is not seen, and a payload only a later
                // member accepts depends on the serializer release (README.support-matrix.md).
                diverging: ['symfony' => [
                    '{"fox":{"marten":1,"stoat":"x"}}' => null,
                    '{"fox":{"marten":1}}' => null,
                    '{"owl":{"marten":1,"stoat":"x"}}' => null,
                    '{"owl":{"marten":1}}' => null,
                    '{"owl":{"marten":1,"stoat":1}}' => null,
                    '{"elk":{"marten":1,"stoat":"x"}}' => null,
                ]],
            ),
        );
    }

    /**
     * A list item or map value that names a NULLABLE array component of dates or enums (`items: {$ref:
     * Days}` over `Days: {type: array, nullable: true, items: {format: date}}`) admits null like the
     * component does. Symfony typed it as the component's own list, `array<?array<DateTimeImmutable>>`,
     * and its `ArrayDenormalizer` handed the null item to the inner date denormalization, which refused
     * it. The same list written inline (`figs`, `tints`, `dateMap`) is held as strings the callback
     * checks, and always accepted the null; a non-nullable component (`chives`) keeps its dates.
     */
    public function testANullableListComponentOfDatesOrEnumsOneContainerDeepAdmitsNull(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $dates = ['type' => 'array', 'nullable' => true, 'items' => ['type' => 'string', 'format' => 'date']];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Days' => $dates,
                'Stamps' => ['type' => 'array', 'nullable' => true, 'items' => ['type' => 'string', 'format' => 'date-time']],
                'Hue' => ['type' => 'string', 'enum' => ['red', 'teal']],
                'Hues' => ['type' => 'array', 'nullable' => true, 'items' => $ref('Hue')],
                'Sprouts' => ['type' => 'array', 'items' => ['type' => 'string', 'format' => 'date']],
                'Probe' => ['type' => 'object', 'properties' => [
                    'plums' => ['type' => 'array', 'items' => $ref('Days')],
                    'stamps' => ['type' => 'array', 'items' => $ref('Stamps')],
                    'hues' => ['type' => 'array', 'items' => $ref('Hues')],
                    'dayMap' => ['type' => 'object', 'additionalProperties' => $ref('Days')],
                    'chives' => ['type' => 'array', 'items' => $ref('Sprouts')],
                    'figs' => ['type' => 'array', 'items' => $dates],
                    'tints' => ['type' => 'array', 'items' => ['type' => 'array', 'nullable' => true, 'items' => $ref('Hue')]],
                    'dateMap' => ['type' => 'object', 'additionalProperties' => $dates],
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'nullable list component of dates or enums in a container',
                payloads: [
                    '{"plums":[null]}' => true,
                    '{"plums":[["2020-01-02"],null]}' => true,
                    '{"plums":[["x"]]}' => false,
                    '{"stamps":[null]}' => true,
                    '{"stamps":[["2020-01-02T10:00:00Z"]]}' => true,
                    '{"stamps":[["x"]]}' => false,
                    '{"hues":[null]}' => true,
                    '{"hues":[["red"],null]}' => true,
                    '{"hues":[["blue"]]}' => false,
                    '{"dayMap":{"a":null}}' => true,
                    '{"dayMap":{"a":["2020-01-02"],"b":null}}' => true,
                    '{"dayMap":{"a":["x"]}}' => false,
                    '{"chives":[["2020-01-02"]]}' => true,
                    '{"chives":[null]}' => false,
                    '{"chives":[["x"]]}' => false,
                    '{"figs":[null]}' => true,
                    '{"figs":[["x"]]}' => false,
                    '{"tints":[null]}' => true,
                    '{"tints":[["blue"]]}' => false,
                    '{"dateMap":{"a":null}}' => true,
                    '{"dateMap":{"a":["x"]}}' => false,
                ],
            ),
        );
    }

    /**
     * Symfony holds a property `$ref` to a union component with a list member as the decoded `array`, so
     * no class is built for the items. An item written `{$ref: Indigo, properties: {ferret: …}}` kept the
     * keys beside the reference and lost Indigo's own: a `kiwi` off its `multipleOf` passed. The same
     * union written inline on the property (`heron`), and the same list on a plain property (`otter`),
     * always checked both.
     */
    public function testAListMemberOfAUnionComponentChecksItsItemReferenceAndTheKeysBesideIt(): void
    {
        $items = ['$ref' => '#/components/schemas/Indigo', 'properties' => ['ferret' => ['type' => 'string']]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Indigo' => ['type' => 'object', 'properties' => ['kiwi' => ['type' => 'number', 'multipleOf' => 0.5]]],
                'Teal' => ['anyOf' => [['type' => 'array', 'items' => $items]]],
                'Mauve' => ['anyOf' => [['type' => 'array', 'items' => $items], ['type' => 'string']]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'walrus' => ['$ref' => '#/components/schemas/Teal'],
                    'puffin' => ['$ref' => '#/components/schemas/Mauve'],
                    'heron' => ['anyOf' => [['type' => 'array', 'items' => $items]]],
                    'otter' => ['type' => 'array', 'items' => $items],
                ]],
            ]],
        ];

        $payloads = [];
        foreach (['walrus', 'puffin', 'heron', 'otter'] as $name) {
            $payloads[sprintf('{"%s":[{"kiwi":-30.875}]}', $name)] = false;
            $payloads[sprintf('{"%s":[{"ferret":5}]}', $name)] = false;
            $payloads[sprintf('{"%s":[{"kiwi":1.5,"ferret":"a"}]}', $name)] = true;
        }
        $payloads['{"puffin":"a"}'] = true;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'union component list item ref siblings', payloads: $payloads),
        );
    }

    /**
     * `oneOf: [{$ref: Teal}, {type: object, additionalProperties: false}]`: Symfony holds the property as
     * the decoded `array` (the closed member has no class), yet the `$ref` branch stayed "is a Teal",
     * which an array never is. `{"panda": -12}` matched no branch and was refused; `{}` matched only the
     * closed member and passed, though Teal admits it too. The `anyOf` spelling (`koala`) always agreed.
     */
    public function testARefBranchOfAUnionHeldAsAnArrayIsSpelledOut(): void
    {
        $branches = [['$ref' => '#/components/schemas/Teal'], ['type' => 'object', 'additionalProperties' => false]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Teal' => ['type' => 'object', 'properties' => ['panda' => ['type' => 'integer']]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'wombat' => ['oneOf' => $branches],
                    'koala' => ['anyOf' => $branches],
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'ref branch of a union held as array',
                payloads: [
                    '{"wombat":{"panda":-12}}' => true,
                    '{"wombat":{}}' => false,
                    '{"wombat":{"panda":"x"}}' => false,
                    '{"koala":{"panda":-12}}' => true,
                    '{"koala":{}}' => true,
                    '{"koala":{"panda":"x"}}' => false,
                ],
            ),
        );
    }

    /**
     * A `$ref` chain under a UNION BRANCH below a container, enforced at every hop in every mode.
     *
     * The recursive case above is the other shape: there the chain repeats, a class materializes at the
     * first hop, and each mode's own cascade carries the rest. Here nothing materializes anywhere —
     * under a container the branch type collapses to `array` — so every level of the chain reaches the
     * consumer ONLY through the constraints the generator inlines, and each mode then has to read those
     * constraints with a different machine: Symfony builds `Assert` specs from them, Laravel a flat rule
     * map, laravel-data its own, runtime walks the schema it holds.
     *
     * 2.15.8 and 2.15.9 were measured on runtime alone, which is exactly the gap that let a recursive
     * schema go unchecked in Laravel mode once before. This is the same question asked of all five.
     *
     * Both branch keywords, because they were broken and fixed a release apart: `oneOf` in 2.15.6-9,
     * `allOf` only in 2.15.11, where it had been skipped on the rule that its `$ref` gets a class —
     * true on a property, false under a container.
     *
     * @param string $invalidJson a payload violating the chain at ONE level
     * @param string $branchKeyword `oneOf` or `allOf`, the two spellings of the same chain
     */
    #[DataProvider('unionChainDepthProvider')]
    public function testARefChainUnderAUnionBranchIsEnforcedAtEveryHopInEveryMode(
        string $key,
        string $invalidJson,
        string $branchKeyword,
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'ChainTag' => [
                        'type' => 'object',
                        'required' => ['label'],
                        'properties' => ['label' => ['type' => 'string', 'minLength' => 2]],
                    ],
                    'ChainLink' => [
                        'type' => 'object',
                        'required' => ['code'],
                        'properties' => [
                            'code' => ['type' => 'string', 'minLength' => 3],
                            'tags' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/ChainTag']],
                        ],
                    ],
                    'ChainMiddle' => [
                        'type' => 'object',
                        'required' => ['links'],
                        'properties' => [
                            'links' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/ChainLink']],
                        ],
                    ],
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['f'],
                        'properties' => [
                            'f' => ['type' => 'array', 'items' => [$branchKeyword => [
                                ['$ref' => '#/components/schemas/ChainMiddle'],
                            ]]],
                        ],
                    ],
                ],
            ],
        ];

        $valid = '{"f":[{"links":[{"code":"abc","tags":[{"label":"ok"}]}]}]}';

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            // The branch keyword belongs in the namespace key: without it both spellings generate into
            // one namespace, PHP keeps the classes it loaded first, and the second spelling silently
            // re-tests the first one's classes — green and proving nothing.
            observe: fn(GenerationMode $mode): array => $this->verdict(
                mode: $mode,
                spec: $spec,
                key: 'chain ' . $branchKeyword . ' ' . $key,
                validJson: $valid,
                invalidJson: $invalidJson,
            ),
            diverges: self::declaredUnionChainDivergences()[$key] ?? [],
            context: $branchKeyword . ' chain ' . $key,
        );
    }

    /**
     * @return array<string, array{0: string, 1: string, 2: string}>
     */
    public static function unionChainDepthProvider(): array
    {
        $cases = [
            // B: the hop every version of the inlining reached.
            'B required' => '{"f":[{}]}',
            // C: reached from 2.15.8.
            'C minLength' => '{"f":[{"links":[{"code":"x"}]}]}',
            'C required' => '{"f":[{"links":[{}]}]}',
            // D: reached from 2.15.9.
            'D minLength' => '{"f":[{"links":[{"code":"abc","tags":[{"label":"z"}]}]}]}',
            'D required' => '{"f":[{"links":[{"code":"abc","tags":[{}]}]}]}',
        ];

        $provided = [];
        foreach (['oneOf', 'allOf'] as $branchKeyword) {
            foreach ($cases as $key => $invalidJson) {
                $provided[$branchKeyword . ' ' . $key] = [$key, $invalidJson, $branchKeyword];
            }
        }

        return $provided;
    }

    /**
     * An `allOf` under a keyword that materializes nothing is enforced in every mode.
     *
     * Symfony, Laravel, laravel-data and yii3 share one constraint filter, and the flag that says
     * "nothing materializes here, keep the composition" was set for the container keys and lost at the
     * first hop into `contentSchema`, `not`, `if`/`then` and `contains`. Those four modes emitted `{}`
     * for a branch carrying `required` and a bound while runtime kept it — measured per key before the
     * flag was threaded through.
     *
     * @param array<string, mixed> $extra the keyword under test, wrapping the same `allOf`
     */
    #[DataProvider('allOfUnderKeywordProvider')]
    public function testAnAllOfUnderANonMaterializingKeywordIsEnforcedInEveryMode(
        string $key,
        array $extra,
        string $validJson,
        string $invalidJson,
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'required' => ['f'], 'properties' => ['f' => $extra]],
            ]],
        ];

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, 'allofunder ' . $key, $validJson, $invalidJson),
            context: 'allOf under ' . $key,
        );
    }

    /**
     * @return array<string, array{0: string, 1: array<string, mixed>, 2: string, 3: string}>
     */
    public static function allOfUnderKeywordProvider(): array
    {
        $deep = ['allOf' => [[
            'type' => 'object',
            'required' => ['marker'],
            'properties' => ['marker' => ['type' => 'string', 'minLength' => 7]],
        ]]];

        return [
            'then' => [
                'then',
                ['type' => 'object', 'properties' => ['marker' => ['type' => 'string']], 'if' => ['type' => 'object']] + ['then' => $deep],
                '{"f":{"marker":"loooong"}}',
                '{"f":{"marker":"short"}}',
            ],
            'contains' => [
                'contains',
                ['type' => 'array', 'items' => ['type' => 'object']] + ['contains' => $deep],
                '{"f":[{"marker":"loooong"}]}',
                '{"f":[{"marker":"short"}]}',
            ],
        ];
    }

    /**
     * What a document states about the OBJECT ITSELF, enforced in every mode.
     *
     * These keywords have no property to hang off, so each mode has to carry them at the class level or
     * lose them. Measured before 2.15.16: runtime, laravel and laravel-data carried none of them and
     * accepted every violation; Symfony carried three of four, losing `minProperties` because on a
     * property that one becomes `#[Assert\Count]` and was dropped from the interpreter to avoid
     * doubling — with no attribute at the class level to take over.
     *
     * @param array<string, mixed> $extra the object-wide keyword under test
     */
    #[DataProvider('objectWideProvider')]
    public function testObjectWideKeywordsAreEnforcedInEveryMode(
        string $key,
        array $extra,
        string $validJson,
        string $invalidJson,
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'kind' => ['type' => 'string'],
                            'code' => ['type' => 'string'],
                            'extra' => ['type' => 'string'],
                        ],
                    ] + $extra,
                ],
            ],
        ];

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, 'objectwide ' . $key, $validJson, $invalidJson),
            context: 'object-wide ' . $key,
        );
    }

    /**
     * @return array<string, array{0: string, 1: array<string, mixed>, 2: string, 3: string}>
     */
    public static function objectWideProvider(): array
    {
        return [
            'minProperties' => [
                'minProperties',
                ['minProperties' => 3],
                '{"kind":"a","code":"b","extra":"c"}',
                '{"kind":"a","code":"b"}',
            ],
            'dependentRequired' => [
                'dependentRequired',
                ['dependentRequired' => ['kind' => ['code']]],
                '{"kind":"a","code":"b"}',
                '{"kind":"a"}',
            ],
            'not' => [
                'not',
                ['not' => ['required' => ['extra']]],
                '{"kind":"a","code":"b"}',
                '{"kind":"a","extra":"c"}',
            ],
            'conditional' => [
                'conditional',
                [
                    'if' => ['required' => ['kind']],
                    'then' => ['properties' => ['code' => ['type' => 'string', 'minLength' => 7]]],
                ],
                '{"kind":"a","code":"loooong"}',
                '{"kind":"a","code":"short"}',
            ],
        ];
    }

    /**
     * A `$ref` under an APPLICATOR, enforced in every mode.
     *
     * The generator's inlining is what makes these keywords work at all — nothing materializes for
     * `contains`, `prefixItems` or `unevaluatedItems`, so each mode reads the same emitted constraints
     * with its own machine. Runtime was measured first and fixed in 2.15.14; this is the same question
     * asked of all five, because the last two rounds of this bug answered differently per mode: `allOf`
     * needed a second fix in Symfony (its interpreter had no such keyword) and a third in Laravel (its
     * rule map already covered part of it).
     *
     * @param string $invalidJson a payload the referenced component forbids
     */
    #[DataProvider('applicatorRefProvider')]
    public function testARefUnderAnApplicatorIsEnforcedInEveryMode(string $key, string $invalidJson): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Marked' => [
                        'type' => 'object',
                        'required' => ['marker'],
                        'properties' => ['marker' => ['type' => 'string', 'minLength' => 7]],
                    ],
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['f'],
                        'properties' => ['f' => self::applicatorProperty($key)],
                    ],
                ],
            ],
        ];

        $valid = match ($key) {
            'unevaluatedItems' => '{"f":["x",{"marker":"loooong"}]}',
            'not' => '{"f":{"other":"y"}}',
            'then' => '{"f":{"marker":"loooong"}}',
            'dependentSchemas' => '{"f":{"kind":"x","marker":"loooong"}}',
            default => '{"f":[{"marker":"loooong"}]}',
        };

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, 'applicator ' . $key, $valid, $invalidJson),
            context: 'applicator ' . $key,
        );
    }

    /**
     * @return array<string, array{0: string, 1: string}>
     */
    public static function applicatorRefProvider(): array
    {
        return [
            'contains' => ['contains', '{"f":[{"marker":"short"}]}'],
            'prefixItems' => ['prefixItems', '{"f":[{"marker":"short"}]}'],
            'unevaluatedItems' => ['unevaluatedItems', '{"f":["x",{"marker":"short"}]}'],
            // `marker` present makes the value MATCH what the reference describes, which `not` forbids.
            'not' => ['not', '{"f":{"marker":"anything"}}'],
            'then' => ['then', '{"f":{"marker":"short"}}'],
            'dependentSchemas' => ['dependentSchemas', '{"f":{"kind":"x","marker":"short"}}'],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function applicatorProperty(string $keyword): array
    {
        $ref = ['$ref' => '#/components/schemas/Marked'];

        return match ($keyword) {
            'contains' => ['type' => 'array', 'items' => ['type' => 'object'], 'contains' => $ref],
            'prefixItems' => ['type' => 'array', 'prefixItems' => [$ref]],
            // `other` exists so the VALID payload can be non-empty: Laravel's `required` rule fails on
            // an empty array, so `{"f":{}}` would be rejected there for a reason that has nothing to do
            // with `not` — the probe, not the code.
            'not' => [
                'type' => 'object',
                'properties' => ['marker' => ['type' => 'string'], 'other' => ['type' => 'string']],
                'not' => $ref,
            ],
            'then' => [
                'type' => 'object',
                'properties' => ['marker' => ['type' => 'string']],
                'if' => ['type' => 'object'],
                'then' => $ref,
            ],
            'dependentSchemas' => [
                'type' => 'object',
                'properties' => ['kind' => ['type' => 'string'], 'marker' => ['type' => 'string']],
                'dependentSchemas' => ['kind' => $ref],
            ],
            default => [
                'type' => 'array',
                'prefixItems' => [['type' => 'string']],
                'unevaluatedItems' => $ref,
            ],
        };
    }

    /**
     * @return array<string, array<string, array{expected: array{valid: bool, invalid: bool}, reason: string}>>
     */
    private static function declaredUnionChainDivergences(): array
    {
        return [];
    }

    /**
     * The same cycle, entered from the class that IS the cycle: `Probe.children` is a list of `Probe`.
     *
     * The case above always reaches the recursive schema through a non-recursive root, and that is the
     * only shape the suite ever measured — which hid a hole the same size as the one it was written for.
     * Seen from the root, the first `$ref` back to the root looked like a fresh class: it was expanded
     * one level and PRUNED of everything the dotted rules were assumed to cover, while
     * `laravelNestedRules()` had emitted no `children.*` path at all, because it cannot expand a cycle
     * either. Measured: a child violating `minimum: 1` was ACCEPTED in laravel and laravel-data mode, and
     * a child sending a string for an integer died as a `TypeError` in the constructor rather than as a
     * 422. Runtime and Symfony walk the real schema and were right all along.
     */
    #[DataProvider('rootRecursiveDepthProvider')]
    public function testARecursiveSchemaIsEnforcedWhenItIsTheRootClassItself(string $key, string $invalidJson): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['id'],
                        'properties' => [
                            'id' => ['type' => 'integer', 'minimum' => 1],
                            'label' => ['type' => 'string', 'not' => ['const' => 'forbidden']],
                            'children' => [
                                'type' => 'array',
                                'items' => ['$ref' => '#/components/schemas/Probe'],
                            ],
                        ],
                    ],
                ],
            ],
        ];

        $valid = '{"id":1,"label":"ok","children":[{"id":2,"children":[{"id":3}]}]}';

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, 'rootrec ' . $key, $valid, $invalidJson),
            context: 'root-recursive ' . $key,
        );
    }

    /**
     * @return array<string, array{0: string, 1: string}>
     */
    public static function rootRecursiveDepthProvider(): array
    {
        $cases = [
            'root minimum' => '{"id":0}',
            'child minimum' => '{"id":1,"children":[{"id":0}]}',
            'grandchild minimum' => '{"id":1,"children":[{"id":2,"children":[{"id":0}]}]}',
            'child type' => '{"id":1,"children":[{"id":"nope"}]}',
            'child required' => '{"id":1,"children":[{"label":"x"}]}',
            'child not' => '{"id":1,"children":[{"id":2,"label":"forbidden"}]}',
            'grandchild not' => '{"id":1,"children":[{"id":2,"children":[{"id":3,"label":"forbidden"}]}]}',
        ];

        $provided = [];
        foreach ($cases as $key => $invalidJson) {
            $provided[$key] = [$key, $invalidJson];
        }

        return $provided;
    }

    /**
     * `format: date-time` accepts exactly the four patterns every mode agrees on
     * (`GeneratedDtoInterface::DATE_TIME_FORMATS`). Symfony mode cannot hold that line: the property is a
     * `DateTimeImmutable`, so the serializer parses the string before any constraint runs — and PHP's
     * parser is generous enough to accept `"yesterday"`.
     *
     * Same shape as the `42.0` and JSON-array boundaries: the serializer decides before generated code
     * gets a say. Pinned rather than left to be discovered, and the reason it is not in the agreeing
     * keyword matrix.
     */
    public function testALooseDateTimeStringIsRefusedWhereverTheGeneratorOwnsTheCheck(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['f'],
                        'properties' => ['f' => ['type' => 'string', 'format' => 'date-time']],
                    ],
                ],
            ],
        ];

        $key = 'loose date-time';
        $valid = '{"f":"2026-03-10T12:00:00+00:00"}';
        $loose = '{"f":"yesterday"}';

        // Every mode, not the three this used to name. The support matrix's row claims all five, and
        // laravel-data and yii3 were asserted by nobody — measured since, and both refuse, but an
        // unmeasured cell is a claim either way.
        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, $key, $valid, $loose),
            diverges: self::diverges(
                mode: GenerationMode::Symfony,
                expected: ['valid' => true, 'invalid' => true],
                reason: 'the property is a DateTimeImmutable, so the serializer parses the string before any '
                    . "generated constraint runs, and PHP's parser accepts \"yesterday\"",
            ),
            context: $key,
        );
    }

    /**
     * The RFC 3339 spellings the four shared patterns (`GeneratedDtoInterface::DATE_TIME_FORMATS`) do
     * not settle, measured on a `format: date-time` PROPERTY. The common answer is what most modes do;
     * every other mode states why. Each row is a README.support-matrix.md row ("RFC 3339 spellings of a
     * `format: date-time` property").
     *
     * `DtoValidator` itself follows RFC 3339 since 2.15.161 (`DtoValidatorTest::testFormatDateTimeFollowsRfc3339`),
     * but a runtime DTO hands it the PARSED value written back as ATOM: what reaches it is decided by
     * the deserializer's four patterns, so the runtime column here is the deserializer's.
     *
     * @param array<string, bool> $diverging accepted or not, by mode value, for the modes that differ
     */
    #[DataProvider('rfc3339DateTimeSpellings')]
    public function testRfc3339DateTimeSpellingsArePinnedPerMode(string $value, bool $accepted, array $diverging): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec(['type' => 'string', 'format' => 'date-time']);
        $key = 'rfc3339 ' . $value;
        $diverges = [];
        foreach ($diverging as $modeValue => $modeAccepted) {
            $diverges += self::diverges(
                mode: GenerationMode::from($modeValue),
                expected: ['valid' => true, 'invalid' => $modeAccepted],
                reason: self::RFC3339_DIVERGENCE_REASONS[$modeValue],
            );
        }

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => $accepted],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, $key, '{"f":"2026-03-10T12:00:00+00:00"}', '{"f":"' . $value . '"}'),
            diverges: $diverges,
            context: $key,
        );
    }

    /**
     * @return array<string, array{0: string, 1: bool, 2: array<string, bool>}>
     */
    public static function rfc3339DateTimeSpellings(): array
    {
        return [
            // RFC 3339 allows both lower case; three of five modes parse with patterns that spell `T` and `Z`.
            // Since 2.15.163 runtime's deserializer reads `t` and `z` as their upper case.
            'lowercase t and z' => ['2026-03-10t12:00:00z', false, ['symfony' => true, 'runtime' => true]],
            'lowercase t, numeric offset' => ['2026-03-10t12:00:00+02:00', false, ['symfony' => true, 'runtime' => true]],
            // Since 2.15.163 laravel and laravel-data judge the plain property with the interpreter's own
            // reader (the RFC 3339 shape and a warning-free parse), as a union of the same value already was:
            // `date_format` formats the parsed value back and compares strings, and no format writes `z`,
            // `-00:00` or a fraction of one, two, four or five digits back as it came.
            'lowercase z' => ['2026-03-10T12:00:00z', true, []],
            'lowercase z after a fraction' => ['2026-03-10T12:00:00.123z', true, []],
            'unknown local offset' => ['2026-03-10T12:00:00-00:00', true, []],
            'one fraction digit' => ['2026-03-10T12:00:00.5Z', true, []],
            'two fraction digits' => ['2026-03-10T12:00:00.12+02:00', true, []],
            'four fraction digits' => ['2026-03-10T12:00:00.1234Z', true, []],
            'five fraction digits' => ['2026-03-10T12:00:00.12345-05:30', true, []],
            // Refused everywhere the generator owns the check, and pinned so the reader above stays strict.
            'offset minute out of range' => ['2026-03-10T12:00:00+02:60', false, ['symfony' => true]],
            'offset hour 24' => ['2026-03-10T12:00:00+24:00', false, ['symfony' => true]],
            'leap second' => ['2026-03-10T23:59:60Z', false, ['symfony' => true]],
            // Not RFC 3339, accepted by all five: one of the shared patterns (see the support matrix's note).
            'no offset' => ['2026-03-10T12:00:00', true, []],
            'space separator, no offset' => ['2026-03-10 12:00:00', true, []],
            // Not RFC 3339, and not a shared pattern.
            'space separator, offset' => ['2026-03-10 12:00:00Z', false, ['symfony' => true]],
            // Since 2.15.163 yii3 matches the raw string against the interpreter's RFC 3339 shape before
            // `#[ToDateTime]`, whose `P` read all four as offsets.
            'offset without colon' => ['2026-03-10T12:00:00+0200', false, ['symfony' => true]],
            'offset of hours only' => ['2026-03-10T12:00:00+02', false, ['symfony' => true]],
            'zone name' => ['2026-03-10T12:00:00EST', false, ['symfony' => true]],
            // Laravel's `date_format` formatted `+25:00` back unchanged (laravel answered with a 500 from the
            // hydration after it); a `not_regex` refused it since 2.15.162, the RFC 3339 shape since 2.15.163.
            'offset hour out of range' => ['2026-03-10T12:00:00+25:00', false, ['symfony' => true]],
            // Neighbours every mode already accepted.
            'numeric offset' => ['2026-03-10T12:00:00-05:30', true, []],
            'fraction and Z' => ['2026-03-10T12:00:00.123456Z', true, []],
        ];
    }

    private const array RFC3339_DIVERGENCE_REASONS = [
        'symfony' => "the property is a DateTimeImmutable, so the serializer parses the string with PHP's free-form parser before any generated constraint runs",
        'yii3' => 'the RFC 3339 shape the raw string is matched against reads the offset `z` in either case, as `#[ToDateTime]`\'s `P` does',
        'runtime' => 'the deserializer reads the separator `t` and the zone `z` as their upper case, as RFC 3339 allows',
    ];

    /**
     * A closed class (`additionalProperties: false`) beside an object branch it cannot be told from in a
     * `oneOf`: the value is held as the decoded object, and the class branch was counted undecided — not
     * refuted — whatever key the object carried, so `{"stray": "x"}` matched nothing and was let in.
     * The other branch inline or behind a `$ref`.
     *
     * @param array<string, mixed> $otherBranch
     */
    #[DataProvider('closedClassBesideAnObjectBranchCases')]
    public function testAClosedClassBranchRefusesAnExtraKeyOfAHeldObject(array $otherBranch, string $case): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas'] = [
            'Probe' => ['type' => 'object', 'properties' => [
                'raven' => ['oneOf' => [['$ref' => '#/components/schemas/Corala'], $otherBranch]],
            ]],
            'Corala' => ['type' => 'object', 'properties' => ['yak' => ['type' => 'number']], 'additionalProperties' => false],
            'Umbera' => ['type' => 'object', 'required' => ['llama']],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'closed class beside an object branch ' . $case,
                payloads: [
                    '{"raven":{"stray":"x"}}' => false,
                    '{"raven":{"yak":"x"}}' => false,
                    '{"raven":{"yak":1}}' => true,
                    '{"raven":{"llama":1}}' => true,
                    '{"raven":{"yak":1,"llama":2}}' => true,
                    '{}' => true,
                ],
            ),
        );
    }

    /**
     * @return array<string, array{0: array<string, mixed>, 1: string}>
     */
    public static function closedClassBesideAnObjectBranchCases(): array
    {
        return [
            'inline' => [['type' => 'object', 'required' => ['llama']], 'inline'],
            'ref' => [['$ref' => '#/components/schemas/Umbera'], 'ref'],
        ];
    }

    /**
     * A lowercase `t` is one answer per mode wherever the date-time sits. Symfony's serializer parses a
     * property and a list's items with PHP's free-form parser, which reads it; a list of lists stays a
     * list of strings there, and the emitted interpreter judged those case-sensitively — the same value
     * accepted one level up was refused. Runtime reads it everywhere since 2.15.163: its deserializer refused
     * it on the parsed property while `DtoValidator` took it in a held list. Laravel, laravel-data and yii3
     * refuse it everywhere (README.support-matrix, "RFC 3339 spellings").
     */
    public function testALowercaseDateTimeIsOneAnswerPerModeAtAnyDepth(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $dateTime = ['type' => 'string', 'format' => 'date-time'];
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'plain' => $dateTime,
            'owl' => ['type' => 'array', 'items' => ['format' => 'date-time']],
            'yak' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => $dateTime]],
        ]];

        $payloads = [];
        $lowercase = [];
        // Runtime holds an untyped item and a list of lists as the decoded strings, and `DtoValidator`
        // judges decoded data by RFC 3339, which allows the lower case (since 2.15.161); since 2.15.163
        // the deserializer reads the parsed property's `t` and `z` as their upper case too.
        foreach (['"%s"', '["%s"]', '[["%s"]]'] as $index => $shape) {
            $property = ['plain', 'owl', 'yak'][$index];
            $payloads[sprintf('{"%s":' . $shape . '}', $property, '2010-11-28T16:04:43+02:00')] = true;
            $payloads[sprintf('{"%s":' . $shape . '}', $property, '2010-11-28T16:04:43Z')] = true;
            $payloads[sprintf('{"%s":' . $shape . '}', $property, '2010-11-30T16:04:43+0x:00')] = false;
            $lowercaseT = sprintf('{"%s":' . $shape . '}', $property, '2010-11-28t16:04:43+02:00');
            $lowercaseBoth = sprintf('{"%s":' . $shape . '}', $property, '2010-11-28t16:04:43z');
            $payloads[$lowercaseT] = false;
            $payloads[$lowercaseBoth] = false;
            $lowercase[$lowercaseT] = true;
            $lowercase[$lowercaseBoth] = true;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'lowercase date-time at any depth',
                payloads: $payloads,
                diverging: ['symfony' => $lowercase, 'runtime' => $lowercase],
            ),
        );
    }

    /**
     * A `format: date-time` wrapped in a union — a single-member `oneOf` / `anyOf`, a `oneOf` of a list
     * of them, a pair with an integer — is judged as the plain property is. The union forms are checked
     * by the emitted interpreter, which tried the shared patterns with PHP's `p` and took `+0200`, `+02`
     * and `+25:00` as offsets, so laravel and laravel-data accepted what the plain property refused;
     * laravel-data crashed on a single-member union of a valid date-time (no cast, the global ATOM one
     * took it), and laravel built a `DateTimeImmutable` from `+25:00` after `date_format` let it through.
     */
    public function testADateTimeInsideAUnionIsJudgedAsThePlainProperty(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $dateTime = ['type' => 'string', 'format' => 'date-time'];
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'plain' => $dateTime,
            'one' => ['oneOf' => [$dateTime]],
            'any' => ['anyOf' => [$dateTime]],
            'arr' => ['oneOf' => [['type' => 'array', 'items' => $dateTime]]],
            'pair' => ['oneOf' => [$dateTime, ['type' => 'integer']]],
            'nul' => ['oneOf' => [$dateTime, ['type' => 'null']]],
            // The plain property's own forms: Laravel's rule sits on a nullable property and on `list.*`.
            'nullable' => ['type' => ['string', 'null'], 'format' => 'date-time'],
            'list' => ['type' => 'array', 'items' => $dateTime],
        ]];

        $payloads = [];
        $wrap = static fn(string $property, string $value): string => in_array($property, ['arr', 'list'], true)
            ? sprintf('{"%s":["%s"]}', $property, $value)
            : sprintf('{"%s":"%s"}', $property, $value);
        $properties = ['plain', 'one', 'any', 'arr', 'pair', 'nul', 'nullable', 'list'];
        // RFC 3339 also allows a lowercase `z`, the unknown local offset `-00:00` (§4.3) and a fraction of
        // any length; a union took all three and laravel's and laravel-data's plain property refused them
        // until 2.15.163, judged by a `date_format` round-trip instead of the interpreter's reader.
        $rfc3339Spellings = ['2024-01-02T10:00:00z', '2024-01-02T10:00:00.123z', '2024-01-02T10:00:00-00:00', '2024-01-02T10:00:00.5Z', '2024-01-02T10:00:00.12345+02:00'];
        foreach ($properties as $property) {
            foreach (['2024-01-02T10:00:00Z', '2024-01-02T10:00:00+02:00', '2024-01-02T10:00:00.585-05:30', '2024-01-02 10:00:00', '2024-01-02T10:00:00', ...$rfc3339Spellings] as $value) {
                $payloads[$wrap($property, $value)] = true;
            }
            foreach (['2024-01-02T10:00:00+0200', '2024-01-02T10:00:00+02', '2024-01-02T10:00:00+25:00', '2024-01-02T10:00:00+24:00', '2024-01-02T10:00:00+02:60', '2024-01-02T23:59:60Z', '2024-01-02T10:00:00EST', '2024-02-30T10:00:00Z', 'x'] as $value) {
                $payloads[$wrap($property, $value)] = false;
            }
        }
        $payloads['{"pair":7}'] = true;
        $payloads['{"nul":null}'] = true;
        // RFC 3339's lower case: symfony's parser and runtime read it in every form (runtime's deserializer
        // since 2.15.163 — it refused the parsed value while `DtoValidator` took it in a held list).
        $lowercase = [];
        foreach ($properties as $property) {
            foreach (['2024-01-02t10:00:00z', '2024-01-02t10:00:00+02:00'] as $value) {
                $payloads[$wrap($property, $value)] = false;
                $lowercase[$wrap($property, $value)] = true;
            }
        }

        // The documented per-mode answers for the plain property (README.support-matrix.md, rows "a loose
        // `format: date-time` string", "RFC 3339 spellings", "an impossible calendar date"): symfony's
        // serializer parses with PHP's free-form parser before any generated constraint runs. Unasserted
        // there: it depends on how the parser is reached. yii3 is asserted since 2.15.163: the raw string
        // is matched against the RFC 3339 shape before `#[ToDateTime]`'s `P`, which took all four offsets.
        $diverging = ['symfony' => $lowercase, 'runtime' => $lowercase];
        foreach ($properties as $property) {
            foreach (['2024-01-02T10:00:00+0200', '2024-01-02T10:00:00+02', '2024-01-02T10:00:00+25:00', '2024-01-02T10:00:00+24:00', '2024-01-02T10:00:00+02:60', '2024-01-02T23:59:60Z', '2024-01-02T10:00:00EST', '2024-02-30T10:00:00Z', 'x'] as $value) {
                $diverging['symfony'][$wrap($property, $value)] = null;
            }
        }
        // A list inside a union is held as the decoded strings in runtime mode; `DtoValidator` judges them
        // with the deserializer's own reader since 2.15.163, so the offset-less spellings are taken there too.

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'date-time inside a union',
                payloads: $payloads,
                diverging: $diverging,
            ),
        );

        // Written back as the string the plain property is; laravel wrote a single-member union, collapsed
        // to `?DateTimeImmutable`, as `{"date": …, "timezone_type": …}`.
        $spec['components']['schemas']['Probe']['properties']['day'] = ['oneOf' => [['type' => 'string', 'format' => 'date']]];
        $spec['components']['schemas']['Probe']['properties']['dawn'] = ['anyOf' => [['type' => 'string', 'format' => 'date'], ['type' => 'null']]];
        $writtenBack = [
            '{"plain":"2024-01-02T10:00:00Z"}' => '{"plain":"2024-01-02T10:00:00+00:00"}',
            '{"one":"2024-01-02T10:00:00Z"}' => '{"one":"2024-01-02T10:00:00+00:00"}',
            '{"any":"2024-01-02T10:00:00+02:00"}' => '{"any":"2024-01-02T10:00:00+02:00"}',
            '{"nul":"2024-01-02T10:00:00Z"}' => '{"nul":"2024-01-02T10:00:00+00:00"}',
            '{"plain":"2024-01-02T10:00:00z"}' => '{"plain":"2024-01-02T10:00:00+00:00"}',
            '{"nullable":"2024-01-02T10:00:00-00:00"}' => '{"nullable":"2024-01-02T10:00:00+00:00"}',
            '{"one":"2024-01-02T10:00:00-00:00"}' => '{"one":"2024-01-02T10:00:00+00:00"}',
            '{"day":"2024-01-02"}' => '{"day":"2024-01-02"}',
            '{"dawn":"2024-01-02"}' => '{"dawn":"2024-01-02"}',
        ];
        // Only the key the payload sent: an absent nullable property is written as `null` by some modes.
        $sentKey = static function (string $written, string $json): string {
            $key = (string)array_key_first((array)json_decode($json, true));
            $decoded = json_decode($written, true);

            return is_array($decoded) && array_key_exists($key, $decoded) ? (string)json_encode([$key => $decoded[$key]]) : $written;
        };
        foreach ($writtenBack as $json => $expected) {
            $this->assertSame(
                expected: $expected,
                actual: $sentKey($this->runtimeRoundTrip($spec, 'date-time inside a union, written back', $json), $json),
                message: 'runtime ' . $json,
            );
            foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
                $this->assertSame(
                    expected: $expected,
                    actual: $sentKey($this->writtenBack($mode, $spec, 'date-time inside a union, written back', $json), $json),
                    message: $mode->value . ' ' . $json,
                );
            }
        }

        // Runtime reads RFC 3339's lower case as the same instant the upper case spells, and writes it back
        // the same way.
        $lowercaseWrittenBack = [
            '{"plain":"2024-01-02t10:00:00z"}' => '{"plain":"2024-01-02T10:00:00+00:00"}',
            '{"one":"2024-01-02t10:00:00+02:00"}' => '{"one":"2024-01-02T10:00:00+02:00"}',
            '{"pair":"2024-01-02T10:00:00.5z"}' => '{"pair":"2024-01-02T10:00:00.500000+00:00"}',
        ];
        foreach ($lowercaseWrittenBack as $json => $expected) {
            $this->assertSame(
                expected: $expected,
                actual: $sentKey($this->runtimeRoundTrip($spec, 'date-time inside a union, written back', $json), $json),
                message: 'runtime ' . $json,
            );
        }
    }

    #[DataProvider('dateOrDateTimeUnionCases')]
    public function testADateOrDateTimeUnionAcceptsBothShapesInEveryMode(
        string $firstFormat,
        string $secondFormat,
        string $values,
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        [$validValue, $invalidValue] = explode('|', $values);
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['f'],
                        'properties' => [
                            'f' => [
                                'nullable' => true,
                                'oneOf' => [
                                    ['type' => 'string', 'format' => $firstFormat],
                                    ['type' => 'string', 'format' => $secondFormat],
                                ],
                            ],
                        ],
                    ],
                ],
            ],
        ];

        $key = "date|date-time {$firstFormat} first, {$validValue} / {$invalidValue}";
        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict(
                mode: $mode,
                spec: $spec,
                key: $key,
                validJson: '{"f":' . $validValue . '}',
                invalidJson: '{"f":' . $invalidValue . '}',
            ),
            diverges: $invalidValue === '"2026-02-30"'
                ? self::diverges(
                    mode: GenerationMode::Symfony,
                    expected: ['valid' => true, 'invalid' => true],
                    reason: 'the serializer parses the date before any generated constraint runs, and PHP rolls '
                        . '2026-02-30 over to 2 March — as for a plain `format: date`',
                )
                : [],
            context: $key,
        );
    }

    /**
     * A `oneOf` of a `format: date` string and a `format: date-time` string is ONE getter returning
     * `?DateTimeImmutable`, and both wire shapes belong to it. Runtime used to read only a top-level
     * `format`, found none, fell back to strict date-time and refused `"2026-12-01"` before the `oneOf`
     * was ever consulted — whichever order the branches came in.
     *
     * @return array<string, array{string, string, string}>
     */
    public static function dateOrDateTimeUnionCases(): array
    {
        $provided = [];
        foreach (['date first' => ['date', 'date-time'], 'date-time first' => ['date-time', 'date']] as $order => $formats) {
            foreach ([
                'date' => '"2026-12-01"',
                'date-time' => '"2026-12-01T10:00:00+00:00"',
                'Z date-time' => '"2026-12-01T10:00:00Z"',
                'midnight date-time' => '"2026-12-01T00:00:00Z"',
            ] as $shape => $validValue) {
                foreach ([
                    'impossible date' => '"2026-02-30"',
                    'garbage' => '"not a date"',
                    'empty' => '""',
                ] as $invalidShape => $invalidValue) {
                    $provided["{$order}, {$shape} / {$invalidShape}"] = [$formats[0], $formats[1], $validValue . '|' . $invalidValue];
                }
            }
        }

        return $provided;
    }

    /**
     * An impossible calendar date under a plain `format: date`. Symfony mode's serializer parses the string
     * before any generated constraint runs, and PHP's date parsing rolls an overflowing day forward instead
     * of failing — the same serializer-decides-first gap as the loose date-time above, found while pinning
     * the date-or-date-time union. Read as `!Y-m-d` (2.15.160), an overflowing MONTH rolls over as well.
     */
    public function testAnImpossibleCalendarDateIsRefusedWhereverTheGeneratorOwnsTheCheck(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['f'],
                        'properties' => ['f' => ['type' => 'string', 'format' => 'date']],
                    ],
                ],
            ],
        ];

        $key = 'impossible calendar date';
        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, $key, '{"f":"2026-12-01"}', '{"f":"2026-02-30"}'),
            diverges: self::diverges(
                mode: GenerationMode::Symfony,
                expected: ['valid' => true, 'invalid' => true],
                reason: 'the serializer parses the date before any generated constraint runs, and PHP rolls '
                    . '2026-02-30 over to 2 March',
            ),
            context: $key,
        );
        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, $key . ' month', '{"f":"2026-12-01"}', '{"f":"2026-13-45"}'),
            diverges: self::diverges(
                mode: GenerationMode::Symfony,
                expected: ['valid' => true, 'invalid' => true],
                reason: 'the serializer reads the date as `!Y-m-d` before any generated constraint runs, and PHP '
                    . 'rolls 2026-13-45 over to 14 February 2027',
            ),
            context: $key . ' month',
        );
    }

    /**
     * MUTUAL recursion — `A.b` is a `B` and `B.a` is an `A` — which is where a per-class fold could have
     * looped forever while being built. It terminates because the fold is registered under its class name
     * before it is computed, and the marker branch finds the key already there.
     */
    public function testMutuallyRecursiveSchemasAreEnforcedInEveryMode(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'required' => ['f'],
                        'properties' => ['f' => ['$ref' => '#/components/schemas/A']],
                    ],
                    'A' => [
                        'type' => 'object',
                        'required' => ['aid'],
                        'properties' => [
                            'aid' => ['type' => 'integer', 'minimum' => 1],
                            'b' => ['$ref' => '#/components/schemas/B'],
                        ],
                    ],
                    'B' => [
                        'type' => 'object',
                        'required' => ['bid'],
                        'properties' => [
                            'bid' => ['type' => 'integer', 'minimum' => 10],
                            'a' => ['$ref' => '#/components/schemas/A'],
                        ],
                    ],
                ],
            ],
        ];

        $valid = '{"f":{"aid":1,"b":{"bid":10,"a":{"aid":2,"b":{"bid":11}}}}}';

        // The violation sits three hops in, past two turns of the A -> B -> A cycle.
        $invalid = '{"f":{"aid":1,"b":{"bid":10,"a":{"aid":2,"b":{"bid":9}}}}}';

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict($mode, $spec, 'mutual', $valid, $invalid),
            context: 'mutual recursion',
        );
    }

    /**
     * `required` binds a property of the whole object, wherever the `allOf` declares it: a `required`
     * in one branch, or beside the `allOf`, names a property another branch — often the `$ref` parent —
     * declares. Only the outer list was read, and only for the branches merged into the class, so an
     * inherited property stayed optional and `{}` went through. Every spelling of the same object must
     * refuse it; the last two pin the requirements that already held, so the fix cannot trade one for
     * the other.
     *
     * @param array<string, array<string, mixed>> $schemas
     */
    #[DataProvider('crossBranchRequiredProvider')]
    public function testARequiredNameBindsAPropertyAnotherAllOfBranchDeclares(array $schemas, string $validJson, string $invalidJson): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => $schemas],
        ];
        $key = 'cross-branch required ' . md5((string)json_encode($schemas));

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict(
                mode: $mode,
                spec: $spec,
                key: $key,
                validJson: $validJson,
                invalidJson: $invalidJson,
            ),
            context: $key,
        );
    }

    /**
     * @return iterable<string, array{array<string, array<string, mixed>>, string, string}>
     */
    public static function crossBranchRequiredProvider(): iterable
    {
        $base = ['type' => 'object', 'properties' => ['name' => ['type' => 'string'], 'size' => ['type' => 'integer']]];
        $ref = ['$ref' => '#/components/schemas/Base'];
        $extra = ['extra' => ['type' => 'boolean']];

        yield 'a branch of required alone' => [['Base' => $base, 'Probe' => ['allOf' => [$ref, ['required' => ['name']]]]], '{"name":"a"}', '{}'];
        yield 'a typed branch of required alone' => [['Base' => $base, 'Probe' => ['allOf' => [$ref, ['type' => 'object', 'required' => ['name']]]]], '{"name":"a"}', '{"size":1}'];
        yield 'a branch with properties of its own' => [['Base' => $base, 'Probe' => ['allOf' => [$ref, ['type' => 'object', 'required' => ['name'], 'properties' => $extra]]]], '{"name":"a","extra":true}', '{"extra":true}'];
        yield 'beside the allOf' => [['Base' => $base, 'Probe' => ['required' => ['name'], 'allOf' => [$ref]]], '{"name":"a"}', '{}'];
        yield 'beside an allOf with a branch' => [['Base' => $base, 'Probe' => ['required' => ['name'], 'allOf' => [$ref, ['type' => 'object', 'properties' => $extra]]]], '{"name":"a"}', '{"extra":true}'];
        yield 'two inline branches' => [['Probe' => ['allOf' => [$base, ['required' => ['name']]]]], '{"name":"a"}', '{}'];
        // Two `$ref`s are merged rather than inherited, which is the other path a class is built by.
        yield 'two merged parents' => [
            [
                'Base' => $base,
                'Tagged' => ['type' => 'object', 'properties' => ['tag' => ['type' => 'string']]],
                'Probe' => ['allOf' => [$ref, ['$ref' => '#/components/schemas/Tagged'], ['required' => ['name', 'tag']]]],
            ],
            '{"name":"a","tag":"b"}',
            '{"name":"a"}',
        ];
        yield 'a grandparent property' => [
            [
                'Base' => $base,
                'Middle' => ['allOf' => [$ref, ['type' => 'object', 'properties' => $extra]]],
                'Probe' => ['allOf' => [['$ref' => '#/components/schemas/Middle'], ['required' => ['name']]]],
            ],
            '{"name":"a"}',
            '{"extra":true}',
        ];
        yield 'control: required in the parent' => [
            ['Base' => [...$base, 'required' => ['name']], 'Probe' => ['allOf' => [$ref, ['type' => 'object', 'properties' => $extra]]]],
            '{"name":"a"}',
            '{"extra":true}',
        ];
        yield 'control: required on the branch\'s own property' => [
            ['Base' => $base, 'Probe' => ['allOf' => [$ref, ['type' => 'object', 'required' => ['extra'], 'properties' => $extra]]]],
            '{"extra":true}',
            '{"name":"a"}',
        ];
    }

    /**
     * A branch that restates a property the parent declares narrows it: under `allOf` both schemas hold,
     * so the parent's `required`, `maxLength`, `enum` and type stay in force beside the branch's own
     * `minLength`. Symfony and both Laravel modes let the branch REPLACE the parent's rules, and runtime
     * refused to generate the document at all ("Property override conflict … parent type string, child
     * type ?string") although nothing in it conflicts.
     *
     * @param array<string, mixed> $restated the branch's schema for `name`
     */
    #[DataProvider('restatedPropertyProvider')]
    public function testABranchRestatingAParentPropertyKeepsTheParentsRules(string $shape, array $restated, string $invalidJson): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        // `tag` is required so that an unknown value fails in yii3 too: there an OPTIONAL enum the
        // hydrator cannot fill is left unset and passes as absent — a gap of its own, outside `allOf`.
        $base = [
            'type' => 'object',
            'required' => ['name', 'tag'],
            'properties' => [
                'name' => ['type' => 'string', 'maxLength' => 3, 'pattern' => '^[a-z]+$'],
                'tag' => ['type' => 'string', 'enum' => ['a', 'b']],
            ],
        ];
        $branch = ['type' => 'object', 'properties' => ['name' => $restated, 'tag' => ['type' => 'string'], 'flag' => ['type' => 'boolean']]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => match ($shape) {
                'inherited' => ['Base' => $base, 'Probe' => ['allOf' => [['$ref' => '#/components/schemas/Base'], $branch]]],
                // Two `$ref`s are merged into one class instead of inherited; the restatement is the same.
                'merged' => [
                    'Base' => $base,
                    'Other' => ['type' => 'object', 'properties' => ['flag' => ['type' => 'boolean']]],
                    'Probe' => ['allOf' => [['$ref' => '#/components/schemas/Base'], ['$ref' => '#/components/schemas/Other'], $branch]],
                ],
                'inline' => ['Probe' => ['allOf' => [$base, $branch]]],
            }],
        ];
        $key = 'restated ' . $shape . ' ' . json_encode($restated) . ' ' . $invalidJson;

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict(
                mode: $mode,
                spec: $spec,
                key: $key,
                validJson: '{"name":"ab","tag":"a","flag":true}',
                invalidJson: $invalidJson,
            ),
            context: $key,
        );
    }

    /**
     * @return iterable<string, array{string, array<string, mixed>, string}>
     */
    public static function restatedPropertyProvider(): iterable
    {
        $invalid = [
            'the parent\'s required' => '{"tag":"a","flag":true}',
            'the parent\'s maxLength' => '{"name":"abcd","tag":"a"}',
            'the branch\'s minLength' => '{"name":"a","tag":"a"}',
            'the parent\'s enum' => '{"name":"ab","tag":"zzz"}',
            'the parent\'s pattern' => '{"name":"AB","tag":"a"}',
        ];
        foreach (['inherited', 'merged', 'inline'] as $shape) {
            foreach (['typed' => ['type' => 'string', 'minLength' => 2], 'untyped' => ['minLength' => 2]] as $spelling => $restated) {
                foreach ($invalid as $rule => $json) {
                    yield $shape . ' ' . $spelling . ': ' . $rule => [$shape, $restated, $json];
                }
            }
            yield $shape . ' untyped: the parent\'s type' => [$shape, ['minLength' => 2], '{"name":12345,"tag":"a"}'];
            // The same keyword on both sides: neither value replaces the other, the stricter one decides.
            yield $shape . ' looser maxLength: the parent\'s' => [$shape, ['type' => 'string', 'maxLength' => 5], '{"name":"abcd","tag":"a"}'];
            yield $shape . ' tighter maxLength: the branch\'s' => [$shape, ['type' => 'string', 'maxLength' => 2], '{"name":"abc","tag":"a"}'];
            // Two patterns have no stricter one; both are kept and both must match.
            yield $shape . ' second pattern: the branch\'s' => [$shape, ['type' => 'string', 'pattern' => '^a'], '{"name":"bc","tag":"a"}'];
            yield $shape . ' second pattern: the parent\'s' => [$shape, ['type' => 'string', 'pattern' => '^a'], '{"name":"aB","tag":"a"}'];
        }
    }

    /**
     * The OAS polymorphism pattern: a base with a `discriminator` and no `mapping`, its variants each
     * `allOf` it. The implicit value is each variant's schema name, as for a `oneOf` of `$ref`s — but
     * the implicit map was built only from the base's own union members, which an `allOf` base does not
     * have, and generation stopped with "Discriminator mapping must be a non-empty map". The explicit
     * mapping is the control: the same document, spelled out, must give the same verdicts.
     *
     * @param string $invalidJson a payload the variant the discriminator names refuses
     */
    #[DataProvider('implicitAllOfDiscriminatorProvider')]
    public function testAnAllOfBaseWithoutMappingSelectsItsVariantsByName(bool $explicit, string $validJson, string $invalidJson): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => self::animalSchemas($explicit) + [
                'Probe' => ['type' => 'object', 'required' => ['pet'], 'properties' => ['pet' => ['$ref' => '#/components/schemas/Animal']]],
            ]],
        ];
        $key = 'allOf discriminator ' . ($explicit ? 'explicit' : 'implicit') . ' ' . $invalidJson;

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict(
                mode: $mode,
                spec: $spec,
                key: $key,
                validJson: $validJson,
                invalidJson: $invalidJson,
            ),
            context: $key,
        );
    }

    /**
     * @return iterable<string, array{bool, string, string}>
     */
    public static function implicitAllOfDiscriminatorProvider(): iterable
    {
        foreach (['explicit mapping' => true, 'no mapping' => false] as $spelling => $explicit) {
            yield $spelling . ': a cat' => [$explicit, '{"pet":{"kind":"Cat","name":"Tom","purr":true}}', '{"pet":{"kind":"Cat","purr":"loud"}}'];
            yield $spelling . ': a dog' => [$explicit, '{"pet":{"kind":"Dog","bark":true}}', '{"pet":{"kind":"Dog","bark":"loud"}}'];
            yield $spelling . ': the base\'s own rule' => [$explicit, '{"pet":{"kind":"Cat","name":"Tom"}}', '{"pet":{"kind":"Cat","name":5}}'];
        }
    }

    /**
     * The OAS `Pet`/`Cat`/`Dog` shape, with or without the mapping it implies.
     *
     * @return array<string, array<string, mixed>>
     */
    private static function animalSchemas(bool $explicitMapping): array
    {
        $discriminator = ['propertyName' => 'kind'];
        if ($explicitMapping) {
            $discriminator['mapping'] = ['Cat' => '#/components/schemas/Cat', 'Dog' => '#/components/schemas/Dog'];
        }

        return [
            'Animal' => [
                'type' => 'object',
                'required' => ['kind'],
                'properties' => ['kind' => ['type' => 'string'], 'name' => ['type' => 'string']],
                'discriminator' => $discriminator,
            ],
            'Cat' => ['allOf' => [['$ref' => '#/components/schemas/Animal'], ['type' => 'object', 'properties' => ['purr' => ['type' => 'boolean']]]]],
            'Dog' => ['allOf' => [['$ref' => '#/components/schemas/Animal'], ['type' => 'object', 'properties' => ['bark' => ['type' => 'boolean']]]]],
        ];
    }

    /**
     * A property whose union names generated classes holds one of them once it is read, and that
     * object's own rules are checked by the object, not by the property. Symfony looked for a single
     * class name in `Alpha|Beta`, found none, and left the `#[Assert\Valid]` cascade off, so `{"a":"x"}`
     * went through against `minLength: 2` while runtime refused it. The list and the map of the same
     * union already held — they are pinned beside it so the fix cannot trade one for the other.
     *
     * @param array<string, mixed> $property the schema of `f`
     * @param array<int, string> $invalidJsons
     */
    #[DataProvider('unionOfClassesProvider')]
    public function testAUnionOfClassesChecksTheBranchItHolds(array $property, string $validJson, array $invalidJsons): void
    {
        $spec = self::probeSpec($property);
        $spec['components']['schemas'] += self::unionMemberSchemas();

        $this->assertHydratingModesRefuse(spec: $spec, key: 'union of classes ' . md5((string)json_encode($property)), validJsons: [$validJson], invalidJsons: $invalidJsons);
    }

    /**
     * @return iterable<string, array{array<string, mixed>, string, array<int, string>}>
     */
    public static function unionOfClassesProvider(): iterable
    {
        $alpha = ['$ref' => '#/components/schemas/Alpha'];
        $beta = ['$ref' => '#/components/schemas/Beta'];

        foreach (['oneOf', 'anyOf'] as $keyword) {
            yield $keyword . ' of two classes' => [[$keyword => [$alpha, $beta]], '{"f":{"a":"xy"}}', ['{"f":{"a":"x"}}', '{"f":{"b":5}}']];
            yield $keyword . ' of two classes or null' => [[$keyword => [$alpha, $beta, ['type' => 'null']]], '{"f":null}', ['{"f":{"a":"x"}}', '{"f":{"b":5}}']];
            yield $keyword . ' of classes in a list' => [['type' => 'array', 'items' => [$keyword => [$alpha, $beta]]], '{"f":[{"b":11}]}', ['{"f":[{"a":"x"}]}', '{"f":[{"b":5}]}']];
        }
        yield 'a discriminated oneOf' => [
            ['oneOf' => [$alpha, $beta], 'discriminator' => ['propertyName' => 'kind', 'mapping' => ['alpha' => '#/components/schemas/Alpha', 'beta' => '#/components/schemas/Beta']]],
            '{"f":{"kind":"beta","b":11}}',
            ['{"f":{"kind":"alpha","a":"x"}}', '{"f":{"kind":"beta","b":5}}'],
        ];
        yield 'control: a single class' => [$alpha, '{"f":{"a":"xy"}}', ['{"f":{"a":"x"}}']];
    }

    /**
     * A union of scalar branches beside a class branch. The class branch extracted to nothing, and an
     * `anyOf` holding a branch the validator cannot read is dropped whole — so the scalar bounds went
     * with it, and `"abcd"` passed `maxLength: 3` in Symfony and in runtime, for `oneOf` as well there.
     * Every branch keeps its rules now: the scalar ones are checked as values, the class one as "is that
     * class", which checked itself — by its cascade in Symfony, while it was hydrated in runtime.
     *
     * @param array<int, string> $invalidJsons
     * @param array<int, GenerationMode> $modes
     */
    #[DataProvider('scalarBesideClassProvider')]
    public function testScalarBranchesBesideAClassBranchKeepTheirRules(string $keyword, array $invalidJsons, array $modes): void
    {
        $spec = self::probeSpec([$keyword => [
            ['type' => 'string', 'maxLength' => 3],
            ['type' => 'integer', 'minimum' => 5],
            ['$ref' => '#/components/schemas/Alpha'],
        ]]);
        $spec['components']['schemas'] += self::unionMemberSchemas();

        $this->assertHydratingModesRefuse(
            spec: $spec,
            key: 'scalar beside class ' . $keyword,
            validJsons: ['{"f":"ab"}', '{"f":7}', '{"f":{"a":"xy"}}'],
            invalidJsons: $invalidJsons,
            modes: $modes,
        );
    }

    /**
     * @return iterable<string, array{string, array<int, string>, array<int, GenerationMode>}>
     */
    public static function scalarBesideClassProvider(): iterable
    {
        foreach (['anyOf', 'oneOf'] as $keyword) {
            yield $keyword . ': the class branch' => [$keyword, ['{"f":{"a":"x"}}'], [GenerationMode::Runtime, GenerationMode::Symfony]];
            yield $keyword . ': the scalar branches' => [$keyword, ['{"f":"abcd"}', '{"f":1}'], [GenerationMode::Runtime, GenerationMode::Symfony]];
        }
    }

    /**
     * The same union one level down, where the class branch meets a value the runtime validator sees
     * in two states. As a list item it is hydrated, so the class is judged like the property above. As
     * a key the schema does not declare it stays the raw payload, which cannot be told from the class:
     * the union is then not judged for an object, and a scalar is still held to the scalar branches.
     *
     * @param array<string, mixed> $propertySchema
     * @param array<int, string> $validJsons
     * @param array<int, string> $invalidJsons
     */
    #[DataProvider('classBranchBelowThePropertyProvider')]
    public function testClassBranchBelowThePropertyKeepsTheScalarRules(array $propertySchema, array $validJsons, array $invalidJsons): void
    {
        $spec = self::probeSpec($propertySchema);
        $spec['components']['schemas'] += self::unionMemberSchemas();

        $this->assertHydratingModesRefuse(
            spec: $spec,
            key: 'class branch below ' . md5((string)json_encode($propertySchema)),
            validJsons: $validJsons,
            invalidJsons: $invalidJsons,
            modes: [GenerationMode::Runtime],
        );
    }

    /**
     * @return iterable<string, array{array<string, mixed>, array<int, string>, array<int, string>}>
     */
    public static function classBranchBelowThePropertyProvider(): iterable
    {
        $union = static fn(string $keyword): array => [$keyword => [
            ['type' => 'string', 'maxLength' => 3],
            ['$ref' => '#/components/schemas/Alpha'],
        ]];
        foreach (['anyOf', 'oneOf'] as $keyword) {
            yield $keyword . ': list items' => [
                ['type' => 'array', 'items' => $union($keyword)],
                ['{"f":["ab",{"a":"xy"}]}'],
                ['{"f":["abcd"]}', '{"f":[{"a":"x"}]}'],
            ];
            yield $keyword . ': map values' => [
                ['type' => 'object', 'additionalProperties' => $union($keyword)],
                ['{"f":{"x":"ab","y":{"a":"xy"}}}'],
                ['{"f":{"x":"abcd"}}'],
            ];
        }
    }

    /**
     * A string enum beside a string branch the enum's own values do not satisfy: `red` is the enum's,
     * `123` the pattern's. Runtime holds the enum as a case, and the string branch took the case for a
     * string while skipping its `pattern` — `red` matched two `oneOf` branches and was refused.
     *
     * @param array<string, mixed> $stringBranch
     */
    #[DataProvider('enumBesideAConstrainedStringProvider')]
    public function testAnEnumCaseIsJudgedByItsValueInAStringBranch(
        string $keyword,
        array $stringBranch,
        string $validJson,
        string $invalidJson,
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec([$keyword => [
            ['$ref' => '#/components/schemas/Tint'],
            $stringBranch,
            ['type' => 'integer'],
        ]]);
        $spec['components']['schemas']['Tint'] = ['type' => 'string', 'enum' => ['red', 'blue']];
        $key = sprintf('enum beside a string branch %s %s %s', $keyword, json_encode($stringBranch), $validJson);

        $this->assertEveryModeYields(
            expected: ['valid' => true, 'invalid' => false],
            observe: fn(GenerationMode $mode): array => $this->verdict(
                mode: $mode,
                spec: $spec,
                key: $key,
                validJson: $validJson,
                invalidJson: $invalidJson,
            ),
            context: $key,
        );
    }

    /**
     * @return iterable<string, array{string, array<string, mixed>, string, string}>
     */
    public static function enumBesideAConstrainedStringProvider(): iterable
    {
        $digits = ['type' => 'string', 'pattern' => '^\d+$'];
        foreach (['oneOf', 'anyOf'] as $keyword) {
            yield $keyword . ': the enum, pattern' => [$keyword, $digits, '{"f":"red"}', '{"f":"abc"}'];
            yield $keyword . ': the other case, pattern' => [$keyword, $digits, '{"f":"blue"}', '{"f":true}'];
            yield $keyword . ': the pattern' => [$keyword, $digits, '{"f":"123"}', '{"f":"12a"}'];
            yield $keyword . ': the integer' => [$keyword, $digits, '{"f":42}', '{"f":null}'];
            yield $keyword . ': the enum, length' => [$keyword, ['type' => 'string', 'minLength' => 5], '{"f":"blue"}', '{"f":"abc"}'];
            yield $keyword . ': the string, length' => [$keyword, ['type' => 'string', 'minLength' => 5], '{"f":"longer"}', '{"f":"abcd"}'];
        }
    }

    /**
     * A `$ref` to an enum beside a scalar branch. Runtime hydrates the enum, so the class branch holds
     * the case and the scalar branch the integer; a wire value that is neither is refused.
     */
    #[DataProvider('enumBranchBesideScalarProvider')]
    public function testEnumBranchBesideAScalarBranchKeepsBoth(string $keyword): void
    {
        $spec = self::probeSpec([$keyword => [
            ['$ref' => '#/components/schemas/Hue'],
            ['type' => 'integer', 'minimum' => 5],
        ]]);
        $spec['components']['schemas']['Hue'] = ['type' => 'string', 'enum' => ['red', 'teal']];

        $this->assertHydratingModesRefuse(
            spec: $spec,
            key: 'enum beside scalar ' . $keyword,
            validJsons: ['{"f":"red"}', '{"f":7}'],
            invalidJsons: ['{"f":"blue"}', '{"f":1}'],
            // Symfony dropped the whole `anyOf` once and accepted `1`: its branch builder knew a DTO
            // branch but not an enum one. laravel-data accepted `"blue"` in both spellings: its enum
            // branch was checked as a string and nothing more.
            modes: GenerationMode::cases(),
        );
    }

    /**
     * The mirror image of the case above, and its optional spelling: an integer-backed enum beside a
     * string branch, and a string-backed one on a property that may be absent. laravel-data's constructor
     * declared the union as the document spelled it, without the enum's backing type, so a member value
     * was a TypeError before the constructor could turn it into the case.
     */
    #[DataProvider('enumBranchBesideScalarProvider')]
    public function testEnumBranchOfEitherBackingKeepsBoth(string $keyword): void
    {
        $spec = self::probeSpec([$keyword => [
            ['$ref' => '#/components/schemas/Level'],
            ['type' => 'string', 'maxLength' => 3],
        ]]);
        $spec['components']['schemas']['Level'] = ['type' => 'integer', 'enum' => [10, 20]];
        $spec['components']['schemas']['Probe']['properties']['g'] = [$keyword => [
            ['$ref' => '#/components/schemas/Hue'],
            ['type' => 'integer', 'minimum' => 5],
        ]];
        $spec['components']['schemas']['Hue'] = ['type' => 'string', 'enum' => ['red', 'teal']];

        $this->assertHydratingModesRefuse(
            spec: $spec,
            key: 'enum of either backing ' . $keyword,
            validJsons: ['{"f":20}', '{"f":"ab"}', '{"f":10,"g":"teal"}', '{"f":"ab","g":9}'],
            invalidJsons: ['{"f":30}', '{"f":"abcd"}', '{"f":10,"g":"blue"}', '{"f":10,"g":2}'],
            modes: GenerationMode::cases(),
        );
    }

    /**
     * @return iterable<string, array{string}>
     */
    public static function enumBranchBesideScalarProvider(): iterable
    {
        yield 'anyOf' => ['anyOf'];
        yield 'oneOf' => ['oneOf'];
    }

    /**
     * A union of ONE object branch and a scalar branch, with no discriminator. The object is a class
     * (a `$ref`) or an inline shape, and either way the verdict must be the schema's: laravel typed the
     * constructor `Shade|string` and handed it the validated array, a TypeError on every valid object;
     * laravel-data checked the object's `required` on a string; symfony asked `Type('array')` of the
     * hydrated class and lost the string to the class; yii3 checked nothing. The list branch beside a
     * boolean is the same question one keyword over: its items are part of the branch.
     *
     * @param array<string, mixed> $property the schema of `f`
     * @param array<int, string> $validJsons
     * @param array<int, string> $invalidJsons
     * @param array<string, array<int, string>> $frameworkDecides payloads a mode's framework judges before
     *     any generated check runs, keyed by mode — not measured there; README.support-matrix has the rows
     */
    #[DataProvider('objectBesideScalarProvider')]
    public function testAnObjectBranchBesideAScalarBranchIsJudgedByTheBranchItMatches(
        array $property,
        array $validJsons,
        array $invalidJsons,
        array $frameworkDecides = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec($property);
        $spec['components']['schemas']['Shade'] = ['type' => 'object', 'required' => ['hue'], 'properties' => ['hue' => ['type' => 'string']]];
        $spec['components']['schemas']['Loose'] = ['type' => 'object', 'properties' => ['hue' => ['type' => 'string']]];
        $key = 'object beside scalar ' . md5((string)json_encode($property));

        $expected = array_fill_keys($validJsons, true) + array_fill_keys($invalidJsons, false);
        $this->assertEveryModeYields(
            expected: $expected,
            observe: function (GenerationMode $mode) use ($spec, $key, $expected, $frameworkDecides): array {
                $observed = [];
                foreach ($expected as $json => $verdict) {
                    $observed[$json] = in_array($json, $frameworkDecides[$mode->value] ?? [], true)
                        ? $verdict
                        : $this->verdict(mode: $mode, spec: $spec, key: $key, validJson: $json, invalidJson: $json)['valid'];
                }

                return $observed;
            },
            context: $key,
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<int, string>, 2: array<int, string>, 3?: array<string, array<int, string>>}>
     */
    public static function objectBesideScalarProvider(): iterable
    {
        $shade = ['$ref' => '#/components/schemas/Shade'];
        $loose = ['$ref' => '#/components/schemas/Loose'];
        $inline = ['type' => 'object', 'required' => ['k'], 'properties' => ['k' => ['type' => 'integer']]];

        foreach (['anyOf', 'oneOf'] as $keyword) {
            yield $keyword . ': a class or a string' => [
                [$keyword => [$shade, ['type' => 'string']]],
                ['{"f":{"hue":"x"}}', '{"f":"ok"}'],
                ['{"f":5}', '{"f":true}', '{"f":[1]}', '{"f":{}}', '{"f":{"hue":5}}'],
            ];
            // A class nothing in it requires can be built from anything. Symfony's serializer tries the
            // class member first and, on 7.4.10, builds it from a scalar as well ("a scalar for a property
            // typed as a generated class"); newer releases refuse the scalar and fall through to the
            // string. A non-empty JSON list is the decoded `{"0":1}` once the framework has decoded it
            // ("a JSON array for a `type: object` property").
            yield $keyword . ': a class with nothing required or a string' => [
                [$keyword => [$loose, ['type' => 'string']]],
                ['{"f":{"hue":"x"}}', '{"f":{}}', '{"f":"ok"}'],
                ['{"f":5}', '{"f":true}', '{"f":[1]}', '{"f":{"hue":5}}'],
                [
                    GenerationMode::Symfony->value => ['{"f":5}', '{"f":true}', '{"f":[1]}'],
                    GenerationMode::Yii3->value => ['{"f":[1]}'],
                ],
            ];
            yield $keyword . ': a class or an integer' => [
                [$keyword => [$shade, ['type' => 'integer']]],
                ['{"f":{"hue":"x"}}', '{"f":3}'],
                ['{"f":"x"}', '{"f":{}}', '{"f":true}'],
            ];
            yield $keyword . ': an inline object or a string' => [
                [$keyword => [$inline, ['type' => 'string']]],
                ['{"f":{"k":1}}', '{"f":"s"}'],
                ['{"f":5}', '{"f":{}}', '{"f":{"k":"x"}}', '{"f":true}'],
            ];
            yield $keyword . ': a list of integers or a boolean' => [
                [$keyword => [['type' => 'array', 'items' => ['type' => 'integer']], ['type' => 'boolean']]],
                ['{"f":[1,2]}', '{"f":[]}', '{"f":true}'],
                ['{"f":["x"]}', '{"f":"x"}', '{"f":5}'],
            ];
        }
    }

    /**
     * A component named after a class the referring file names for something else — Symfony's
     * `Context`, Laravel's `Validator`, PHP's `BackedEnum`. Both meanings sit in Probe's file, and the
     * component's own file declares the name: either the import won and the component's type was the
     * library's, or the component's file did not load. Validated and hydrated in every mode, it must
     * behave as the same component under a neutral name does.
     */
    #[DataProvider('libraryClassNameProvider')]
    public function testAComponentNamedAfterALibraryClassValidates(string $component): void
    {
        $spec = self::probeSpec(['$ref' => '#/components/schemas/' . $component]);
        $spec['components']['schemas']['Probe']['properties']['at'] = ['type' => 'string', 'format' => 'date-time'];
        $spec['components']['schemas']['Probe']['minProperties'] = 1;
        $spec['components']['schemas'][$component] = [
            'type' => 'object',
            'required' => ['at'],
            'properties' => [
                'at' => ['type' => 'string', 'format' => 'date-time'],
                'first_name' => ['type' => 'string', 'minLength' => 2],
                'tone' => ['type' => 'string', 'enum' => ['red', 'teal']],
            ],
        ];

        $this->assertHydratingModesRefuse(
            spec: $spec,
            key: 'library class name ' . $component,
            validJsons: ['{"f":{"at":"2026-03-10T12:00:00+00:00","first_name":"Ann","tone":"teal"},"at":"2026-03-10T12:00:00+03:00"}'],
            invalidJsons: [
                '{"f":{"at":"later"}}',
                '{"f":{"at":"2026-03-10T12:00:00+00:00","first_name":"A"}}',
                '{"f":{"at":"2026-03-10T12:00:00+00:00","tone":"blue"}}',
                '{"f":{"at":"2026-03-10T12:00:00+00:00"},"at":"later"}',
            ],
