                ]) + ['Cat' => $cat, 'Dog' => $dog],
                [
                    '{}' => true,
                    '{"pet":{"kind":"cat"}}' => true,
                    '{"pet":{"kind":"dog"}}' => true,
                    '{"pet":null}' => true,
                    '{"pet":{"kind":"cow"}}' => false,
                    '{"pet":7}' => false,
                    '{"den":{"pet":{"kind":"cat"}}}' => true,
