                ] + $probe(['owl' => ['anyOf' => [['type' => 'boolean'], $ref('Olive')]]]),
                [
                    '{}' => true,
                    '{"owl":true}' => true,
                    '{"owl":{"egret":2}}' => true,
                    '{"owl":{"egret":5}}' => false,
                    '{"owl":{"lynx":5}}' => false,
                    '{"owl":{"lynx":null}}' => false,
