    /**
     * The integer alias inside `oneOf: [{anyOf: [$ref Count, {type: string}]}, null]` stays an integer:
     * typed by the class `Count` that is never written, the value was refused — and with the class
     * gone but the type left a bare `string`, it would come back as `"5"`.
     */
    public function testAScalarAliasInANestedUnionKeepsItsJsonType(): void
    {
        $count = ['$ref' => '#/components/schemas/Count'];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'c' => ['oneOf' => [['anyOf' => [$count, ['type' => 'string']]], ['type' => 'null']]],
                    'a' => ['type' => 'object', 'additionalProperties' => ['anyOf' => [$count]]],
                ]],
                'Count' => ['type' => 'integer'],
            ]],
        ];

        $this->assertSame('{"c":5}', $this->runtimeRoundTrip($spec, 'nested alias int', '{"c":5}'));
        $this->assertSame('{"c":"5"}', $this->runtimeRoundTrip($spec, 'nested alias int', '{"c":"5"}'));
        $this->assertSame('{"a":{"k":1}}', $this->runtimeRoundTrip($spec, 'nested alias int', '{"a":{"k":1}}'));
    }

    /**
     * Discriminated unions whose variants spell the discriminator property as a one-value enum
     * (`kind: {type: string, enum: [circle]}`), listed inline on the property or behind a component, under
     * `oneOf` and `anyOf`, plus the plain-string spelling behind a component. The discriminator picks the
     * variant: a payload naming one variant is judged by that variant alone, a missing, unknown or
     * non-string tag is refused, and so are a non-object and `null` where the union is not nullable. No
     * payload may crash any mode.
     *
     * @param array<string, mixed> $propertySchema
     * @param array<string, array<string, mixed>> $components
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param bool $required whether `f` is required; an optional one may be left out, but not sent as `null`
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise,
     *     by the README.support-matrix divergence named beside the case
     * @param list<GenerationMode> $skippedModes modes a case does not measure, for the reason named beside it
     */
    #[DataProvider('discriminatedUnionShapeProvider')]
    public function testDiscriminatedUnionShapesValidateInEveryMode(
        string $openApiVersion,
        array $propertySchema,
        array $components,
        array $payloads,
        bool $required = true,
        array $diverging = [],
        array $skippedModes = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec($propertySchema);
        $spec['openapi'] = $openApiVersion;
        $spec['components']['schemas'] += $components;
        if (!$required) {
            $spec['components']['schemas']['Probe']['required'] = [];
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'discriminated shape ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
                skippedModes: $skippedModes,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, mixed>, 2: array<string, array<string, mixed>>, 3: array<string, bool>, 4?: bool, 5?: array<string, array<string, bool|null>>, 6?: list<GenerationMode>}>
     */
    public static function discriminatedUnionShapeProvider(): iterable
    {
        $variant = static fn(string $tag, string $field): array => [
            'type' => 'object',
            'required' => ['kind', $field],
            'properties' => ['kind' => ['type' => 'string', 'enum' => [$tag]], $field => ['type' => 'integer']],
        ];
        $enumTagged = ['Circle' => $variant('circle', 'r'), 'Oval' => $variant('oval', 'w')];
        $mapped = [
            'propertyName' => 'kind',
            'mapping' => ['circle' => '#/components/schemas/Circle', 'oval' => '#/components/schemas/Oval'],
        ];
        $branches = [['$ref' => '#/components/schemas/Circle'], ['$ref' => '#/components/schemas/Oval']];
        $payloads = [
            '{"f":{"kind":"circle","r":1}}' => true,
            '{"f":{"kind":"oval","w":2}}' => true,
            '{"f":{"kind":"circle"}}' => false,
            '{"f":{"kind":"oval","r":1}}' => false,
            '{"f":{"kind":"zz","r":1}}' => false,
            '{"f":{"kind":{"zz":1}}}' => false,
            '{"f":{"kind":5,"r":1}}' => false,
            '{"f":{}}' => false,
            '{"f":"zzq"}' => false,
            '{"f":null}' => false,
        ];

        foreach (['oneOf', 'anyOf'] as $keyword) {
            foreach (['3.0.3', '3.1.0'] as $version) {
                yield sprintf('inline %s, enum tags, mapped, %s', $keyword, $version) => [
                    $version,
                    [$keyword => $branches, 'discriminator' => $mapped],
                    $enumTagged,
                    $payloads,
                ];
            }
            yield sprintf('component %s, enum tags, mapped', $keyword) => [
                '3.1.0',
                ['$ref' => '#/components/schemas/Shape'],
                $enumTagged + ['Shape' => [$keyword => $branches, 'discriminator' => $mapped]],
                $payloads,
            ];
        }
        foreach (['3.0.3', '3.1.0'] as $version) {
            yield 'optional component oneOf, enum tags, implicit mapping, ' . $version => [
                $version,
                ['$ref' => '#/components/schemas/Shape'],
                [
                    'Circle' => $variant('Circle', 'r'),
                    'Oval' => $variant('Oval', 'w'),
                    'Shape' => ['oneOf' => $branches, 'discriminator' => ['propertyName' => 'kind']],
                ],
                ['{}' => true, '{"f":{"kind":"Oval","w":2}}' => true, '{"f":null}' => false, '{"f":{"kind":"Oval"}}' => false],
                false,
            ];
            yield 'optional component oneOf, enum tags, mapped, ' . $version => [
                $version,
                ['$ref' => '#/components/schemas/Shape'],
                $enumTagged + ['Shape' => ['oneOf' => $branches, 'discriminator' => $mapped]],
                ['{}' => true, '{"f":{"kind":"oval","w":2}}' => true, '{"f":null}' => false, '{"f":"zzq"}' => false],
                false,
            ];
        }
        yield 'optional component oneOf of an integer and an object, no discriminator' => [
            '3.1.0',
            ['$ref' => '#/components/schemas/Mark'],
            ['Mark' => ['oneOf' => [['type' => 'integer'], ['type' => 'object', 'required' => ['x'], 'properties' => ['x' => ['type' => 'integer']]]]]],
            ['{}' => true, '{"f":{"x":1}}' => true, '{"f":null}' => false],
            false,
        ];
        yield 'optional nullable component oneOf, enum tags, mapped' => [
            '3.1.0',
            ['anyOf' => [['$ref' => '#/components/schemas/Shape'], ['type' => 'null']]],
            $enumTagged + ['Shape' => ['oneOf' => $branches, 'discriminator' => $mapped]],
            ['{}' => true, '{"f":null}' => true, '{"f":{"kind":"oval","w":2}}' => true, '{"f":{"kind":"oval"}}' => false],
            false,
        ];

        $plain = static fn(string $field): array => [
            'type' => 'object',
            'required' => ['kind', $field],
            'properties' => ['kind' => ['type' => 'string'], $field => ['type' => 'integer']],
        ];
        // Deeper inline positions: an inline object's property and list items.
        yield 'inline oneOf inside an inline object, enum tags, mapped' => [
            '3.1.0',
            ['type' => 'object', 'required' => ['g'], 'properties' => ['g' => ['oneOf' => $branches, 'discriminator' => $mapped]]],
            $enumTagged,
            [
                '{"f":{"g":{"kind":"circle","r":1}}}' => true,
                '{"f":{"g":{"kind":"oval","w":2}}}' => true,
                '{"f":{"g":{"kind":"zzq","r":1}}}' => false,
                '{"f":{"g":{"kind":"circle"}}}' => false,
                '{"f":{"g":{"kind":{"zz":1}}}}' => false,
                '{"f":{"g":{}}}' => false,
            ],
        ];
        yield 'list of an inline anyOf, enum tags, mapped' => [
            '3.1.0',
            ['type' => 'array', 'items' => ['anyOf' => $branches, 'discriminator' => $mapped]],
            $enumTagged,
            [
                '{"f":[{"kind":"circle","r":1},{"kind":"oval","w":2}]}' => true,
                '{"f":[]}' => true,
                '{"f":[{"kind":"zzq","r":1}]}' => false,
                '{"f":[{"kind":"oval"}]}' => false,
                '{"f":[{"kind":{"zz":1}}]}' => false,
                '{"f":[null]}' => false,
            ],
        ];

        $plainTagged = ['Circle' => $plain('r'), 'Oval' => $plain('w')];
        foreach (['oneOf', 'anyOf'] as $keyword) {
            yield sprintf('inline %s, plain string tags, mapped', $keyword) => [
                '3.1.0',
                [$keyword => $branches, 'discriminator' => $mapped],
                $plainTagged,
                $payloads,
            ];
        }
        // LV-R3-7: members that require nothing but the tag OVERLAP — each takes the other's payload.
        $loose = static fn(string $field, string $type): array => [
            'type' => 'object',
            'required' => ['kind'],
            'properties' => ['kind' => ['type' => 'string'], $field => ['type' => $type]],
        ];
        yield 'inline oneOf, overlapping members, implicit mapping' => [
            '3.0.3',
            ['oneOf' => [['$ref' => '#/components/schemas/Cat'], ['$ref' => '#/components/schemas/Dog']], 'discriminator' => ['propertyName' => 'kind']],
            ['Cat' => $loose('claws', 'integer'), 'Dog' => $loose('bark', 'string')],
            [
                '{"f":{"kind":"Cat","claws":3}}' => true,
                '{"f":{"kind":"Dog","bark":"woof"}}' => true,
                // The tag names Dog, whose `bark` fails; the bare `oneOf` matches Cat alone, which
                // leaves `bark` alone. Refused where the discriminator dispatches (laravel and, since
                // 2.15.153, laravel-data), accepted where the branches are counted (runtime).
                '{"f":{"kind":"Dog","bark":5}}' => null,
                '{"f":{"kind":"Cat","claws":"x"}}' => null,
            ],
            true,
            ['laravel' => ['{"f":{"kind":"Dog","bark":5}}' => false], 'laravel-data' => ['{"f":{"kind":"Dog","bark":5}}' => false]],
        ];
        yield 'component oneOf, plain string tags, implicit mapping' => [
            '3.1.0',
            ['$ref' => '#/components/schemas/Shape'],
            [
                'Circle' => $plain('r'),
                'Square' => $plain('s'),
                'Shape' => [
                    'oneOf' => [['$ref' => '#/components/schemas/Circle'], ['$ref' => '#/components/schemas/Square']],
                    'discriminator' => ['propertyName' => 'kind'],
                ],
            ],
            [
                '{"f":{"kind":"Circle","r":1}}' => true,
                '{"f":{"kind":"Square","s":2}}' => true,
                '{"f":{"kind":"Square","r":1}}' => false,
                '{"f":{"kind":"Cow","r":1}}' => false,
                '{"f":{"kind":{"zz":1}}}' => false,
                '{"f":{"kind":["Circle"],"r":1}}' => false,
                '{"f":{}}' => false,
                '{"f":null}' => false,
            ],
        ];

        // The same union on a property of an inline object that is itself a union branch: hoisted as it
        // is on a plain inline object, so symfony and yii3 dispatch by the tag there too. laravel-data
        // built the FIRST member there until 2.15.153, and a valid second member was a `CannotCastEnum`
        // 500; it dispatches by the tag in every position now.
        $tagged = static fn(string $kind, array $more = []): array => [
            'type' => 'object',
            'required' => ['kind'],
            'properties' => ['kind' => ['type' => 'string', 'enum' => [$kind]], ...$more],
        ];
        $heron = ['oneOf' => [['$ref' => '#/components/schemas/Amber'], ['$ref' => '#/components/schemas/Indigo']], 'discriminator' => ['propertyName' => 'kind']];
        foreach (['anyOf', 'oneOf', 'allOf'] as $keyword) {
            $holder = ['type' => 'object', 'required' => ['heron'], 'properties' => ['heron' => $heron]];
            yield sprintf('inline discriminator on a property of an inline %s branch', $keyword) => [
                '3.0.3',
                [$keyword => $keyword === 'allOf' ? [$holder] : [$holder, ['type' => 'string']]],
                ['Amber' => $tagged('Amber'), 'Indigo' => $tagged('Indigo', ['raven' => ['type' => 'integer']])],
                [
                    '{"f":{"heron":{"kind":"Indigo","raven":1}}}' => true,
                    '{"f":{"heron":{"kind":"Amber"}}}' => true,
                    '{"f":{"heron":{"raven":1}}}' => false,
                    '{"f":{"heron":{"kind":"Indigo","raven":"x"}}}' => false,
                    '{"f":{"heron":{"kind":"Cow"}}}' => false,
                    '{"f":{}}' => false,
                    '{"f":5}' => false,
                ],
            ];
        }
        // The control: the same union under a plain inline object property.
        yield 'inline discriminator on a property of an inline object' => [
            '3.0.3',
            ['type' => 'object', 'required' => ['heron'], 'properties' => ['heron' => $heron]],
            ['Amber' => $tagged('Amber'), 'Indigo' => $tagged('Indigo', ['raven' => ['type' => 'integer']])],
            [
                '{"f":{"heron":{"kind":"Indigo","raven":1}}}' => true,
                '{"f":{"heron":{"kind":"Amber"}}}' => true,
                '{"f":{"heron":{"raven":1}}}' => false,
                '{"f":{"heron":{"kind":"Cow"}}}' => false,
            ],
        ];
    }

    /**
     * A temporal format reached through a composition, and a wire value of the wrong shape sent to a
     * plain enum. Each once crashed a mode or refused a valid value: the date inside an `allOf` /
     * `anyOf` was parsed as a date-time, the union of a date-time and another type was typed as a
     * `DateTimeImmutable` union the frameworks cannot hydrate, the 3.1 nullable spelling refused a
     * valid timestamp, and an object sent to an enum property was handed to `new` on the enum.
     *
     * @param array<string, mixed> $propertySchema
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging
     */
    #[DataProvider('temporalAndEnumShapeProvider')]
    public function testTemporalCompositionsAndEnumShapesNeverCrash(array $propertySchema, array $payloads, array $diverging = []): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec($propertySchema);

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'temporal shape ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return array<string, array{0: array<string, mixed>, 1: array<string, bool>, 2?: array<string, array<string, bool|null>>}>
     */
    public static function temporalAndEnumShapeProvider(): array
    {
        $date = ['type' => 'string', 'format' => 'date'];
        $dateTime = ['type' => 'string', 'format' => 'date-time'];
        $datePayloads = [
            '{"f":"2018-06-18"}' => true,
            '{"f":"not a date"}' => false,
            '{"f":5}' => false,
            '{"f":{"zz":1}}' => false,
        ];
        $dateTimePayloads = [
            '{"f":"2018-06-18T10:20:30Z"}' => true,
            '{"f":"not a timestamp"}' => false,
            '{"f":{"zz":1}}' => false,
        ];

        return [
            'an object or a list sent to a string enum' => [
                ['type' => 'string', 'enum' => ['amber', 'red']],
                [
                    '{"f":"amber"}' => true,
                    '{"f":"blue"}' => false,
                    '{"f":{"zz":1}}' => false,
                    '{"f":[1,2]}' => false,
                    '{"f":[]}' => false,
                    '{"f":5}' => false,
                ],
            ],
            'an object or a list sent to an integer enum' => [
                ['type' => 'integer', 'enum' => [1, 2]],
                [
                    '{"f":1}' => true,
                    '{"f":3}' => false,
                    '{"f":{"zz":1}}' => false,
                    '{"f":[1,2]}' => false,
                ],
            ],
            'an object sent to a nullable enum' => [
                ['type' => ['string', 'null'], 'enum' => ['amber', 'red', null]],
                [
                    '{"f":"red"}' => true,
                    '{"f":null}' => true,
                    '{"f":"blue"}' => false,
                    '{"f":{"zz":1}}' => false,
                    '{"f":["red"]}' => false,
                ],
            ],
            'an object sent to an enum with a default' => [
                ['type' => 'string', 'enum' => ['amber', 'red'], 'default' => 'red'],
                [
                    '{"f":"amber"}' => true,
                    '{"f":{"zz":1}}' => false,
                    '{"f":["amber"]}' => false,
                ],
            ],
            'an object or a list sent to an enum beside a string' => [
                ['anyOf' => [['type' => 'integer', 'enum' => [-16]], ['type' => 'string']]],
                [
                    '{"f":-16}' => true,
                    '{"f":"x"}' => true,
                    '{"f":-15}' => false,
                    '{"f":{"zz":1}}' => false,
                    '{"f":[1]}' => false,
                ],
            ],
            'format date in an allOf' => [['allOf' => [$date]], $datePayloads],
            'format date in an anyOf' => [['anyOf' => [$date]], $datePayloads],
            'format date in a oneOf' => [['oneOf' => [$date]], $datePayloads],
            'format date-time in an allOf' => [['allOf' => [$dateTime]], $dateTimePayloads],
            'format date-time in an anyOf' => [['anyOf' => [$dateTime]], $dateTimePayloads],
            'an integer or a date-time' => [
                ['oneOf' => [['type' => 'integer'], $dateTime]],
                [
                    '{"f":-27}' => true,
                    '{"f":"2018-06-18T10:20:30Z"}' => true,
                    '{"f":"not a timestamp"}' => false,
                    '{"f":true}' => false,
                    '{"f":{"zz":1}}' => false,
                ],
            ],
            'a boolean or a date-time' => [
                ['anyOf' => [['type' => 'boolean'], $dateTime]],
                [
                    '{"f":true}' => true,
                    '{"f":false}' => true,
                    '{"f":"2018-06-18T10:20:30Z"}' => true,
                    '{"f":"not a timestamp"}' => false,
                    '{"f":5}' => false,
                ],
            ],
            'a boolean or a date' => [
                ['anyOf' => [['type' => 'boolean'], $date]],
                [
                    '{"f":true}' => true,
                    '{"f":"2018-06-18"}' => true,
                    '{"f":"not a date"}' => false,
                    '{"f":5}' => false,
                ],
            ],
            'a list or a date' => [
                ['oneOf' => [['type' => 'array'], $date]],
                [
                    '{"f":[]}' => true,
                    '{"f":[1,"a"]}' => true,
                    '{"f":"2018-06-18"}' => true,
                    '{"f":"not a date"}' => false,
                    '{"f":5}' => false,
                ],
            ],
            'an integer, a list or a date' => [
                ['oneOf' => [['type' => 'integer', 'maximum' => -18], ['type' => 'array'], $date]],
                [
                    '{"f":-20}' => true,
                    '{"f":[]}' => true,
                    '{"f":"2018-06-18"}' => true,
                    // Beside an `array` member `#[ToString]` cannot stop `#[ToDateTime]` reading the int as a
                    // timestamp (README.support-matrix "an integer for a `oneOf` of `format: date`, `integer`
                    // and …"), but yii3 checks the integer member's `maximum` on the raw value first.
                    '{"f":-5}' => false,
                    '{"f":"not a date"}' => false,
                ],
            ],
            'a date-time or null, the 3.1 spelling' => [
                ['anyOf' => [$dateTime, ['type' => 'null']]],
                [
                    '{"f":"2018-06-18T10:20:30Z"}' => true,
                    '{"f":null}' => true,
                    '{"f":"not a timestamp"}' => false,
                    '{"f":5}' => false,
                ],
            ],
            'a date-time or null as a oneOf' => [
                ['oneOf' => [$dateTime, ['type' => 'null']]],
                [
                    '{"f":"2018-06-18T10:20:30Z"}' => true,
                    '{"f":null}' => true,
                    '{"f":"not a timestamp"}' => false,
                ],
            ],
            'a date or null, the 3.1 spelling' => [
                ['anyOf' => [$date, ['type' => 'null']]],
                [
                    '{"f":"2018-06-18"}' => true,
                    '{"f":null}' => true,
                    '{"f":"not a date"}' => false,
                ],
            ],
            'a date-time or null, the type array spelling' => [
                ['type' => ['string', 'null'], 'format' => 'date-time'],
                [
                    '{"f":"2018-06-18T10:20:30Z"}' => true,
                    '{"f":null}' => true,
                    '{"f":"not a timestamp"}' => false,
                ],
            ],
        ];
    }

    /**
     * Unions whose members disagree on type, each member carrying its own keywords: an enum, a length, a
     * map's value schema, a list's item schema, `nullable`. A member's keywords judge only the values of
     * that member's type — a string member's `minLength` says nothing about a number, an integer enum is
     * not "matched" by every object — and a value a member's type admits but its keywords refuse matches
     * no member. Every mode must give the document's answer, and never crash.
     *
     * @param array<string, mixed> $propertySchema
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise,
     *     by the README.support-matrix divergence named beside the case
     */
    #[DataProvider('unionMemberKeywordProvider')]
    public function testUnionMemberKeywordsJudgeOnlyTheirOwnType(
        string $openApiVersion,
        array $propertySchema,
        array $payloads,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec($propertySchema);
        $spec['openapi'] = $openApiVersion;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union member keywords ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return array<string, array{0: string, 1: array<string, mixed>, 2: array<string, bool>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function unionMemberKeywordProvider(): array
    {
        // "a scalar for a property typed as a generated class": symfony/serializer 7.4.10 builds an empty
        // object from a scalar when the class requires nothing; newer releases refuse it.
        $symfonyMayBuildAnEmptyObject = static fn(string ...$jsons): array => ['symfony' => array_fill_keys($jsons, null)];
        // "a JSON array for a `type: object` property": the serializer and the hydrator build the object
        // before any validator sees the raw body.
        $arrayAsObject = static fn(string $json): array => ['symfony' => [$json => true], 'yii3' => [$json => true]];

        return [
            'oneOf of an integer enum and an open object' => [
                '3.1.0',
                ['oneOf' => [['type' => 'integer', 'enum' => [-6]], ['type' => 'object']]],
                ['{"f":-6}' => true, '{"f":{}}' => true, '{"f":{"a":1}}' => true, '{"f":-5}' => false, '{"f":"x"}' => false],
                $symfonyMayBuildAnEmptyObject('{"f":-5}', '{"f":"x"}'),
            ],
            'anyOf of an integer enum and an open object' => [
                '3.1.0',
                ['anyOf' => [['type' => 'integer', 'enum' => [-6, 4]], ['type' => 'object']]],
                ['{"f":-6}' => true, '{"f":4}' => true, '{"f":{"a":1}}' => true, '{"f":-5}' => false],
                $symfonyMayBuildAnEmptyObject('{"f":-5}'),
            ],
            'oneOf of a number map and a short string list' => [
                '3.1.0',
                ['oneOf' => [
                    ['type' => 'object', 'additionalProperties' => ['type' => 'number']],
                    ['type' => 'array', 'items' => ['type' => 'string', 'maxLength' => 3]],
                ]],
                [
                    '{"f":["ab"]}' => true,
                    '{"f":[]}' => true,
                    '{"f":{"a":1.5}}' => true,
                    '{"f":[7]}' => false,
                    '{"f":["abcdef"]}' => false,
                    '{"f":{"a":"x"}}' => false,
                    '{"f":"ab"}' => false,
                ],
            ],
            'anyOf of a number map and a short string list' => [
                '3.1.0',
                ['anyOf' => [
                    ['type' => 'object', 'additionalProperties' => ['type' => 'number']],
                    ['type' => 'array', 'items' => ['type' => 'string', 'maxLength' => 3]],
                ]],
                ['{"f":["ab"]}' => true, '{"f":{"a":1.5}}' => true, '{"f":[7]}' => false, '{"f":["abcdef"]}' => false, '{"f":{"a":"x"}}' => false],
            ],
            'list of oneOf of a number map and a short string list' => [
                '3.1.0',
                ['type' => 'array', 'items' => ['oneOf' => [
                    ['type' => 'object', 'additionalProperties' => ['type' => 'number']],
                    ['type' => 'array', 'items' => ['type' => 'string', 'maxLength' => 3]],
                ]]],
                ['{"f":[["ab"]]}' => true, '{"f":[{"a":1.5}]}' => true, '{"f":[[7]]}' => false, '{"f":[["abcdef"]]}' => false],
            ],
            'anyOf of a lone open object' => [
                '3.1.0',
                ['anyOf' => [['type' => 'object']]],
                ['{"f":{}}' => true, '{"f":{"a":1}}' => true, '{"f":[1,2]}' => false, '{"f":"x"}' => false],
                $arrayAsObject('{"f":[1,2]}') + $symfonyMayBuildAnEmptyObject('{"f":"x"}'),
            ],
            'oneOf of a lone open object' => [
                '3.1.0',
                ['oneOf' => [['type' => 'object']]],
                ['{"f":{"a":1}}' => true, '{"f":[1,2]}' => false],
                $arrayAsObject('{"f":[1,2]}'),
            ],
            'inline oneOf of a string and an object with a required boolean' => [
                '3.1.0',
                ['oneOf' => [
                    ['type' => 'string'],
                    ['type' => 'object', 'properties' => ['g' => ['type' => 'boolean']], 'required' => ['g']],
                ]],
                ['{"f":"hi"}' => true, '{"f":{"g":true}}' => true, '{"f":{}}' => false, '{"f":{"g":"x"}}' => false, '{"f":5}' => false],
                // "a scalar for a property typed as a generated class": under `#[MapRequestPayload]`,
                // symfony/serializer 7.4.10 tries the class member first and, building it from the scalar,
                // collects "the class misses the "g" property" before the string member is tried; newer
                // releases refuse the scalar for the class and take the string.
                ['symfony' => ['{"f":"hi"}' => null]],
            ],
            'anyOf of a number enum and a string' => [
                '3.1.0',
                ['anyOf' => [['type' => 'number', 'enum' => [5]], ['type' => 'string']]],
                ['{"f":5}' => true, '{"f":"x"}' => true, '{"f":6}' => false, '{"f":true}' => false],
            ],
            'oneOf of a string enum and an integer' => [
                '3.1.0',
                ['oneOf' => [['type' => 'string', 'enum' => ['red']], ['type' => 'integer']]],
                ['{"f":"red"}' => true, '{"f":3}' => true, '{"f":"blue"}' => false],
            ],
            'oneOf of a long string and a number' => [
                '3.1.0',
                ['oneOf' => [['type' => 'string', 'minLength' => 3], ['type' => 'number']]],
                ['{"f":5}' => true, '{"f":2.5}' => true, '{"f":"abc"}' => true, '{"f":"ab"}' => false, '{"f":true}' => false],
            ],
            'anyOf of a short string and an integer' => [
                '3.1.0',
                ['anyOf' => [['type' => 'string', 'maxLength' => 2], ['type' => 'integer', 'minimum' => 10]]],
                ['{"f":12345}' => true, '{"f":"ab"}' => true, '{"f":"abc"}' => false, '{"f":5}' => false],
            ],
            'anyOf of a string and null, the 3.1 spelling' => [
                '3.1.0',
                ['anyOf' => [['type' => 'string'], ['type' => 'null']]],
                ['{"f":"x"}' => true, '{"f":null}' => true, '{"f":7}' => false, '{"f":true}' => false],
            ],
            'oneOf of an integer and null, the 3.1 spelling' => [
                '3.1.0',
                ['oneOf' => [['type' => 'integer'], ['type' => 'null']]],
                ['{"f":7}' => true, '{"f":null}' => true, '{"f":"x"}' => false, '{"f":true}' => false],
            ],
            'oneOf of a nullable number and a string, the 3.0 spelling' => [
                '3.0.3',
                ['oneOf' => [['type' => 'number', 'nullable' => true], ['type' => 'string']]],
                ['{"f":null}' => true, '{"f":1.5}' => true, '{"f":"x"}' => true, '{"f":true}' => false],
            ],
            'list of a nullable number or a string, the 3.0 spelling' => [
                '3.0.3',
                ['type' => 'array', 'items' => ['oneOf' => [['type' => 'number', 'nullable' => true], ['type' => 'string']]]],
                ['{"f":[null]}' => true, '{"f":[1.5]}' => true, '{"f":["x"]}' => true, '{"f":[true]}' => false],
            ],
            'oneOf of a nullable integer and a string, the 3.0 spelling' => [
                '3.0.3',
                ['oneOf' => [['type' => 'integer', 'nullable' => true], ['type' => 'string']]],
                ['{"f":null}' => true, '{"f":1}' => true, '{"f":"x"}' => true, '{"f":true}' => false],
            ],
            'map of a nullable number or a string, the 3.0 spelling' => [
                '3.0.3',
                ['type' => 'object', 'additionalProperties' => ['oneOf' => [['type' => 'number', 'nullable' => true], ['type' => 'string']]]],
                ['{"f":{"a":null}}' => true, '{"f":{"a":1}}' => true, '{"f":{"a":true}}' => false],
            ],
            'optional oneOf of a nullable number and a string, the 3.0 spelling' => [
                '3.0.3',
                ['type' => 'object', 'properties' => ['g' => ['oneOf' => [['type' => 'number', 'nullable' => true], ['type' => 'string']]]]],
                ['{"f":{"g":null}}' => true, '{"f":{}}' => true, '{"f":{"g":1}}' => true, '{"f":{"g":true}}' => false],
            ],
            'optional anyOf of a number and a nullable string, the 3.0 spelling' => [
                '3.0.3',
                ['type' => 'object', 'properties' => ['g' => ['anyOf' => [['type' => 'number'], ['type' => 'string', 'nullable' => true]]]]],
                ['{"f":{"g":null}}' => true, '{"f":{"g":"x"}}' => true, '{"f":{"g":true}}' => false],
            ],
            'optional anyOf of a string and null, the 3.1 spelling' => [
                '3.1.0',
                ['type' => 'object', 'properties' => ['g' => ['anyOf' => [['type' => 'string'], ['type' => 'null']]]]],
                ['{"f":{"g":null}}' => true, '{"f":{"g":"x"}}' => true, '{"f":{}}' => true, '{"f":{"g":7}}' => false, '{"f":{"g":true}}' => false],
            ],
            'anyOf of a number and a nullable string, the 3.0 spelling' => [
                '3.0.3',
                ['anyOf' => [['type' => 'number'], ['type' => 'string', 'nullable' => true]]],
                ['{"f":null}' => true, '{"f":1.5}' => true, '{"f":"x"}' => true, '{"f":true}' => false],
            ],
        ];
    }

    /**
     * Containers whose members carry their own rules: positional `prefixItems` before `items`, declared
     * properties beside an `additionalProperties` schema, a map of a nullable enum, a map alias with a
     * sibling count keyword, an array alias of a string alias, and a JSON object where an array belongs.
     * Every mode must give the document's answer, and never crash.
     *
     * @param array<string, mixed> $propertySchema
     * @param array<string, array<string, mixed>> $components
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise,
     *     by the README.support-matrix divergence named beside the case
     */
    #[DataProvider('containerShapeProvider')]
    public function testContainerMembersAreJudgedByTheirOwnSchema(
        string $openApiVersion,
        array $propertySchema,
        array $components,
        array $payloads,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec($propertySchema);
        $spec['openapi'] = $openApiVersion;
        $spec['components']['schemas'] += $components;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'container shape ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return array<string, array{0: string, 1: array<string, mixed>, 2: array<string, array<string, mixed>>, 3: array<string, bool>, 4?: array<string, array<string, bool|null>>}>
     */
    public static function containerShapeProvider(): array
    {
        $tuple = ['type' => 'array', 'prefixItems' => [['type' => 'integer']], 'items' => ['type' => 'string']];
        $weights = ['Weights' => ['type' => 'object', 'additionalProperties' => ['type' => 'number']]];
        $uuid = '"0b7e6c1a-3f4d-4c2b-9a8e-1d2c3b4a5f60"';

        return [
            // "a non-object ITEM of a list or map of DTOs" with an item class that requires nothing:
            // symfony/serializer 7.4.10 builds the null or the scalar into an empty object, and no
            // missing key refuses it (the `Tag` cases of `crashShapeProvider` require `id`). Left
            // unasserted for symfony: newer serializer releases refuse it.
            'non-object item of a list of requirement-free DTOs' => [
                '3.0.3',
                ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Lime']],
                ['Lime' => ['type' => 'object', 'properties' => ['llama' => ['type' => 'string']]]],
                [
                    '{"f":[{"llama":"x"}]}' => true,
                    '{"f":[{}]}' => true,
                    '{"f":[null]}' => false,
                    '{"f":["x"]}' => false,
                    '{"f":[7]}' => false,
                ],
                [
                    'symfony' => ['{"f":[null]}' => null, '{"f":["x"]}' => null, '{"f":[7]}' => null],
                ],
            ],
            'non-object value of a map of requirement-free DTOs' => [
                '3.0.3',
                ['type' => 'object', 'additionalProperties' => ['$ref' => '#/components/schemas/Lime']],
                ['Lime' => ['type' => 'object', 'properties' => ['llama' => ['type' => 'string']]]],
                [
                    '{"f":{"ka":{"llama":"x"}}}' => true,
                    '{"f":{"ka":null}}' => false,
                    '{"f":{"ka":"x"}}' => false,
                ],
                [
                    'symfony' => ['{"f":{"ka":null}}' => null, '{"f":{"ka":"x"}}' => null],
                ],
            ],
            'prefixItems before items' => [
                '3.1.0',
                $tuple,
                [],
                [
                    '{"f":[]}' => true,
                    '{"f":[-75]}' => true,
                    '{"f":[-75,"a"]}' => true,
                    '{"f":[-75,"a","b"]}' => true,
                    '{"f":["a"]}' => false,
                    '{"f":[-75,5]}' => false,
                    '{"f":[-75,"a",5]}' => false,
                ],
            ],
            'prefixItems of two before items' => [
                '3.1.0',
                ['type' => 'array', 'prefixItems' => [['type' => 'integer'], ['type' => 'boolean']], 'items' => ['type' => 'string']],
                [],
                ['{"f":[1,true,"a"]}' => true, '{"f":[1]}' => true, '{"f":[1,"a"]}' => false, '{"f":[1,true,2]}' => false],
            ],
            'prefixItems without items' => [
                '3.1.0',
                ['type' => 'array', 'prefixItems' => [['type' => 'integer']]],
                [],
                ['{"f":[1]}' => true, '{"f":[1,"a",true]}' => true, '{"f":["a"]}' => false],
            ],
            'prefixItems inside a list' => [
                '3.1.0',
                ['type' => 'array', 'items' => $tuple],
                [],
                ['{"f":[[-75],[-75,"a"]]}' => true, '{"f":[[-75,"a"],["a"]]}' => false, '{"f":[[-75,5]]}' => false],
            ],
            'declared property beside an additionalProperties schema' => [
                '3.1.0',
                ['type' => 'object', 'properties' => ['ibis' => ['type' => 'boolean']], 'additionalProperties' => ['type' => 'integer']],
                [],
                [
                    '{"f":{"ibis":true}}' => true,
                    '{"f":{"ibis":true,"x":3}}' => true,
                    '{"f":{"x":3}}' => true,
                    '{"f":{"ibis":true,"x":"a"}}' => false,
                    '{"f":{"ibis":3}}' => false,
                ],
                // "a key `additionalProperties: {schema}` admits beside the named properties": the
                // serializer and the hydrator fill the declared properties only.
                ['symfony' => ['{"f":{"ibis":true,"x":"a"}}' => true], 'yii3' => ['{"f":{"ibis":true,"x":"a"}}' => true]],
            ],
            'map of a nullable enum, the 3.1 spelling' => [
                '3.1.0',
                ['type' => 'object', 'additionalProperties' => ['anyOf' => [['type' => 'string', 'enum' => ['violet']], ['type' => 'null']]]],
                [],
                ['{"f":{"a":null}}' => true, '{"f":{"a":"violet"}}' => true, '{"f":{"a":"red"}}' => false, '{"f":{"a":3}}' => false],
            ],
            'list of a nullable enum, the 3.1 spelling' => [
                '3.1.0',
                ['type' => 'array', 'items' => ['anyOf' => [['type' => 'string', 'enum' => ['violet']], ['type' => 'null']]]],
                [],
                ['{"f":[null]}' => true, '{"f":["violet",null]}' => true, '{"f":["red"]}' => false, '{"f":[3]}' => false],
            ],
            'map of a nullable component enum' => [
                '3.1.0',
                ['type' => 'object', 'additionalProperties' => ['anyOf' => [['$ref' => '#/components/schemas/Hue'], ['type' => 'null']]]],
                ['Hue' => ['type' => 'string', 'enum' => ['violet', 'teal']]],
                ['{"f":{"a":null}}' => true, '{"f":{"a":"teal"}}' => true, '{"f":{"a":"red"}}' => false],
            ],
            'list of a nullable component enum' => [
                '3.1.0',
                ['type' => 'array', 'items' => ['anyOf' => [['$ref' => '#/components/schemas/Hue'], ['type' => 'null']]]],
                ['Hue' => ['type' => 'string', 'enum' => ['violet', 'teal']]],
                ['{"f":[null]}' => true, '{"f":["teal"]}' => true, '{"f":["red"]}' => false],
            ],
            'map of a nullable date' => [
                '3.1.0',
                ['type' => 'object', 'additionalProperties' => ['type' => ['string', 'null'], 'format' => 'date']],
                [],
                // Symfony holds a nullable date value as its string since 3.0, so its null is accepted.
                ['{"f":{"a":null}}' => true, '{"f":{"a":"2020-01-02"}}' => true, '{"f":{"a":5}}' => false],
            ],
            'map of a nullable enum, the 3.0 spelling' => [
                '3.0.3',
                ['type' => 'object', 'additionalProperties' => ['type' => 'string', 'enum' => ['violet', null], 'nullable' => true]],
                [],
                ['{"f":{"a":null}}' => true, '{"f":{"a":"violet"}}' => true, '{"f":{"a":"red"}}' => false],
            ],
            'map alias with a sibling maxProperties' => [
                '3.1.0',
                ['$ref' => '#/components/schemas/Weights', 'maxProperties' => 1],
                $weights,
                [
                    '{"f":{}}' => true,
                    '{"f":{"a":1.5}}' => true,
                    '{"f":{"a":"x"}}' => false,
                    '{"f":null}' => false,
                    '{"f":{"a":1,"b":2}}' => false,
                ],
            ],
            'map alias with a sibling minProperties' => [
                '3.1.0',
                ['$ref' => '#/components/schemas/Weights', 'minProperties' => 1],
                $weights,
                ['{"f":{"a":1.5}}' => true, '{"f":{}}' => false, '{"f":{"a":"x"}}' => false],
            ],
            'map alias' => [
                '3.1.0',
                ['$ref' => '#/components/schemas/Weights'],
                $weights,
                ['{"f":{"a":1.5}}' => true, '{"f":{"a":"x"}}' => false, '{"f":null}' => false],
            ],
            'array alias of a string alias' => [
                '3.1.0',
                ['$ref' => '#/components/schemas/Ids'],
                [
                    'Uuid' => ['type' => 'string', 'format' => 'uuid'],
                    'Ids' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Uuid'], 'minItems' => 1],
                ],
                ['{"f":[' . $uuid . ']}' => true, '{"f":[]}' => false, '{"f":["x"]}' => false, '{"f":[5]}' => false],
            ],
            'array of a string alias' => [
                '3.1.0',
                ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Uuid'], 'minItems' => 1],
                ['Uuid' => ['type' => 'string', 'format' => 'uuid']],
                ['{"f":[' . $uuid . ']}' => true, '{"f":[]}' => false, '{"f":["x"]}' => false],
            ],
            'optional array alias of a string alias' => [
                '3.1.0',
                ['type' => 'object', 'properties' => ['g' => ['$ref' => '#/components/schemas/Ids']]],
                [
                    'Uuid' => ['type' => 'string', 'format' => 'uuid'],
                    'Ids' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Uuid'], 'minItems' => 1],
                ],
                ['{"f":{"g":[' . $uuid . ']}}' => true, '{"f":{"g":[]}}' => false, '{"f":{"g":["x"]}}' => false],
            ],
            'map alias with a sibling maxProperties, one level down' => [
                '3.1.0',
                ['type' => 'object', 'properties' => ['g' => ['$ref' => '#/components/schemas/Weights', 'maxProperties' => 1]]],
                $weights,
                ['{"f":{"g":{"a":1.5}}}' => true, '{"f":{"g":{"a":"x"}}}' => false, '{"f":{"g":{"a":1,"b":2}}}' => false],
            ],
            'array alias of a number alias with sibling item counts' => [
                '3.1.0',
                ['$ref' => '#/components/schemas/Amber', 'minItems' => 1, 'maxItems' => 3],
                [
                    'Azure' => ['type' => 'number', 'minimum' => -3.5, 'exclusiveMaximum' => -2],
                    'Amber' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Azure']],
                ],
                ['{"f":[-3]}' => true, '{"f":[]}' => false, '{"f":[0]}' => false],
            ],
            'array alias with sibling item counts in a class extended beside its reference' => [
                '3.1.0',
                ['$ref' => '#/components/schemas/Crimson', 'properties' => ['lynx' => ['type' => 'boolean']]],
                [
                    'Azure' => ['type' => 'number', 'minimum' => -3.5, 'exclusiveMaximum' => -2],
                    'Amber' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Azure']],
                    'Crimson' => ['type' => 'object', 'properties' => ['quokka' => ['$ref' => '#/components/schemas/Amber', 'minItems' => 1, 'maxItems' => 3]], 'required' => ['quokka']],
                ],
                ['{"f":{"quokka":[-3]}}' => true, '{"f":{"quokka":[]}}' => false, '{"f":{"quokka":[0]}}' => false],
            ],
            'a JSON object for an array of integers' => [
                '3.1.0',
                ['type' => 'array', 'items' => ['type' => 'integer']],
                [],
                ['{"f":[1]}' => true, '{"f":[]}' => true, '{"f":{"zz":1}}' => false, '{"f":["a"]}' => false],
            ],
            'a JSON object for an array of strings' => [
                '3.1.0',
                ['type' => 'array', 'items' => ['type' => 'string']],
                [],
                ['{"f":["a"]}' => true, '{"f":{"zz":"a"}}' => false],
            ],
        ];
    }

    /**
     * Shapes the generator normalises before any mode renders them — a `$ref` with sibling keywords as
     * a list's `items`, a null-admitting array alias as a union member, a 3.0 `nullable` beside
     * `allOf: [$ref enum]` inside a union, a component whose `anyOf` arms only name required properties,
     * a nullable list of maps of nullable numbers, a date one union deeper, and an array alias of
     * nullable discriminated-union items. Every mode must give the document's answer, and never crash.
     *
     * @param array<string, array<string, mixed>> $schemas the component schemas, `Probe` among them
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise
     */
    #[DataProvider('schemaNormalisationShapeProvider')]
    public function testSchemaNormalisationShapesValidateInEveryMode(
        string $openApiVersion,
        array $schemas,
        array $payloads,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => $openApiVersion,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => $schemas],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'normalisation shape ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, array<string, mixed>>, 2: array<string, bool>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function schemaNormalisationShapeProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $probe = static fn(array $properties, array $required = []): array => [
            'type' => 'object',
            'required' => $required,
            'properties' => $properties,
        ];

        // A `$ref` with sibling keywords as a list's items: both sides judge every item.
        $circle = ['type' => 'object', 'properties' => ['hue' => ['type' => 'integer']]];
        $siblingItems = $ref('Circle') + ['properties' => ['tail' => ['type' => 'string']]];
        $itemPayloads = [
            '{"fox":[{"hue":1,"tail":"a"}]}' => true,
            '{"fox":[]}' => true,
            '{"fox":[{"hue":"x"}]}' => false,
            '{"fox":[{"tail":5}]}' => false,
            '{"fox":"zzq"}' => false,
        ];
        $ringSpellings = [
            'an alias as a nullable union branch' => [['anyOf' => [$ref('Ring'), ['type' => 'null']]], ['{"fox":null}' => true]],
            'an alias referenced directly' => [$ref('Ring'), ['{"fox":null}' => false]],
            'an alias beside an integer' => [['anyOf' => [$ref('Ring'), ['type' => 'integer']]], ['{"fox":7}' => true]],
            'inline items, a nullable union branch' => [
                ['anyOf' => [['type' => 'array', 'items' => $siblingItems], ['type' => 'null']]],
                ['{"fox":null}' => true],
            ],
        ];
        foreach ($ringSpellings as $name => [$fox, $extra]) {
            yield 'list items: a $ref beside siblings, ' . $name => [
                '3.1.0',
                [
                    'Circle' => $circle,
                    'Ring' => ['type' => 'array', 'items' => $siblingItems],
                    'Probe' => $probe(['fox' => $fox]),
                ],
                $itemPayloads + $extra,
            ];
        }
        yield 'list items: a bare $ref, an alias as a nullable union branch' => [
            '3.1.0',
            [
                'Circle' => $circle,
                'Ring' => ['type' => 'array', 'items' => $ref('Circle')],
                'Probe' => $probe(['fox' => ['anyOf' => [$ref('Ring'), ['type' => 'null']]]]),
            ],
            ['{"fox":[{"hue":1}]}' => true, '{"fox":null}' => true, '{"fox":[{"hue":"x"}]}' => false],
        ];

        // A null-admitting array alias as a member of a union: the property admits null.
        foreach (['3.0.3' => ['type' => 'array', 'nullable' => true], '3.1.0' => ['type' => ['array', 'null']]] as $version => $saffron) {
            $mauve = $version === '3.0.3' ? ['type' => 'string', 'nullable' => true] : ['type' => ['string', 'null']];
            yield 'a null-admitting array alias as a union member, ' . $version => [
                $version,
                [
                    'Saffron' => $saffron,
                    'Mauve' => $mauve,
                    'Probe' => $probe(
                        properties: [
                            'heron' => ['oneOf' => [$ref('Saffron'), ['type' => 'integer']]],
                            'crane' => ['anyOf' => [$ref('Saffron'), ['type' => 'integer']]],
                            'pink' => ['oneOf' => [$ref('Saffron')]],
                            'stork' => ['oneOf' => [$ref('Mauve'), ['type' => 'integer']]],
                        ],
                        required: ['pink'],
                    ),
                ],
                [
                    '{"pink":null}' => true,
                    '{"pink":[1]}' => true,
                    '{"pink":[],"heron":null}' => true,
                    '{"pink":[],"heron":[1]}' => true,
                    '{"pink":[],"heron":5}' => true,
                    '{"pink":[],"crane":null}' => true,
                    '{"pink":[],"stork":null}' => true,
                    '{"pink":[],"heron":"zzq"}' => false,
                    '{"pink":"zzq"}' => false,
                    '{}' => false,
                ],
            ];
        }

        // 3.0: `nullable` beside `allOf: [$ref enum]`, as a branch of a union.
        $nullableIndigo = ['allOf' => [$ref('Indigo')], 'nullable' => true];
        yield 'a 3.0 nullable allOf of an enum $ref as a union branch' => [
            '3.0.3',
            [
                'Indigo' => ['type' => 'string', 'enum' => ['amber']],
                'Probe' => $probe([
                    'plover' => ['anyOf' => [$nullableIndigo]],
                    'green' => ['anyOf' => [$nullableIndigo, ['type' => 'integer']]],
                    'crow' => $nullableIndigo,
                    'pink' => ['anyOf' => [['allOf' => [['type' => 'string', 'enum' => ['amber']]], 'nullable' => true]]],
                ]),
            ],
            [
                '{"plover":null}' => true,
                '{"plover":"amber"}' => true,
                '{"plover":"zzq"}' => false,
                '{"green":null}' => true,
                '{"green":3}' => true,
                '{"green":"zzq"}' => false,
                '{"crow":null}' => true,
                '{"crow":"zzq"}' => false,
                '{"pink":null}' => true,
                '{"pink":"zzq"}' => false,
            ],
        ];

        // A component with properties whose `anyOf` arms only say which of them is required.
        $badge = [
            'type' => 'object',
            'properties' => ['red' => ['type' => 'string'], 'blue' => ['type' => 'integer']],
            'anyOf' => [['required' => ['red']], ['required' => ['blue']]],
        ];
        yield 'a component with properties and an anyOf of required lists' => [
            '3.0.3',
            ['Badge' => $badge, 'Probe' => $probe(['fox' => $ref('Badge')])],
            [
                '{"fox":{"red":"a"}}' => true,
                '{"fox":{"blue":1}}' => true,
                '{"fox":{"red":"a","blue":1}}' => true,
                '{}' => true,
                '{"fox":{}}' => false,
                '{"fox":{"red":5}}' => false,
                '{"fox":{"blue":"x"}}' => false,
            ],
        ];
        yield 'a root object with properties and an anyOf of required lists' => [
            '3.0.3',
            ['Probe' => $badge],
            ['{"red":"a"}' => true, '{"blue":1}' => true, '{}' => false, '{"red":5}' => false, '{"blue":"x"}' => false],
        ];
        yield 'a root object built from an allOf, beside an anyOf of required lists' => [
            '3.0.3',
            ['Probe' => [
                'allOf' => [['type' => 'object', 'properties' => $badge['properties']]],
                'anyOf' => $badge['anyOf'],
            ]],
            ['{"red":"a"}' => true, '{"blue":1}' => true, '{}' => false, '{"red":5}' => false],
        ];

        yield 'a nullable list of maps of nullable numbers' => [
            '3.0.3',
            ['Probe' => $probe([
                'dingo' => [
                    'type' => 'array',
                    'nullable' => true,
                    'items' => ['type' => 'object', 'additionalProperties' => ['type' => 'number', 'nullable' => true]],
                ],
            ])],
            [
                '{"dingo":null}' => true,
                '{"dingo":[{"a":1.5,"b":null}]}' => true,
                '{"dingo":[]}' => true,
                '{"dingo":[{"a":"zzq"}]}' => false,
            ],
        ];

        $date = ['type' => 'string', 'format' => 'date'];
        yield 'a date one union deeper' => [
            '3.0.3',
            ['Probe' => $probe([
                'red' => ['oneOf' => [['anyOf' => [$date]]]],
                'blue' => ['anyOf' => [$date]],
                'green' => ['allOf' => [$date]],
            ])],
            [
                '{"red":"2023-06-20"}' => true,
                '{"blue":"2023-06-20"}' => true,
                '{"green":"2023-06-20"}' => true,
                '{"red":"zzq"}' => false,
            ],
        ];

        // An array alias whose items are a nullable discriminated union, beside the inline spelling.
        $nullableShapeItems = ['anyOf' => [$ref('Shape'), ['type' => 'null']]];
        yield 'an array alias of nullable discriminated-union items' => [
            '3.1.0',
            [
                'Circle' => [
                    'type' => 'object',
                    'required' => ['kind'],
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']]],
                ],
                'Square' => [
                    'type' => 'object',
                    'required' => ['kind'],
                    'properties' => [
                        'kind' => ['type' => 'string', 'enum' => ['square']],
                        'side' => ['type' => 'number', 'minimum' => 0],
                    ],
                ],
                'Shape' => [
                    'oneOf' => [$ref('Circle'), $ref('Square')],
                    'discriminator' => [
                        'propertyName' => 'kind',
                        'mapping' => ['circle' => '#/components/schemas/Circle', 'square' => '#/components/schemas/Square'],
                    ],
                ],
                'Shapes' => ['type' => 'array', 'items' => $nullableShapeItems],
                'Probe' => $probe([
                    'urchin' => $ref('Shapes'),
                    'bilby' => ['type' => 'array', 'items' => $nullableShapeItems],
                ]),
            ],
            [
                '{"urchin":[{"kind":"square","side":1}]}' => true,
                '{"urchin":[null,{"kind":"circle"}]}' => true,
                '{"urchin":[{"kind":"square","side":-1}]}' => false,
                '{"urchin":[{"kind":"square","side":true}]}' => false,
                '{"bilby":[{"kind":"square","side":1}]}' => true,
                '{"bilby":[null,{"kind":"circle"}]}' => true,
                '{"bilby":[{"kind":"square","side":-1}]}' => false,
            ],
            // support matrix: "a `null` ITEM of a nullable list of DTOs" — laravel-data builds a DTO out
            // of every element and has no null case.
            ['laravel-data' => ['{"urchin":[null,{"kind":"circle"}]}' => false, '{"bilby":[null,{"kind":"circle"}]}' => false]],
        ];
    }

    /**
     * Shapes the laravel and laravel-data renderers answered on their own: a union member that names
     * its type one composition deeper, a `null` item of a list of a discriminated union, nullable
     * `allOf`-object items, a class beside a free-form object, the member rules of a list of a
     * discriminated union. Every mode must give the document's answer, and never crash.
     *
     * @param array<string, array<string, mixed>> $schemas the component schemas, `Probe` among them
     * @param array<string, bool|null> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise
     */
    #[DataProvider('laravelRendererShapeProvider')]
    public function testLaravelRendererShapesValidateInEveryMode(
        string $openApiVersion,
        array $schemas,
        array $payloads,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => $openApiVersion,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => $schemas],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'laravel renderer ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, array<string, mixed>>, 2: array<string, bool|null>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function laravelRendererShapeProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $probe = static fn(array $properties): array => ['type' => 'object', 'properties' => $properties];

        // A union whose object member names its type one composition deeper still refuses a JSON list.
        yield 'object member inside a nested composition' => [
            '3.0.3',
            ['Probe' => $probe([
                'red' => ['anyOf' => [['anyOf' => [['type' => 'object'], ['type' => 'integer']]]]],
                'blue' => ['anyOf' => [['allOf' => [['type' => 'string']]], ['type' => 'object']]],
                // Pinned: the flat spellings already refused the list.
                'green' => ['anyOf' => [['type' => 'object'], ['type' => 'integer']]],
                'pink' => ['anyOf' => [['type' => 'string'], ['type' => 'object']]],
            ])],
            [
                '{"red":[2]}' => false,
                '{"blue":[2]}' => false,
                '{"green":[2]}' => false,
                '{"pink":[2]}' => false,
                '{"red":{"a":1}}' => true,
                '{"red":3}' => true,
                '{"blue":"s"}' => true,
                '{"blue":{"a":1}}' => true,
                '{"blue":true}' => false,
            ],
            // README.support-matrix "a JSON array for a `type: object` property".
            [
                'symfony' => ['{"red":[2]}' => true, '{"blue":[2]}' => true, '{"green":[2]}' => true, '{"pink":[2]}' => true],
                'yii3' => ['{"red":[2]}' => true, '{"blue":[2]}' => true, '{"green":[2]}' => true, '{"pink":[2]}' => true],
            ],
        ];

        $tagged = static fn(bool $enumTags): array => [
            'Cat' => ['type' => 'object', 'required' => ['kind'], 'properties' => [
                'kind' => $enumTags ? ['type' => 'string', 'enum' => ['cat']] : ['type' => 'string'],
                'paw' => ['type' => 'number'],
            ]],
            'Dog' => ['type' => 'object', 'required' => ['kind'], 'properties' => [
                'kind' => $enumTags ? ['type' => 'string', 'enum' => ['dog']] : ['type' => 'string'],
                'tail' => ['type' => 'number'],
            ]],
            'Pet' => [
                'oneOf' => [$ref('Cat'), $ref('Dog')],
                'discriminator' => ['propertyName' => 'kind', 'mapping' => [
                    'cat' => '#/components/schemas/Cat',
                    'dog' => '#/components/schemas/Dog',
                ]],
            ],
        ];
        $petLists = [
            'red' => ['type' => 'array', 'items' => $ref('Pet')],
            'blue' => $ref('Pet'),
            'green' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Pet'), ['type' => 'null']]]],
            'pink' => ['oneOf' => [$ref('Pet'), ['type' => 'null']]],
        ];

        // A `null` item where the items admit null, as the property spelling admits it.
        yield 'null item of a list of a discriminated union' => [
            '3.0.3',
            $tagged(true) + ['Probe' => $probe($petLists)],
            [
                '{"green":[null]}' => true,
                '{"green":[null,{"kind":"dog","tail":1}]}' => true,
                '{"pink":null}' => true,
                '{"red":[null]}' => false,
                '{"green":[{"kind":"cat","paw":1}]}' => true,
                '{"green":[{"kind":"cat","paw":"x"}]}' => false,
                '{"green":[5]}' => false,
            ],
            // README.support-matrix "a `null` ITEM of a nullable list of DTOs": laravel-data resolves the
            // member of every item before any rule runs, and has no null case.
            ['laravel-data' => ['{"green":[null]}' => false, '{"green":[null,{"kind":"dog","tail":1}]}' => false]],
        ];

        // Every item is judged by the member its tag names: a cat's `paw` must be a number.
        yield 'member rules of a list of a discriminated union' => [
            '3.0.3',
            $tagged(false) + ['Probe' => $probe($petLists)],
            [
                '{"red":[{"kind":"cat","paw":"x"}]}' => false,
                '{"green":[{"kind":"cat","paw":"x"}]}' => false,
                '{"blue":{"kind":"cat","paw":"x"}}' => false,
                '{"red":[{"kind":"dog","tail":"x"}]}' => false,
                '{"green":[null]}' => true,
                '{"red":[]}' => true,
            ],
            ['laravel-data' => ['{"green":[null]}' => false]],
        ];

        // Nullable `allOf`-object items: each object item is still checked against the object.
        $walrus = ['type' => 'object', 'properties' => ['walrus' => ['type' => 'string', 'maxLength' => 2]]];
        $walrusPayloads = static fn(string $name, bool $nullable): array => [
            '{"' . $name . '":[{"walrus":"ab"}]}' => true,
            '{"' . $name . '":[{"walrus":"abc"}]}' => false,
            '{"' . $name . '":[{"walrus":5}]}' => false,
            '{"' . $name . '":[null]}' => $nullable,
            '{"' . $name . '":["x"]}' => false,
        ];
        yield 'nullable allOf-object items' => [
            '3.0.3',
            ['Probe' => $probe([
                'red' => ['type' => 'array', 'items' => ['allOf' => [$walrus], 'nullable' => true]],
                // Pinned: without `nullable`, and with the object spelled inline.
                'blue' => ['type' => 'array', 'items' => ['allOf' => [$walrus]]],
                'pink' => ['type' => 'array', 'items' => $walrus + ['nullable' => true]],
            ])],
            $walrusPayloads('red', true) + $walrusPayloads('blue', false) + $walrusPayloads('pink', true),
            // README.support-matrix "a non-object ITEM of a list or map of DTOs": depends on the
            // serializer release for an item class that requires nothing. README.support-matrix "a `null`
            // ITEM of a nullable list of DTOs": laravel-data's `#[DataCollectionOf]` built the null into
            // an empty item and wrote it back as `{}`; it is refused before that now. Since 2.15.155 the
            // `allOf` items are a class of their own too, and answer as the inline one does — yii3's
            // hydrator drops an item it cannot build, the first row again.
            [
                'symfony' => ['{"pink":["x"]}' => null, '{"red":["x"]}' => null, '{"blue":[null]}' => null, '{"blue":["x"]}' => null],
                'laravel-data' => ['{"pink":[null]}' => false, '{"red":[null]}' => false],
                'yii3' => ['{"blue":[null]}' => null, '{"blue":["x"]}' => null],
            ],
        ];

        // A class beside a free-form object: an object the class refuses is the free-form member's.
        yield 'class beside a free-form object' => [
            '3.0.3',
            [
                'Lime' => ['type' => 'object', 'required' => ['hue'], 'properties' => ['hue' => ['type' => 'string']]],
                'Probe' => $probe([
                    'red' => ['anyOf' => [['type' => 'array'], $ref('Lime'), ['type' => 'object']]],
                    'blue' => ['anyOf' => [$ref('Lime'), ['type' => 'object']]],
                    // Pinned: without the free-form member the class must match.
                    'green' => ['anyOf' => [['type' => 'array'], $ref('Lime')]],
                ]),
            ],
            [
                '{"red":{"any":1}}' => true,
                '{"blue":{"any":1}}' => true,
                '{"red":{"hue":5}}' => true,
                '{"blue":{"hue":5}}' => true,
                '{"red":{"hue":"x"}}' => true,
                '{"blue":{"hue":"x"}}' => true,
                '{"red":[1]}' => true,
                '{"blue":3}' => false,
                '{"green":{"hue":"x"}}' => true,
                '{"green":[1]}' => true,
                '{"green":{"hue":5}}' => false,
            ],
            // Symfony's serializer answers a union of a class and `array` by the serializer release (the
            // README.support-matrix row "a scalar for a union of an `array` member and a generated class").
            ['symfony' => [
                '{"red":{"any":1}}' => null,
                '{"blue":{"any":1}}' => null,
                '{"red":{"hue":5}}' => null,
                '{"blue":{"hue":5}}' => null,
                '{"red":[1]}' => null,
                '{"green":[1]}' => null,
            ]],
        ];

        // A null ITEM of a list or map of a plain class. laravel mode's `toArray()` mapped every item
        // through a closure typed `Fox $item`, a `TypeError` on the response side; laravel-data's
        // `#[DataCollectionOf]` built a `Fox` out of the null — `CannotCreateData` when `Fox` requires
        // a property, an empty `Owl` written back as `{}` when it requires none.
        $fox = ['type' => 'object', 'required' => ['tail'], 'properties' => ['tail' => ['type' => 'boolean']]];
        $orNull = static fn(array $schema): array => ['oneOf' => [$schema, ['type' => 'null']]];
        $nullableFoxes = ['type' => 'array', 'items' => $orNull($ref('Fox'))];
        yield 'null item of a list or map of a plain class' => [
            '3.0.3',
            [
                'Fox' => $fox,
                'Owl' => ['type' => 'object', 'properties' => ['hoot' => ['type' => 'string']]],
                'Inner' => $probe(['reds' => $nullableFoxes]),
                'Probe' => $probe([
                    'reds' => $nullableFoxes,
                    'blues' => ['type' => 'array', 'items' => ['nullable' => true] + $fox],
                    'owls' => ['type' => 'array', 'items' => $orNull($ref('Owl'))],
                    'pinks' => ['type' => 'object', 'additionalProperties' => $orNull($ref('Fox'))],
                    'inner' => $ref('Inner'),
                    // Pinned: items that admit no null refuse it in every mode.
                    'greens' => ['type' => 'array', 'items' => $ref('Fox')],
                ]),
            ],
            [
                '{"reds":[null]}' => true,
                '{"reds":[{"tail":true},null]}' => true,
                '{"blues":[null]}' => true,
                '{"owls":[null]}' => true,
                '{"pinks":{"k":null}}' => true,
                '{"inner":{"reds":[null]}}' => true,
                '{"reds":[{"tail":true}]}' => true,
                '{"blues":[{"tail":false}]}' => true,
                '{"owls":[{}]}' => true,
                '{"pinks":{"k":{"tail":true}}}' => true,
                '{"inner":{"reds":[{"tail":true}]}}' => true,
                '{"reds":[{}]}' => false,
                '{"reds":["x"]}' => false,
                '{"pinks":{"k":{}}}' => false,
                '{"greens":[null]}' => false,
            ],
            // README.support-matrix "a `null` ITEM of a nullable list of DTOs": refused before
            // `#[DataCollectionOf]` builds it. yii3 refuses the non-object item of `greens` since 2.15.163.
            ['laravel-data' => [
                '{"reds":[null]}' => false,
                '{"reds":[{"tail":true},null]}' => false,
                '{"blues":[null]}' => false,
                '{"owls":[null]}' => false,
                '{"pinks":{"k":null}}' => false,
                '{"inner":{"reds":[null]}}' => false,
            ]],
        ];

        // An inline union of classes whose FIRST member holds a discriminated union. laravel-data takes
        // that member as the property's class and reads the inner union's discriminator out of `toy`
        // whatever arrived — a string `toy` was a `TypeError` in `DataMorphClassResolver`, a 500, for a
        // valid dog as well as for an invalid cat.
        $toyUnion = [
            'oneOf' => [$ref('Ball'), $ref('Rope')],
            'discriminator' => ['propertyName' => 'kind'],
        ];
        yield 'discriminated union inside the first member of an inline class union' => [
            '3.0.3',
            [
                'Cat' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['cat']], 'toy' => $ref('Toy')]],
                'Dog' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['dog']], 'toy' => ['type' => 'string']]],
                'Toy' => $toyUnion,
                'Ball' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['Ball']]]],
                'Rope' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['Rope']]]],
                'Probe' => $probe([
                    'pet' => [
                        'oneOf' => [$ref('Cat'), $ref('Dog')],
                        'discriminator' => ['propertyName' => 'kind', 'mapping' => ['cat' => '#/components/schemas/Cat', 'dog' => '#/components/schemas/Dog']],
                    ],
                ]),
            ],
            [
                '{"pet":{"kind":"dog","toy":"red"}}' => true,
                '{"pet":{"kind":"dog"}}' => true,
                '{"pet":{"kind":"cat","toy":{"kind":"Ball"}}}' => true,
                '{"pet":{"kind":"cat"}}' => true,
                '{"pet":{"kind":"cat","toy":"red"}}' => false,
                '{"pet":{"toy":"red"}}' => false,
                '{"pet":{"kind":"cat","toy":{"kind":"Kite"}}}' => false,
            ],
            // README.support-matrix "a discriminated union inside the FIRST member of an inline union of
            // classes": laravel-data dispatches by the tag since 2.15.153, but its messages-and-attributes
            // resolver still reads Toy's discriminator out of whatever `toy` arrived, so a dog's string
            // `toy` is refused — a 422, where it was a `TypeError` before 2.15.151.
            ['laravel-data' => ['{"pet":{"kind":"dog","toy":"red"}}' => false]],
        ];

        // A string enum beside a `format: date` string, with and without a boolean beside them. laravel
        // handed the date string to the `BoxA|DateTimeImmutable` constructor as a string, a `TypeError`;
        // laravel-data ran its global ATOM date cast on every value, the enum's `red` and `true` included.
        $red = ['type' => 'string', 'enum' => ['red']];
        $date = ['type' => 'string', 'format' => 'date'];
        yield 'string enum beside a date' => [
            '3.0.3',
            ['Probe' => $probe([
                'hue' => ['oneOf' => [$red, $date]],
                'mood' => ['oneOf' => [['type' => 'boolean'], $red, $date]],
                'day' => ['anyOf' => [$red, $date]],
                // Pinned: a date beside a boolean or an integer, and an enum beside a boolean.
                'flag' => ['oneOf' => [['type' => 'boolean'], $date]],
                'count' => ['oneOf' => [['type' => 'integer'], $date]],
                'mark' => ['oneOf' => [['type' => 'boolean'], $red]],
            ])],
            [
                '{"hue":"2024-01-02"}' => true,
                '{"hue":"red"}' => true,
                '{"mood":"2024-01-02"}' => true,
                '{"mood":"red"}' => true,
                '{"mood":true}' => true,
                '{"mood":false}' => true,
                '{"day":"2024-01-02"}' => true,
                '{"day":"red"}' => true,
                '{"flag":true}' => true,
                '{"flag":"2024-01-02"}' => true,
                '{"count":3}' => true,
                '{"count":"2024-01-02"}' => true,
                '{"mark":true}' => true,
                '{"mark":"red"}' => true,
                '{"hue":"blue"}' => false,
                '{"hue":true}' => false,
                '{"mood":"blue"}' => false,
                '{"mood":3}' => false,
                '{"day":"2024-13-45"}' => false,
                '{"day":"+1 day"}' => false,
                '{"mark":"blue"}' => false,
            ],
            // Symfony reads the date beside the enum with `!Y-m-d` since 2.15.162, which refuses `+1 day`
            // and rolls month 13 over (README.support-matrix, the impossible calendar date row).
            ['symfony' => ['{"day":"2024-13-45"}' => true]],
        ];
    }

    /**
     * A failure inside an object a union substituted is reported at the key that failed, not at the
     * property: `{"bee": {}}` misses `bee.zebu`, as `{"bee": {"x": 1}}` does.
     */
    public function testLaravelModesKeyAMissingKeyOfAnEmptyObjectAtItsPath(): void
    {
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => ['Probe' => ['type' => 'object', 'properties' => [
                'bee' => ['oneOf' => [
                    ['type' => 'object', 'required' => ['zebu'], 'properties' => ['zebu' => ['type' => 'string']]],
                    ['type' => 'array'],
                ]],
                'ant' => ['anyOf' => [['type' => 'object', 'required' => ['zebu']], ['type' => 'integer']]],
                'fly' => ['type' => 'object', 'required' => ['zebu'], 'not' => ['required' => ['moth']]],
            ]]]],
        ];
        foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
            foreach (['bee', 'ant', 'fly'] as $name) {
                foreach (['{}', '{"x":1}'] as $object) {
                    $errors = $this->laravelModeErrors($mode, $spec, 'empty object key', '{"' . $name . '":' . $object . '}');
                    $this->assertContains($name . '.zebu', array_keys($errors), $mode->value . ' ' . $name . ' ' . $object . ': ' . json_encode($errors));
                }
            }
        }
    }

    /**
     * Laravel mode builds the DTO from the validated array, and a null the rules let through must stay
     * null there: `oneOf: [{$ref: Saffron}]` with a nullable array alias was read back as `[]`.
     */
    public function testLaravelKeepsTheNullOfANullableArrayAliasUnionMember(): void
    {
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Saffron' => ['type' => 'array', 'nullable' => true],
                'Probe' => [
                    'type' => 'object',
                    'required' => ['pink'],
                    'properties' => ['pink' => ['oneOf' => [['$ref' => '#/components/schemas/Saffron']]]],
                ],
            ]],
        ];
        $fqcn = $this->generate($spec, $this->namespaceFor(GenerationMode::Laravel, 'nullable array alias member'), 'laravel');

        $dto = call_user_func([$fqcn, 'fromValidated'], ['pink' => null]);

        $this->assertIsObject($dto);
        $this->assertNull(call_user_func([$dto, 'getPink']));
    }

    /**
     * The item of an array alias written `{$ref: Circle, properties: {tail: …}}` is both sides on the
     * way back out too: the runtime built the bare `Circle` and wrote `[{}]` for a `tail` it dropped.
     */
    public function testRuntimeWritesBackBothSidesOfAnAliasItemBesideItsReference(): void
    {
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Circle' => ['type' => 'object', 'properties' => ['hue' => ['type' => 'integer']]],
                'Ring' => [
                    'type' => 'array',
                    'items' => ['$ref' => '#/components/schemas/Circle', 'properties' => ['tail' => ['type' => 'string']]],
                ],
                'Probe' => ['type' => 'object', 'properties' => ['fox' => ['$ref' => '#/components/schemas/Ring']]],
            ]],
        ];

        $this->assertSame(
            expected: '{"fox":[{"hue":1,"tail":"a"}]}',
            actual: $this->runtimeRoundTrip($spec, 'alias item beside its reference', '{"fox":[{"hue":1,"tail":"a"}]}'),
        );
    }

    /**
     * Unions the runtime read wrong while the other modes held: a class branch of its own (an inline
     * object, a `$ref` with keys beside it, an `allOf` merged into one object) beside an `array` member,
     * which took the JSON object as a map so the class was never built; `[]` against a class branch
     * beside a list member that refuses it; a list read as an object by `{type: object}` inside an
     * `allOf` branch; an inline discriminator over members that overlap; and a member two discriminated
     * component unions share. Each case is a whole `components.schemas` map with `Probe` as the root.
     *
     * @param array<string, array<string, mixed>> $schemas
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise
     * @param list<GenerationMode> $skippedModes modes that refuse to generate the shape, named beside the case
     */
    #[DataProvider('runtimeUnionShapeProvider')]
    public function testRuntimeUnionShapesValidateInEveryMode(
        array $schemas,
        array $payloads,
        array $diverging = [],
        array $skippedModes = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => $schemas],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'runtime union shape ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
                skippedModes: $skippedModes,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, array<string, mixed>>, 1: array<string, bool>, 2?: array<string, array<string, bool|null>>, 3?: list<GenerationMode>}>
     */
    public static function runtimeUnionShapeProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $probe = static fn(array $fox): array => ['type' => 'object', 'properties' => ['fox' => $fox]];
        $numberCircle = ['type' => 'object', 'properties' => ['hue' => ['type' => 'number']]];
        $stringCircle = ['type' => 'object', 'properties' => ['hue' => ['type' => 'string']]];

        yield 'a $ref with keys beside it, beside an array member' => [
            [
                'Probe' => $probe(['anyOf' => [$ref('Circle') + ['properties' => ['tail' => ['type' => 'number']]], ['type' => 'array']]]),
                'Circle' => $numberCircle,
            ],
            [
                '{"fox":{"hue":{"zz":1}}}' => false,
                '{"fox":{"hue":null}}' => false,
                '{"fox":{"tail":"x"}}' => false,
                '{"fox":{"hue":2,"tail":1}}' => true,
                '{"fox":[1]}' => true,
            ],
        ];
        yield 'a bare $ref beside an array member' => [
            ['Probe' => $probe(['anyOf' => [$ref('Circle'), ['type' => 'array']]]), 'Circle' => $numberCircle],
            ['{"fox":{"hue":null}}' => false, '{"fox":{"hue":2}}' => true, '{"fox":[1]}' => true],
        ];
        yield 'an inline object naming an enum component, beside an array member' => [
            [
                'Probe' => $probe(['anyOf' => [
                    ['type' => 'integer'],
                    ['type' => 'object', 'properties' => ['hue' => $ref('Size')]],
                    ['type' => 'array'],
                ]]),
                'Size' => ['type' => 'integer', 'enum' => [1]],
            ],
            [
                '{"fox":{"hue":{"zz":1}}}' => false,
                '{"fox":{"hue":2}}' => false,
                '{"fox":{"hue":1}}' => true,
                '{"fox":3}' => true,
                '{"fox":[1]}' => true,
            ],
        ];
        // A nested union holds its object member as the raw array: the spelled-out member is all that
        // checks it, and an enum component a property names has to arrive there as its members — with a
        // `description` or `title` beside the `$ref` as much as without one.
        $walrusObject = static fn(array $walrus): array => [
            'type' => 'object',
            'required' => ['walrus'],
            'properties' => ['walrus' => $walrus],
        ];
        $stringList = ['type' => 'array', 'items' => ['type' => 'string']];
        $ivory = ['type' => 'string', 'enum' => ['amber', 'teal']];
        $coral = ['type' => 'integer', 'enum' => [-10, -16]];
        yield 'a nested union object naming an enum component beside a description' => [
            [
                'Probe' => $probe(['anyOf' => [
                    ['oneOf' => [$walrusObject(['description' => 'heron'] + $ref('Ivory')), ['type' => 'string']]],
                    $stringList,
                ]]),
                'Ivory' => $ivory,
            ],
            ['{"fox":{"walrus":"zzq"}}' => false, '{"fox":{"walrus":5}}' => false, '{"fox":{"walrus":"amber"}}' => true, '{"fox":"x"}' => true, '{"fox":["x"]}' => true],
        ];
        yield 'a nested union object naming a bare enum component' => [
            [
                'Probe' => $probe(['anyOf' => [['oneOf' => [$walrusObject($ref('Ivory')), ['type' => 'string']]], $stringList]]),
                'Ivory' => $ivory,
            ],
            ['{"fox":{"walrus":"zzq"}}' => false, '{"fox":{"walrus":5}}' => false, '{"fox":{"walrus":"teal"}}' => true, '{"fox":["x"]}' => true],
        ];
        yield 'a nested union of two objects, one naming an enum component beside a title' => [
            [
                'Probe' => $probe(['anyOf' => [
                    ['oneOf' => [
                        [
                            'type' => 'object',
                            'required' => ['walrus', 'crane'],
                            'properties' => ['walrus' => ['type' => 'integer'], 'crane' => ['type' => 'string']],
                        ],
                        $walrusObject(['title' => 'Heron'] + $ref('Coral')),
                    ]],
                    $stringList,
                ]]),
                'Coral' => $coral,
            ],
            [
                '{"fox":{"walrus":"zzq"}}' => false,
                '{"fox":{"walrus":7}}' => false,
                '{"fox":{"walrus":-10}}' => true,
                '{"fox":{"walrus":7,"crane":"c"}}' => true,
                '{"fox":{"walrus":-10,"crane":"c"}}' => false,
                '{"fox":["x"]}' => true,
                '{"fox":[1]}' => false,
            ],
        ];
        yield 'a nested union of two objects, one naming a bare enum component' => [
            [
                'Probe' => $probe(['anyOf' => [
                    ['oneOf' => [
                        [
                            'type' => 'object',
                            'required' => ['walrus', 'crane'],
                            'properties' => ['walrus' => ['type' => 'integer'], 'crane' => ['type' => 'string']],
                        ],
                        $walrusObject($ref('Coral')),
                    ]],
                    $stringList,
                ]]),
                'Coral' => $coral,
            ],
            [
                '{"fox":{"walrus":"zzq"}}' => false,
                '{"fox":{"walrus":7}}' => false,
                '{"fox":{"walrus":-16}}' => true,
                // Only the first member matches: the built first class was judged against the second
                // member's spelling, whose `required: [walrus]` alone it met.
                '{"fox":{"walrus":7,"crane":"c"}}' => true,
                '{"fox":{"walrus":-10,"crane":"c"}}' => false,
                '{"fox":["x"]}' => true,
                '{"fox":[1]}' => false,
            ],
        ];
        yield 'a flat union of the same two objects beside an array member' => [
            [
                'Probe' => $probe(['oneOf' => [
                    [
                        'type' => 'object',
                        'required' => ['walrus', 'crane'],
                        'properties' => ['walrus' => ['type' => 'integer'], 'crane' => ['type' => 'string']],
                    ],
                    $walrusObject($ref('Coral')),
                    $stringList,
                ]]),
                'Coral' => $coral,
            ],
            [
                '{"fox":{"walrus":"zzq"}}' => false,
                '{"fox":{"walrus":7}}' => false,
                '{"fox":{"walrus":-16}}' => true,
                '{"fox":{"walrus":7,"crane":"c"}}' => true,
                '{"fox":{"walrus":-10,"crane":"c"}}' => false,
                '{"fox":["x"]}' => true,
                '{"fox":[1]}' => false,
            ],
        ];
        yield 'an inline object with an inline enum, beside an array member' => [
            ['Probe' => $probe(['anyOf' => [
                ['type' => 'array'],
                ['type' => 'number'],
                ['type' => 'object', 'properties' => ['hue' => ['type' => 'integer', 'enum' => [10]]]],
            ]])],
            ['{"fox":{"hue":-20}}' => false, '{"fox":{"hue":10}}' => true, '{"fox":2.5}' => true, '{"fox":[1]}' => true],
        ];
        yield 'the same without the array member' => [
            ['Probe' => $probe(['anyOf' => [
                ['type' => 'number'],
                ['type' => 'object', 'properties' => ['hue' => ['type' => 'integer', 'enum' => [10]]]],
            ]])],
            ['{"fox":{"hue":-20}}' => false, '{"fox":{"hue":10}}' => true, '{"fox":3}' => true],
        ];
        yield 'an allOf of a $ref and an object, beside an array member' => [
            [
                'Probe' => $probe(['anyOf' => [
                    ['type' => 'array'],
                    ['allOf' => [$ref('Circle'), ['type' => 'object', 'properties' => ['tail' => ['type' => 'boolean']]]]],
                ]]),
                'Circle' => $stringCircle,
            ],
            [
                '{"fox":{"hue":null}}' => false,
                '{"fox":{"tail":3}}' => false,
                '{"fox":{"hue":"a","tail":true}}' => true,
                '{"fox":[1]}' => true,
            ],
        ];
        yield 'an inline object requiring a name it does not declare, beside an array member' => [
            ['Probe' => $probe(['anyOf' => [
                ['type' => 'object', 'properties' => ['cat' => ['type' => 'string', 'maxLength' => 1]], 'required' => ['dog']],
                ['type' => 'array'],
            ]])],
            ['{"fox":{"cat":"g","dog":1}}' => true, '{"fox":{"cat":"g"}}' => false, '{"fox":{"cat":"ga","dog":1}}' => false, '{"fox":[1]}' => true],
            [
                // Symfony holds the object in the `array` member, beside which the class is not checked.
                'symfony' => ['{"fox":{"cat":"g"}}' => null, '{"fox":{"cat":"ga","dog":1}}' => null],
            ],
        ];
        yield 'an empty list against a class beside a list member that refuses it' => [
            [
                'Probe' => $probe(['anyOf' => [['type' => 'array', 'minItems' => 1], $ref('Circle')]]),
                'Circle' => ['type' => 'object'] + $stringCircle,
            ],
            ['{"fox":[]}' => false, '{"fox":{}}' => true, '{"fox":[1]}' => true, '{"fox":{"hue":"a"}}' => true],
            [
                // The serializer builds `[]` into the class member; whether it does depends on its release.
                'symfony' => ['{"fox":[]}' => null],
                // The hydrator holds `{}` as the empty array, which the list member's `minItems` refuses.
                'yii3' => ['{"fox":{}}' => false],
            ],
        ];
        yield 'an empty list beside a number member' => [
            ['Probe' => $probe(['anyOf' => [['type' => 'array', 'minItems' => 1], ['type' => 'number']]])],
            ['{"fox":[]}' => false, '{"fox":[1]}' => true, '{"fox":2}' => true],
        ];
        yield 'a list against an object inside allOf, beside a list member' => [
            ['Probe' => $probe(['anyOf' => [
                ['type' => 'array', 'items' => ['type' => 'string', 'enum' => ['red']]],
                ['allOf' => [['type' => 'object']]],
            ]])],
            ['{"fox":["zzq"]}' => false, '{"fox":[[2]]}' => false, '{"fox":["red"]}' => true, '{"fox":{"a":1}}' => true, '{"fox":{}}' => true],
        ];
        yield 'a list against a plain object member, beside a list member' => [
            ['Probe' => $probe(['anyOf' => [
                ['type' => 'array', 'items' => ['type' => 'string', 'enum' => ['red']]],
                ['type' => 'object'],
            ]])],
            ['{"fox":["zzq"]}' => false, '{"fox":["red"]}' => true, '{"fox":{}}' => true],
        ];

        $shape = static fn(string $own): array => [
            'type' => 'object',
            'required' => ['kind'],
            'properties' => ['kind' => ['type' => 'string'], $own => ['type' => 'number']],
        ];
        $discriminated = [
            'oneOf' => [$ref('Circle'), $ref('Square')],
            'discriminator' => [
                'propertyName' => 'kind',
                'mapping' => ['circle' => '#/components/schemas/Circle', 'square' => '#/components/schemas/Square'],
            ],
        ];
        yield 'an inline discriminator over members that overlap' => [
            [
                'Probe' => ['type' => 'object', 'properties' => ['left' => $discriminated]],
                'Circle' => $shape('radius'),
                'Square' => $shape('side'),
            ],
            [
                '{"left":{"kind":"square","side":2}}' => true,
                '{"left":{"kind":"square","radius":1}}' => true,
                '{"left":{"kind":"circle","radius":1}}' => true,
                '{"left":{"kind":"circle","radius":"x"}}' => false,
                '{"left":{"kind":"tri"}}' => false,
            ],
        ];
        yield 'a member two discriminated unions share' => [
            [
                'Probe' => ['type' => 'object', 'properties' => [
                    'left' => $ref('ShapeA'),
                    'right' => $ref('ShapeB'),
                    'many' => ['type' => 'array', 'items' => $ref('ShapeA')],
                ]],
                'ShapeA' => $discriminated,
                'ShapeB' => $discriminated,
                'Circle' => $shape('radius'),
                'Square' => $shape('side'),
            ],
            [
                '{"left":{"kind":"circle","radius":1}}' => true,
                '{"right":{"kind":"square","side":1}}' => true,
                '{"many":[{"kind":"circle","radius":1},{"kind":"square","side":2}]}' => true,
                '{"left":{"kind":"circle","radius":"x"}}' => false,
                '{"many":[{"kind":"circle","radius":"x"}]}' => false,
                '{"left":{"kind":"tri"}}' => false,
            ],
            [],
            // laravel-data refuses to generate it: a member extends its morph base, and has one parent.
            [GenerationMode::LaravelData],
        ];
        yield 'a member of one discriminated union' => [
            [
                'Probe' => ['type' => 'object', 'properties' => ['left' => $ref('ShapeA')]],
                'ShapeA' => $discriminated,
                'Circle' => $shape('radius'),
                'Square' => $shape('side'),
            ],
            ['{"left":{"kind":"circle","radius":1}}' => true, '{"left":{"kind":"square","radius":1}}' => true, '{"left":{"kind":"circle","radius":"x"}}' => false, '{"left":{"kind":"tri"}}' => false],
        ];
    }

    /**
     * Union containers the symfony and yii3 constraints once let through: a numeric branch's keywords
     * beside a date branch and an array-typed member, the items of a list of a nullable `$ref` union,
     * a null item of a scalar list branch, and a container branch whose items `$ref` a union component.
     *
     * @param array<string, array<string, mixed>> $schemas the component schemas, `Probe` among them
     * @param array<string, bool|null> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise
     */
    #[DataProvider('unionContainerConstraintProvider')]
    public function testUnionContainerConstraintsValidateInEveryMode(
        string $openApiVersion,
        array $schemas,
        array $payloads,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => $openApiVersion,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => $schemas],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union container ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, array<string, mixed>>, 2: array<string, bool|null>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function unionContainerConstraintProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $probe = static fn(array $properties): array => ['type' => 'object', 'properties' => $properties];

        // A numeric branch beside a date branch and an array-typed member keeps its enum and bounds:
        // yii3 read the refused number as a Unix timestamp. The controls — no array member — already did.
        yield 'a numeric branch beside a date and an array-typed member' => [
            '3.1.0',
            [
                'Probe' => $probe([
                    'raven' => ['anyOf' => [['type' => 'number', 'enum' => [3]], ['type' => 'string', 'format' => 'date'], ['type' => 'object']]],
                    'heron' => ['anyOf' => [['type' => 'integer', 'minimum' => 3], ['type' => 'string', 'format' => 'date'], ['type' => 'object']]],
                    'egret' => ['anyOf' => [['type' => 'number', 'minimum' => 3], ['type' => 'string', 'format' => 'date-time'], ['type' => 'object']]],
                    'stork' => ['anyOf' => [['type' => 'number', 'enum' => [3]], ['type' => 'string', 'format' => 'date'], ['type' => 'array', 'items' => ['type' => 'string']]]],
                    'crane' => ['oneOf' => [['type' => 'string', 'format' => 'date'], ['type' => 'number', 'enum' => [5.5]], ['type' => 'object']]],
                    'plain' => ['anyOf' => [['type' => 'number', 'enum' => [3]], ['type' => 'string', 'format' => 'date']]],
                ]),
            ],
            [
                '{"raven":3}' => true,
                '{"raven":4}' => false,
                '{"raven":1}' => false,
                '{"raven":"2024-01-02"}' => true,
                '{"raven":"abc"}' => false,
                '{"heron":4}' => true,
                '{"heron":1}' => false,
                '{"egret":1.5}' => false,
                '{"egret":"2024-01-02T10:00:00+00:00"}' => true,
                '{"stork":["a"]}' => true,
                '{"stork":4}' => false,
                '{"stork":3}' => true,
                '{"crane":11}' => false,
                '{"crane":"2024-01-02"}' => true,
                '{"plain":4}' => false,
                '{"plain":3}' => true,
            ],
        ];

        // The controls of the next case: an integer branch's `maximum` beside a date and a boolean
        // member is carried by the raw check, and without the boolean member `#[ToString]` keeps the
        // integer from becoming a timestamp date.
        yield 'an integer branch beside a date: the carried bound and the guarded union' => [
            '3.0.3',
            [
                'Probe' => $probe([
                    'lemur' => ['oneOf' => [['type' => 'boolean'], ['type' => 'integer', 'maximum' => 5], ['type' => 'string', 'format' => 'date']]],
                    'otter' => ['oneOf' => [['type' => 'integer', 'multipleOf' => 5], ['type' => 'string', 'format' => 'date']]],
                ]),
            ],
            [
                '{"lemur":101}' => false,
                '{"lemur":5}' => true,
                '{"lemur":true}' => true,
                '{"lemur":"2024-01-02"}' => true,
                '{"otter":101}' => false,
                '{"otter":10}' => true,
                '{"otter":"2024-01-02"}' => true,
            ],
        ];

        // An integer branch beside a date and a boolean member keeps its `multipleOf` and its 3.0
        // `exclusiveMinimum: true` / `exclusiveMaximum: true` bounds: no `#[ToString]` guards that
        // union, yii3 read the refused integer as a Unix timestamp, and the raw check carried neither.
        yield 'an integer branch beside a date and a boolean: multipleOf and the 3.0 exclusive bounds' => [
            '3.0.3',
            [
                'Probe' => $probe([
                    'lemur' => ['oneOf' => [['type' => 'boolean'], ['type' => 'integer', 'multipleOf' => 5], ['type' => 'string', 'format' => 'date']]],
                    'otter' => ['oneOf' => [['type' => 'boolean'], ['type' => 'integer', 'minimum' => 5, 'exclusiveMinimum' => true], ['type' => 'string', 'format' => 'date']]],
                    'marten' => ['oneOf' => [['type' => 'boolean'], ['type' => 'integer', 'maximum' => 5, 'exclusiveMaximum' => true], ['type' => 'string', 'format' => 'date']]],
                    'badger' => ['oneOf' => [['type' => 'boolean'], ['type' => 'integer', 'multipleOf' => 2.5], ['type' => 'string', 'format' => 'date']]],
                ]),
            ],
            [
                '{"lemur":101}' => false,
                '{"lemur":10}' => true,
                '{"lemur":10.0}' => true,
                '{"lemur":true}' => true,
                '{"lemur":"2024-01-02"}' => true,
                '{"otter":3}' => false,
                '{"otter":5}' => false,
                '{"otter":6}' => true,
                '{"otter":false}' => true,
                '{"otter":"2024-01-02"}' => true,
                '{"marten":5}' => false,
                '{"marten":7}' => false,
                '{"marten":4}' => true,
                '{"marten":"2024-01-02"}' => true,
                '{"badger":5}' => true,
                '{"badger":7}' => false,
                '{"badger":"2024-01-02"}' => true,
            ],
            // Whether the serializer takes a whole float for `int` depends on its version.
            ['symfony' => ['{"lemur":10.0}' => null]],
        ];

        // The integer member beside a date may sit one level down — in a nested `anyOf` / `oneOf`, or
        // asserted through an `allOf`. yii3's raw check found only a direct branch, carried a bare
        // integer rule, and `#[ToDateTime]` read the refused integer as a timestamp date. `flat` is
        // the control that already refused.
        yield 'a nested integer member beside a date and a boolean' => [
            '3.1.0',
            [
                'Probe' => $probe([
                    'flat' => ['anyOf' => [['type' => 'string', 'format' => 'date'], ['type' => 'integer', 'maximum' => -30], ['type' => 'boolean']]],
                    'nested' => ['anyOf' => [['type' => 'string', 'format' => 'date'], ['anyOf' => [['type' => 'integer', 'maximum' => -30], ['type' => 'boolean']]]]],
                    'divided' => ['anyOf' => [['type' => 'string', 'format' => 'date'], ['oneOf' => [['type' => 'integer', 'multipleOf' => 5], ['type' => 'boolean']]]]],
                    'asserted' => ['anyOf' => [['type' => 'string', 'format' => 'date'], ['allOf' => [['type' => 'integer', 'maximum' => -30]]], ['type' => 'boolean']]],
                ]),
            ],
            [
                '{"flat":-25}' => false,
                '{"flat":-31}' => true,
                '{"nested":-25}' => false,
                '{"nested":-31}' => true,
                '{"nested":true}' => true,
                '{"nested":"2024-01-02"}' => true,
                '{"divided":-36}' => false,
                '{"divided":-35}' => true,
                '{"divided":"2024-01-02"}' => true,
                '{"asserted":-25}' => false,
                '{"asserted":-31}' => true,
                '{"asserted":false}' => true,
            ],
        ];

        // The 3.0 `exclusiveMinimum: true` of a nested integer member is the strict comparison.
        yield 'a nested integer member beside a date: the 3.0 exclusive bound' => [
            '3.0.3',
            [
                'Probe' => $probe([
                    'nested' => ['anyOf' => [['type' => 'string', 'format' => 'date'], ['anyOf' => [['type' => 'integer', 'minimum' => 5, 'exclusiveMinimum' => true], ['type' => 'boolean']]]]],
                ]),
            ],
            [
                '{"nested":5}' => false,
                '{"nested":3}' => false,
                '{"nested":6}' => true,
                '{"nested":true}' => true,
            ],
        ];

        // The items of a list of a `$ref` beside null are checked, as the map form and the
        // `allOf` + `nullable` items already were.
        $umber = ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['Umber']]]];
        $sepia = ['type' => 'object', 'required' => ['cat'], 'properties' => ['cat' => ['type' => 'integer'], 'kind' => ['type' => 'string', 'maxLength' => 2]]];
        yield 'a list of a $ref beside null' => [
            '3.1.0',
            [
                'Umber' => $umber,
                'Sepia' => $sepia,
                'Probe' => $probe([
                    'ocelot' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Umber'), ['type' => 'null']]]],
                    'margay' => ['type' => 'array', 'items' => ['anyOf' => [$ref('Sepia'), ['type' => 'null']]]],
                    'serval' => ['type' => 'object', 'additionalProperties' => ['oneOf' => [$ref('Umber'), ['type' => 'null']]]],
                ]),
            ],
            [
                '{"ocelot":[{"kind":"Saffron"}]}' => false,
                // Symfony 7.4.10 builds a scalar item into a requirement-free class (support matrix: "a
                // non-object ITEM of a list or map of DTOs"); a newer serializer refuses it.
                '{"ocelot":[5]}' => null,
                '{"ocelot":["x"]}' => null,
                '{"margay":[5]}' => false,
                '{"ocelot":[null]}' => true,
                '{"ocelot":[{"kind":"Umber"},null]}' => true,
                '{"ocelot":[]}' => true,
                '{"margay":[{}]}' => false,
                '{"margay":[{"cat":1,"kind":"abc"}]}' => false,
                '{"margay":[{"cat":1,"kind":"ab"}]}' => true,
                '{"serval":{"a":{"kind":"Saffron"}}}' => false,
                '{"serval":{"a":null}}' => true,
                '{"serval":{"a":{"kind":"Umber"}}}' => true,
            ],
            // README.support-matrix "a `null` ITEM of a nullable list of DTOs": laravel-data's
            // `#[DataCollectionOf]` built the null into an empty `Umber`, written back as `{}`.
            ['laravel-data' => [
                '{"ocelot":[null]}' => false,
                '{"ocelot":[{"kind":"Umber"},null]}' => false,
                '{"serval":{"a":null}}' => false,
            ]],
        ];
        // The same items behind a list component named beside a sibling keyword, the items a
        // discriminated union: yii3 held them as decoded arrays and checked none. The bare reference
        // and the inline list already were.
        $jade = ['oneOf' => [$ref('Umber'), $ref('Saffron')], 'discriminator' => ['propertyName' => 'kind']];
        yield 'a list component of a nullable union, beside a sibling keyword' => [
            '3.1.0',
            [
                'Umber' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['Umber']], 'cat' => ['type' => 'integer']]],
                'Saffron' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['Saffron']], 'egret' => ['type' => 'string', 'maxLength' => 0]]],
                'Jade' => $jade,
                'Ivory' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Jade'), ['type' => 'null']]], 'minItems' => 1],
                'Probe' => $probe([
                    'ocelot' => $ref('Ivory') + ['maxItems' => 2],
                    'bare' => $ref('Ivory'),
                    'inline' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Jade'), ['type' => 'null']]]],
                ]),
            ],
            [
                '{"ocelot":[{"kind":"Saffron","egret":"f"}]}' => false,
                '{"ocelot":[{"kind":"Saffron","egret":""}]}' => true,
                '{"ocelot":[{"kind":"Umber","cat":"x"}]}' => false,
                '{"ocelot":[{"kind":"Teal"}]}' => false,
                '{"ocelot":[null]}' => true,
                '{"ocelot":[]}' => false,
                '{"ocelot":[null,null,null]}' => false,
                '{"bare":[{"kind":"Saffron","egret":"f"}]}' => false,
                '{"bare":[{"kind":"Umber","cat":1}]}' => true,
                '{"inline":[{"kind":"Saffron","egret":"f"}]}' => false,
                '{"inline":[null]}' => true,
            ],
            // Support matrix: "a `null` ITEM of a nullable list of DTOs" — `DataCollectionOf` has no null case.
            ['laravel-data' => ['{"ocelot":[null]}' => false, '{"inline":[null]}' => false]],
        ];
        yield 'a list of an allOf $ref, nullable' => [
            '3.0.3',
            [
                'Umber' => $umber,
                'Probe' => $probe(['ocelot' => ['type' => 'array', 'items' => ['allOf' => [$ref('Umber')], 'nullable' => true]]]),
            ],
            [
                '{"ocelot":[{"kind":"Saffron"}]}' => false,
                '{"ocelot":[null]}' => true,
                '{"ocelot":[{"kind":"Umber"}]}' => true,
            ],
        ];

        // A null item of a scalar list or map branch beside a scalar branch is refused: inside `All`
        // symfony's `Type` takes null for valid.
        yield 'a null item of a scalar container branch' => [
            '3.1.0',
            [
                'Probe' => $probe([
                    'raven' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'boolean']], ['type' => 'string']]],
                    'heron' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'integer']], ['type' => 'string']]],
                    'egret' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'boolean']], ['type' => 'integer']]],
                    'stork' => ['anyOf' => [['type' => 'object', 'additionalProperties' => ['type' => 'boolean']], ['type' => 'string']]],
                    'crane' => ['anyOf' => [['type' => 'array', 'items' => ['type' => ['boolean', 'null']]], ['type' => 'string']]],
                ]),
            ],
            [
                '{"raven":[null]}' => false,
                '{"raven":[true]}' => true,
                '{"raven":"a"}' => true,
                '{"raven":[1]}' => false,
                '{"heron":[null]}' => false,
                '{"heron":[1]}' => true,
                '{"egret":[null]}' => false,
                '{"egret":[false]}' => true,
                '{"egret":2}' => true,
                '{"stork":{"a":null}}' => false,
                '{"stork":{"a":true}}' => true,
                '{"crane":[null]}' => true,
                '{"crane":[true]}' => true,
            ],
        ];
        yield 'a null item of a scalar container branch, 3.0 nullable items' => [
            '3.0.3',
            [
                'Probe' => $probe([
                    'raven' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'boolean', 'nullable' => true]], ['type' => 'string']]],
                    'heron' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'boolean']], ['type' => 'string']]],
                ]),
            ],
            [
                '{"raven":[null]}' => true,
                '{"raven":[true]}' => true,
                '{"raven":[1]}' => false,
                '{"heron":[null]}' => false,
            ],
        ];

        // A container branch of a property-level union whose items `$ref` a union component is held
        // raw, so its items are checked against the component's schema, not its class.
        $mauve = ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'ferret' => ['type' => 'string', 'pattern' => '^[a-c0-4]*$']]];
        $sienna = ['type' => 'object', 'required' => ['kind', 'plover'], 'properties' => ['kind' => ['enum' => ['square']], 'plover' => ['type' => 'boolean']]];
        $azure = [
            'anyOf' => [$ref('Mauve'), $ref('Sienna')],
            'discriminator' => ['propertyName' => 'kind', 'mapping' => ['circle' => '#/components/schemas/Mauve', 'square' => '#/components/schemas/Sienna']],
        ];
        $nullableAzure = ['oneOf' => [$ref('Azure'), ['type' => 'null']]];
        yield 'a container branch of $refs to a union component' => [
            '3.1.0',
            [
                'Mauve' => $mauve,
                'Sienna' => $sienna,
                'Azure' => $azure,
                'Amber' => ['oneOf' => [['type' => 'object', 'additionalProperties' => $nullableAzure], ['type' => 'null']]],
                'Coral' => $ref('Amber'),
                'Probe' => $probe([
                    'named' => $ref('Amber'),
                    'aliased' => $ref('Coral'),
                    'lynx' => ['oneOf' => [['type' => 'object', 'additionalProperties' => $nullableAzure], ['type' => 'null']]],
                    'puma' => ['oneOf' => [['type' => 'object', 'additionalProperties' => $nullableAzure], ['type' => 'string']]],
                    'tiger' => ['oneOf' => [['type' => 'array', 'items' => $nullableAzure], ['type' => 'null']]],
                    'jaguar' => ['oneOf' => [['type' => 'object', 'additionalProperties' => $ref('Azure')], ['type' => 'null']]],
                    'cougar' => ['type' => 'object', 'additionalProperties' => $ref('Azure')],
                    'otter' => ['anyOf' => [['type' => 'object', 'additionalProperties' => $nullableAzure], ['type' => 'array', 'items' => ['type' => 'string']], ['type' => 'integer']]],
                ]),
            ],
            [
                // No tag: the discriminator requires one, whichever member would take the rest.
                '{"lynx":{"ka":{"ferret":"010a11"}}}' => false,
                '{"named":{"ka":{"kind":"circle","ferret":"01"}}}' => true,
                '{"named":{"ka":{"kind":"circle","ferret":"zz"}}}' => false,
                '{"named":null}' => true,
                '{"aliased":{"ka":{"kind":"circle","ferret":"01"}}}' => true,
                '{"aliased":{"ka":{"kind":"circle","ferret":"zz"}}}' => false,
                '{"lynx":{"ka":{"kind":"circle","ferret":"01"}}}' => true,
                '{"lynx":{"ka":{"kind":"circle","ferret":"zz"}}}' => false,
                '{"lynx":{"ka":null}}' => true,
                '{"lynx":null}' => true,
                '{"puma":{"ka":{"kind":"circle","ferret":"01"}}}' => true,
                '{"puma":{"ka":{"kind":"circle","ferret":"zz"}}}' => false,
                '{"puma":"a"}' => true,
                '{"tiger":[{"kind":"circle","ferret":"01"}]}' => true,
                '{"tiger":[{"kind":"circle","ferret":"zz"}]}' => false,
                '{"tiger":[null]}' => true,
                '{"jaguar":{"ka":{"kind":"circle","ferret":"01"}}}' => true,
                '{"jaguar":{"ka":{"kind":"circle","ferret":"zz"}}}' => false,
                '{"jaguar":{"ka":{"kind":"square","plover":true}}}' => true,
                '{"cougar":{"ka":{"kind":"circle","ferret":"zz"}}}' => false,
                '{"cougar":{"ka":{"kind":"circle","ferret":"01"}}}' => true,
                '{"otter":{"ka":{"kind":"circle","ferret":"01"}}}' => true,
                '{"otter":{"ka":{"kind":"circle","ferret":"zz"}}}' => false,
                '{"otter":["a"]}' => true,
                '{"otter":3}' => true,
            ],
            // `lynx` and `tiger` are the map and list of `Azure` items beside null that `type: [object |
            // array, "null"]` spells, and laravel-data builds each item through `#[DataCollectionOf]`:
            // README.support-matrix, "a `null` ITEM of a nullable list of DTOs … a discriminated union's
            // included" — the generated guard refuses the null, as for the plain `{type: array, items:
            // {oneOf: [{$ref: Azure}, {type: null}]}}`. Held decoded behind the null union, it was judged.
            ['laravel-data' => ['{"lynx":{"ka":null}}' => null, '{"tiger":[null]}' => null]],
        ];
    }

    /**
     * Shapes the symfony and yii3 renderers and the interpreter tree once let through: a union member
     * written as a multi-part `allOf`, an enum member beside a class and a scalar, a `$ref` to a union
     * component of an object and an array, an optional `allOf`-wrapped inline object sent as null, and a
     * list of a discriminated union inside a null or scalar union. Every mode must give the document's
     * answer, and never crash.
     *
     * @param array<string, array<string, mixed>> $schemas the component schemas, `Probe` among them
     * @param array<string, bool> $payloads JSON payload => accepted
     * @param array<string, array<string, bool|null>> $diverging mode => the payloads that mode answers otherwise
     */
    #[DataProvider('rendererShapeProvider')]
    public function testRendererShapesValidateInEveryMode(
        string $openApiVersion,
        array $schemas,
        array $payloads,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => $openApiVersion,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => $schemas],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'renderer shape ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, array<string, mixed>>, 2: array<string, bool>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function rendererShapeProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $probe = static fn(array $properties): array => ['type' => 'object', 'properties' => $properties];

        // A union member written as an `allOf` of a type and a bound: the member is that type.
        $shortString = ['allOf' => [['type' => 'string'], ['maxLength' => 3]]];
        yield 'a multi-part allOf as the one union member' => [
            '3.0.3',
            ['Probe' => $probe(['zebu' => ['anyOf' => [$shortString]], 'lynx' => ['oneOf' => [$shortString]], 'panda' => $shortString])],
            [
                '{"zebu":true}' => false,
                '{"lynx":true}' => false,
                '{"zebu":2.5}' => false,
                '{"zebu":{"zz":1}}' => false,
                '{"panda":true}' => false,
                '{"zebu":"ab"}' => true,
                '{"lynx":"ab"}' => true,
                '{"zebu":"abcd"}' => false,
                '{}' => true,
            ],
        ];
        yield 'a multi-part allOf as the one union member, a format beside the type' => [
            '3.1.0',
            ['Probe' => $probe([
                'panda' => ['anyOf' => [['allOf' => [['format' => 'int64'], ['type' => 'integer']]]]],
                'tern' => ['type' => 'object', 'properties' => ['crane' => ['anyOf' => [['allOf' => [['format' => 'email'], ['type' => 'string']]]]]]],
            ])],
            [
                '{"panda":2.5}' => false,
                '{"panda":3}' => true,
                '{"tern":{"crane":{"zz":1}}}' => false,
                '{"tern":{"crane":"a@b.io"}}' => true,
            ],
        ];

        // An enum member beside a class and a scalar: the enum's backing value is a member too.
        $vole = ['type' => 'object', 'properties' => ['vole' => ['type' => 'string']]];
        $eight = ['type' => 'integer', 'enum' => [8]];
        yield 'an enum member beside a class and a scalar' => [
            '3.1.0',
            ['Probe' => $probe([
                'panda' => ['oneOf' => [['type' => 'string'], $eight, $vole]],
                'lynx' => ['oneOf' => [['type' => 'string'], $eight]],
                'heron' => ['oneOf' => [$eight, $vole]],
                'ibis' => ['oneOf' => [['type' => 'string'], ['type' => 'integer'], $vole]],
            ])],
            [
                '{"panda":8}' => true,
                '{"panda":9}' => false,
                '{"panda":"x"}' => true,
                '{"panda":{"vole":"a"}}' => true,
                '{"panda":{"vole":1}}' => false,
                '{"lynx":8}' => true,
                '{"heron":8}' => true,
                '{"heron":9}' => false,
                '{"ibis":8}' => true,
            ],
            // A scalar beside a class member is built into the class by older serializer releases —
            // the support matrix row "a scalar for a property typed as a generated class".
            ['symfony' => ['{"panda":9}' => null, '{"heron":9}' => null]],
        ];

        // A `$ref` to a union component of an object and an array: the object branch is checked as the
        // inline spelling's is.
        $kiwiBranch = $ref('Indigo') + ['properties' => ['kiwi' => ['type' => 'number', 'multipleOf' => 2]]];
        $tenBranch = ['type' => 'object', 'properties' => ['zebu' => ['type' => 'integer', 'enum' => [10]]]];
        yield 'a $ref to a union component of an object and an array' => [
            '3.1.0',
            [
                'Indigo' => ['type' => 'object', 'properties' => ['zebu' => ['type' => 'number']]],
                'Scarlet' => ['anyOf' => [$kiwiBranch, ['type' => 'array']]],
                'Ochre' => ['anyOf' => [['type' => 'array'], $tenBranch]],
                'Probe' => $probe([
                    'toucan' => $ref('Scarlet'),
                    'macaw' => ['anyOf' => [$kiwiBranch, ['type' => 'array']]],
                    'robin' => $ref('Ochre'),
                    'lark' => ['anyOf' => [['type' => 'array'], $tenBranch]],
                ]),
            ],
            [
                '{"toucan":{"zebu":{"zz":1}}}' => false,
                '{"toucan":{"zebu":"x"}}' => false,
                '{"toucan":{"kiwi":3}}' => false,
                '{"toucan":{"kiwi":null}}' => false,
                '{"toucan":{"kiwi":4,"zebu":1.5}}' => true,
                '{"toucan":[1,2]}' => true,
                '{"toucan":5}' => false,
                '{"macaw":{"kiwi":3}}' => false,
                '{"macaw":{"kiwi":4}}' => true,
                '{"robin":{"zebu":-20}}' => false,
                '{"robin":{"zebu":10}}' => true,
                '{"robin":[1,2]}' => true,
                '{"lark":{"zebu":-20}}' => false,
                '{"lark":{"zebu":10}}' => true,
            ],
        ];

        // An optional inline object wrapped in `allOf`, sent as null: refused like the bare object.
        foreach (['3.0.3', '3.1.0'] as $version) {
            yield 'an optional allOf-wrapped inline object sent as null, ' . $version => [
                $version,
                [
                    'Fern' => $vole,
                    'Probe' => $probe([
                        'lemur' => ['allOf' => [$vole]],
                        'gibbon' => ['allOf' => [['type' => 'object', 'properties' => []]]],
                        'civet' => $vole,
                        'pine' => $ref('Fern'),
                        'oak' => ['allOf' => [$ref('Fern')]],
                    ]),
                ],
                [
                    '{"lemur":null}' => false,
                    '{"gibbon":null}' => false,
                    '{"civet":null}' => false,
                    '{"pine":null}' => false,
                    '{"oak":null}' => false,
                    '{"lemur":{"vole":"a"}}' => true,
                    '{"lemur":{}}' => true,
                    '{"gibbon":{}}' => true,
                    '{}' => true,
                ],
            ];
        }

        // A list of a discriminated union inside a null or scalar union: the items are the union's.
        $shapeList = ['type' => 'array', 'items' => $ref('Shape')];
        $squareMinusOne = '[{"kind":"square","side":-1}]';
        yield 'a list of a discriminated union inside a null or scalar union' => [
            '3.1.0',
            [
                'Circle' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']]]],
                'Square' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['square']], 'side' => ['type' => 'number', 'minimum' => 0]],
                    'required' => ['kind'],
                ],
                'Shapes' => $shapeList,
                'Shape' => [
                    'oneOf' => [$ref('Circle'), $ref('Square')],
                    'discriminator' => [
                        'propertyName' => 'kind',
                        'mapping' => ['circle' => '#/components/schemas/Circle', 'square' => '#/components/schemas/Square'],
                    ],
                ],
                'Probe' => $probe([
                    'urchin' => $ref('Shapes'),
                    'quokka' => ['oneOf' => [$shapeList, ['type' => 'null']]],
                    'lynx' => ['oneOf' => [$shapeList, ['type' => 'integer']]],
                    'pika' => ['type' => ['array', 'null'], 'items' => $ref('Shape')],
                ]),
            ],
            [
                '{"quokka":' . $squareMinusOne . '}' => false,
                '{"quokka":[{"kind":"square","side":true}]}' => false,
                '{"quokka":[{"kind":null}]}' => false,
                '{"quokka":[{"kind":"oval"}]}' => false,
                '{"quokka":[{"kind":"square","side":1},{"kind":"circle"}]}' => true,
                '{"quokka":null}' => true,
                '{"lynx":' . $squareMinusOne . '}' => false,
                '{"lynx":[{"kind":"oval"}]}' => false,
                '{"lynx":[{"kind":"circle"}]}' => true,
                '{"lynx":3}' => true,
                '{"pika":' . $squareMinusOne . '}' => false,
                '{"urchin":' . $squareMinusOne . '}' => false,
            ],
        ];

        // A `$ref` union branch to a component that admits null itself: the union admits it too.
        // Beside it the controls — the reference as the whole property, a nullable scalar alias as
        // the branch — already did.
        foreach (['3.0.3' => ['type' => 'object', 'nullable' => true], '3.1.0' => ['type' => ['object', 'null']]] as $version => $nullableObject) {
            yield 'a $ref branch to a nullable object component, ' . $version => [
                $version,
                [
                    'Mauve' => $nullableObject + ['properties' => ['toucan' => ['type' => 'string']], 'required' => ['toucan']],
                    'Tint' => $version === '3.0.3' ? ['type' => 'string', 'nullable' => true] : ['type' => ['string', 'null']],
                    'Probe' => $probe([
                        'kiwi' => ['anyOf' => [$ref('Mauve'), ['type' => 'string']]],
                        'pear' => ['oneOf' => [$ref('Mauve'), ['type' => 'integer']]],
                        'whole' => $ref('Mauve'),
                        'plum' => ['anyOf' => [$ref('Tint'), ['type' => 'integer']]],
                    ]),
                ],
                [
                    '{"kiwi":null}' => true,
                    '{"kiwi":{"toucan":"x"}}' => true,
                    '{"kiwi":"a"}' => true,
                    '{"kiwi":5}' => false,
                    '{"kiwi":{}}' => false,
                    '{"pear":null}' => true,
                    '{"pear":3}' => true,
                    '{"pear":"a"}' => false,
                    '{"whole":null}' => true,
                    '{"plum":null}' => true,
                    '{"plum":true}' => false,
                ],
                // The serializer tries the class member first, and 7.4.10 collects its missing
                // `toucan` under `#[MapRequestPayload]` — README.support-matrix, "a scalar for a
                // property typed as a generated class". Newer releases differ, so unasserted.
                ['symfony' => ['{"kiwi":"a"}' => null, '{"pear":3}' => null]],
            ];
        }

        // An inline object branch beside a `$ref` to a list: the branch checks its properties —
        // an enum and a `$ref` to an enum — as it does beside an inline list.
        yield 'an inline object branch beside a $ref to a list' => [
            '3.0.3',
            [
                'Crate' => ['type' => 'array'],
                'Teal' => ['type' => 'integer', 'enum' => [5, 2]],
                'Probe' => $probe([
                    'bison' => ['oneOf' => [['type' => 'object', 'properties' => ['egret' => ['type' => 'integer', 'enum' => [-18]]]], $ref('Crate')]],
                    'lynx' => ['anyOf' => [$ref('Crate'), ['type' => 'object', 'properties' => ['yak' => $ref('Teal')]]]],
                    'heron' => ['oneOf' => [['type' => 'object', 'properties' => ['egret' => ['type' => 'integer', 'enum' => [-18]]]], ['type' => 'array']]],
                    // Requiring a name it does not declare, the branch stays spelled out in runtime:
                    // the spelling keeps the enums of its properties.
                    'okapi' => ['anyOf' => [
                        ['type' => 'object', 'required' => ['zz'], 'properties' => ['egret' => ['type' => 'integer', 'enum' => [-18]], 'yak' => $ref('Teal')]],
                        $ref('Crate'),
                    ]],
                ]),
            ],
            [
                '{"bison":{"egret":-84}}' => false,
                '{"bison":{"egret":-18}}' => true,
                '{"bison":[1,2]}' => true,
                '{"bison":5}' => false,
                '{"lynx":{"yak":true}}' => false,
                '{"lynx":{"yak":7}}' => false,
                '{"lynx":{"yak":5}}' => true,
                '{"lynx":[]}' => true,
                '{"heron":{"egret":-84}}' => false,
                '{"heron":{"egret":-18}}' => true,
                '{"okapi":{"zz":1,"egret":-84}}' => false,
                '{"okapi":{"zz":1,"yak":7}}' => false,
                '{"okapi":[1]}' => true,
            ],
        ];

        // A list item or map value that is a bare `$ref` to a component admitting null admits null
        // too — directly, through an alias, and for a free-form object or a map component. The
        // controls — the reference as the whole property, a nullable scalar item, the null spelled on
        // the item — already did.
        foreach (['3.0.3' => ['type' => 'object', 'nullable' => true], '3.1.0' => ['type' => ['object', 'null']]] as $version => $nullableObject) {
            yield 'a container of $refs to a nullable component, ' . $version => [
                $version,
                [
                    'Crate' => $nullableObject + ['properties' => ['lid' => ['type' => 'string']]],
                    'Azure' => $ref('Crate'),
                    'Loose' => $nullableObject,
                    'Hue' => $nullableObject + ['additionalProperties' => ['type' => 'string']],
                    'Word' => $version === '3.0.3' ? ['type' => 'string', 'nullable' => true] : ['type' => ['string', 'null']],
                    'Probe' => $probe([
                        'boxes' => ['type' => 'array', 'items' => $ref('Crate')],
                        'bag' => ['type' => 'object', 'additionalProperties' => $ref('Crate')],
                        'many' => ['type' => 'array', 'items' => $ref('Azure')],
                        'loose' => ['type' => 'array', 'items' => $ref('Loose')],
                        'maps' => ['type' => 'array', 'items' => $ref('Hue')],
                        'tags' => ['type' => 'array', 'items' => $ref('Word')],
                        'box' => $ref('Crate'),
                        'one' => $ref('Azure'),
                        'spelled' => ['type' => 'array', 'items' => $ref('Crate') + ['nullable' => true]],
                    ]),
                ],
                [
                    '{"boxes":[null]}' => true,
                    '{"boxes":[{"lid":"a"},null]}' => true,
                    '{"boxes":[{"lid":1}]}' => false,
                    '{"bag":{"k":null}}' => true,
                    '{"bag":{"k":{"lid":"a"}}}' => true,
                    '{"bag":{"k":{"lid":1}}}' => false,
                    '{"many":[null]}' => true,
                    '{"many":[{"lid":"a"}]}' => true,
                    '{"many":[{"lid":1}]}' => false,
                    '{"loose":[null]}' => true,
                    '{"loose":[{"x":1}]}' => true,
                    '{"loose":[5]}' => false,
                    '{"maps":[null]}' => true,
                    '{"maps":[{"a":"b"}]}' => true,
                    '{"maps":[{"a":1}]}' => false,
                    '{"tags":[null,"a"]}' => true,
                    '{"tags":[1]}' => false,
                    '{"box":null}' => true,
                    '{"one":null}' => true,
                    '{"spelled":[null]}' => true,
                    '{"spelled":[{"lid":1}]}' => false,
                ],
                // README.support-matrix "a `null` ITEM of a nullable list of DTOs": laravel-data's
                // `#[DataCollectionOf]` built the null into an empty `Crate`, written back as `{}`.
                ['laravel-data' => [
                    '{"boxes":[null]}' => false,
                    '{"boxes":[{"lid":"a"},null]}' => false,
                    '{"bag":{"k":null}}' => false,
                    '{"many":[null]}' => false,
                    '{"spelled":[null]}' => false,
                ]],
            ];
        }

        // A map value that is a union of a free-form object, alone or beside null, is an object —
        // not the items-less list a bare `array` stands for. The controls — the plain object value,
        // the `allOf` of it, the union as a list item — already were.
        yield 'a map value that is a union of a free-form object' => [
            '3.1.0',
            [
                'Probe' => $probe([
                    'bag' => ['type' => 'object', 'additionalProperties' => ['anyOf' => [['type' => 'object']]]],
                    'm1' => ['type' => 'object', 'additionalProperties' => ['oneOf' => [['type' => 'object']]]],
                    'm3' => ['type' => 'object', 'additionalProperties' => ['anyOf' => [['type' => 'object'], ['type' => 'null']]]],
                    'plain' => ['type' => 'object', 'additionalProperties' => ['type' => 'object']],
                    'wrapped' => ['type' => 'object', 'additionalProperties' => ['allOf' => [['type' => 'object']]]],
                    'list' => ['type' => 'array', 'items' => ['anyOf' => [['type' => 'object']]]],
                    'whole' => ['anyOf' => [['type' => 'object']]],
                ]),
            ],
            [
                '{"bag":{"k":{"x":1}}}' => true,
                '{"bag":{"k":{}}}' => true,
                '{"bag":{"k":5}}' => false,
                '{"bag":{"k":null}}' => false,
                '{"m1":{"k":{"x":1}}}' => true,
                '{"m1":{"k":"a"}}' => false,
                '{"m3":{"k":{"x":1}}}' => true,
                '{"m3":{"k":null}}' => true,
                '{"m3":{"k":"a"}}' => false,
                '{"plain":{"k":{"x":1}}}' => true,
                '{"wrapped":{"k":{"x":1}}}' => true,
                '{"list":[{"x":1}]}' => true,
                '{"plain":{"k":{}}}' => true,
                '{"list":[{}]}' => true,
                '{"whole":{}}' => true,
                '{"list":[5]}' => false,
            ],
        ];
        // A list of a scalar UNION component wrapped in a one-branch `anyOf`, an `allOf`, or a `oneOf`
        // beside null was typed `array<Spoke>` — a class never written. Symfony refused every list at
        // deserialization (`must be one of "Spoke[]"`), runtime died on `unknown type "Spoke"` for the
        // `allOf`. The bare list (`wagon`) and a list of a scalar ALIAS (`raft`) already worked.
        $spokes = ['type' => 'array', 'items' => $ref('Spoke')];
        yield 'a wrapped list of a scalar union component' => [
            '3.1.0',
            [
                'Probe' => $probe([
                    'wagon' => $spokes,
                    'cart' => ['anyOf' => [$spokes]],
                    'sled' => ['allOf' => [$spokes]],
                    'barge' => ['oneOf' => [$spokes, ['type' => 'null']]],
                    'raft' => ['anyOf' => [['type' => 'array', 'items' => $ref('Plank')]]],
                ]),
                'Spoke' => ['oneOf' => [['type' => 'string'], ['type' => 'integer']]],
                'Plank' => ['type' => 'string'],
            ],
            [
                '{"wagon":["a",3]}' => true,
                '{"wagon":[true]}' => false,
                '{"cart":["a",3]}' => true,
                '{"cart":[true]}' => false,
                '{"sled":["a",3]}' => true,
                '{"sled":[true]}' => false,
                '{"barge":["a",3]}' => true,
                '{"barge":null}' => true,
                '{"barge":[true]}' => false,
                '{"raft":["a"]}' => true,
                '{"raft":[3]}' => false,
            ],
        ];
        // The same for a MAP of a scalar union component: wrapped in a one-member `allOf`, its values
        // were typed `array<string, Spoke>` — a class never written. Runtime refused to load the DTO,
        // the other modes named the missing class. The bare map (`hamper`) already worked.
        $spokeMap = ['type' => 'object', 'additionalProperties' => $ref('Spoke')];
        yield 'a wrapped map of a scalar union component' => [
            '3.1.0',
            [
                'Probe' => $probe([
                    'hamper' => $spokeMap,
                    'crate' => ['allOf' => [$spokeMap]],
                    'chest' => ['allOf' => [['allOf' => [$spokeMap]]]],
                ]),
                'Spoke' => ['oneOf' => [['type' => 'string'], ['type' => 'integer']]],
            ],
            [
                '{"hamper":{"a":"x","b":3}}' => true,
                '{"hamper":{"a":true}}' => false,
                '{"crate":{"a":"x","b":3}}' => true,
                '{"crate":{"a":true}}' => false,
                '{"chest":{"a":"x","b":3}}' => true,
                '{"chest":{"a":true}}' => false,
            ],
        ];
    }

    /**
     * An overlapping `oneOf` of two inline objects whose matched member carries a keyword only the
     * interpreter checks — `enum` beside `minimum`, a `not` — is still counted by the enclosing DTO. The
     * member class then had an interpreter of its own, and Symfony's skipped the whole property schema for
     * such a nested DTO, the `oneOf` around it with it: `{}` matched both branches and passed. With a member
     * whose keywords are all attributes (`lark`) the enclosing DTO judged the union, and refused.
     */
    public function testAnOverlappingOneOfIsCountedAroundAMemberThatChecksItself(): void
    {
        $urchin = ['type' => 'object', 'properties' => ['urchin' => ['type' => 'integer']]];
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'koala' => ['oneOf' => [
                ['type' => 'object', 'properties' => ['newt' => ['type' => 'integer', 'enum' => [55], 'minimum' => 55]]],
                $urchin,
            ]],
            'heron' => ['oneOf' => [
                ['type' => 'object', 'properties' => ['newt' => ['type' => 'integer']], 'not' => ['required' => ['zzz']]],
                $urchin,
            ]],
            // The `not` names a declared property, which the hydrated member does carry.
            'ibis' => ['oneOf' => [
                ['type' => 'object', 'properties' => ['newt' => ['type' => 'integer']], 'not' => ['required' => ['newt']]],
                $urchin,
            ]],
            // The control: `minimum` alone is an attribute, the member has no interpreter to defer to.
            'lark' => ['oneOf' => [
                ['type' => 'object', 'properties' => ['newt' => ['type' => 'integer', 'minimum' => 55]]],
                $urchin,
            ]],
        ]];

        $payloads = [];
        foreach (['koala', 'heron', 'lark'] as $name) {
            $payloads['{"' . $name . '":{"stray":"hd"}}'] = false;
            $payloads['{"' . $name . '":{}}'] = false;
            $payloads['{"' . $name . '":{"urchin":2}}'] = false;
            $payloads['{"' . $name . '":{"newt":55}}'] = false;
        }
        $payloads['{"heron":{"zzz":1}}'] = true;
        $payloads['{"heron":{"zzz":1,"urchin":"x"}}'] = false;
        $payloads['{"ibis":{"newt":1}}'] = true;
        $payloads['{"ibis":{}}'] = false;
        $payloads['{"ibis":{"newt":1,"urchin":"x"}}'] = false;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'overlapping oneOf around a self-checking member',
                payloads: $payloads,
                // `zzz` is no property of either member: the serializer leaves it behind before any
                // validator runs, so the hydrated member reads as `{}` and matches both branches — the
                // boundary of the "sees only the keys the class declares" divergences.
                // `{"newt":1}` may match a member whose class the serializer does not try first: README
                // .support-matrix, "an object only a member whose class name does not sort first … accepts".
                diverging: ['symfony' => ['{"heron":{"zzz":1}}' => null, '{"ibis":{"newt":1}}' => null]],
            ),
        );
    }

    /**
     * An inline object branch spelled with `allOf` keeps its constraints in a union yii3 holds as a raw
     * array — one nested in an outer nullable union, or one beside a member that is `allOf: [{type:
     * string}, {$ref: Indigo}]`. No class is built for such a branch, yet the interpreter reduced it to a
     * branch "the class checks", or to a bare `{type: object}`, or moved its `enum` into a PHP enum type
     * the array never holds: any object passed. The same branches without `allOf`, and the unions whose
     * property is hydrated into the member class, always refused.
     *
     * The same two shapes in the other modes: Symfony holds `oneOf: [{type: object, required: [gecko]},
     * {…allOf…}]` as `?array` and reduced the `allOf` branch the same way (`{}` passed, `{"gecko": 1}`
     * matched twice); nested in the nullable wrapper, the free-form member went unseen, the class stayed
     * in the type — Symfony refused `{"gecko": 1}` for the class's `crane`, both Laravel modes died in
     * its constructor.
     *
     * @param array<string, mixed> $spec
     * @param array<string, bool|null> $payloads
     */
    #[DataProvider('inlineAllOfBranchOfArrayHeldUnionProvider')]
    public function testAnInlineAllOfBranchOfAnArrayHeldUnionKeepsItsConstraints(array $spec, array $payloads): void
    {
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'inline allOf branch ' . md5((string)json_encode($spec)), payloads: $payloads),
        );
    }

    /**
     * @return iterable<string, array{array<string, mixed>, array<string, bool|null>}>
     */
    public static function inlineAllOfBranchOfArrayHeldUnionProvider(): iterable
    {
        $spec = static fn(array $properties, array $components = []): array => [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => ['Probe' => ['type' => 'object', 'properties' => $properties]] + $components],
        ];
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $indigo = ['Indigo' => ['type' => 'string']];
        $crimson = ['Crimson' => ['type' => 'integer', 'multipleOf' => 5, 'enum' => [0, -20, -10]]];
        $craneBranch = ['type' => 'object', 'allOf' => [['type' => 'object', 'properties' => ['crane' => ['type' => 'string']], 'required' => ['crane']]]];
        $ravenBranch = ['type' => 'object', 'allOf' => [['type' => 'object', 'properties' => ['raven' => ['type' => 'string', 'enum' => ['blue', 'amber']]]]]];
        $yakBranch = ['type' => 'object', 'allOf' => [['type' => 'object', 'properties' => ['yak' => $ref('Crimson')]]]];

        yield 'nested in a nullable union' => [
            $spec(['lynx' => ['oneOf' => [['oneOf' => [['type' => 'object', 'required' => ['gecko']], $craneBranch]], ['type' => 'null']]]]),
            [
                '{"lynx":{}}' => false,
                '{"lynx":{"crane":1}}' => false,
                '{"lynx":{"hyena":null}}' => false,
                '{"lynx":{"gecko":1,"crane":"a"}}' => false,
                '{"lynx":{"gecko":1}}' => true,
                '{"lynx":{"crane":"a"}}' => true,
                '{"lynx":null}' => true,
            ],
        ];
        yield 'nested in a nullable union, control without the outer union' => [
            $spec(['lynx' => ['oneOf' => [['type' => 'object', 'required' => ['gecko']], $craneBranch]]]),
            [
                '{"lynx":{}}' => false,
                '{"lynx":{"crane":1}}' => false,
                '{"lynx":{"gecko":1}}' => true,
                '{"lynx":{"crane":"a"}}' => true,
            ],
        ];
        yield 'beside an allOf string member, enum property' => [
            $spec(['lynx' => ['anyOf' => [$ravenBranch, ['allOf' => [['type' => 'string', 'enum' => ['violet', 'blue']], $ref('Indigo')]]]]], $indigo),
            [
                '{"lynx":{"raven":"zzq"}}' => false,
                '{"lynx":{"raven":"blue"}}' => true,
                '{"lynx":"violet"}' => true,
                '{"lynx":"amber"}' => false,
            ],
        ];
        yield 'beside an allOf string member, control with a plain string member' => [
            $spec(['sable' => ['anyOf' => [$ravenBranch, ['type' => 'string', 'enum' => ['violet', 'blue']]]]]),
            [
                '{"sable":{"raven":"zzq"}}' => false,
                '{"sable":{"raven":"blue"}}' => true,
                '{"sable":"violet"}' => true,
            ],
        ];
        yield 'beside an allOf string member, referenced enum property' => [
            $spec(['sable' => ['anyOf' => [$yakBranch, ['allOf' => [['type' => 'string'], $ref('Indigo')]]]]], $crimson + $indigo),
            [
                '{"sable":{"yak":7}}' => false,
                '{"sable":{"yak":2.5}}' => false,
                '{"sable":{"yak":-20}}' => true,
                '{"sable":"x"}' => true,
            ],
        ];
        yield 'an allOf branch of a nested anyOf' => [
            $spec(['gecko' => ['anyOf' => [
                ['anyOf' => [
                    ['allOf' => [['type' => 'object'], ['type' => 'object', 'properties' => ['zebu' => ['minimum' => 3.5, 'type' => 'number']], 'required' => ['zebu']]]],
                    ['type' => 'string', 'enum' => ['red', 'blue', 'cyan']],
                    ['type' => 'object', 'properties' => ['okapi' => [], 'zebu' => ['type' => 'number', 'minimum' => 3.5]], 'required' => ['zebu', 'okapi']],
                ]],
                ['type' => 'null'],
            ]]]),
            [
                '{"gecko":{}}' => false,
                '{"gecko":{"okapi":""}}' => false,
                '{"gecko":{"zebu":3}}' => false,
                '{"gecko":{"zebu":[2]}}' => false,
                '{"gecko":"green"}' => false,
                '{"gecko":{"zebu":4}}' => true,
                '{"gecko":{"zebu":4,"okapi":1}}' => true,
                '{"gecko":"red"}' => true,
                '{"gecko":null}' => true,
            ],
        ];
    }

    /**
     * An inline undiscriminated `oneOf` / `anyOf` of two object members is checked against its members,
     * the way a union component of the same two is: a value matching neither is refused, and one
     * matching the second member is accepted and held whole. yii3 built the FIRST class from any
     * object and checked nothing — `{}` passed, and a Teal arrived as an Olive with `dog` dropped.
     * Symfony's serializer builds the first member too and, under `#[MapRequestPayload]`, collects
     * that member's missing properties instead of trying the next (README.support-matrix, "an object
     * only a member whose class name does not sort first … accepts"); the answer is the serializer's, so
     * unasserted. The laravel modes have a table of their own.
     */
    public function testAnInlineUndiscriminatedUnionOfObjectsIsCheckedAgainstItsMembers(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $olive = ['type' => 'object', 'required' => ['cat'], 'properties' => ['cat' => ['type' => 'string']]];
        $teal = ['type' => 'object', 'required' => ['dog'], 'properties' => ['dog' => ['type' => 'integer']]];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Olive' => $olive,
                'Teal' => $teal,
                'Zebra' => ['type' => 'object', 'required' => ['stripe'], 'properties' => ['stripe' => ['type' => 'integer']]],
                'Ant' => ['type' => 'object', 'required' => ['leg'], 'properties' => ['leg' => ['type' => 'integer']]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'bison' => ['anyOf' => [$ref('Olive'), $ref('Teal')]],
                    // Declared `Zebra` first, but `Ant` sorts first by NAME — the order symfony tries.
                    'zebu' => ['oneOf' => [$ref('Zebra'), $ref('Ant')]],
                    'heron' => ['oneOf' => [$ref('Olive'), $ref('Teal')]],
                    'okapi' => ['anyOf' => [$olive, $ref('Teal')]],
                    // Two INLINE members: each is named apart, as `<Owner><Property>AnyOf1` and `…AnyOf2`.
                    'lynx' => ['anyOf' => [$olive, $teal]],
                    'puma' => ['oneOf' => [$olive, $teal]],
                    'ibex' => ['anyOf' => [['allOf' => [$olive]], ['allOf' => [$teal]]]],
                ]],
            ]],
        ];
        $symfonyUnasserted = [];
        foreach (['bison', 'heron', 'okapi', 'lynx', 'puma', 'ibex'] as $name) {
            $symfonyUnasserted['{"' . $name . '":{"dog":1}}'] = null;
        }
        // The serializer builds ONE member and drops the other's key, so a value both `oneOf` members
        // accept is no longer seen whole by the time the validator runs — as for `heron`'s references.
        $symfonyUnasserted['{"puma":{"cat":"a","dog":1}}'] = null;
        $symfonyUnasserted['{"heron":{"cat":"a","dog":1}}'] = null;
        // symfony/serializer 7.4 builds `Ant` first and refuses `stripe` for its missing `leg`.
        $symfonyUnasserted['{"zebu":{"stripe":1}}'] = null;
        $symfonyUnasserted['{"zebu":{"leg":1}}'] = null;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'inline undiscriminated union of objects',
                payloads: [
                    '{"bison":{}}' => false,
                    '{"bison":{"dog":"x"}}' => false,
                    '{"bison":{"dog":1}}' => true,
                    '{"bison":{"cat":"a"}}' => true,
                    '{"bison":5}' => false,
                    '{"heron":{}}' => false,
                    '{"heron":{"dog":"x"}}' => false,
                    '{"heron":{"dog":1}}' => true,
                    '{"heron":{"cat":"a"}}' => true,
                    // Both referenced members accept it. The runtime built the first and stopped, so the
                    // second match went unseen and `dog` was dropped on the way out.
                    '{"heron":{"cat":"a","dog":1}}' => false,
                    '{"bison":{"cat":"a","dog":1}}' => true,
                    '{"okapi":{}}' => false,
                    '{"okapi":{"dog":"x"}}' => false,
                    '{"okapi":{"dog":1}}' => true,
                    '{"okapi":{"cat":"a"}}' => true,
                    '{"lynx":{}}' => false,
                    '{"lynx":{"dog":"x"}}' => false,
                    '{"lynx":{"dog":1}}' => true,
                    '{"lynx":{"cat":"a"}}' => true,
                    '{"lynx":5}' => false,
                    '{"puma":{}}' => false,
                    '{"puma":{"dog":"x"}}' => false,
                    '{"puma":{"dog":1}}' => true,
                    '{"puma":{"cat":"a"}}' => true,
                    '{"puma":{"cat":"a","dog":1}}' => false,
                    '{"ibex":{}}' => false,
                    '{"ibex":{"dog":"x"}}' => false,
                    '{"ibex":{"dog":1}}' => true,
                    '{"ibex":{"cat":"a"}}' => true,
                    '{"zebu":{"stripe":1}}' => true,
                    '{"zebu":{"leg":1}}' => true,
                    '{"zebu":{}}' => false,
                    '{"zebu":{"stripe":"x"}}' => false,
                ],
                diverging: ['symfony' => $symfonyUnasserted],
            ),
        );

        // Held whole: runtime builds the member the payload matches, yii3 keeps the decoded object.
        $this->assertSame(
            expected: '{"bison":{"dog":1}}',
            actual: $this->runtimeRoundTrip($spec, 'inline undiscriminated union of objects', '{"bison":{"dog":1}}'),
        );
        $fqcn = $this->generate($spec, $this->namespaceFor(GenerationMode::Yii3, 'inline undiscriminated union of objects'), 'yii3');
        $held = (new Yii3Container())->hydrate($fqcn, ['bison' => ['dog' => 1]]);
        $this->assertSame(expected: ['dog' => 1], actual: $held->bison ?? null);

        // Both Laravel modes build the member the payload matches: Laravel handed the array to a
        // constructor typed `Olive|Teal` (a TypeError, a 500), laravel-data cast every value to the first
        // class and refused a Teal for Olive's `cat`.
        foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
            foreach (['{"bison":{"dog":1}}', '{"bison":{"cat":"a"}}', '{"puma":{"dog":1}}', '{"puma":{"cat":"a"}}'] as $json) {
                $this->assertSame(
                    expected: $json,
                    actual: $this->writtenBack($mode, $spec, 'inline undiscriminated union of objects', $json),
                    message: $mode->value,
                );
            }
        }
    }

    /**
     * A union COMPONENT of classes beside a scalar — `swan: {anyOf: [$ref Shape, {type: string}]}`, Shape
     * an undiscriminated `anyOf` of two classes — is checked against the members of the component and
     * held whole. Symfony holds the object as the decoded array since 2.15.155, yet its `AtLeastOneOf`
     * still asked for `Type(Shape::class)` or a string, so every valid object was refused; the `oneOf`
     * spelling (`heron`) was the callback's and always worked. yii3 added the `array` member only when
     * the WHOLE type was the interface: the hydrator could not build `Shape`, the property was left
     * unset, and nothing was checked — `{"swan": {"radius": "a"}}` and `{"swan": 5}` passed, and
     * `{"heron": 7}` was cast to `"7"` for the string member. A lone `$ref` to the union (`crane`) is
     * the control.
     */
    public function testAUnionComponentBesideAScalarIsCheckedAgainstItsMembers(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Circle' => ['type' => 'object', 'properties' => ['radius' => ['type' => 'number']], 'required' => ['radius']],
                'Square' => ['type' => 'object', 'properties' => ['side' => ['type' => 'number']], 'required' => ['side']],
                'Shape' => ['anyOf' => [$ref('Circle'), $ref('Square')]],
                'Figure' => ['oneOf' => [$ref('Circle'), $ref('Square')]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'swan' => ['anyOf' => [$ref('Shape'), ['type' => 'string']]],
                    'heron' => ['oneOf' => [$ref('Figure'), ['type' => 'string']]],
                    'crane' => $ref('Figure'),
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union component beside a scalar',
                payloads: [
                    '{"swan":{"radius":1}}' => true,
                    '{"swan":{"side":2}}' => true,
                    '{"swan":{"radius":1,"side":2}}' => true,
                    '{"swan":"x"}' => true,
                    '{"swan":5}' => false,
                    '{"swan":{"radius":"a"}}' => false,
                    '{"heron":{"radius":1}}' => true,
                    '{"heron":{"side":1}}' => true,
                    '{"heron":"x"}' => true,
                    '{"heron":{"radius":1,"side":2}}' => false,
                    '{"heron":{"radius":"a"}}' => false,
                    '{"heron":7}' => false,
                    '{"crane":{"radius":1}}' => true,
                    '{"crane":{"radius":1,"side":2}}' => false,
                ],
            ),
        );

        // Held whole: yii3 keeps the decoded object it cannot build into the interface.
        $fqcn = $this->generate($spec, $this->namespaceFor(GenerationMode::Yii3, 'union component beside a scalar'), 'yii3');
        $container = new Yii3Container();
        $this->assertSame(expected: ['radius' => 1], actual: $container->hydrate($fqcn, ['swan' => ['radius' => 1]])->swan ?? null);
        $this->assertSame(expected: ['side' => 1], actual: $container->hydrate($fqcn, ['heron' => ['side' => 1]])->heron ?? null);
        $this->assertSame(expected: 'x', actual: $container->hydrate($fqcn, ['heron' => 'x'])->heron ?? null);
    }

    /**
     * A union of components beside a scalar is checked against its members wherever it sits: as a list
     * item, as a map value, beside `null` and inline with three classes and a boolean. Both Laravel modes
     * once typed such a property `Shape|string` and crashed on the decoded object; pinned in every mode.
     */
    public function testAUnionComponentBesideAScalarIsCheckedAgainstItsMembersInEveryPosition(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Circle' => ['type' => 'object', 'properties' => ['radius' => ['type' => 'number']], 'required' => ['radius']],
                'Square' => ['type' => 'object', 'properties' => ['side' => ['type' => 'number']], 'required' => ['side']],
                'Star' => ['type' => 'object', 'properties' => ['points' => ['type' => 'integer']], 'required' => ['points']],
                'Figure' => ['oneOf' => [$ref('Circle'), $ref('Square'), $ref('Star')]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'wrens' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Figure'), ['type' => 'string']]]],
                    'kites' => ['type' => 'object', 'additionalProperties' => ['anyOf' => [$ref('Figure'), ['type' => 'integer']]]],
                    'robin' => ['oneOf' => [$ref('Figure'), ['type' => 'null']]],
                    'finch' => ['anyOf' => [$ref('Circle'), $ref('Square'), $ref('Star'), ['type' => 'boolean']]],
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union component beside a scalar in every position',
                payloads: [
                    '{"wrens":[{"radius":1},"x",{"points":3}]}' => true,
                    '{"wrens":[5]}' => false,
                    '{"wrens":[{"radius":"a"}]}' => false,
                    '{"wrens":[{"radius":1,"side":2}]}' => false,
                    '{"kites":{"a":{"side":2},"b":4}}' => true,
                    '{"kites":{"a":"x"}}' => false,
                    '{"kites":{"a":{"points":"a"}}}' => false,
                    '{"robin":{"radius":1}}' => true,
                    '{"robin":null}' => true,
                    '{"robin":"x"}' => false,
                    '{"robin":{"radius":1,"side":2}}' => false,
                    '{"finch":{"points":3}}' => true,
                    '{"finch":true}' => true,
                    '{"finch":"x"}' => false,
                    '{"finch":{"points":"a"}}' => false,
                ],
                // The serializer builds the inline union's member whose class name sorts first (`Circle`)
                // and reports its missing `radius` — README.support-matrix, "an object only a member whose
                // class name does not sort first of an inline undiscriminated union of classes accepts".
                diverging: ['symfony' => ['{"finch":{"points":3}}' => null]],
            ),
        );
    }

    /**
     * An empty object goes out as `{}` in both Laravel modes — nested, as an item of a list or a map of
     * them, and at the root. laravel-data transforms a `Data` into a PHP array, so an empty one was
     * written `[]`: `{"owl":{}}` came back `{"owl":[]}`, and `{}` as `[]`. `json_encode()` of the
     * laravel-data object itself still writes `[]` at the root: the `jsonSerialize()` it reaches is
     * declared `: array` upstream (README.support-matrix, "an empty map on the wire").
     */
    public function testAnEmptyObjectIsWrittenBackAsAnObject(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Shape' => ['type' => 'object', 'properties' => ['tail' => ['type' => 'string']]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'owl' => $ref('Shape'),
                    'bats' => ['type' => 'array', 'items' => $ref('Shape')],
                    'yaks' => ['type' => 'object', 'additionalProperties' => $ref('Shape')],
                ]],
            ]],
        ];
        $payloads = [
            '{}',
            '{"owl":{}}',
            '{"owl":{"tail":"x"}}',
            '{"bats":[{},{"tail":"x"}]}',
            '{"yaks":{"a":{}}}',
        ];
        foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
            foreach ($payloads as $json) {
                $this->assertSame(
                    expected: $json,
                    actual: $this->writtenBack($mode, $spec, 'empty object written back', $json),
                    message: $mode->value,
                );
            }
        }

        $fqcn = $this->generate($spec, $this->namespaceFor(GenerationMode::LaravelData, 'empty object written back'), 'laravel-data');
        $dto = $this->payloadOutcome(GenerationMode::LaravelData, $fqcn, '{}')->dto;
        $this->assertSame(expected: '[]', actual: json_encode($dto));
    }

    /**
     * An item or a map value that is an object only through a union or an `allOf` — `items: {anyOf:
     * [{type: object}, {type: integer}]}`, `allOf: [{type: object}]`, a `null` member beside it — or one
     * list further down (`items: {type: array, items: {type: object}}`) goes back out as `{}` when
     * empty, as the plain `items: {type: object}` already did. Plain laravel wrote it `[]`: such items
     * went through `toJsonValue()`, which cannot tell an empty object from an empty list, and a map of
     * `{type: object}` values lost the braces of an empty one the same way. A union that also admits an
     * array keeps writing the value as it is, `[]` for an empty one: the schema cannot say which it was.
     * laravel-data writes an empty map `[]` (README.support-matrix, "an empty map on the wire").
     */
    public function testAnEmptyObjectItemOfAUnionIsWrittenBackAsAnObject(): void
    {
        $object = ['type' => 'object'];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'reeds' => ['type' => 'array', 'items' => ['anyOf' => [$object, ['type' => 'integer']]]],
                    'vines' => ['type' => 'object', 'additionalProperties' => ['anyOf' => [$object, ['type' => 'integer']]]],
                    'ferns' => ['type' => 'array', 'items' => ['allOf' => [$object]]],
                    'moss' => ['type' => 'array', 'items' => ['oneOf' => [$object, ['type' => 'string']]]],
                    'ivies' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => $object]],
                    'stems' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => ['anyOf' => [$object, ['type' => 'integer']]]]],
                    'lilies' => ['type' => 'array', 'items' => ['anyOf' => [['allOf' => [$object]], ['type' => 'null']]]],
                    'pods' => ['type' => 'object', 'additionalProperties' => $object],
                    // Controls, already `{}`.
                    'buds' => ['type' => 'array', 'items' => $object],
                    'twig' => $object,
                    'bark' => ['allOf' => [$object]],
                    'sap' => ['anyOf' => [$object, ['type' => 'integer']]],
                    // Control: an array member beside the object one, written as the value is.
                    'roots' => ['type' => 'array', 'items' => ['anyOf' => [$object, ['type' => 'array']]]],
                ]],
            ]],
        ];
        $key = 'empty object item of a union written back';
        $payloads = [
            '{"reeds":[{},3]}' => '{"reeds":[{},3]}',
            '{"reeds":[{}]}' => '{"reeds":[{}]}',
            '{"reeds":[{"a":{"b":1}}]}' => '{"reeds":[{"a":{"b":1}}]}',
            '{"vines":{"a":{},"b":2}}' => '{"vines":{"a":{},"b":2}}',
            '{"vines":{}}' => '{"vines":{}}',
            '{"ferns":[{}]}' => '{"ferns":[{}]}',
            '{"moss":[{},"x"]}' => '{"moss":[{},"x"]}',
            '{"ivies":[[{}],[]]}' => '{"ivies":[[{}],[]]}',
            '{"stems":[[{},1]]}' => '{"stems":[[{},1]]}',
            '{"lilies":[{},null]}' => '{"lilies":[{},null]}',
            '{"pods":{"a":{}}}' => '{"pods":{"a":{}}}',
            '{"buds":[{}]}' => '{"buds":[{}]}',
            '{"twig":{}}' => '{"twig":{}}',
            '{"bark":{}}' => '{"bark":{}}',
            '{"sap":{}}' => '{"sap":{}}',
            '{"roots":[{},[]]}' => '{"roots":[[],[]]}',
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    ...array_fill_keys(array_keys($payloads), true),
                    '{"reeds":["x"]}' => false,
                    '{"ivies":[[1]]}' => false,
                    '{"vines":{"a":"x"}}' => false,
                ],
                // Not this test's subject: the runtime refuses an object for a property that is
                // `allOf: [{type: object}]` alone ("expects array, got object").
                diverging: ['runtime' => ['{"bark":{}}' => null]],
            ),
        );
        foreach ($payloads as $json => $written) {
            $this->assertSame(
                expected: $written,
                actual: $this->writtenBack(GenerationMode::Laravel, $spec, $key, $json),
                message: $json,
            );
        }
    }

    /**
     * A `null` item of a list of an undiscriminated union COMPONENT that admits null (`many: {items:
     * $ref Shade}`, `Shade: {oneOf: [$ref Olive, $ref Teal, {type: null}]}`) is accepted and written back
     * as `null` in laravel-data, as in plain laravel. Those items are the decoded arrays, with no
     * `#[DataCollectionOf]` since 2.15.154, but the guard that refuses a null item for that attribute
     * still reached them: `{"many":[null]}` was a 422, "many.0 expects object, got null". A null item
     * where the union does not admit one stays refused, and so does an item no member takes.
     */
    public function testANullItemOfAListOfANullableUnionComponentIsAccepted(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'shade' => $ref('Shade'),
                    'many' => ['type' => 'array', 'items' => $ref('Shade')],
                    'firm' => ['type' => 'array', 'items' => $ref('Hue')],
                ]],
                'Shade' => ['oneOf' => [$ref('Olive'), $ref('Teal'), ['type' => 'null']]],
                'Hue' => ['oneOf' => [$ref('Olive'), $ref('Teal')]],
                'Olive' => ['type' => 'object', 'required' => ['leaf'], 'properties' => ['leaf' => ['type' => 'string']]],
                'Teal' => ['type' => 'object', 'required' => ['fin'], 'properties' => ['fin' => ['type' => 'integer']]],
            ]],
        ];
        $key = 'null item of a list of a nullable union component';

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    '{"many":[null]}' => true,
                    '{"many":[{"leaf":"x"},null]}' => true,
                    '{"many":[{"leaf":1}]}' => false,
                    '{"many":[3]}' => false,
                    '{"firm":[null]}' => false,
                    '{"firm":[{"fin":2}]}' => true,
                ],
                // Not this test's subject: yii3 counts a null item as matching more than one `oneOf`
                // member of the component.
                diverging: ['yii3' => ['{"many":[null]}' => null, '{"many":[{"leaf":"x"},null]}' => null]],
            ),
        );
        foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
            foreach (['[null]', '[{"leaf":"x"},null]'] as $items) {
                $written = json_decode($this->writtenBack($mode, $spec, $key, sprintf('{"many":%s}', $items)), true);
                $this->assertIsArray($written, $mode->value);
                $this->assertSame(expected: json_decode($items, true), actual: $written['many'] ?? 'absent', message: $mode->value);
            }
        }
    }

    /**
     * A `oneOf` of a `$ref` class and a member the PHP type spells `array` — an inline object with no
     * properties of its own, or `type: array` — refuses an object neither member takes. The runtime kept
     * the payload as the `array` member once the class could not be built from it, and the validator
     * then counted the class branch as undecided about a raw object and accepted with no branch matched:
     * `{"kiwi":{"vole":7}}` went through although `vole` must be a string, and so did `{"kiwi":{"vole":
     * "x"}}` against a class that requires `panda`. The raw object is now judged against the class's own
     * `required` and property rules. An object the class does take still is, and one both members take
     * is still more than one.
     */
    public function testARawObjectIsJudgedAgainstTheClassBesideAnArrayMember(): void
    {
        $ref = ['$ref' => '#/components/schemas/Umber'];
        $spec = static fn(array $kiwi, array $umber): array => [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => ['kiwi' => $kiwi]],
                'Umber' => ['type' => 'object', ...$umber],
            ]],
        ];
        $requiredOnly = ['oneOf' => [['type' => 'object', 'required' => ['hyena']], $ref]];
        $cases = [
            'raw object beside a required-only member' => [
                $spec($requiredOnly, ['properties' => ['vole' => ['type' => 'string']]]),
                [
                    '{"kiwi":{"vole":7}}' => false,
                    '{"kiwi":{"vole":"x"}}' => true,
                    '{"kiwi":{}}' => true,
                    '{"kiwi":{"hyena":1}}' => false,
                    '{"kiwi":{"hyena":1,"vole":7}}' => true,
                ],
            ],
            'raw object beside a required-only member, class with required' => [
                $spec($requiredOnly, ['required' => ['panda'], 'properties' => ['vole' => ['type' => 'string']]]),
                [
                    '{"kiwi":{"vole":"x"}}' => false,
                    '{"kiwi":{"panda":1,"vole":"x"}}' => true,
                    '{"kiwi":{"hyena":1}}' => true,
                ],
            ],
            'raw object in a nested union beside a list member' => [
                $spec(
                    ['oneOf' => [
                        ['oneOf' => [
                            ['type' => 'object', 'properties' => ['hyena' => ['type' => 'boolean']]],
                            ['type' => 'array'],
                            $ref,
                        ]],
                        ['type' => 'null'],
                    ]],
                    ['required' => ['panda'], 'properties' => ['panda' => ['type' => 'string']]],
                ),
                [
                    '{"kiwi":{"hyena":2.5}}' => false,
                    '{"kiwi":{"hyena":true}}' => true,
                    '{"kiwi":null}' => true,
                ],
            ],
        ];

        $misses = [];
        foreach ($cases as $key => [$caseSpec, $payloads]) {
            foreach ($this->payloadTableMisses(spec: $caseSpec, key: $key, payloads: $payloads) as $miss) {
                $misses[] = $key . ': ' . $miss;
            }
        }
        $this->assertSame(expected: [], actual: $misses);

        // The name the class requires without declaring it is asked of the raw body only: built by
        // hand, the class has no slot for it and still normalizes.
        $key = 'raw object beside a required-only member, class with required';
        $fqcn = $this->generate($cases[$key][0], $this->namespaceFor(GenerationMode::Runtime, $key), 'runtime');
        $umber = substr($fqcn, 0, (int)strrpos($fqcn, '\\')) . '\Umber';
        $this->assertSame(
            expected: '{"vole":"x"}',
            actual: (new DtoNormalizer())->validateAndNormalizeToJson(new $umber(vole: 'x')),
        );
    }

    /**
     * A raw object judged against a class branch refuses `null` on a property the class does not let
     * be null. `oneOf: [{oneOf: [{required: [gibbon]}, $ref Scarlet]}, {type: array}]` with `Scarlet.puffin:
     * string` (required) took `{"zebu":{"puffin":null}}` in runtime mode: the raw object was kept, and
     * the validator dropped the rules of every null-valued property, so nothing refused the null. A
     * property that admits null — `nullable: true`, `type: [string, "null"]` — still takes it; the class
     * directly in the outer `oneOf` was refused already and stays so.
     *
     * @param array<string, mixed> $schemas
     * @param array<string, bool|null> $payloads
     */
    #[DataProvider('rawObjectNullCases')]
    public function testARawObjectRefusesNullOnAPropertyTheClassDoesNotLetBeNull(string $version, array $schemas, array $payloads): void
    {
        $spec = [
            'openapi' => $version,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => $schemas],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: (string)$this->dataName(),
                payloads: $payloads,
                // `{}` and `[]` are one decoded PHP array there, so `{}` is the empty list the `array`
                // member takes (README.support-matrix, "an EMPTY JSON container").
                diverging: [
                    GenerationMode::Symfony->value => ['{"zebu":{}}' => null],
                    GenerationMode::Yii3->value => ['{"zebu":{}}' => null],
                ],
            ),
        );
    }

    /**
     * The specs and payloads of {@see testARawObjectRefusesNullOnAPropertyTheClassDoesNotLetBeNull()}.
     *
     * @return iterable<string, array{0: string, 1: array<string, mixed>, 2: array<string, bool|null>}>
     */
    public static function rawObjectNullCases(): iterable
    {
        $probe = static fn(array $zebu): array => ['type' => 'object', 'properties' => ['zebu' => $zebu]];
        $nested = ['oneOf' => [
            ['oneOf' => [
                ['type' => 'object', 'properties' => ['gibbon' => ['type' => 'integer']], 'required' => ['gibbon']],
                ['$ref' => '#/components/schemas/Scarlet'],
            ]],
            ['type' => 'array', 'items' => ['type' => 'string']],
        ]];
        $flat = ['oneOf' => [
            ['type' => 'object', 'properties' => ['gibbon' => ['type' => 'integer']], 'required' => ['gibbon']],
            ['$ref' => '#/components/schemas/Scarlet'],
            ['type' => 'array', 'items' => ['type' => 'string']],
        ]];
        $scarlet = static fn(array $puffin): array => [
            'type' => 'object',
            'properties' => ['puffin' => $puffin],
            'required' => ['puffin'],
        ];
        $refusesNull = [
            '{"zebu":{"puffin":null}}' => false,
            '{"zebu":{"puffin":5}}' => false,
            '{"zebu":{}}' => false,
            '{"zebu":{"puffin":"a"}}' => true,
            '{"zebu":{"gibbon":1}}' => true,
        ];
        $takesNull = [
            '{"zebu":{"puffin":null}}' => true,
            '{"zebu":{"puffin":5}}' => false,
            '{"zebu":{"puffin":"a"}}' => true,
        ];

        yield 'nested union, non-nullable property' => [
            '3.0.3',
            ['Probe' => $probe($nested), 'Scarlet' => $scarlet(['type' => 'string'])],
            $refusesNull,
        ];
        yield 'flat union, non-nullable property' => [
            '3.0.3',
            ['Probe' => $probe($flat), 'Scarlet' => $scarlet(['type' => 'string'])],
            $refusesNull,
        ];
        yield 'nested union, optional non-nullable property' => [
            '3.0.3',
            ['Probe' => $probe($nested), 'Scarlet' => ['type' => 'object', 'properties' => ['puffin' => ['type' => 'string']]]],
            ['{"zebu":{"puffin":null}}' => false, '{"zebu":{"puffin":"a"}}' => true],
        ];
        yield 'nested union, nullable property' => [
            '3.0.3',
            ['Probe' => $probe($nested), 'Scarlet' => $scarlet(['type' => 'string', 'nullable' => true])],
            $takesNull,
        ];
        yield 'nested union, property typed string or null' => [
            '3.1.0',
            ['Probe' => $probe($nested), 'Scarlet' => $scarlet(['type' => ['string', 'null']])],
            $takesNull,
        ];
    }

    /**
     * A property typed with a union COMPONENT of classes and no `discriminator` (`comp: $ref Shade`,
     * `Shade: {anyOf: [$ref Olive, $ref Teal]}`) is built as the member the payload matches, as the
     * inline `anyOf: [$ref Olive, $ref Teal]` is — directly, as a list item, and under `oneOf` only when
     * exactly one member matches. The runtime refused every payload with `Unsupported type: Shade`: the
     * union's interface was handed to the cast as if it were a class. yii3 holds the decoded object and
     * checks it against every member. The other three still cannot build one and say so at generation
     * time (README.support-matrix, "hydration of a union of OBJECTS with no `discriminator`").
     */
    public function testAnUndiscriminatedUnionComponentOfClassesIsBuiltAsItsMatchingMember(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Olive' => ['type' => 'object', 'required' => ['cat'], 'properties' => ['cat' => ['type' => 'integer']]],
                'Teal' => ['type' => 'object', 'required' => ['dog'], 'properties' => ['dog' => ['type' => 'integer']]],
                'Shade' => ['anyOf' => [$ref('Olive'), $ref('Teal')]],
                'Hue' => ['oneOf' => [$ref('Olive'), $ref('Teal')]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'comp' => $ref('Shade'),
                    'compOne' => $ref('Hue'),
                    'many' => ['type' => 'array', 'items' => $ref('Hue')],
                ]],
            ]],
        ];
        $key = 'undiscriminated union component of classes';
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    '{"comp":{"cat":1}}' => true,
                    '{"comp":{"dog":1}}' => true,
                    '{"comp":{"cat":1,"dog":2}}' => true,
                    '{"comp":{}}' => false,
                    '{"comp":{"dog":"x"}}' => false,
                    '{"comp":5}' => false,
                    '{"compOne":{"cat":1}}' => true,
                    '{"compOne":{"dog":1}}' => true,
                    '{"compOne":{"cat":1,"dog":2}}' => false,
                    '{"compOne":{}}' => false,
                    '{"many":[{"cat":1},{"dog":2}]}' => true,
                    '{"many":[{"cat":1,"dog":2}]}' => false,
                ],
                skippedModes: [GenerationMode::Laravel, GenerationMode::LaravelData],
            ),
        );

        // The Laravel modes build a PROPERTY typed as the component as its matching member since
        // 2.15.153 — the first under `anyOf` — as the inline `Olive|Teal`. A list item of it is not
        // (README.support-matrix, "hydration of a union COMPONENT"), so `many` is left out here.
        $laravelSpec = $spec;
        $laravelSpec['components']['schemas']['Probe']['properties'] = array_diff_key(
            $spec['components']['schemas']['Probe']['properties'],
            ['many' => true],
        );
        $laravelKey = $key . ' as a property';
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $laravelSpec,
                key: $laravelKey,
                payloads: [
                    '{"comp":{"cat":1}}' => true,
                    '{"comp":{"dog":1}}' => true,
                    '{"comp":{"cat":1,"dog":2}}' => true,
                    '{"comp":{}}' => false,
                    '{"comp":{"cat":"x"}}' => false,
                    '{"comp":5}' => false,
                    '{"compOne":{"cat":1}}' => true,
                    '{"compOne":{"dog":1}}' => true,
                    '{"compOne":{"cat":1,"dog":2}}' => false,
                ],
                skippedModes: [GenerationMode::Runtime, GenerationMode::Symfony, GenerationMode::Yii3],
            ),
        );
        foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
            foreach (['{"comp":{"cat":1},"compOne":{"dog":2}}' => '{"comp":{"cat":1},"compOne":{"dog":2}}', '{"comp":{"dog":1}}' => '{"comp":{"dog":1}}', '{"comp":{"cat":1,"dog":2}}' => '{"comp":{"cat":1}}'] as $json => $written) {
                $this->assertSame(expected: $written, actual: $this->writtenBack($mode, $laravelSpec, $laravelKey, $json), message: $mode->value);
            }
        }

        $built = function (string $json) use ($spec, $key): array {
            $fqcn = $this->generate($spec, $this->namespaceFor(GenerationMode::Runtime, $key), 'runtime');
            $dto = (new DtoDeserializer())->deserialize(Request::create(
                uri: '/',
                method: 'POST',
                server: ['CONTENT_TYPE' => 'application/json'],
                content: $json,
            ), $fqcn);
            $classes = [];
            foreach (['getComp', 'getCompOne'] as $getter) {
                $member = $dto->{$getter}();
                $classes[] = is_object($member) ? substr(strrchr($member::class, '\\') ?: $member::class, 1) : null;
            }

            return $classes;
        };
        $this->assertSame(expected: ['Olive', null], actual: $built('{"comp":{"cat":1}}'));
        $this->assertSame(expected: ['Teal', 'Teal'], actual: $built('{"comp":{"dog":1},"compOne":{"dog":2}}'));
        $this->assertSame(expected: [null, 'Olive'], actual: $built('{"compOne":{"cat":1}}'));
        $this->assertSame(
            expected: '{"comp":{"dog":1},"compOne":{"cat":2}}',
            actual: $this->runtimeRoundTrip($spec, $key, '{"comp":{"dog":1},"compOne":{"cat":2}}'),
        );
    }

    /**
     * A `$ref` union branch whose class spells `additionalProperties` or `patternProperties` as a `$ref`
     * (`crane: {oneOf: [$ref Ivory, string]}`, `Ivory: {additionalProperties: {$ref: Jade}}`). The Laravel
     * modes fold the branch's class into the interpreter, and that fold ran nested in the outer extraction,
     * which does not inline references: the `$ref` scrubbed to nothing and the branch took any extra key
     * — `{"crane": {"stray": "zzq"}}` passed for a boolean `Jade`. The inline spelling (`ermine`), the
     * class as a plain property (`puma`) and the class as list items (`quail`) always refused it.
     */
    public function testAReferenceUnionBranchChecksTheReferencedValuesOfItsExtraKeys(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $branch = static fn(string $name): array => ['oneOf' => [$ref($name), ['type' => 'string']]];
        $holder = static fn(array $extra): array => ['type' => 'object', 'properties' => ['puffin' => ['type' => 'string']], ...$extra];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Jade' => ['type' => 'boolean'],
                'Short' => ['type' => 'string', 'maxLength' => 2],
                'Teal' => ['type' => 'object', 'properties' => ['panda' => ['type' => 'integer']]],
                'Ivory' => $holder(['additionalProperties' => $ref('Jade')]),
                'Amber' => $holder(['additionalProperties' => $ref('Short')]),
                'Coral' => $holder(['additionalProperties' => $ref('Teal')]),
                'Plum' => $holder(['patternProperties' => ['^s' => $ref('Jade')]]),
                'Probe' => ['type' => 'object', 'properties' => [
                    'crane' => $branch('Ivory'),
                    'heron' => $branch('Amber'),
                    'lynx' => $branch('Coral'),
                    'okapi' => $branch('Plum'),
                    // The controls.
                    'ermine' => ['oneOf' => [$holder(['additionalProperties' => ['type' => 'boolean']]), ['type' => 'string']]],
                    'puma' => $ref('Ivory'),
                    'quail' => ['type' => 'array', 'items' => $ref('Ivory')],
                ]],
            ]],
        ];

        $payloads = [];
        foreach (['crane', 'okapi', 'ermine', 'puma'] as $name) {
            $payloads['{"' . $name . '":{"stray":"zzq"}}'] = false;
            $payloads['{"' . $name . '":{"stray":true}}'] = true;
        }
        $payloads += [
            '{"quail":[{"stray":"zzq"}]}' => false,
            '{"quail":[{"stray":true}]}' => true,
            '{"heron":{"stray":"zzq"}}' => false,
            '{"heron":{"stray":"zz"}}' => true,
            '{"heron":{"stray":5}}' => false,
            '{"lynx":{"stray":{"panda":"x"}}}' => false,
            '{"lynx":{"stray":{"panda":1}}}' => true,
            '{"lynx":{"stray":5}}' => false,
            // A key the pattern does not cover is no extra one there.
            '{"okapi":{"other":"zzq"}}' => true,
            '{"crane":"s"}' => true,
        ];

        // support matrix: "a key `additionalProperties: {schema}` admits beside the named properties" —
        // the Symfony serializer and the yii3 hydrator leave the undeclared key behind unchecked.
        $unchecked = array_map(static fn(bool $accepted): bool => true, array_filter($payloads, static fn(bool $accepted): bool => !$accepted));

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'ref branch extra keys',
                payloads: $payloads,
                diverging: ['symfony' => $unchecked, 'yii3' => $unchecked],
            ),
        );
    }

    /**
     * An inline `discriminator` on a property (`pet: {oneOf: [$ref Cat, $ref Dog], discriminator:
     * {propertyName: kind}}`, no component base) whose members overlap apart from the tag. laravel-data
     * ignored it: it counted the bare `oneOf`, refused every valid payload as matching both members,
     * accepted `{"kind": "Dog", "bark": "x"}` — Cat alone matches it — and built that as a Cat, `bark`
     * dropped. It dispatches by the tag as Laravel mode does: the mapping's value, else the member's name.
     */
    public function testAnInlineDiscriminatorBuildsTheMemberItsTagNames(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $member = static fn(string $field): array => [
            'type' => 'object',
            'required' => ['kind'],
            'properties' => ['kind' => ['type' => 'string'], $field => ['type' => 'integer']],
        ];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Cat' => $member('meow'),
                'Dog' => $member('bark'),
                'Probe' => ['type' => 'object', 'properties' => [
                    'pet' => ['oneOf' => [$ref('Cat'), $ref('Dog')], 'discriminator' => ['propertyName' => 'kind']],
                    'mapped' => [
                        'anyOf' => [$ref('Cat'), $ref('Dog')],
                        'discriminator' => ['propertyName' => 'kind', 'mapping' => ['c' => '#/components/schemas/Cat', 'd' => '#/components/schemas/Dog']],
                    ],
                ]],
            ]],
        ];
        $key = 'inline discriminator builds the tagged member';
        $modes = [GenerationMode::Laravel, GenerationMode::LaravelData];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    '{"pet":{"kind":"Cat","meow":1}}' => true,
                    '{"pet":{"kind":"Dog","bark":5}}' => true,
                    '{"pet":{"kind":"Dog","bark":"x"}}' => false,
                    '{"pet":{"kind":"Eel"}}' => false,
                    '{"mapped":{"kind":"d","bark":5}}' => true,
                    '{"mapped":{"kind":"d","bark":"x"}}' => false,
                    '{"mapped":{"kind":"Dog","bark":5}}' => false,
                ],
                skippedModes: array_values(array_filter(
                    array: GenerationMode::cases(),
                    callback: static fn(GenerationMode $mode): bool => !in_array($mode, $modes, true),
                )),
            ),
        );

        foreach ($modes as $mode) {
            foreach (['{"pet":{"kind":"Dog","bark":5}}', '{"pet":{"kind":"Cat","meow":1}}', '{"mapped":{"kind":"d","bark":5}}'] as $json) {
                $this->assertSame(expected: $json, actual: $this->writtenBack($mode, $spec, $key, $json), message: $mode->value);
            }
        }
    }

    /**
     * A discriminated union made nullable by wrapping it — `oneOf: [{oneOf: [$ref Cat, $ref Dog],
     * discriminator}, {type: null}]` — on a property of an inline object that is itself a union BRANCH,
     * a list item or a map value, and a plain discriminated union on a property of a list item. The
     * flattening walk followed properties alone and the symfony hoist stopped at items, so the union
     * lost its discriminator there: symfony built the first member (a valid Dog refused for Cat's enum
     * and its required `purr`), laravel and laravel-data built a Blue as a Red and wrote `wing` away.
     * The neighbours — a plain inline object, a `$ref` holder, the flat spelling — already worked.
     *
     * @param array<string, mixed> $property the schema of `fox`
     * @param array<string, bool> $payloads
     * @param list<string> $writtenBack payloads every mode must write back unchanged
     * @param array<string, array<string, bool|null>> $diverging
     */
    #[DataProvider('discriminatedUnionInsideAnInlineObjectProvider')]
    public function testADiscriminatedUnionInsideAnInlineObjectKeepsItsDiscriminator(
        string $openApiVersion,
        array $property,
        array $payloads,
        array $writtenBack,
        array $diverging = [],
    ): void {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => $openApiVersion,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => ['fox' => $property]],
                'Box' => ['type' => 'object', 'properties' => ['pet' => self::wrappedPetUnion()]],
                'Base' => ['type' => 'object', 'properties' => ['lemur' => ['type' => 'string']]],
                'Cat' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['Cat']], 'purr' => ['type' => 'string']],
                    'required' => ['kind', 'purr'],
                ],
                'Dog' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['Dog']], 'bark' => ['type' => 'integer']],
                    'required' => ['kind'],
                ],
                'Red' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string'], 'tail' => ['type' => 'string']],
                    'required' => ['kind'],
                ],
                'Blue' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string'], 'wing' => ['type' => 'boolean']],
                    'required' => ['kind'],
                ],
            ]],
        ];
        $key = 'discriminated union inside an inline object ' . md5((string)json_encode($spec));

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: $key, payloads: $payloads, diverging: $diverging),
        );
        foreach ($writtenBack as $json) {
            $written = json_decode($json, true);
            $this->assertEquals(expected: [$written, $written, $written], actual: $this->writtenBackByTheWritingModes($spec, $key, $json));
        }
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, mixed>, 2: array<string, bool>, 3: list<string>, 4?: array<string, array<string, bool|null>>}>
     */
    public static function discriminatedUnionInsideAnInlineObjectProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $object = static fn(array $pet): array => ['type' => 'object', 'properties' => ['pet' => $pet]];
        $plain = ['oneOf' => [$ref('Cat'), $ref('Dog')], 'discriminator' => ['propertyName' => 'kind']];
        $wrapped = self::wrappedPetUnion();
        $refHolder = static fn(array $pet): array => [...$ref('Base'), 'properties' => ['pet' => $pet]];
        $flat = ['oneOf' => [$ref('Cat'), $ref('Dog'), ['type' => 'null']], 'discriminator' => ['propertyName' => 'kind']];
        $colour = static fn(string $keyword): array => [
            $keyword => [['anyOf' => [$ref('Red'), $ref('Blue')], 'discriminator' => ['propertyName' => 'kind']], ['type' => 'null']],
        ];
        $pets = static fn(string $wrap, bool $nullable): array => [
            sprintf($wrap, '{"kind":"Dog","bark":1}') => true,
            sprintf($wrap, '{"kind":"Cat","purr":"r"}') => true,
            sprintf($wrap, 'null') => $nullable,
            sprintf($wrap, '{"kind":"Dog","bark":"x"}') => false,
            sprintf($wrap, '{"kind":"Cat"}') => false,
            sprintf($wrap, '{"kind":"Eel"}') => false,
        ];
        $orNull = static fn(array $schema): array => ['anyOf' => [$schema, ['type' => 'null']]];

        // Cause: the wrapped union on a property of an inline object that is a union branch.
        yield 'wrapped union in an anyOf branch' => [
            '3.1.0',
            $orNull($object($wrapped)),
            $pets('{"fox":{"pet":%s}}', true) + ['{"fox":null}' => true],
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
        yield 'wrapped colour union in an anyOf branch' => [
            '3.1.0',
            $orNull($object($colour('anyOf'))),
            ['{"fox":{"pet":{"kind":"Blue","wing":true}}}' => true, '{"fox":{"pet":{"kind":"Red","tail":"t"}}}' => true, '{"fox":{"pet":{"kind":"Blue","wing":"x"}}}' => false],
            ['{"fox":{"pet":{"kind":"Blue","wing":true}}}', '{"fox":{"pet":{"kind":"Red","tail":"t"}}}'],
        ];
        yield 'wrapped colour union in a oneOf branch' => [
            '3.1.0',
            ['oneOf' => [$object($colour('anyOf')), ['type' => 'null']]],
            ['{"fox":{"pet":{"kind":"Blue","wing":true}}}' => true, '{"fox":{"pet":{"kind":"Blue","wing":"x"}}}' => false],
            ['{"fox":{"pet":{"kind":"Blue","wing":true}}}'],
        ];
        // Cause: a union on a property of a list item, or of a map value.
        yield 'plain union in a list item' => [
            '3.1.0',
            ['type' => 'array', 'items' => $object($plain)],
            $pets('{"fox":[{"pet":%s}]}', false),
            ['{"fox":[{"pet":{"kind":"Dog","bark":1}}]}'],
        ];
        yield 'wrapped union in a list item' => [
            '3.1.0',
            ['type' => 'array', 'items' => $object($wrapped)],
            $pets('{"fox":[{"pet":%s}]}', true),
            ['{"fox":[{"pet":{"kind":"Dog","bark":1}}]}'],
        ];
        yield 'nullable union in a list item, OAS 3.0' => [
            '3.0.3',
            ['type' => 'array', 'items' => $object([...$plain, 'nullable' => true])],
            $pets('{"fox":[{"pet":%s}]}', true),
            ['{"fox":[{"pet":{"kind":"Dog","bark":1}}]}'],
        ];
        yield 'wrapped union in a map value' => [
            '3.1.0',
            ['type' => 'object', 'additionalProperties' => $object($wrapped)],
            $pets('{"fox":{"ka":{"pet":%s}}}', true),
            ['{"fox":{"ka":{"pet":{"kind":"Dog","bark":1}}}}'],
        ];
        // The runtime built an inline `anyOf` with no mapping by the first member that took the payload:
        // `wing: "x"` rode along on a Red as an extra key.
        yield 'wrapped colour union in a plain inline object' => [
            '3.1.0',
            $object($colour('anyOf')),
            ['{"fox":{"pet":{"kind":"Blue","wing":true}}}' => true, '{"fox":{"pet":{"kind":"Red","tail":"t"}}}' => true, '{"fox":{"pet":{"kind":"Blue","wing":"x"}}}' => false],
            ['{"fox":{"pet":{"kind":"Blue","wing":true}}}', '{"fox":{"pet":{"kind":"Red","tail":"t"}}}'],
        ];
        // Cause: the union on a property of a `$ref` holder with sibling `properties` — a class of its
        // own — that is a union branch, a list item or a map value. The hoist walked only inline
        // subschemas there, so symfony typed the property as the plain union and built its first member.
        yield 'plain union in a referenced holder with properties in a oneOf branch' => [
            '3.1.0',
            ['oneOf' => [$refHolder($plain), ['type' => 'null']]],
            $pets('{"fox":{"pet":%s}}', false) + ['{"fox":null}' => true],
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
        yield 'plain union in a referenced holder with properties in a list item' => [
            '3.1.0',
            ['type' => 'array', 'items' => $refHolder($plain)],
            $pets('{"fox":[{"pet":%s}]}', false),
            ['{"fox":[{"pet":{"kind":"Dog","bark":1}}]}'],
        ];
        yield 'plain union in a referenced holder with properties in a map value' => [
            '3.1.0',
            ['type' => 'object', 'additionalProperties' => $refHolder($plain)],
            $pets('{"fox":{"ka":{"pet":%s}}}', false),
            ['{"fox":{"ka":{"pet":{"kind":"Dog","bark":1}}}}'],
        ];
        yield 'wrapped union in a referenced holder with properties in an anyOf branch' => [
            '3.1.0',
            $orNull($refHolder($wrapped)),
            $pets('{"fox":{"pet":%s}}', true) + ['{"fox":null}' => true],
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
        // Neighbours that already worked.
        yield 'plain union in a referenced holder with properties' => [
            '3.1.0',
            $refHolder($plain),
            $pets('{"fox":{"pet":%s}}', false),
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
        yield 'plain union in an inline object in a oneOf branch' => [
            '3.1.0',
            ['oneOf' => [$object($plain), ['type' => 'null']]],
            $pets('{"fox":{"pet":%s}}', false) + ['{"fox":null}' => true],
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
        yield 'wrapped union in a plain inline object' => [
            '3.1.0',
            $object($wrapped),
            $pets('{"fox":{"pet":%s}}', true),
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
        yield 'wrapped union in a referenced holder' => [
            '3.1.0',
            $orNull($ref('Box')),
            $pets('{"fox":{"pet":%s}}', true),
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
        yield 'flat union in an anyOf branch' => [
            '3.1.0',
            $orNull($object($flat)),
            $pets('{"fox":{"pet":%s}}', true),
            ['{"fox":{"pet":{"kind":"Dog","bark":1}}}'],
        ];
    }

    /**
     * `pet: oneOf: [{oneOf: [$ref Cat, $ref Dog], discriminator: kind}, {type: null}]`.
     *
     * @return array<string, mixed>
     */
    private static function wrappedPetUnion(): array
    {
        return ['oneOf' => [
            ['oneOf' => [['$ref' => '#/components/schemas/Cat'], ['$ref' => '#/components/schemas/Dog']], 'discriminator' => ['propertyName' => 'kind']],
            ['type' => 'null'],
        ]];
    }

    /**
     * Discriminator mapping keys that are numeric strings — `{"1": Red, "2": Blue}`, valid OpenAPI —
     * arrive as PHP integer keys once the document is decoded. The inline union dropped them and lost its
     * discriminator (laravel, laravel-data and runtime refused every payload as matching both members),
     * and the component spelling stopped generation with "mapping key must be a non-empty string". The
     * tag is a string on the wire and is compared as one: an integer `2` is not the tag `"2"`.
     */
    #[DataProvider('numericMappingKeyProvider')]
    public function testANumericDiscriminatorMappingKeyIsATag(bool $component, array $mapping): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $union = ['oneOf' => [$ref('Red'), $ref('Blue')], 'discriminator' => ['propertyName' => 'kind', 'mapping' => $mapping]];
        [$redTag, $blueTag] = array_map(strval(...), array_keys($mapping));
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => ['walrus' => $component ? $ref('Shade') : $union]],
                'Red' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string'], 'tail' => ['type' => 'string']],
                    'required' => ['kind'],
                ],
                'Blue' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string'], 'wing' => ['type' => 'boolean']],
                    'required' => ['kind'],
                ],
            ]],
        ];
        if ($component) {
            $spec['components']['schemas']['Shade'] = $union;
        }
        $key = 'numeric mapping key ' . md5((string)json_encode($spec));
        $blue = '{"walrus":{"kind":"' . $blueTag . '","wing":true}}';
        $red = '{"walrus":{"kind":"' . $redTag . '","tail":"t"}}';

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    $blue => true,
                    $red => true,
                    '{"walrus":{"kind":"' . $blueTag . '","wing":"x"}}' => false,
                    '{"walrus":{"kind":"Blue","wing":true}}' => false,
                    '{"walrus":{"kind":"zz"}}' => false,
                    // The tag property is a string: an integer is not a tag, whatever it reads as.
                    '{"walrus":{"kind":2}}' => false,
                ],
            ),
        );
        foreach ([$blue, $red] as $json) {
            $written = json_decode($json, true);
            $this->assertEquals(expected: [$written, $written, $written], actual: $this->writtenBackByTheWritingModes($spec, $key, $json));
        }
    }

    /**
     * @return iterable<string, array{bool, array<string, string>}>
     */
    public static function numericMappingKeyProvider(): iterable
    {
        $numeric = ['1' => '#/components/schemas/Red', '2' => '#/components/schemas/Blue'];
        $named = ['crimson' => '#/components/schemas/Red', 'navy' => '#/components/schemas/Blue'];

        yield 'inline, numeric keys' => [false, $numeric];
        yield 'component, numeric keys' => [true, $numeric];
        // Neighbours: string keys already worked.
        yield 'inline, named keys' => [false, $named];
        yield 'component, named keys' => [true, $named];
    }

    /**
     * A `oneOf` of object branches where a branch is a class of its own — an inline object, an `allOf`
     * around a `$ref`, a `$ref` with keywords beside it. The deserializer builds the one class that
     * accepts the payload; the runtime validator then counted the branches again against that BUILT
     * object, where an inline branch spelled out as `{type: object, properties: …}` matched any object
     * of another class (the key it would have refused was dropped), and an `allOf` branch lost its
     * `$ref` half and matched any object. A valid payload was refused as matching two branches.
     *
     * Symfony is unasserted: its serializer builds the first member it can and reports that member's
     * gaps (README.support-matrix.md, "an object only a member whose class name does not sort first …"), a framework boundary that
     * differs between serializer releases.
     *
     * @param array<string, mixed> $plum the schema of `plum`
     * @param array<string, bool> $payloads
     */
    #[DataProvider('objectUnionBranchClassProvider')]
    public function testAnObjectUnionBranchIsJudgedAsItsOwnClass(array $plum, array $payloads): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => ['plum' => $plum]],
                'Olive' => [
                    'type' => 'object',
                    'properties' => ['stoat' => ['type' => 'integer']],
                    'required' => ['stoat'],
                ],
                'Teal' => [
                    'type' => 'object',
                    'properties' => ['marten' => ['type' => 'integer']],
                    'required' => ['marten'],
                ],
            ]],
        ];
        $key = 'object union branch class ' . md5((string)json_encode($spec));

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: $payloads,
                diverging: [GenerationMode::Symfony->value => array_fill_keys(array_keys($payloads), null)],
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>}>
     */
    public static function objectUnionBranchClassProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $openStoat = ['type' => 'object', 'properties' => ['stoat' => ['type' => 'integer']]];
        $requiredMarten = ['type' => 'object', 'properties' => ['marten' => ['type' => 'integer']], 'required' => ['marten']];

        // Cause R1: two inline object branches, the first open.
        yield 'two inline branches' => [
            ['oneOf' => [$openStoat, $requiredMarten]],
            [
                '{"plum":{"marten":1,"stoat":"x"}}' => true,
                '{"plum":{"stoat":1}}' => true,
                '{"plum":{"marten":1}}' => false,
                '{"plum":{"stoat":1,"marten":1}}' => false,
                '{"plum":{"stoat":"x"}}' => false,
            ],
        ];
        // Cause R1: an inline open branch beside a `$ref`.
        yield 'inline branch beside a ref' => [
            ['oneOf' => [$openStoat, $ref('Teal')]],
            [
                '{"plum":{"marten":1,"stoat":"x"}}' => true,
                '{"plum":{"stoat":1}}' => true,
                '{"plum":{"marten":1}}' => false,
            ],
        ];
        // Cause R2: an `allOf` around a `$ref` as a branch.
        yield 'allOf around a ref' => [
            ['oneOf' => [$ref('Olive'), ['allOf' => [$ref('Teal'), ['type' => 'object', 'properties' => ['newt' => ['type' => 'string']]]]]]],
            [
                '{"plum":{"stoat":1}}' => true,
                '{"plum":{"marten":1}}' => true,
                '{"plum":{"marten":1,"newt":"n"}}' => true,
                '{"plum":{"stoat":1,"marten":1}}' => false,
                '{"plum":{"marten":1,"newt":2}}' => false,
                '{"plum":{}}' => false,
            ],
        ];
        // Cause R2: a `$ref` with `properties: {}` beside it, against an open inline branch.
        yield 'ref with empty properties beside it' => [
            ['oneOf' => [$openStoat, ['properties' => [], '$ref' => '#/components/schemas/Teal']]],
            [
                '{"plum":{"stoat":1}}' => true,
                '{"plum":{"marten":1}}' => false,
                '{"plum":{"stoat":1,"marten":1}}' => false,
            ],
        ];
        // Cause R1 beside a scalar branch and a bare `$ref`.
        yield 'inline branch beside an integer and a ref' => [
            ['oneOf' => [['type' => 'integer'], $openStoat, $ref('Teal')]],
            [
                '{"plum":3}' => true,
                '{"plum":{"stoat":1}}' => true,
                '{"plum":{"marten":1,"stoat":"x"}}' => true,
                '{"plum":{"marten":1}}' => false,
                '{"plum":"x"}' => false,
            ],
        ];
        // Cause R1 on a nullable property.
        yield 'nullable inline branches' => [
            ['oneOf' => [$openStoat, $requiredMarten, ['type' => 'null']]],
            [
                '{"plum":null}' => true,
                '{"plum":{"marten":1,"stoat":"x"}}' => true,
                '{"plum":{"marten":1}}' => false,
            ],
        ];
        // Neighbour: two `$ref` branches already worked.
        yield 'two refs' => [
            ['oneOf' => [$ref('Olive'), $ref('Teal')]],
            [
                '{"plum":{"stoat":1}}' => true,
                '{"plum":{"marten":1}}' => true,
                '{"plum":{"stoat":1,"marten":1}}' => false,
            ],
        ];
    }

    /**
     * A `format: date-time` string beside TWO or more object branches — typed
     * `DateTimeImmutable|FoxA|FoxB|array` in yii3 — got `#[ToString]` before `#[ToDateTime]`: the guard
     * that keeps it off a union holding a generated class asked for exactly ONE class, so two let it
     * through. `ToString` emptied the object into `""`, the property was left unset, and the interpreter
     * and the nested validation saw no value: `{"hue":"zzq"}` was accepted and `{"tint":"a"}` held as
     * null. One object branch, a plain string and no string at all were already right.
     *
     * @param array<string, mixed> $property the schema of `fox`
     * @param array<string, bool> $payloads
     * @param list<string> $heldObjects payloads whose `fox` yii3 must hold as an object
     */
    #[DataProvider('dateBesideObjectBranchesProvider')]
    public function testADateBesideObjectBranchesKeepsTheObject(array $property, array $payloads, array $heldObjects): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => ['Probe' => ['type' => 'object', 'properties' => ['fox' => $property]]]],
        ];
        $key = 'date beside object branches ' . md5((string)json_encode($spec));

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: $key, payloads: $payloads),
        );

        $fqcn = $this->generate($spec, $this->namespaceFor(GenerationMode::Yii3, $key), GenerationMode::Yii3->value);
        foreach ($heldObjects as $json) {
            $payload = json_decode($json, true);
            $this->assertIsArray($payload);
            $input = (new Yii3Container())->hydrateValidatedInput(class: $fqcn, payload: $payload);
            $this->assertNotNull($input->getFox(), $json);
        }
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>, 2: list<string>}>
     */
    public static function dateBesideObjectBranchesProvider(): iterable
    {
        $date = ['type' => 'string', 'format' => 'date-time'];
        $hue = ['type' => 'object', 'properties' => ['hue' => ['type' => 'integer']]];
        $tint = ['type' => 'object', 'properties' => ['tint' => ['type' => 'string']], 'required' => ['tint']];
        $dates = [
            '{"fox":"2024-01-02T03:04:05+00:00"}' => true,
            '{"fox":"nope"}' => false,
        ];

        // Cause: two object branches beside the date.
        yield 'date beside two object branches' => [
            ['anyOf' => [$date, $hue, $tint]],
            $dates + [
                '{"fox":{"hue":"zzq"}}' => false,
                '{"fox":{"hue":null}}' => false,
                '{"fox":{"tint":"a"}}' => true,
                '{"fox":{"hue":1}}' => true,
            ],
            ['{"fox":{"tint":"a"}}', '{"fox":{"hue":1}}'],
        ];
        // Neighbour: one object branch.
        yield 'date beside one object branch' => [
            ['anyOf' => [$date, $hue]],
            $dates + ['{"fox":{"hue":"zzq"}}' => false, '{"fox":{"hue":1}}' => true],
            ['{"fox":{"hue":1}}'],
        ];
        // Neighbour: two object branches, no date.
        yield 'two object branches without a date' => [
            ['anyOf' => [$hue, $tint]],
            ['{"fox":{"hue":"zzq"}}' => false, '{"fox":{"tint":"a"}}' => true, '{"fox":{"hue":1}}' => true],
            ['{"fox":{"tint":"a"}}'],
        ];
    }

    /**
     * A union of generated classes BELOW the root — `Den.walrus: anyOf [$ref Red, $ref Blue]` reached
     * through `Probe.hyena` — had laravel-data add the FIRST member's rules at its path, while the
     * constructor built whichever member validates. A valid Blue was refused for Red's `shade: string`
     * or Red's `kind` enum. The member checks now follow the member the constructor picks; an unknown tag
     * is refused, not a `CannotCastEnum` 500. The root union was already right.
     *
     * Symfony is unasserted on a later member: its serializer builds the members of a union type in
     * class-name order, and whether it moves past the first depends on its version (README.support-matrix,
     * "an object only a member whose class name does not sort first … accepts").
     *
     * @param array<string, mixed>|null $hyena the schema of `hyena`, or null for `walrus` on the root
     * @param array<string, bool> $payloads
     * @param list<string> $laterMembers valid payloads of a later member, symfony left unasserted
     */
    #[DataProvider('unionOfClassesBelowTheRootProvider')]
    public function testAUnionOfClassesBelowTheRootChecksTheMemberItBuilds(?array $hyena, array $payloads, array $laterMembers): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $walrus = ['oneOf' => [$ref('Red'), $ref('Blue')]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => $hyena === null ? ['walrus' => $walrus] : ['hyena' => $hyena]],
                'Den' => ['type' => 'object', 'properties' => ['walrus' => $walrus]],
                'Red' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['Red']], 'tail' => ['type' => 'string']],
                    'required' => ['kind', 'tail'],
                ],
                'Blue' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['Blue']], 'wing' => ['type' => 'boolean']],
                    'required' => ['kind'],
                ],
                'Pale' => [
                    'type' => 'object',
                    'properties' => ['shade' => ['type' => 'string']],
                    'required' => ['shade'],
                ],
                'Deep' => [
                    'type' => 'object',
                    'properties' => ['shade' => ['type' => 'integer']],
                    'required' => ['shade'],
                ],
                'Vat' => ['type' => 'object', 'properties' => ['walrus' => ['anyOf' => [$ref('Pale'), $ref('Deep')]]]],
            ]],
        ];
        $key = 'union of classes below the root ' . md5((string)json_encode($spec));
        $diverging = [GenerationMode::Symfony->value => array_fill_keys($laterMembers, null)];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: $key, payloads: $payloads, diverging: $diverging),
        );
        // Below the root the union is answered as on the root, message for message: the first member's
        // rules added a `Rule::enum` of its own there, and a Red without its `tail` got a second,
        // spurious "The selected hyena.walrus.kind is invalid." beside the union's report.
        if ($hyena !== null && array_key_exists('{"hyena":{"walrus":{"kind":"Red"}}}', $payloads)) {
            $rootSpec = $spec;
            $rootSpec['components']['schemas']['Probe']['properties'] = ['walrus' => $walrus];
            $rootKey = 'union of classes on the root ' . md5((string)json_encode($rootSpec));
            foreach (['{"kind":"Red"}', '{"kind":"Zzz"}', '{"kind":"Blue","wing":"x"}'] as $member) {
                $belowRoot = [];
                foreach ($this->laravelModeErrors(GenerationMode::LaravelData, $spec, $key, '{"hyena":{"walrus":' . $member . '}}') as $path => $messages) {
                    $belowRoot[$path] = $messages;
                }
                $onTheRoot = [];
                foreach ($this->laravelModeErrors(GenerationMode::LaravelData, $rootSpec, $rootKey, '{"walrus":' . $member . '}') as $path => $messages) {
                    $onTheRoot['hyena.' . $path] = $messages;
                }
                $this->assertSame(expected: $onTheRoot, actual: $belowRoot, message: $member);
            }
        }
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>|null, 1: array<string, bool>, 2: list<string>}>
     */
    public static function unionOfClassesBelowTheRootProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $walrus = ['oneOf' => [$ref('Red'), $ref('Blue')]];
        $colours = static fn(string $wrap): array => [
            sprintf($wrap, '{"kind":"Blue"}') => true,
            sprintf($wrap, '{"kind":"Blue","wing":true}') => true,
            sprintf($wrap, '{"kind":"Red","tail":"t"}') => true,
            sprintf($wrap, '{"kind":"Red"}') => false,
            sprintf($wrap, '{"kind":"Blue","wing":"x"}') => false,
            sprintf($wrap, '{"kind":"Zzz"}') => false,
            sprintf($wrap, '{"kind":"Ochre","urchin":null}') => false,
        ];

        // Cause: below the root, through a `$ref` holder, an inline object and a nullable inline object.
        $red = '{"hyena":{"walrus":{"kind":"Red","tail":"t"}}}';
        yield 'through a ref holder' => [$ref('Den'), $colours('{"hyena":{"walrus":%s}}'), [$red]];
        yield 'through an inline object' => [
            ['type' => 'object', 'properties' => ['walrus' => $walrus]],
            $colours('{"hyena":{"walrus":%s}}'),
            [$red],
        ];
        yield 'through a nullable inline object' => [
            ['anyOf' => [['type' => 'object', 'properties' => ['walrus' => $walrus]], ['type' => 'null']]],
            $colours('{"hyena":{"walrus":%s}}') + ['{"hyena":null}' => true],
            [$red],
        ];
        // Cause: members that disagree on a property's type, no enum.
        yield 'members disagreeing on a type' => [
            $ref('Vat'),
            [
                '{"hyena":{"walrus":{"shade":3}}}' => true,
                '{"hyena":{"walrus":{"shade":"a"}}}' => true,
                '{"hyena":{"walrus":{"shade":true}}}' => false,
                '{"hyena":{"walrus":{}}}' => false,
            ],
            ['{"hyena":{"walrus":{"shade":"a"}}}'],
        ];
        // Neighbour: the same union on the root.
        yield 'on the root' => [null, $colours('{"walrus":%s}'), ['{"walrus":{"kind":"Red","tail":"t"}}']];
    }

    /**
     * A list of an undiscriminated union COMPONENT — `shades: {type: array, items: $ref Shade}`,
     * `Shade: anyOf [$ref Red, $ref Blue]` — got laravel-data's `#[DataCollectionOf(Shade::class)]`.
     * `Shade` is an interface, not a Data class, and spatie resolves the attribute while it builds the
     * class's config, so every request was a `CannotFindDataClass` 500, `{}` included. The discriminated
     * union was already right.
     *
     * A list that holds valid items is not asserted in symfony and laravel without a discriminator: they
     * cannot build such an item, the README.support-matrix row on hydrating a union COMPONENT of objects
     * with no `discriminator`. laravel-data keeps the items as the decoded arrays.
     *
     * @param array<string, mixed> $shade the schema of `Shade`
     * @param array<string, bool> $payloads
     * @param list<GenerationMode> $notBuildingItems modes left out of the list of valid items
     */
    #[DataProvider('listOfAUnionComponentProvider')]
    public function testAListOfAUnionComponentIsUsable(array $shade, array $payloads, array $notBuildingItems): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'name' => ['type' => 'string'],
                    'shades' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Shade']],
                ]],
                'Shade' => $shade,
                'Red' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string'], 'tail' => ['type' => 'string']],
                    'required' => ['tail'],
                ],
                'Blue' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string'], 'wing' => ['type' => 'boolean']],
                    'required' => ['wing'],
                ],
            ]],
        ];
        $key = 'list of a union component ' . md5((string)json_encode($spec));

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: $key, payloads: $payloads),
        );
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: ['{"shades":[{"kind":"Red","tail":"t"},{"kind":"Blue","wing":true}]}' => true],
                skippedModes: $notBuildingItems,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>, 2: list<GenerationMode>}>
     */
    public static function listOfAUnionComponentProvider(): iterable
    {
        $members = [['$ref' => '#/components/schemas/Red'], ['$ref' => '#/components/schemas/Blue']];
        $payloads = [
            '{}' => true,
            '{"name":"a"}' => true,
            '{"shades":[]}' => true,
            '{"shades":[{"kind":"Blue","wing":"x"}]}' => false,
            '{"shades":[{"kind":"Red"}]}' => false,
            '{"shades":{"kind":"Red","tail":"t"}}' => false,
        ];

        // Cause: no discriminator.
        $notBuilding = [GenerationMode::Laravel];
        yield 'anyOf without a discriminator' => [['anyOf' => $members], $payloads, $notBuilding];
        yield 'oneOf without a discriminator' => [['oneOf' => $members], $payloads, $notBuilding];
        // Neighbour: the discriminated union.
        yield 'oneOf with a discriminator' => [['oneOf' => $members, 'discriminator' => ['propertyName' => 'kind']], $payloads, []];
    }

    /**
     * A free-form object spelled by an `allOf` — `allOf: [{type: object}]` — in a list item or a map
     * value, beside `null` or a scalar in an `anyOf`, has no class to build, so in the Laravel modes only
     * the raw-body check can tell a JSON list from it. That check knew an object by `type` and the
     * `anyOf` / `oneOf` branches alone, and for an item or value never asked whether a union beside a
     * scalar holds an object — `anyOf: [$ref Lynx, {type: string}]` as an item took `[1,2]` too:
     * `{"fox":[[1,2]]}` was accepted and written back as `[[1,2]]`.
     *
     * Symfony and yii3 take a JSON list for an object (README.support-matrix, "a JSON array for a `type:
     * object` property"); those payloads are not asserted there.
     *
     * @param array<string, mixed> $fox
     * @param array<string, bool> $payloads
     */
    #[DataProvider('freeFormObjectByAnAllOfProvider')]
    public function testAFreeFormObjectSpelledByAnAllOfIsNotAList(array $fox, array $payloads): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => ['fox' => $fox]];
        $spec['components']['schemas']['Lynx'] = ['type' => 'object', 'properties' => ['ear' => ['type' => 'string']]];
        $lists = array_filter(
            array: $payloads,
            callback: static fn(bool $accepted, string $json): bool => !$accepted && str_contains($json, '[1,2]'),
            mode: ARRAY_FILTER_USE_BOTH,
        );
        $unasserted = array_map(static fn(bool $accepted): ?bool => null, $lists);

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'free-form object by an allOf ' . md5((string)json_encode($fox)),
                payloads: $payloads,
                diverging: ['symfony' => $unasserted, 'yii3' => $unasserted],
            ),
        );
    }

    /**
     * @return iterable<string, array{array<string, mixed>, array<string, bool>}>
     */
    public static function freeFormObjectByAnAllOfProvider(): iterable
    {
        $object = ['allOf' => [['type' => 'object']]];
        $list = static fn(array $items): array => ['type' => 'array', 'items' => $items];
        $map = static fn(array $values): array => ['type' => 'object', 'additionalProperties' => $values];

        // Cause: the `allOf` beside `null`, and a union of an object and a scalar as an item or value.
        yield 'list item anyOf of an allOf and null' => [
            $list(['anyOf' => [$object, ['type' => 'null']]]),
            ['{"fox":[{"a":1},null]}' => true, '{"fox":[[1,2]]}' => false, '{"fox":[5]}' => false],
        ];
        yield 'list item anyOf of an allOf and an integer' => [
            $list(['anyOf' => [$object, ['type' => 'integer']]]),
            ['{"fox":[{"a":1},5]}' => true, '{"fox":[[1,2]]}' => false, '{"fox":["a"]}' => false],
        ];
        yield 'list item anyOf of an object and an integer' => [
            $list(['anyOf' => [['type' => 'object'], ['type' => 'integer']]]),
            ['{"fox":[{"a":1},5]}' => true, '{"fox":[[1,2]]}' => false],
        ];
        yield 'list item anyOf of a class and a string' => [
            $list(['anyOf' => [['$ref' => '#/components/schemas/Lynx'], ['type' => 'string']]]),
            ['{"fox":["a",{"ear":"x"}]}' => true, '{"fox":[[1,2]]}' => false, '{"fox":[{"ear":1}]}' => false],
        ];
        yield 'map value anyOf of an allOf and a string' => [
            $map(['anyOf' => [$object, ['type' => 'string']]]),
            ['{"fox":{"ka":{"a":1},"kb":"x"}}' => true, '{"fox":{"ka":[1,2]}}' => false, '{"fox":{"ka":5}}' => false],
        ];
        yield 'map value anyOf of an allOf and null' => [
            $map(['anyOf' => [$object, ['type' => 'null']]]),
            ['{"fox":{"ka":{"a":1},"kb":null}}' => true, '{"fox":{"ka":[1,2]}}' => false],
        ];
        // Neighbours: the `allOf` alone as an item or value, and on the property beside `null`.
        yield 'list item allOf' => [$list($object), ['{"fox":[{"a":1}]}' => true, '{"fox":[[1,2]]}' => false]];
        yield 'map value allOf' => [$map($object), ['{"fox":{"ka":{"a":1}}}' => true, '{"fox":{"ka":[1,2]}}' => false]];
        yield 'property anyOf of an allOf and null' => [
            ['anyOf' => [$object, ['type' => 'null']]],
            ['{"fox":{"a":1}}' => true, '{"fox":null}' => true, '{"fox":[1,2]}' => false],
        ];
        // A list member keeps the list: the union is the interpreter's.
        yield 'list item anyOf of an allOf and an array' => [
            $list(['anyOf' => [$object, ['type' => 'array']]]),
            ['{"fox":[{"a":1},[1,2]]}' => true, '{"fox":[5]}' => false],
        ];
    }

    /**
     * A one-member `allOf` with something asserted or annotated BESIDE it is that member plus the
     * sibling, wherever it stands. Two spellings kept the wrapper and lost the member's rules: list items
     * `{allOf: [{$ref: Ochre}], description: …}` over a union component were a bare list in symfony
     * (no item class, no interpreter entry), and a property `{allOf: [{oneOf: […]}], nullable: true}`
     * (or `minProperties`) left yii3 holding an object branch as a raw array nobody checked. The bare
     * spellings beside them are the controls.
     *
     * @param array<string, mixed> $probe
     * @param array<string, bool> $payloads
     * @param array<string, array<string, bool|null>> $diverging
     */
    #[DataProvider('allOfWrapperWithSiblingsProvider')]
    public function testAnAllOfWrapperWithSiblingsIsItsMemberPlusTheSiblings(array $probe, array $payloads, array $diverging = []): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['openapi'] = '3.0.3';
        $spec['components']['schemas'] = [
            'Probe' => ['type' => 'object', 'properties' => $probe],
            'Azure' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['hexagon']]]],
            'Amber' => [
                'type' => 'object',
                'required' => ['kind'],
                'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']], 'egret' => ['type' => 'integer', 'maximum' => 36]],
            ],
            'Ochre' => ['anyOf' => [['$ref' => '#/components/schemas/Azure'], ['$ref' => '#/components/schemas/Amber']]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'allOf wrapper with siblings ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>, 2?: array<string, array<string, bool|null>>}>
     */
    public static function allOfWrapperWithSiblingsProvider(): iterable
    {
        $ochre = ['allOf' => [['$ref' => '#/components/schemas/Ochre']]];
        $unionItems = [
            '{"stoat":[{"kind":"circle","egret":3}]}' => true,
            '{"stoat":[{"kind":"hexagon"}]}' => true,
            '{"stoat":[]}' => true,
            '{"stoat":[{"kind":"zzq"}]}' => false,
            '{"stoat":[{"kind":"circle","egret":99}]}' => false,
            '{"stoat":[{"kind":"circle","egret":2.5}]}' => false,
        ];

        yield 'list items, no sibling' => [['stoat' => ['type' => 'array', 'items' => $ochre]], $unionItems];
        yield 'list items, description beside' => [
            ['stoat' => ['type' => 'array', 'items' => $ochre + ['description' => 'Wrapped.']]],
            $unionItems,
        ];
        yield 'list items, title and readOnly beside' => [
            ['stoat' => ['type' => 'array', 'items' => $ochre + ['title' => 'Wrapped', 'readOnly' => false]]],
            $unionItems,
        ];
        yield 'list items, nullable beside' => [
            ['stoat' => ['type' => 'array', 'items' => $ochre + ['nullable' => true]]],
            ['{"stoat":[null]}' => true] + $unionItems,
        ];
        $nested = [];
        foreach ($unionItems as $json => $accepted) {
            $nested[str_replace('"stoat":[', '"stoat":[[', substr($json, 0, -1)) . ']}'] = $accepted;
        }
        yield 'list of lists, description beside' => [
            ['stoat' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => $ochre + ['description' => 'Wrapped.']]]],
            $nested,
        ];
        yield 'list items, plain class $ref with description beside' => [
            ['stoat' => ['type' => 'array', 'items' => ['allOf' => [['$ref' => '#/components/schemas/Amber']], 'description' => 'Wrapped.']]],
            [
                '{"stoat":[{"kind":"circle","egret":3}]}' => true,
                '{"stoat":[{"kind":"zzq"}]}' => false,
                '{"stoat":[{"kind":"circle","egret":99}]}' => false,
                '{"stoat":[{"kind":"circle","egret":2.5}]}' => false,
            ],
        ];
        yield 'map value, description beside' => [
            ['stoat' => ['type' => 'object', 'additionalProperties' => $ochre + ['description' => 'Wrapped.']]],
            [
                '{"stoat":{"a":{"kind":"circle","egret":3}}}' => true,
                '{"stoat":{"a":{"kind":"hexagon"}}}' => true,
                '{"stoat":{"a":{"kind":"zzq"}}}' => false,
                '{"stoat":{"a":{"kind":"circle","egret":99}}}' => false,
                '{"stoat":{"a":{"kind":"circle","egret":2.5}}}' => false,
            ],
        ];

        $tapir = ['type' => 'object', 'properties' => ['tapir' => ['type' => 'string', 'maxLength' => 1]]];
        $union = static fn(string $keyword): array => ['allOf' => [[$keyword => [
            ['type' => 'boolean'],
            ['allOf' => [['type' => 'object'], $tapir]],
        ]]]];
        $hyena = [
            '{"hyena":true}' => true,
            '{"hyena":{"tapir":"a"}}' => true,
            '{"hyena":{"tapir":7}}' => false,
            '{"hyena":{"tapir":"abc"}}' => false,
            '{"hyena":"x"}' => false,
        ];

        yield 'wrapped oneOf, no sibling' => [['hyena' => $union('oneOf')], $hyena];
        yield 'wrapped oneOf, nullable beside' => [['hyena' => $union('oneOf') + ['nullable' => true]], ['{"hyena":null}' => true] + $hyena];
        yield 'wrapped anyOf, nullable beside' => [['hyena' => $union('anyOf') + ['nullable' => true]], ['{"hyena":null}' => true] + $hyena];
        yield 'wrapped oneOf, minProperties beside' => [['hyena' => $union('oneOf') + ['minProperties' => 0]], $hyena];
        yield 'wrapped oneOf of a number and a multipleOf object, nullable beside' => [
            ['hyena' => ['allOf' => [['oneOf' => [
                ['type' => 'boolean'],
                ['type' => 'number', 'maximum' => -4.5],
                ['allOf' => [['type' => 'object', 'properties' => ['ocelot' => ['type' => 'integer', 'multipleOf' => 3]]], ['type' => 'object', 'properties' => []]]],
            ]]], 'nullable' => true]],
            [
                '{"hyena":null}' => true,
                '{"hyena":-5}' => true,
                '{"hyena":{"ocelot":6}}' => true,
                '{"hyena":{"ocelot":true}}' => false,
                '{"hyena":{"ocelot":4}}' => false,
                '{"hyena":3}' => false,
            ],
        ];
    }

    /**
     * A union whose class branches the PHP type cannot hold, reached through a wrapper. Until 2.15.163
     * symfony lost the branch's checks in three spellings: a property `{allOf: [$ref Crim]}` over a
     * union with a list member (typed `?array`, the class branch left "is an Ivory", which any raw
     * object passed); an array COMPONENT whose items are `{allOf: [$ref Scarlet]}` over a union
     * component (a bare list, no item checks at all); and an inline union branch `{type: object, allOf:
     * […]}` (only `type: object` kept, so it matched every object beside the other branch). The bare
     * spellings beside each are the controls.
     *
     * @param array<string, mixed> $schemas
     * @param array<string, bool|null> $payloads
     * @param array<string, array<string, bool|null>> $diverging
     */
    #[DataProvider('wrappedUnionBranchProvider')]
    public function testAUnionBranchReachedThroughAWrapperKeepsItsChecks(string $openapi, array $schemas, array $payloads, array $diverging = []): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['openapi'] = $openapi;
        $spec['components']['schemas'] = $schemas;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'wrapped union branch ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, mixed>, 2: array<string, bool|null>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function wrappedUnionBranchProvider(): iterable
    {
        $ivory = [
            'type' => 'object',
            'properties' => ['yak' => ['type' => 'number'], 'egret' => ['type' => 'number', 'maximum' => 1]],
            'required' => ['yak', 'egret'],
        ];
        $crim = ['anyOf' => [['type' => 'array', 'items' => ['type' => 'string']], ['$ref' => '#/components/schemas/Ivory']]];
        $cranePayloads = [
            '{"crane":{"yak":1,"egret":0.5}}' => true,
            '{"crane":["a","b"]}' => true,
            '{"crane":{"yak":1}}' => false,
            '{"crane":{"yak":1,"egret":5}}' => false,
            '{"crane":{"yak":-5.5}}' => false,
            '{"crane":{"egret":0}}' => false,
            '{"crane":[1]}' => false,
            '{"crane":"x"}' => false,
        ];
        $craneSchemas = static fn(array $crane, array $crimSchema): array => [
            'Probe' => ['type' => 'object', 'properties' => ['crane' => $crane]],
            'Crim' => $crimSchema,
            'Ivory' => $ivory,
        ];
        $crimRef = ['$ref' => '#/components/schemas/Crim'];
        yield 'property $ref to a union with a list member' => ['3.1.0', $craneSchemas($crimRef, $crim), $cranePayloads];
        yield 'property allOf over a union with a list member' => ['3.1.0', $craneSchemas(['allOf' => [$crimRef]], $crim), $cranePayloads];
        yield 'property allOf over a union with a date, a list and a null member' => [
            '3.1.0',
            $craneSchemas(['allOf' => [$crimRef]], ['anyOf' => [['type' => 'string', 'format' => 'date'], ...$crim['anyOf'], ['type' => 'null']]]),
            [
                '{"crane":"2024-01-02"}' => true,
                '{"crane":null}' => true,
                '{"crane":{"yak":1,"egret":0}}' => true,
                '{"crane":{"yak":-5.5}}' => false,
                '{"crane":{"egret":0}}' => false,
                '{"crane":{"yak":1,"egret":5}}' => false,
            ],
        ];

        $scarletRef = ['$ref' => '#/components/schemas/Scarlet'];
        $otterSchemas = static fn(array $olive, bool $discriminated): array => [
            'Probe' => ['type' => 'object', 'properties' => ['otter' => ['$ref' => '#/components/schemas/Olive']]],
            'Olive' => $olive,
            'Crimson' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']]],
            'Azure' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'raven' => ['type' => 'string', 'minLength' => 2]]],
            'Scarlet' => ['oneOf' => [['$ref' => '#/components/schemas/Crimson'], ['$ref' => '#/components/schemas/Azure']]]
                + ($discriminated ? ['discriminator' => ['propertyName' => 'kind', 'mapping' => [
                    'oval' => '#/components/schemas/Crimson',
                    'circle' => '#/components/schemas/Azure',
                ]]] : []),
        ];
        $discriminatedItems = [
            '{"otter":[{"kind":"circle","raven":"ab"}]}' => true,
            '{"otter":[{"kind":"oval"}]}' => true,
            '{"otter":[]}' => true,
            '{"otter":["zzq"]}' => false,
            '{"otter":[{"kind":"circle","raven":"i"}]}' => false,
            '{"otter":[{"kind":"circle","raven":null}]}' => false,
        ];
        // Crimson admits every object, so an item Azure takes as well matches twice.
        $overlappingItems = [
            '{"otter":[{"kind":"circle","raven":"i"}]}' => true,
            '{"otter":[]}' => true,
            '{"otter":["zzq"]}' => false,
            '{"otter":[{"kind":"circle","raven":"ab"}]}' => false,
        ];
        foreach (['discriminated' => [true, $discriminatedItems], 'undiscriminated' => [false, $overlappingItems]] as $name => [$discriminated, $items]) {
            yield 'array component, items $ref, ' . $name => ['3.0.3', $otterSchemas(['type' => 'array', 'items' => $scarletRef], $discriminated), $items];
            yield 'array component, items allOf, ' . $name => ['3.0.3', $otterSchemas(['type' => 'array', 'items' => ['allOf' => [$scarletRef]]], $discriminated), $items];
            $inline = $otterSchemas([], $discriminated);
            $inline['Probe']['properties']['otter'] = ['type' => 'array', 'items' => ['allOf' => [$scarletRef]]];
            yield 'inline array, items allOf, ' . $name => ['3.0.3', array_diff_key($inline, ['Olive' => true]), $items];
        }
        // Since 3.0 the one-member `allOf` is the bare `items: {$ref: Azure}`, a list of DTOs: symfony's
        // serializer builds the string item into an empty `Azure`, which requires nothing — the
        // support-matrix row "a non-object ITEM of a list or map of DTOs", a framework boundary.
        yield 'array component, items allOf of a plain class' => [
            '3.0.3',
            $otterSchemas(['type' => 'array', 'items' => ['allOf' => [['$ref' => '#/components/schemas/Azure']]]], false),
            [
                '{"otter":[{"kind":"circle","raven":"ab"}]}' => true,
                '{"otter":["zzq"]}' => false,
                '{"otter":[{"kind":"circle","raven":"i"}]}' => false,
            ],
            ['symfony' => ['{"otter":["zzq"]}' => null]],
        ];

        $hyenaFragment = ['type' => 'object', 'properties' => ['hyena' => ['type' => 'string']], 'required' => ['hyena']];
        $toucanSchemas = static fn(string $keyword, array $branch): array => [
            'Probe' => ['type' => 'object', 'properties' => ['toucan' => [$keyword => [$branch, ['$ref' => '#/components/schemas/Azureb']]]]],
            'Azureb' => ['type' => 'object', 'properties' => ['sable' => ['type' => 'integer']], 'required' => ['sable']],
        ];
        $toucanPayloads = [
            '{"toucan":{"sable":16}}' => true,
            '{"toucan":{"sable":16,"llama":24}}' => true,
            '{"toucan":{"hyena":"x"}}' => true,
            '{"toucan":{}}' => false,
            '{"toucan":{"sable":"x"}}' => false,
            '{"toucan":{"hyena":3}}' => false,
        ];
        // Symfony's serializer builds the member whose class name sorts first, `Azureb` before `ProbeToucan`
        // (README.support-matrix, the inline undiscriminated union row): a value only the inline branch
        // takes is refused there, and one both take loses `hyena` on the way in.
        $boundary = ['symfony' => ['{"toucan":{"hyena":"x"}}' => null, '{"toucan":{"hyena":"x","sable":3}}' => null]];
        foreach (['bare allOf' => ['allOf' => [$hyenaFragment]], 'type beside allOf' => ['type' => 'object', 'allOf' => [['type' => 'object'], $hyenaFragment]]] as $name => $branch) {
            yield 'oneOf branch, ' . $name => ['3.1.0', $toucanSchemas('oneOf', $branch), ['{"toucan":{"hyena":"x","sable":3}}' => false] + $toucanPayloads, $boundary];
            yield 'anyOf branch, ' . $name => ['3.1.0', $toucanSchemas('anyOf', $branch), ['{"toucan":{"hyena":"x","sable":3}}' => true] + $toucanPayloads, $boundary];
        }
    }

    /**
     * A union COMPONENT whose `oneOf` holds a direct member beside a branch that is itself a union —
     * `Olive: {oneOf: [{anyOf: [$ref Amber]}, $ref Scarlet]}` — has every class of both branches as a
     * member. The runtime read only the direct one: a payload only Amber accepts was refused for the
     * keys Scarlet requires, and one both accept was built as Scarlet alone, `lemur` dropped, instead of
     * refused for matching two `oneOf` branches. The one-member nested union also got no interface file,
     * so Amber implemented nothing the property could hold. Plain `$ref`s, an `allOf` wrapper and the
     * same union written on the property are the controls.
     *
     * Symfony's serializer builds an inline union's first class, so it sits out the spelling on the
     * property (README.support-matrix).
     *
     * @param array<string, mixed> $olive
     * @param array<string, bool|null> $payloads
     * @param list<GenerationMode> $skippedModes
     */
    #[DataProvider('unionComponentNestedBranchProvider')]
    public function testAUnionComponentKeepsTheMembersOfANestedUnionBranch(
        array $olive,
        bool $inline,
        bool $overlapping,
        array $payloads,
        array $skippedModes = [],
    ): void {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['openapi'] = '3.0.3';
        $spec['components']['schemas'] = [
            'Probe' => ['type' => 'object', 'properties' => ['crane' => $inline ? $olive : ['$ref' => '#/components/schemas/Olive']]],
            'Amber' => [
                'type' => 'object',
                'required' => ['macaw', 'lemur'],
                'properties' => ['macaw' => ['type' => 'string'], 'lemur' => ['type' => 'integer']],
            ],
            'Scarlet' => $overlapping
                ? ['type' => 'object', 'required' => ['macaw'], 'properties' => ['macaw' => ['type' => 'string']]]
                : ['type' => 'object', 'required' => ['ibis'], 'properties' => ['ibis' => ['type' => 'string']]],
            'Teal' => ['type' => 'object', 'required' => ['heron'], 'properties' => ['heron' => ['type' => 'string']]],
        ];
        if (!$inline) {
            $spec['components']['schemas']['Olive'] = $olive;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union component nested branch ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                skippedModes: $skippedModes,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: bool, 2: bool, 3: array<string, bool|null>, 4?: list<GenerationMode>}>
     */
    public static function unionComponentNestedBranchProvider(): iterable
    {
        $amber = ['$ref' => '#/components/schemas/Amber'];
        $scarlet = ['$ref' => '#/components/schemas/Scarlet'];
        $teal = ['$ref' => '#/components/schemas/Teal'];
        $disjoint = [
            '{"crane":{"macaw":"ab","lemur":3}}' => true,
            '{"crane":{"ibis":"x"}}' => true,
            '{"crane":{"macaw":"ab"}}' => false,
            '{"crane":{"macaw":"ab","lemur":"x"}}' => false,
        ];
        $overlapping = [
            '{"crane":{"macaw":"ab","lemur":3}}' => false,
            '{"crane":{"macaw":"ab"}}' => true,
            '{"crane":{"lemur":3}}' => false,
        ];
        $spellings = [
            'plain $ref' => [['oneOf' => [$amber, $scarlet]], false, []],
            'allOf wrapper' => [['oneOf' => [['allOf' => [$amber]], $scarlet]], false, []],
            'nested anyOf' => [['oneOf' => [['anyOf' => [$amber]], $scarlet]], false, []],
            'nested anyOf, nullable' => [['oneOf' => [['anyOf' => [$amber], 'nullable' => true], $scarlet]], false, []],
            'nested oneOf' => [['oneOf' => [['oneOf' => [$amber]], $scarlet]], false, []],
            'nested anyOf, on the property' => [['oneOf' => [['anyOf' => [$amber]], $scarlet]], true, [GenerationMode::Symfony]],
        ];
        foreach ($spellings as $name => [$olive, $inline, $skipped]) {
            yield $name . ', disjoint' => [$olive, $inline, false, $disjoint, $skipped];
            yield $name . ', overlapping' => [$olive, $inline, true, $overlapping, $skipped];
        }

        // Two members of ONE nested `anyOf` accepting the payload are one `oneOf` branch; two of a
        // nested `oneOf` are a refusal there as well.
        $both = ['{"crane":{"macaw":"ab","lemur":3}}' => true, '{"crane":{"heron":"x"}}' => true, '{"crane":{"lemur":3}}' => false];
        yield 'nested anyOf of two overlapping members' => [['oneOf' => [['anyOf' => [$amber, $scarlet]], $teal]], false, true, $both];
        yield 'nested oneOf of two overlapping members' => [
            ['oneOf' => [['oneOf' => [$amber, $scarlet]], $teal]],
            false,
            true,
            ['{"crane":{"macaw":"ab","lemur":3}}' => false] + $both,
        ];
    }

    /**
     * A union COMPONENT whose branch is itself a union — an inline `anyOf` of two classes (`Shade:
     * {anyOf: [{anyOf: [$ref Amber, $ref Coral]}, $ref Scarlet]}`), a one-member wrapper (`{anyOf: [$ref
     * Amber]}`) or a `$ref` to another undiscriminated union component (`Mix`) — is built as the class a
     * payload matches, as a property, and in laravel as a list item. Laravel and laravel-data read only
     * bare `$ref` branches: the property stayed typed as the interface, and every payload the validator
     * accepted died on the "no discriminator" throw (laravel) or a TypeError (laravel-data). The same
     * nesting written on the property is the control; symfony's serializer builds an inline union's first
     * class (README.support-matrix), so it sits that one out.
     *
     * @param array<string, mixed> $fox
     * @param array<string, array<string, mixed>> $components
     * @param array<string, bool> $payloads
     * @param list<GenerationMode> $skippedModes
     */
    #[DataProvider('unionComponentOfNestedUnionsProvider')]
    public function testAUnionComponentOfNestedUnionsIsBuiltAsItsMatchingClass(
        array $fox,
        array $components,
        array $payloads,
        array $skippedModes = [],
    ): void {
        $closed = static fn(string $name, array $type): array => [
            'type' => 'object',
            'required' => [$name],
            'properties' => [$name => $type],
            'additionalProperties' => false,
        ];
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas'] = [
            'Probe' => ['type' => 'object', 'required' => ['fox'], 'properties' => ['fox' => $fox]],
            'Amber' => $closed('hue', ['type' => 'string']),
            'Coral' => $closed('tone', ['type' => 'integer']),
            'Scarlet' => $closed('shade', ['type' => 'boolean']),
        ] + $components;
        $key = 'union component of nested unions ' . md5((string)json_encode($spec));

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: $key, payloads: $payloads, skippedModes: $skippedModes),
        );
        foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
            foreach (array_keys(array_filter($payloads)) as $json) {
                $this->assertSame(expected: $json, actual: $this->writtenBack($mode, $spec, $key, (string)$json), message: $mode->value);
            }
        }
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, array<string, mixed>>, 2: array<string, bool>, 3?: list<GenerationMode>}>
     */
    public static function unionComponentOfNestedUnionsProvider(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $refused = ['{"fox":{"zz":1}}' => false, '{"fox":{"hue":"x","shade":true}}' => false, '{"fox":5}' => false];
        $threeClasses = [
            '{"fox":{"hue":"red"}}' => true,
            '{"fox":{"tone":3}}' => true,
            '{"fox":{"shade":true}}' => true,
            '{"fox":{"tone":"x"}}' => false,
        ] + $refused;
        $twoClasses = [
            '{"fox":{"hue":"red"}}' => true,
            '{"fox":{"shade":true}}' => true,
            '{"fox":{"tone":3}}' => false,
        ] + $refused;
        $nestedPair = ['anyOf' => [['anyOf' => [$ref('Amber'), $ref('Coral')]], $ref('Scarlet')]];
        $wrapper = ['oneOf' => [['anyOf' => [$ref('Amber')]], $ref('Scarlet')]];

        yield 'nested anyOf of two classes' => [$ref('Shade'), ['Shade' => $nestedPair], $threeClasses];
        yield 'one-member anyOf wrapper' => [$ref('Shade'), ['Shade' => $wrapper], $twoClasses];
        yield 'member that is a union component' => [
            $ref('Shade'),
            ['Mix' => ['anyOf' => [$ref('Amber'), $ref('Coral')]], 'Shade' => ['anyOf' => [$ref('Mix'), $ref('Scarlet')]]],
            $threeClasses,
        ];
        yield 'list item, nested anyOf of two classes' => [
            ['type' => 'array', 'items' => $ref('Shade')],
            ['Shade' => $nestedPair],
            [
                '{"fox":[{"tone":3}]}' => true,
                '{"fox":[{"hue":"a"},{"shade":false}]}' => true,
                '{"fox":[{"zz":1}]}' => false,
                '{"fox":[{"hue":"x","shade":true}]}' => false,
            ],
        ];
        yield 'nested anyOf of two classes, on the property' => [$nestedPair, [], $threeClasses, [GenerationMode::Symfony]];
        yield 'one-member anyOf wrapper, on the property' => [$wrapper, [], $twoClasses, [GenerationMode::Symfony]];
    }

    /**
     * A property spelled `allOf: [$ref Mauve]` over a MAP component (`Mauve: {type: object,
     * additionalProperties: …}`) is the map the bare `$ref` names: same value class or enum, same PHP
     * type, same constraints. The wrapped spelling was typed `array<string, mixed>` and its values went
     * unchecked — the runtime kept only the target's own `type: object`, symfony emitted no constraint,
     * laravel and laravel-data built no value class and ruled `'ibis.*'` nothing. `emu`, the bare `$ref`
     * beside it, is the control and pins what the short spelling always did.
     *
     * @param array<string, array<string, mixed>> $components
     * @param array<string, mixed> $ibis
     * A non-object value or item of a container of classes is the framework boundary of
     * README.support-matrix.md ("a non-object ITEM of a list or map of DTOs"), for both spellings alike.
     *
     * @param array<string, bool> $payloads
     * @param array<string, array<string, bool|null>> $diverging
     */
    #[DataProvider('mapBehindASingleRefAllOfProvider')]
    public function testAMapBehindASingleRefAllOfIsTheMapItsReferenceNames(
        array $components,
        array $ibis,
        array $payloads,
        array $diverging = [],
    ): void {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['openapi'] = '3.0.3';
        $spec['components']['schemas'] = [
            'Probe' => ['type' => 'object', 'properties' => ['ibis' => $ibis, 'emu' => ['$ref' => '#/components/schemas/Mauve']]],
        ] + $components;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'map behind a single-ref allOf ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, array<string, mixed>>, 1: array<string, mixed>, 2: array<string, bool>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function mapBehindASingleRefAllOfProvider(): iterable
    {
        $wrapped = ['allOf' => [['$ref' => '#/components/schemas/Mauve']]];
        $both = static function (array $payloads): array {
            $table = [];
            foreach ($payloads as $value => $accepted) {
                $table['{"ibis":' . $value . '}'] = $accepted;
                $table['{"emu":' . $value . '}'] = $accepted;
            }

            return $table;
        };
        $cobalt = [
            'type' => 'object',
            'properties' => ['okapi' => ['type' => 'integer'], 'hyena' => ['type' => 'string', 'maxLength' => 0]],
        ];
        // Symfony: a scalar value of a map of requirement-free classes depends on the serializer release.
        $scalarValue = ['symfony' => ['{"ibis":{"ka":"x"}}' => null, '{"emu":{"ka":"x"}}' => null]];
        $cobaltPayloads = $both([
            '{"ka":{"okapi":2,"hyena":""}}' => true,
            '{}' => true,
            '{"ka":{"okapi":2.5}}' => false,
            '{"ka":{"okapi":null}}' => false,
            '{"ka":"x"}' => false,
            '{"ka":{"hyena":"i"}}' => false,
        ]);

        yield 'a $ref value' => [
            ['Mauve' => ['type' => 'object', 'additionalProperties' => ['$ref' => '#/components/schemas/Cobalt']], 'Cobalt' => $cobalt],
            $wrapped,
            $cobaltPayloads,
            $scalarValue,
        ];
        yield 'a $ref value, annotations beside the allOf' => [
            ['Mauve' => ['type' => 'object', 'additionalProperties' => ['$ref' => '#/components/schemas/Cobalt']], 'Cobalt' => $cobalt],
            $wrapped + ['description' => 'Wrapped.', 'readOnly' => false],
            $cobaltPayloads,
            $scalarValue,
        ];
        yield 'a $ref value, nullable beside the allOf' => [
            ['Mauve' => ['type' => 'object', 'additionalProperties' => ['$ref' => '#/components/schemas/Cobalt']], 'Cobalt' => $cobalt],
            $wrapped + ['nullable' => true],
            ['{"ibis":null}' => true] + $cobaltPayloads,
            $scalarValue,
        ];
        yield 'an inline value with an enum' => [
            ['Mauve' => ['type' => 'object', 'additionalProperties' => [
                'type' => 'object',
                'properties' => ['ferret' => ['type' => 'integer', 'enum' => [-36, -24]]],
                'required' => ['ferret'],
            ]]],
            $wrapped,
            $both([
                '{"ka":{"ferret":-24}}' => true,
                '{"ka":{"ferret":-102}}' => false,
                '{"ka":{}}' => false,
                '{"ka":"x"}' => false,
            ]),
        ];
        yield 'an inline value with a string enum and a bound' => [
            ['Mauve' => ['type' => 'object', 'additionalProperties' => [
                'type' => 'object',
                'properties' => ['hyena' => ['type' => 'string', 'maxLength' => 0], 'kind' => ['type' => 'string', 'enum' => ['red']]],
            ]]],
            $wrapped,
            $both([
                '{"ka":{"hyena":"","kind":"red"}}' => true,
                '{"ka":{"hyena":"i"}}' => false,
                '{"ka":{"kind":"zzq"}}' => false,
            ]),
        ];
        yield 'a discriminated union value' => [
            [
                'Coral' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']], 'robin' => ['type' => 'string', 'enum' => ['red']]],
                    'required' => ['kind', 'robin'],
                ],
                'Umber' => [
                    'type' => 'object',
                    'properties' => ['kind' => ['type' => 'string', 'enum' => ['hexagon']], 'raven' => ['type' => 'boolean']],
                    'required' => ['kind'],
                ],
                'Crimson' => [
                    'oneOf' => [['$ref' => '#/components/schemas/Coral'], ['$ref' => '#/components/schemas/Umber']],
                    'discriminator' => [
                        'propertyName' => 'kind',
                        'mapping' => ['circle' => '#/components/schemas/Coral', 'hexagon' => '#/components/schemas/Umber'],
                    ],
                ],
                'Mauve' => ['type' => 'object', 'additionalProperties' => ['$ref' => '#/components/schemas/Crimson']],
            ],
            $wrapped,
            $both([
                '{"ka":{"kind":"circle","robin":"red"}}' => true,
                '{"ka":{"kind":"hexagon"}}' => true,
                '{"ka":{"kind":"zzq"}}' => false,
                '{"ka":{"kind":"circle","robin":"blue"}}' => false,
            ]),
        ];
        // Pinned: a list behind the same `allOf` was unwrapped already.
        yield 'a list component' => [
            ['Mauve' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Cobalt']], 'Cobalt' => $cobalt],
            $wrapped,
            $both([
                '[{"okapi":2}]' => true,
                '[{"okapi":2.5}]' => false,
                '["x"]' => false,
                '[{"hyena":"i"}]' => false,
            ]),
            [
                'symfony' => ['{"ibis":["x"]}' => null, '{"emu":["x"]}' => null],
            ],
        ];
    }

    /**
     * An `allOf` part that is itself an `allOf` is flattened into the class the outer one builds, as many
     * levels down as it is written: `{allOf: [{type: object, allOf: [{properties: {kiwi}, required:
     * [kiwi]}]}]}` is the object of a required integer `kiwi`. The inner part was not merged, so the class
     * had no properties: symfony, yii3 and the runtime accepted `{"kiwi": "x"}`, symfony and yii3 an
     * object without `kiwi`, and yii3 died on `toOpenApiValidationPayload()` of the empty class.
     *
     * @param array<string, mixed> $q
     */
    #[DataProvider('nestedAllOfPartProvider')]
    public function testAnAllOfPartThatIsAnAllOfIsFlattenedIntoTheClass(array $q): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => ['q' => $q]];
        $spec['components']['schemas']['Kiwi'] = ['type' => 'object', 'properties' => ['kiwi' => ['type' => 'integer']], 'required' => ['kiwi']];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'nested allOf part ' . md5((string)json_encode($q)),
                payloads: [
                    '{"q":{"kiwi":1}}' => true,
                    '{"q":{"kiwi":1,"extra":true}}' => true,
                    '{"q":{"kiwi":"x"}}' => false,
                    '{"q":{}}' => false,
                    '{"q":5}' => false,
                ],
            ),
        );
    }

    /**
     * @return iterable<string, array{array<string, mixed>}>
     */
    public static function nestedAllOfPartProvider(): iterable
    {
        $kiwi = ['properties' => ['kiwi' => ['type' => 'integer']], 'required' => ['kiwi']];

        yield 'typed part over an allOf' => [['allOf' => [['type' => 'object', 'allOf' => [$kiwi]]]]];
        yield 'bare part over a typed allOf' => [['allOf' => [['allOf' => [['type' => 'object'] + $kiwi]]]]];
        yield 'three levels' => [['allOf' => [['allOf' => [['allOf' => [['type' => 'object'] + $kiwi]]]]]]];
        yield 'nested part beside a sibling part' => [['allOf' => [['type' => 'object'], ['allOf' => [$kiwi]]]]];
        yield 'nested part naming a $ref beside a property' => [['allOf' => [['allOf' => [
            ['$ref' => '#/components/schemas/Kiwi'],
            ['properties' => ['plum' => ['type' => 'string']]],
        ]]]]];
        // Pinned: one level, and an `allOf` beside `type: object` on the property itself.
        yield 'one level' => [['allOf' => [['type' => 'object'] + $kiwi]]];
        yield 'allOf beside type on the property' => [['type' => 'object', 'allOf' => [$kiwi]]];
    }

    /**
     * A class composed of nothing it could hold — `{properties: {}}`, an `allOf` of such parts, one
     * beside a `$ref` to one — answers every payload in every mode. Yii3 wrote no
     * `toOpenApiValidationPayload()` for a class of no properties and nothing to interpret, which its
     * own `getData()` calls: any object for it was a 500.
     */
    public function testAClassComposedOfNothingAnswersInEveryMode(): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'lark' => ['allOf' => [['allOf' => [['properties' => []]]], ['properties' => []]]],
            'wren' => ['allOf' => [['$ref' => '#/components/schemas/Hollow'], ['properties' => []]]],
            'kite' => ['$ref' => '#/components/schemas/Hollow'],
        ]];
        $spec['components']['schemas']['Hollow'] = ['properties' => []];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'class composed of nothing',
                payloads: [
                    '{"lark":{}}' => true,
                    '{"lark":{"any":1}}' => true,
                    '{"wren":{}}' => true,
                    '{"kite":{"any":"x"}}' => true,
                    '{}' => true,
                ],
            ),
        );
    }

    /**
     * A property, list item or map value typed as a union COMPONENT of classes with no `discriminator`
     * (`Shade: {anyOf: [$ref Zebra, $ref Ant]}`) is held in symfony mode as the decoded object, checked
     * against the members by the callback. It was the union's interface — `?Shade $shade`, `array<Shade>`
     * — which the serializer cannot build, so every object was refused, valid ones included, and only
     * `{}` or an empty list got through; a list of lists of it, typed `mixed` below, checked nothing.
     * Every mode answers the table the same way.
     */
    public function testAnUndiscriminatedUnionComponentIsUsableWhereverItSits(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Zebra' => ['type' => 'object', 'properties' => ['stripe' => ['type' => 'integer']], 'required' => ['stripe']],
                'Ant' => ['type' => 'object', 'properties' => ['leg' => ['type' => 'integer']], 'required' => ['leg']],
                'Shade' => ['anyOf' => [$ref('Zebra'), $ref('Ant')]],
                'Hue' => ['oneOf' => [$ref('Zebra'), $ref('Ant')]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'shade' => $ref('Shade'),
                    'hue' => $ref('Hue'),
                    'herd' => ['type' => 'array', 'items' => $ref('Shade')],
                    'flock' => ['type' => 'array', 'items' => $ref('Hue')],
                    'hues' => ['type' => 'object', 'additionalProperties' => $ref('Shade')],
                    'rows' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => $ref('Shade')]],
                ]],
            ]],
        ];
        $key = 'undiscriminated union component held as the decoded object';

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    '{"shade":{"leg":1}}' => true,
                    '{"shade":{"stripe":1}}' => true,
                    '{"shade":{"stripe":1,"leg":2}}' => true,
                    '{"shade":{}}' => false,
                    '{"shade":{"stripe":"x"}}' => false,
                    '{"shade":5}' => false,
                    '{"hue":{"leg":1}}' => true,
                    '{"hue":{"stripe":1,"leg":2}}' => false,
                    '{"herd":[{"leg":1}]}' => true,
                    '{"herd":[{"leg":1},{"stripe":2}]}' => true,
                    '{"herd":[{}]}' => false,
                    '{"herd":[{"stripe":"x"}]}' => false,
                    '{"flock":[{"leg":1}]}' => true,
                    '{"flock":[{"stripe":1,"leg":2}]}' => false,
                    '{"hues":{"ka":{"leg":1},"kb":{"stripe":2}}}' => true,
                    '{"hues":{"ka":{}}}' => false,
                    '{"rows":[[{"leg":1}],[{"stripe":2}]]}' => true,
                    '{"rows":[[{}]]}' => false,
                    // Neighbours: nothing, and empty containers.
                    '{}' => true,
                    '{"herd":[]}' => true,
                    '{"hues":{}}' => true,
                ],
            ),
        );

        // A union of INLINE members beside the object's own keywords, `nullable` beside the reference:
        // the null it admits matched both untyped members, refused as matching more than one. Symfony
        // only — the others are warned about this shape at generation time (UnhydratableUnionParityTest).
        $contact = [
            'type' => 'object',
            'required' => ['kind', 'value'],
            'additionalProperties' => false,
            'properties' => ['kind' => ['type' => 'string', 'enum' => ['mail', 'phone']], 'value' => ['type' => 'string']],
            // `type: object` makes each arm a member class; without it the arms only narrow Shade's own
            // properties and Shade is one class (`testAnObjectBesideAnAnyOfOfPropertyFragmentsIsOneClass`).
            'oneOf' => [
                ['type' => 'object', 'properties' => ['kind' => ['enum' => ['mail']], 'value' => ['format' => 'email']]],
                ['type' => 'object', 'properties' => ['kind' => ['enum' => ['phone']], 'value' => ['pattern' => '^[0-9]{7,15}$']]],
            ],
        ];
        $inlineSpec = $spec;
        $inlineSpec['components']['schemas']['Shade'] = $contact;
        $inlineSpec['components']['schemas']['Probe']['properties'] = [
            'shade' => $ref('Shade') + ['nullable' => true],
            'herd' => ['type' => 'array', 'items' => $ref('Shade')],
            'hues' => ['type' => 'object', 'additionalProperties' => $ref('Shade')],
        ];
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $inlineSpec,
                key: $key . ' with inline members',
                payloads: [
                    '{"shade":{"kind":"mail","value":"a@b.co"}}' => true,
                    '{"shade":{"kind":"phone","value":"1234567"}}' => true,
                    '{"shade":{"kind":"mail","value":"zz"}}' => false,
                    '{"shade":{"kind":"mail","value":"a@b.co","x":1}}' => false,
                    '{"shade":null}' => true,
                    '{"herd":[{"kind":"phone","value":"1234567"}]}' => true,
                    '{"herd":[{"kind":"phone"}]}' => false,
                    '{"hues":{"ka":{"kind":"mail","value":"a@b.co"}}}' => true,
                    '{"hues":{"ka":{"kind":"fax","value":"1"}}}' => false,
                ],
                skippedModes: [GenerationMode::Runtime, GenerationMode::Laravel, GenerationMode::LaravelData, GenerationMode::Yii3],
            ),
        );

        // The decoded objects, as the payload carried them.
        $dto = $this->payloadOutcome(
            mode: GenerationMode::Symfony,
            fqcn: $this->generate($spec, $this->namespaceFor(GenerationMode::Symfony, $key), GenerationMode::Symfony->value),
            json: '{"shade":{"leg":1},"herd":[{"stripe":2},{"leg":3}]}',
            symfonyContext: self::SYMFONY_REQUEST_PAYLOAD_CONTEXT,
        )->dto;
        $this->assertIsObject($dto);
        $this->assertSame(expected: ['leg' => 1], actual: $dto->getShade());
        $this->assertSame(expected: [['stripe' => 2], ['leg' => 3]], actual: $dto->getHerd());

        // The interface stays in the type: a DTO built by hand — a response — still holds a member, and
        // the callback judges it as the payload it reports.
        $namespace = $this->namespaceFor(GenerationMode::Symfony, $key);
        $probeClass = $namespace . '\Probe';
        $zebraClass = $namespace . '\Zebra';
        $antClass = $namespace . '\Ant';
        $built = new $probeClass();
        $built->setShade(new $zebraClass(stripe: 1));
        $built->setHue(new $antClass(leg: 2));
        $built->setHerd([new $antClass(leg: 3), ['stripe' => 4]]);
        $this->assertCount(
            expectedCount: 0,
            haystack: Validation::createValidatorBuilder()->enableAttributeMapping()->getValidator()->validate($built),
        );
        $built->setHerd([['stripe' => 'x']]);
        $this->assertNotCount(
            expectedCount: 0,
            haystack: Validation::createValidatorBuilder()->enableAttributeMapping()->getValidator()->validate($built),
        );
    }

    /**
     * A list item or map value of a union COMPONENT of classes with no `discriminator` (`shades: {items:
     * $ref Shade}`, `Shade: {anyOf: [$ref Olive, $ref Teal]}`) is built in laravel mode as the member it
     * matches — the first under `anyOf` — as a property of that type has been since 2.15.153. The item
     * still went to the generator's own "union with no discriminator" `RuntimeException`, a 500 for
     * every valid non-empty list. laravel-data holds such items as the decoded arrays
     * (README.support-matrix, "hydration of a union COMPONENT").
     */
    public function testAListOrMapOfAUnionComponentIsBuiltAsItsMatchingMemberInLaravel(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Olive' => ['type' => 'object', 'properties' => ['leaf' => ['type' => 'string']], 'required' => ['leaf']],
                'Teal' => ['type' => 'object', 'properties' => ['fin' => ['type' => 'integer']], 'required' => ['fin']],
                'Shade' => ['anyOf' => [$ref('Olive'), $ref('Teal')]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'shades' => ['type' => 'array', 'items' => $ref('Shade')],
                    'hues' => ['type' => 'object', 'additionalProperties' => $ref('Shade')],
                    'rows' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => $ref('Shade')]],
                    'tint' => $ref('Shade'),
                ]],
            ]],
        ];
        $key = 'list or map of a union component';

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    '{"shades":[{"fin":2}]}' => true,
                    '{"shades":[{"leaf":"x"},{"fin":2}]}' => true,
                    '{"shades":[{}]}' => false,
                    '{"shades":[{"fin":"x"}]}' => false,
                    '{"hues":{"ka":{"fin":2},"kb":{"leaf":"x"}}}' => true,
                    '{"hues":{"ka":{}}}' => false,
                    '{"rows":[[{"fin":2}],[{"leaf":"x"}]]}' => true,
                    '{"rows":[[{}]]}' => false,
                    // Neighbours: the property, and an empty list.
                    '{"tint":{"fin":2}}' => true,
                    '{"shades":[]}' => true,
                ],
                skippedModes: [GenerationMode::Runtime, GenerationMode::LaravelData, GenerationMode::Yii3],
            ),
        );

        $fqcn = $this->generate($spec, $this->namespaceFor(GenerationMode::Laravel, $key), GenerationMode::Laravel->value);
        $shortName = static fn(mixed $member): ?string => is_object($member) ? substr(strrchr($member::class, '\\') ?: $member::class, 1) : null;
        $dto = $this->payloadOutcome(
            GenerationMode::Laravel,
            $fqcn,
            '{"shades":[{"fin":2},{"leaf":"x"},{"leaf":"y","fin":3}],"hues":{"ka":{"fin":2},"kb":{"leaf":"x"}},"rows":[[{"fin":2}]],"tint":{"fin":2}}',
        )->dto;
        $this->assertIsObject($dto);
        $this->assertSame(expected: ['Teal', 'Olive', 'Olive'], actual: array_map($shortName, $dto->getShades()));
        $this->assertSame(expected: ['ka' => 'Teal', 'kb' => 'Olive'], actual: array_map($shortName, $dto->getHues()));
        $this->assertSame(expected: [['Teal']], actual: array_map(static fn(array $row): array => array_map($shortName, $row), $dto->getRows()));
        $this->assertSame(expected: 'Teal', actual: $shortName($dto->getTint()));
        $this->assertSame(
            expected: '{"shades":[{"fin":2},{"leaf":"x"}],"hues":{"ka":{"fin":2}}}',
            actual: $this->writtenBack(GenerationMode::Laravel, $spec, $key, '{"shades":[{"fin":2},{"leaf":"x"}],"hues":{"ka":{"fin":2}}}'),
        );
    }

    /**
     * A list ITEM that is an object behind a composition — `items: {allOf: [{type: object, …}]}`,
     * `items: {anyOf: [{type: object, …}, {type: null}]}` — is an object with its own class, as the
     * same schema as a property or a map value always was. It got none: the item was declared `mixed`
     * and kept as the decoded array, so an empty object item `{}` was written back as `[]`, in every
     * mode that writes one, and a list where the object belonged was held as one.
     *
     * The item is then a DTO like any other, with the limits README.support-matrix gives a list of DTOs:
     * a non-object item in symfony ("a non-object ITEM of a list or map of DTOs"), a `null`
     * item in laravel-data ("a `null` ITEM of a nullable list of DTOs").
     */
    public function testAComposedObjectItemHasItsOwnClass(): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $object = ['type' => 'object', 'properties' => ['red' => ['type' => 'string']]];
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'leaves' => ['type' => 'array', 'items' => ['anyOf' => [$object, ['type' => 'null']]]],
            'stems' => ['type' => 'array', 'items' => ['allOf' => [$object]]],
            'twigs' => ['type' => 'array', 'items' => ['oneOf' => [$object]]],
            // The controls: the same object as a property, as a map value and as a plain item.
            'petal' => ['allOf' => [$object]],
            'roots' => ['type' => 'object', 'additionalProperties' => ['allOf' => [$object]]],
            'bark' => ['type' => 'array', 'items' => $object],
        ]];
        $key = 'composed object item';

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: $key,
                payloads: [
                    '{"stems":[{}]}' => true,
                    '{"stems":[{"red":"a"}]}' => true,
                    '{"stems":[{"red":1}]}' => false,
                    '{"stems":[5]}' => false,
                    '{"leaves":[{},null]}' => true,
                    '{"leaves":[{"red":1}]}' => false,
                    '{"twigs":[{"red":"a"}]}' => true,
                    '{"twigs":[{"red":1}]}' => false,
                    '{"petal":{}}' => true,
                    '{"roots":{"ka":{}}}' => true,
                    '{"bark":[{}]}' => true,
                    '{"bark":[5]}' => false,
                ],
                diverging: [
                    'symfony' => ['{"stems":[5]}' => null, '{"bark":[5]}' => null],
                    'laravel-data' => ['{"leaves":[{},null]}' => false],
                ],
            ),
        );

        $written = ['{"stems":[{}]}', '{"stems":[{"red":"a"}]}', '{"leaves":[{}]}', '{"twigs":[{}]}', '{"petal":{}}', '{"roots":{"ka":{}}}', '{"bark":[{}]}'];
        foreach ($written as $json) {
            $this->assertSame(expected: $json, actual: $this->runtimeRoundTrip($spec, $key, $json));
            foreach ([GenerationMode::Laravel, GenerationMode::LaravelData] as $mode) {
                $this->assertSame(
                    expected: $json,
                    actual: $this->writtenBack($mode, $spec, $key, $json),
                    message: $mode->value,
                );
            }
        }

        // Symfony and yii3 write nothing back: the item they hold is the class, not an array.
        foreach ([GenerationMode::Symfony, GenerationMode::Yii3] as $mode) {
            $this->generate($spec, $this->namespaceFor($mode, $key), $mode->value);
            foreach (['Stems', 'Leaves', 'Twigs'] as $name) {
                $this->assertTrue(
                    condition: class_exists($this->namespaceFor($mode, $key) . '\Probe' . $name . 'Item'),
                    message: $mode->value . ' ' . $name,
                );
            }
        }
    }

    /**
     * A JSON list is not an object, also where the object is spelled by an `allOf`: a list item or a
     * map value `{allOf: [{type: object}]}`, the same inside an `anyOf` beside `null`. The runtime read
     * only `type` and the `anyOf` / `oneOf` branches to know that a value had to be an object, never an
     * `allOf`, and took `[1, 2]` for one.
     *
     * Symfony and yii3 build the object before anything sees the raw body, and take a JSON list for an
     * object everywhere: README.support-matrix, "a JSON array for a `type: object` property". Those
     * payloads are not asserted there, nor a scalar item of a list of DTOs ("a non-object ITEM of a
     * list or map of DTOs"); laravel-data refuses a `null` one ("a `null` ITEM of a nullable list of
     * DTOs").
     *
     * @param array<string, mixed> $fox
     * @param array<string, bool> $payloads
     * @param array<string, array<string, bool|null>> $diverging mode => payloads it answers otherwise
     */
    #[DataProvider('objectOnlyByAllOfProvider')]
    public function testAnObjectSpelledByAnAllOfIsNotAList(array $fox, array $payloads, array $diverging = []): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => ['fox' => $fox]];
        $builtFirst = [];
        foreach (array_keys($payloads) as $json) {
            if (preg_match('/\[\[|"a":\[|"fox":\[1|\[5\]/', $json) === 1) {
                $builtFirst[$json] = null;
            }
        }
        $diverging += ['symfony' => [], 'yii3' => [], 'laravel-data' => []];
        $diverging['symfony'] += $builtFirst;
        $diverging['yii3'] += $builtFirst;
        if (array_key_exists('{"fox":[null]}', $payloads)) {
            $diverging['laravel-data'] += ['{"fox":[null]}' => false];
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'object by allOf ' . md5((string)json_encode($fox)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>, 2?: array<string, array<string, bool|null>>}>
     */
    public static function objectOnlyByAllOfProvider(): iterable
    {
        $crane = ['type' => 'object', 'properties' => ['crane' => ['type' => 'string']]];
        $list = static fn(array $items): array => ['type' => 'array', 'items' => $items];
        $listPayloads = [
            '{"fox":[{"crane":"a"}]}' => true,
            '{"fox":[[1,2]]}' => false,
            '{"fox":[["a"]]}' => false,
            '{"fox":[5]}' => false,
            '{"fox":[{"crane":1}]}' => false,
        ];

        // Cause: the object is an `allOf`.
        yield 'list item allOf' => [$list(['allOf' => [$crane]]), $listPayloads];
        yield 'list item anyOf of an allOf and null' => [
            $list(['anyOf' => [['allOf' => [['type' => 'object']]], ['type' => 'null']]]),
            ['{"fox":[{},null]}' => true, '{"fox":[[1,2]]}' => false, '{"fox":[5]}' => false],
        ];
        yield 'list item anyOf of a two-member allOf and null' => [
            $list(['anyOf' => [
                ['allOf' => [$crane, ['type' => 'object', 'properties' => ['fox' => ['type' => 'string']]]]],
                ['type' => 'null'],
            ]]),
            $listPayloads + ['{"fox":[null]}' => true],
        ];
        yield 'map value allOf' => [
            ['type' => 'object', 'additionalProperties' => ['allOf' => [['type' => 'object']]]],
            ['{"fox":{"a":{}}}' => true, '{"fox":{"a":[1,2]}}' => false, '{"fox":{"a":5}}' => false],
        ];
        // Neighbours: no `allOf`, and the `allOf` on the property itself.
        yield 'list item anyOf of an object and null' => [$list(['anyOf' => [$crane, ['type' => 'null']]]), $listPayloads];
        yield 'property allOf' => [
            ['allOf' => [$crane]],
            ['{"fox":{"crane":"a"}}' => true, '{"fox":[1,2]}' => false, '{"fox":{"crane":1}}' => false],
        ];
    }

    /**
     * A union member whose `required` names a key it does not declare — `{$ref: Teal, required:
     * [zebu]}`, an inline object with `required: [zebu]` and no `zebu` property — matches only a
     * payload that carries that key. The member's class has no slot for it, and the runtime counted
     * the member as matched once the class was built: `{"marten": 1}` matched `$ref Teal` without
     * `zebu`, so an `anyOf` let it through and a `oneOf` refused it as matching two members. Such a
     * member of a union COMPONENT got no class at all.
     *
     * @param array<string, mixed> $plum
     * @param array<string, bool> $payloads
     */
    #[DataProvider('unionMemberUndeclaredRequiredProvider')]
    public function testAUnionMemberRequiresTheKeysItDoesNotDeclare(array $plum, array $payloads): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas'] = [
            'Teal' => ['type' => 'object', 'properties' => ['marten' => ['type' => 'integer']]],
            'Shade' => ['oneOf' => [
                ['type' => 'object', 'properties' => ['stoat' => ['type' => 'integer']]],
                ['$ref' => '#/components/schemas/Teal', 'required' => ['zebu']],
            ]],
            'Probe' => ['type' => 'object', 'properties' => ['plum' => $plum]],
        ];
        $key = 'union member undeclared required ' . md5((string)json_encode($plum));

        foreach ($payloads as $json => $accepted) {
            $this->assertSame(
                expected: $accepted,
                actual: !str_starts_with($this->runtimeRoundTrip($spec, $key, $json), 'refused'),
                message: $json . ': ' . $this->runtimeRoundTrip($spec, $key, $json),
            );
        }
    }

    /**
     * @return iterable<string, array{array<string, mixed>, array<string, bool>}>
     */
    public static function unionMemberUndeclaredRequiredProvider(): iterable
    {
        $teal = ['$ref' => '#/components/schemas/Teal', 'required' => ['zebu']];
        $stoat = ['type' => 'object', 'properties' => ['stoat' => ['type' => 'integer']]];

        // Cause: the member is a `$ref` with `required` beside it, or an inline object.
        yield 'anyOf string or ref' => [
            ['anyOf' => [['type' => 'string'], $teal]],
            ['{"plum":{"marten":1}}' => false, '{"plum":{"marten":1,"zebu":2}}' => true, '{"plum":"a"}' => true],
        ];
        yield 'oneOf object or ref' => [
            ['oneOf' => [$stoat, $teal]],
            [
                '{"plum":{"marten":1}}' => true,
                '{"plum":{"stoat":1}}' => true,
                // Both members match.
                '{"plum":{"marten":1,"zebu":2}}' => false,
            ],
        ];
        yield 'oneOf required object or ref' => [
            ['oneOf' => [$stoat + ['required' => ['stoat']], $teal]],
            ['{"plum":{"stoat":1}}' => true, '{"plum":{"marten":1}}' => false, '{"plum":{"marten":1,"zebu":2}}' => true],
        ];
        yield 'oneOf of two inline objects' => [
            ['oneOf' => [
                $stoat + ['required' => ['stoat']],
                ['type' => 'object', 'properties' => ['marten' => ['type' => 'integer']], 'required' => ['zebu']],
            ]],
            ['{"plum":{"stoat":1}}' => true, '{"plum":{"marten":1}}' => false, '{"plum":{"marten":1,"zebu":2}}' => true],
        ];
        // The union as a component: its member was not even a class, and every payload was refused
        // as "Unsupported type".
        $shade = ['$ref' => '#/components/schemas/Shade'];
        yield 'component oneOf' => [
            $shade,
            ['{"plum":{"marten":1}}' => true, '{"plum":{"stoat":1}}' => true, '{"plum":{"marten":1,"zebu":2}}' => false],
        ];
        yield 'list of a component oneOf' => [
            ['type' => 'array', 'items' => $shade],
            ['{"plum":[{"marten":1}]}' => true, '{"plum":[{"stoat":1}]}' => true, '{"plum":[{"marten":1,"zebu":2}]}' => false],
        ];
        // Neighbours: the same `required` beside a `$ref` outside a union, and on an inline member.
        yield 'ref outside a union' => [$teal, ['{"plum":{"marten":1}}' => false, '{"plum":{"marten":1,"zebu":2}}' => true]];
        yield 'anyOf string or inline object' => [
            ['anyOf' => [['type' => 'string'], ['type' => 'object', 'properties' => ['marten' => ['type' => 'integer']], 'required' => ['zebu']]]],
            ['{"plum":{"marten":1}}' => false, '{"plum":{"marten":1,"zebu":2}}' => true],
        ];
    }

    /**
     * A union COMPONENT whose member is an alias (`Alias: {$ref: Hen}`) checks the member as the class
     * the alias names. The alias gets no class of its own, and symfony's branch marker named it, so
     * every object was refused as matching no branch while the DTO held a `Hen`. The same alias in an
     * inline union already resolved, and is the neighbour pinned here.
     */
    public function testAnAliasMemberOfAUnionComponentIsTheClassItNames(): void
    {
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'fox' => ['$ref' => '#/components/schemas/Mix'],
                            'owl' => ['oneOf' => [
                                ['$ref' => '#/components/schemas/Alias'],
                                ['type' => 'array', 'items' => ['type' => 'integer']],
                            ]],
                        ],
                    ],
                    'Hen' => ['type' => 'object', 'properties' => ['tern' => ['type' => 'string']]],
                    'Alias' => ['$ref' => '#/components/schemas/Hen'],
                    'Mix' => ['oneOf' => [
                        ['$ref' => '#/components/schemas/Alias'],
                        ['type' => 'array', 'items' => ['type' => 'integer']],
                    ]],
                ],
            ],
        ];
        $payloads = [];
        foreach (['fox', 'owl'] as $field) {
            $payloads += [
                sprintf('{"%s":{"tern":"x"}}', $field) => true,
                sprintf('{"%s":[1]}', $field) => true,
                sprintf('{"%s":{"tern":1}}', $field) => false,
                sprintf('{"%s":["a"]}', $field) => false,
            ];
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'alias member of a union component', payloads: $payloads),
        );
    }

    /**
     * A component that writes no keyword (`Anything: {}`, `Desc: {description: …}`) admits any JSON
     * value, as the inline `{}` does, and is `mixed` like it. It used to be an empty final class: symfony
     * refused an object in a union with it and wrote `3` back as `[]`, yii3 died calling a method the
     * class did not have, and a list matched no branch but the array one, so a `oneOf` let it through.
     */
    public function testAKeywordlessComponentAdmitsAnyValue(): void
    {
        $components = [
            'Anything' => [],
            'Desc' => ['description' => 'anything'],
        ];
        $direct = self::probeSpec(['$ref' => '#/components/schemas/Anything']);
        $direct['components']['schemas']['Probe']['required'] = [];
        $direct['components']['schemas']['Probe']['properties']['owl'] = ['$ref' => '#/components/schemas/Desc'];
        $direct['components']['schemas'] += $components;
        $directPayloads = [
            '{"f":3}' => true,
            '{"f":"x"}' => true,
            '{"f":{"vole":false}}' => true,
            '{"f":[1]}' => true,
            '{"owl":"x"}' => true,
            '{"owl":{"a":1}}' => true,
            '{"owl":2.5}' => true,
        ];
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $direct, key: 'keywordless component', payloads: $directPayloads),
        );
        foreach (GenerationMode::cases() as $mode) {
            $fqcn = $this->generate($direct, $this->namespaceFor($mode, 'keywordless component'), $mode->value);
            $listed = scandir(dirname((string)(new ReflectionClass($fqcn))->getFileName()));
            $this->assertIsArray($listed);
            $this->assertNotContains('Anything.php', $listed, $mode->value);
            $this->assertNotContains('Desc.php', $listed, $mode->value);
            // yii3 spells `mixed` as the union of the JSON types, for its hydrator.
            $this->assertContains(
                needle: (string)(new ReflectionProperty($fqcn, 'f'))->getType(),
                haystack: ['mixed', 'array|string|int|float|bool|null'],
                message: $mode->value,
            );
        }
        // Both keys present: laravel-data writes an absent optional key back as null.
        foreach (['{"f":3,"owl":"x"}', '{"f":{"vole":false},"owl":{"a":1}}', '{"f":[1],"owl":2.5}'] as $json) {
            $this->assertSame(
                expected: array_fill(0, 3, json_decode($json, true)),
                actual: $this->writtenBackByTheWritingModes($direct, 'keywordless component', $json),
                message: $json,
            );
        }

        // Symfony holds the decoded value itself, not an empty object.
        $symfonyDto = $this->payloadOutcome(
            mode: GenerationMode::Symfony,
            fqcn: $this->generate($direct, $this->namespaceFor(GenerationMode::Symfony, 'keywordless component'), 'symfony'),
            json: '{"f":3,"owl":{"a":1}}',
            symfonyContext: self::SYMFONY_REQUEST_PAYLOAD_CONTEXT,
        )->dto;
        $this->assertIsObject($symfonyDto);
        $this->assertSame(3, (new ReflectionProperty($symfonyDto, 'f'))->getValue($symfonyDto));
        $this->assertSame(['a' => 1], (new ReflectionProperty($symfonyDto, 'owl'))->getValue($symfonyDto));

        // In a union beside an array: a list matches both branches, so `oneOf` refuses it.
        $union = self::probeSpec(['oneOf' => [['$ref' => '#/components/schemas/Anything'], ['type' => 'array']]]);
        $union['components']['schemas'] += $components;
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $union,
                key: 'keywordless component in a union',
                payloads: [
                    '{"f":{"vole":false}}' => true,
                    '{"f":3}' => true,
                    '{"f":"x"}' => true,
                    '{"f":[1]}' => false,
                    '{"f":[]}' => false,
                ],
            ),
        );
    }

    /**
     * A union COMPONENT reached through a property `$ref`, with a member `{$ref: Hen, properties: {…}}`:
     * both the reference and its siblings judge an object. yii3 holds the object as the decoded array,
     * and beside a `null` member the branch went to a `Hen` class the property never holds — every
     * object passed. The union without `null` (`a`), without `bool` (`c`, the class is built) and the
     * same union inline (`bee`) already refused, and are the neighbours pinned here.
     */
    public function testARefWithSiblingsMemberOfAUnionComponentIsChecked(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $henWithSibling = $ref('Hen') + ['properties' => ['yak' => ['type' => 'number']]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'a' => $ref('Mixa'),
                            'b' => $ref('Mixb'),
                            'c' => $ref('Mixc'),
                            'd' => $ref('Mixd'),
                            'bee' => ['oneOf' => [['type' => 'string'], ['type' => 'boolean'], $henWithSibling, ['type' => 'null']]],
                        ],
                    ],
                    'Hen' => [
                        'type' => 'object',
                        'properties' => [
                            'tern' => ['type' => 'string', 'maxLength' => 2],
                            'lark' => ['type' => 'integer', 'enum' => [-36]],
                            'wren' => ['type' => 'number'],
                        ],
                    ],
                    'Mixa' => ['oneOf' => [['type' => 'string'], ['type' => 'boolean'], $henWithSibling]],
                    'Mixb' => ['oneOf' => [['type' => 'boolean'], $henWithSibling, ['type' => 'null']]],
                    'Mixc' => ['oneOf' => [['type' => 'string'], $henWithSibling, ['type' => 'null']]],
                    'Mixd' => ['oneOf' => [['type' => 'string'], ['type' => 'boolean'], $henWithSibling, ['type' => 'null']]],
                ],
            ],
        ];
        $payloads = [];
        foreach (['a', 'b', 'c', 'd', 'bee'] as $field) {
            $payloads += [
                sprintf('{"%s":{"tern":"ab","lark":-36}}', $field) => true,
                sprintf('{"%s":{"tern":"abc"}}', $field) => false,
                sprintf('{"%s":{"lark":36}}', $field) => false,
                sprintf('{"%s":{"wren":null}}', $field) => false,
                sprintf('{"%s":{"yak":"x"}}', $field) => false,
            ];
        }
        foreach (['b', 'd', 'bee'] as $field) {
            $payloads += [sprintf('{"%s":null}', $field) => true, sprintf('{"%s":true}', $field) => true];
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'ref with siblings member of a union component', payloads: $payloads),
        );
    }

    /**
     * The same member in a union of objects only (`Duo`), which yii3 types by an interface and holds as
     * the decoded array: `{$ref: Teal, required: [zebu]}` was checked as a class never built, so an
     * object that matched neither member, or both, passed. The inline list of the same union (`herd`)
     * already refused, and is the neighbour pinned here.
     */
    public function testARefWithSiblingsMemberOfAUnionOfObjectsIsChecked(): void
    {
        $duo = ['oneOf' => [
            ['type' => 'object', 'properties' => ['marten' => ['type' => 'integer']]],
            ['$ref' => '#/components/schemas/Teal', 'required' => ['zebu']],
        ]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'fox' => ['$ref' => '#/components/schemas/Duo'],
                            'herd' => ['type' => 'array', 'items' => $duo],
                        ],
                    ],
                    'Teal' => ['type' => 'object', 'properties' => ['zebu' => ['type' => 'integer']]],
                    'Duo' => $duo,
                ],
            ],
        ];
        $payloads = [
            '{"fox":{"marten":1}}' => true,
            '{"fox":{"marten":"x"}}' => false,
            '{"fox":{"marten":1,"zebu":2}}' => false,
            '{"herd":[{"marten":1}]}' => true,
            '{"herd":[{"marten":"x"}]}' => false,
            '{"herd":[{"marten":1,"zebu":2}]}' => false,
        ];

        $this->assertSame(
            expected: [],
            // laravel and laravel-data cannot hydrate an undiscriminated union of classes at all
            // (UnhydratableUnionParityTest).
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'ref with siblings member of a union of objects',
                payloads: $payloads,
                skippedModes: [GenerationMode::Laravel, GenerationMode::LaravelData],
            ),
        );
    }

    /**
     * A union component that carries object keywords beside its `oneOf` (`Shade: {type: object,
     * required: [kind], properties: {…}, oneOf: [{…}, {…}]}`). yii3 checked the decoded array against
     * the members alone, so `value` passed as a string; and `nullable` beside the reference became a
     * `null` member which the members of object keywords alone matched as well — null was refused as
     * matching more than one branch.
     */
    public function testAUnionComponentKeepsItsObjectKeywords(): void
    {
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'shade' => ['$ref' => '#/components/schemas/Shade', 'nullable' => true],
                            'plain' => ['$ref' => '#/components/schemas/Shade'],
                            'herd' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Shade']],
                        ],
                    ],
                    'Shade' => [
                        'type' => 'object',
                        'required' => ['kind'],
                        'properties' => ['kind' => ['type' => 'string'], 'value' => ['type' => 'integer']],
                        'oneOf' => [
                            ['properties' => ['kind' => ['enum' => ['phone']]], 'required' => ['value']],
                            ['properties' => ['kind' => ['enum' => ['mail']]]],
                        ],
                    ],
                ],
            ],
        ];
        $payloads = [
            '{"shade":null}' => true,
            '{"plain":null}' => false,
        ];
        foreach (['shade', 'plain'] as $field) {
            $payloads += [
                sprintf('{"%s":{"kind":"mail"}}', $field) => true,
                sprintf('{"%s":{"kind":"phone","value":1}}', $field) => true,
                sprintf('{"%s":{"kind":"phone"}}', $field) => false,
                sprintf('{"%s":{"value":1}}', $field) => false,
                sprintf('{"%s":{"value":"x","kind":"mail"}}', $field) => false,
            ];
        }
        $payloads += [
            '{"herd":[{"kind":"mail","value":1}]}' => true,
            '{"herd":[{"value":"x","kind":"mail"}]}' => false,
        ];

        $this->assertSame(
            expected: [],
            // Only symfony and yii3 hydrate an undiscriminated union of classes; the other modes refuse
            // it by design (UnhydratableUnionParityTest).
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union component with object keywords',
                payloads: $payloads,
                skippedModes: [GenerationMode::Runtime, GenerationMode::Laravel, GenerationMode::LaravelData],
            ),
        );
    }

    /**
     * A union branch that is a `$ref` with sibling keywords is a class of its own (it extends the
     * target). Beside a member that admits an object — a map, a free-form object, an untyped branch —
     * the branch cannot be marked "is that class": a payload the class refuses stays the raw array the
     * map took, and only the spelling can still refuse it. The spelling was the siblings alone: the
     * target's `required`, types and lengths were gone, and an enum sibling had moved into an enum
     * class, so `{"bison":{"tern":5}}` and `{"bison":{"raven":3}}` were accepted as the array member.
     *
     * The member beside it was counted as admitting an object by its top-level `type` only: a scalar
     * spelled `allOf: [{type: string}]` or `oneOf: [string, integer]` counted as one, the union was
     * never marked, and the lossy spelling decided — `{"bison":{"tern":"c0"}}` passed `maxLength: 1`.
     *
     * @param array<string, mixed> $bison
     * @param array<string, mixed> $sienna
     * @param array<string, bool> $payloads
     * @param array<string, array<string, bool|null>> $diverging mode => payloads it answers otherwise
     */
    #[DataProvider('refWithSiblingsBesideAnObjectMemberProvider')]
    public function testARefWithSiblingsBranchBesideAnObjectMemberKeepsItsTarget(array $bison, array $sienna, array $payloads, array $diverging = []): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas'] = [
            'Probe' => ['type' => 'object', 'properties' => ['bison' => $bison]],
            'Sienna' => $sienna,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'ref with siblings beside an object member ' . md5((string)json_encode([$bison, $sienna])),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, mixed>, 2: array<string, bool>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function refWithSiblingsBesideAnObjectMemberProvider(): iterable
    {
        $sienna = ['type' => 'object', 'properties' => ['tern' => ['type' => 'string']], 'required' => ['tern']];
        $ravenBranch = ['$ref' => '#/components/schemas/Sienna', 'properties' => ['raven' => ['type' => 'integer', 'enum' => [0]]]];
        $booleanMap = ['type' => 'object', 'additionalProperties' => ['type' => 'boolean']];
        // Symfony types a union of a class and a map `array`, builds no class, and leaves the class
        // branch to the class that is never built (`x-php-checked-by-class`), its property enums moved
        // into enum types the array does not hold. An inline object member beside a map loses its enums
        // the same way. Not this question; left unasserted there.
        $unbuiltInSymfony = static fn(array $payloads): array => ['symfony' => array_fill_keys(keys: $payloads, value: null)];

        // Cause: beside a map, the branch was spelled by its siblings alone.
        yield 'beside a map' => [
            ['anyOf' => [$ravenBranch, $booleanMap]],
            $sienna,
            [
                '{"bison":{"tern":5}}' => false,
                '{"bison":{"raven":3}}' => false,
                '{"bison":{"tern":"a","raven":3}}' => false,
                '{"bison":{"tern":"a","raven":0}}' => true,
                '{"bison":{"tern":"a"}}' => true,
                '{"bison":{"lynx":true}}' => true,
                '{"bison":{"lynx":1}}' => false,
            ],
            $unbuiltInSymfony(['{"bison":{"tern":5}}', '{"bison":{"raven":3}}', '{"bison":{"tern":"a","raven":3}}', '{"bison":{"lynx":1}}']),
        ];
        yield 'beside a map, target requires nothing' => [
            ['anyOf' => [$ravenBranch, $booleanMap]],
            ['type' => 'object', 'properties' => ['tern' => ['type' => 'string']]],
            [
                '{"bison":{"raven":3}}' => false,
                '{"bison":{"raven":0}}' => true,
                '{"bison":{"tern":"a"}}' => true,
                '{"bison":{"tern":5}}' => false,
            ],
            $unbuiltInSymfony(['{"bison":{"raven":3}}', '{"bison":{"tern":5}}']),
        ];
        yield 'beside a map and a list' => [
            ['anyOf' => [
                ['$ref' => '#/components/schemas/Sienna', 'properties' => ['stoat' => ['type' => 'string'], 'raven' => ['type' => 'integer', 'enum' => [0]]]],
                ['allOf' => [['type' => 'string'], []]],
                ['type' => 'array', 'maxItems' => 3],
                $booleanMap,
            ]],
            $sienna,
            [
                '{"bison":{"raven":-65}}' => false,
                '{"bison":{"tern":"a","raven":-65}}' => false,
                '{"bison":{"tern":"a","raven":0}}' => true,
                '{"bison":"a"}' => true,
                '{"bison":[1]}' => true,
            ],
            $unbuiltInSymfony(['{"bison":{"raven":-65}}', '{"bison":{"tern":"a","raven":-65}}']),
        ];

        // Cause: a scalar member spelled by a composition counted as admitting an object.
        $shortTern = ['type' => 'object', 'properties' => ['tern' => ['type' => 'string', 'maxLength' => 1]]];
        $stoatBranch = ['$ref' => '#/components/schemas/Sienna', 'properties' => ['stoat' => ['type' => 'string']]];
        $scalarPayloads = [
            '{"bison":{"tern":"c0"}}' => false,
            '{"bison":{"tern":"c"}}' => true,
            '{"bison":{"stoat":5}}' => false,
            '{"bison":"a"}' => true,
            '{"bison":[1]}' => true,
            '{"bison":5}' => false,
        ];
        yield 'beside an allOf string' => [
            ['anyOf' => [$stoatBranch, ['allOf' => [['type' => 'string']]], ['type' => 'array']]],
            $shortTern,
            $scalarPayloads,
        ];
        yield 'beside an allOf string and an empty member' => [
            ['anyOf' => [$stoatBranch, ['allOf' => [['type' => 'string'], []]], ['type' => 'array']]],
            $shortTern,
            $scalarPayloads,
        ];
        yield 'beside a oneOf of scalars' => [
            ['anyOf' => [$stoatBranch, ['oneOf' => [['type' => 'string'], ['type' => 'integer']]], ['type' => 'array']]],
            $shortTern,
            [...$scalarPayloads, '{"bison":5}' => true, '{"bison":true}' => false],
        ];
        // Neighbours: a plain scalar member, and a member that does admit an object through a composition.
        yield 'beside a plain string' => [
            ['anyOf' => [$stoatBranch, ['type' => 'string'], ['type' => 'array']]],
            $shortTern,
            $scalarPayloads,
        ];
        yield 'beside an anyOf with a map' => [
            ['anyOf' => [$stoatBranch, ['anyOf' => [['type' => 'string'], $booleanMap]]]],
            $shortTern,
            [
                '{"bison":{"tern":"c0"}}' => false,
                '{"bison":{"tern":"c"}}' => true,
                '{"bison":"a"}' => true,
                '{"bison":{"lynx":true}}' => true,
            ],
            $unbuiltInSymfony(['{"bison":{"tern":"c0"}}']),
        ];
    }

    /**
     * A property spelled only `allOf: [{type: object}]` is typed `array` and holds any JSON object. The
     * runtime read the top-level `type` and the `anyOf` / `oneOf` branches to know a value may be an
     * object, never a top-level `allOf`, and refused every object: 'param "bark" expects array, got
     * object'. A list and a scalar stay refused, and so does an object under an `allOf` that also
     * names a non-object type.
     *
     * @param array<string, mixed> $bark
     * @param array<string, bool> $payloads
     * @param array<string, array<string, bool|null>> $diverging mode => payloads it answers otherwise
     */
    #[DataProvider('objectByAllOfAloneProvider')]
    public function testAnObjectSpelledByAnAllOfAloneHoldsAnyObject(array $bark, array $payloads, array $diverging = []): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas'] = ['Probe' => ['type' => 'object', 'properties' => ['bark' => $bark]]];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'object by allOf alone ' . md5((string)json_encode($bark)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>, 2?: array<string, array<string, bool|null>>}>
     */
    public static function objectByAllOfAloneProvider(): iterable
    {
        $payloads = ['{"bark":{}}' => true, '{"bark":{"a":1}}' => true, '{"bark":[]}' => false, '{"bark":5}' => false];
        // Symfony and yii3 take a JSON list for an object: README.support-matrix, "a JSON array for a
        // `type: object` property".
        $listTakenForAnObject = ['symfony' => ['{"bark":[]}' => null], 'yii3' => ['{"bark":[]}' => null]];

        // Cause: the object is an `allOf`.
        yield 'allOf object' => [['allOf' => [['type' => 'object']]], $payloads, $listTakenForAnObject];
        yield 'allOf object and an empty member' => [['allOf' => [['type' => 'object'], []]], $payloads, $listTakenForAnObject];
        // Neighbours: the plain object, and an `allOf` that also names a non-object type.
        yield 'object' => [['type' => 'object'], $payloads, $listTakenForAnObject];
        // Parts that disagree on `type` admit no value. yii3 declares the property as its `string` part,
        // and its hydrator dropped the object it could not cast to one, so the payload read as one
        // without the key and was accepted — until that part's raw type rule refused it.
        yield 'allOf object and string' => [
            ['allOf' => [['type' => 'object'], ['type' => 'string']]],
            ['{"bark":{}}' => false, '{"bark":{"a":1}}' => false, '{"bark":"a"}' => false, '{"bark":5}' => false, '{}' => true],
        ];
        yield 'allOf integer and string' => [
            ['allOf' => [['type' => 'integer'], ['type' => 'string']]],
            ['{"bark":{}}' => false, '{"bark":[1]}' => false, '{"bark":"a"}' => false, '{"bark":5}' => false, '{"bark":"5"}' => false, '{}' => true],
        ];
    }

    /**
     * A union of `$ref` classes is one value; JSON Schema applies every keyword beside the `oneOf` /
     * `anyOf` to that same value. Three shapes of that were lost:
     *
     * - `type: object` beside an inline discriminated union stopped the union from being hoisted into
     *   an interface with a discriminator map. Symfony then built a member by guessing and refused the
     *   valid payload ("discriminator kind must match concrete class"); yii3 counted both members as a
     *   match ("more than one allowed oneOf branch") — its interpreter read the discriminator only when
     *   exactly one branch matched.
     * - own `properties` / `required` beside the union were not checked: symfony and yii3 dropped them
     *   from the constraint of a `$ref` to a discriminated component, laravel and laravel-data from an
     *   inline union, and the runtime refused every payload of an undiscriminated union component.
     * - a union component with a `{type: 'null'}` member got a second null branch in yii3, so `null`
     *   matched two `oneOf` branches and was refused.
     *
     * @param array<string, mixed> $schemas the components; `Probe` is the class under test
     * @param array<string, bool> $payloads
     * @param array<string, array<string, bool|null>> $diverging mode => payloads it answers otherwise
     */
    #[DataProvider('unionSiblingsProvider')]
    public function testKeywordsBesideAUnionOfClassesApplyToTheValue(array $schemas, array $payloads, array $diverging = []): void
    {
        if (!class_exists(Validation::class)) {
            $this->markTestSkipped('symfony/validator not installed');
        }

        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas'] = $schemas;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union siblings ' . md5((string)json_encode($schemas)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>, 2?: array<string, array<string, bool|null>>}>
     */
    public static function unionSiblingsProvider(): iterable
    {
        $tagged = static fn(string $own, string $ownType, array $extra = []): array => [
            'type' => 'object',
            'required' => ['kind'],
            'properties' => ['kind' => ['type' => 'string', ...$extra], $own => ['type' => $ownType]],
        ];
        $members = [
            'Mail' => $tagged('stamp', 'string'),
            'Crate' => $tagged('slats', 'integer'),
        ];
        $enumMembers = [
            'Mail' => $tagged('stamp', 'string', ['enum' => ['mail']]),
            'Crate' => $tagged('slats', 'integer', ['enum' => ['crate']]),
        ];
        $union = [['$ref' => '#/components/schemas/Mail'], ['$ref' => '#/components/schemas/Crate']];
        $discriminator = [
            'propertyName' => 'kind',
            'mapping' => ['mail' => '#/components/schemas/Mail', 'crate' => '#/components/schemas/Crate'],
        ];
        $probe = static fn(array $plain): array => ['type' => 'object', 'properties' => ['plain' => $plain]];
        $tagPayloads = [
            '{"plain":{"kind":"mail","stamp":"s"}}' => true,
            '{"plain":{"kind":"crate","slats":2}}' => true,
            '{"plain":{"kind":"crate","slats":"x"}}' => false,
            '{"plain":{"kind":"mail","stamp":5}}' => false,
        ];
        $ownValue = ['type' => 'object', 'properties' => ['value' => ['type' => 'integer']]];
        // Symfony's serializer keeps no key the member it builds does not declare, so a key only the
        // union's own `properties` name is gone before anything validates: README.support-matrix, "a
        // property beside a union of classes".
        $droppedInSymfony = static fn(array $payloads): array => ['symfony' => array_fill_keys(keys: $payloads, value: null)];
        // Without a discriminator symfony builds the member whose class name sorts first (`Crate`):
        // README.support-matrix, "an object only a member whose class name does not sort first …".
        $sortedFirstInSymfony = static fn(array $payloads): array => ['symfony' => array_fill_keys(keys: $payloads, value: null)];
        $valuePayloads = [
            '{"plain":{"kind":"mail","value":"x"}}' => false,
            '{"plain":{"kind":"mail","value":1}}' => true,
            '{"plain":{"kind":"crate","slats":2,"value":3}}' => true,
            '{"plain":{"kind":"crate","slats":"x","value":3}}' => false,
        ];

        // Cause: `type: object` beside an inline discriminated union.
        yield 'inline discriminated, type object' => [
            ['Probe' => $probe(['type' => 'object', 'oneOf' => $union, 'discriminator' => $discriminator]), ...$members],
            $tagPayloads,
        ];
        // Neighbour: the same union without `type`.
        yield 'inline discriminated' => [
            ['Probe' => $probe(['oneOf' => $union, 'discriminator' => $discriminator]), ...$members],
            $tagPayloads,
        ];

        // Cause: own properties beside a discriminated union component.
        yield 'discriminated component with own properties' => [
            ['Probe' => $probe(['$ref' => '#/components/schemas/Parcel']), 'Parcel' => [...$ownValue, 'oneOf' => $union, 'discriminator' => $discriminator], ...$members],
            $valuePayloads,
            $droppedInSymfony(['{"plain":{"kind":"mail","value":"x"}}']),
        ];
        // The members declare `value` too, so every mode holds it — symfony included.
        $declaringValue = ['type' => 'object', 'required' => ['kind', 'value'], 'properties' => ['kind' => ['type' => 'string'], 'value' => ['type' => 'integer']]];
        yield 'discriminated component with own properties the members declare' => [
            [
                'Probe' => $probe(['$ref' => '#/components/schemas/Parcel']),
                'Parcel' => [
                    'type' => 'object',
                    'required' => ['value'],
                    'properties' => ['value' => ['type' => 'integer', 'minimum' => 0]],
                    'oneOf' => $union,
                    'discriminator' => $discriminator,
                ],
                'Mail' => $declaringValue,
                'Crate' => $declaringValue,
            ],
            [
                '{"plain":{"kind":"mail","value":-1}}' => false,
                '{"plain":{"kind":"crate","value":-1}}' => false,
                '{"plain":{"kind":"mail","value":1}}' => true,
                '{"plain":{"kind":"crate","value":2}}' => true,
                '{"plain":{"kind":"mail"}}' => false,
            ],
        ];
        // Cause: own properties beside an inline discriminated union.
        yield 'inline discriminated with own properties' => [
            ['Probe' => $probe([...$ownValue, 'oneOf' => $union, 'discriminator' => $discriminator]), ...$members],
            $valuePayloads,
            $droppedInSymfony(['{"plain":{"kind":"mail","value":"x"}}']),
        ];
        yield 'inline discriminated with own required and maxLength' => [
            ['Probe' => $probe([
                'type' => 'object',
                'required' => ['value'],
                'properties' => ['value' => ['type' => 'integer'], 'note' => ['type' => 'string', 'maxLength' => 2]],
                'oneOf' => $union,
                'discriminator' => $discriminator,
            ]), ...$members],
            [
                '{"plain":{"kind":"mail"}}' => false,
                '{"plain":{"kind":"mail","value":5,"note":"long"}}' => false,
                '{"plain":{"kind":"mail","value":5,"note":"ok"}}' => true,
                '{"plain":{"kind":"crate","slats":1,"value":1}}' => true,
            ],
            $droppedInSymfony(['{"plain":{"kind":"mail"}}', '{"plain":{"kind":"mail","value":5,"note":"long"}}']),
        ];
        yield 'inline anyOf with own required and maxLength' => [
            ['Probe' => $probe([
                'type' => 'object',
                'required' => ['value'],
                'properties' => ['value' => ['type' => 'integer'], 'note' => ['type' => 'string', 'maxLength' => 2]],
                'anyOf' => $union,
            ]), ...$enumMembers],
            [
                '{"plain":{"kind":"mail"}}' => false,
                '{"plain":{"kind":"mail","value":5,"note":"long"}}' => false,
                '{"plain":{"kind":"mail","value":5,"note":"ok"}}' => true,
                '{"plain":{"kind":"crate","slats":1,"value":1}}' => true,
            ],
            $sortedFirstInSymfony(['{"plain":{"kind":"mail"}}', '{"plain":{"kind":"mail","value":5,"note":"long"}}', '{"plain":{"kind":"mail","value":5,"note":"ok"}}']),
        ];
        // Cause: an undiscriminated union component with own properties.
        yield 'undiscriminated component with own properties' => [
            ['Probe' => $probe(['$ref' => '#/components/schemas/Parcel']), 'Parcel' => [...$ownValue, 'oneOf' => $union], ...$enumMembers],
            [...$valuePayloads, '{"plain":{"kind":"mail","stamp":"s"}}' => true],
        ];
        yield 'inline undiscriminated with own properties' => [
            ['Probe' => $probe([...$ownValue, 'oneOf' => $union]), ...$enumMembers],
            [...$valuePayloads, '{"plain":{"kind":"mail","stamp":"s"}}' => true],
            $sortedFirstInSymfony(['{"plain":{"kind":"mail","value":"x"}}', '{"plain":{"kind":"mail","value":1}}', '{"plain":{"kind":"mail","stamp":"s"}}']),
        ];

        // Cause: held as the decoded value — a list item, a map value — a discriminated union was a
        // `oneOf` of its members' schemas, and the tag was read only once exactly one had matched.
        yield 'list and map of an inline discriminated union' => [
            ['Probe' => ['type' => 'object', 'properties' => [
                'list' => ['type' => 'array', 'items' => ['oneOf' => $union, 'discriminator' => $discriminator]],
                'map' => ['type' => 'object', 'additionalProperties' => ['oneOf' => $union, 'discriminator' => $discriminator]],
                'orNull' => ['type' => 'array', 'items' => ['oneOf' => [...$union, ['type' => 'null']], 'discriminator' => $discriminator]],
            ]], ...$members],
            [
                '{"list":[{"kind":"mail","stamp":"s"}]}' => true,
                '{"list":[{"kind":"crate","slats":2}]}' => true,
                '{"list":[{"kind":"crate","slats":"x"}]}' => false,
                '{"list":[{"kind":"zebra"}]}' => false,
                '{"map":{"a":{"kind":"mail","stamp":"s"}}}' => true,
                '{"map":{"a":{"kind":"crate","slats":"x"}}}' => false,
                '{"orNull":[null,{"kind":"mail","stamp":"s"}]}' => true,
                '{"orNull":[{"kind":"crate","slats":"x"}]}' => false,
            ],
        ];
        // The same check on the items of a list of an undiscriminated union component.
        yield 'list of an undiscriminated component with own properties' => [
            [
                'Probe' => $probe(['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Parcel']]),
                'Parcel' => [...$ownValue, 'oneOf' => $union],
                ...$enumMembers,
            ],
            [
                '{"plain":[{"kind":"crate","value":"x"}]}' => false,
                '{"plain":[{"kind":"crate","value":1}]}' => true,
                '{"plain":[{"kind":"crate","slats":"x"}]}' => false,
            ],
        ];

        // Cause: a second null branch in a nullable union component.
        $olive = ['type' => 'object', 'required' => ['leaf'], 'properties' => ['leaf' => ['type' => 'string']]];
        $teal = ['type' => 'object', 'required' => ['fin'], 'properties' => ['fin' => ['type' => 'integer']]];
        $shade = ['$ref' => '#/components/schemas/Shade'];
        yield 'nullable union component' => [
            [
                'Probe' => ['type' => 'object', 'properties' => [
                    'one' => $shade,
                    'many' => ['type' => 'array', 'items' => $shade],
                    'map' => ['type' => 'object', 'additionalProperties' => $shade],
                ]],
                'Shade' => ['oneOf' => [['$ref' => '#/components/schemas/Olive'], ['$ref' => '#/components/schemas/Teal'], ['type' => 'null']]],
                'Olive' => $olive,
                'Teal' => $teal,
            ],
            [
                '{"one":null}' => true,
                '{"many":[null]}' => true,
                '{"map":{"a":null}}' => true,
                '{"one":{"leaf":"a"}}' => true,
                '{"many":[{"fin":1},null]}' => true,
                '{"one":{"leaf":5}}' => false,
                '{"many":[{"fin":"x"}]}' => false,
            ],
        ];
    }

    /**
     * What becomes of a key only the union's own `properties` name, once the payload passed. The value
     * is typed as the member the tag names, which has no slot for it: a slot would take a wrapper
     * class around the member, which the generator does not write. So the key is checked and then
     * dropped by laravel and laravel-data — README.support-matrix, "a property beside a union of
     * classes". The runtime keeps it: a component's members are generated as subclasses of it and
     * inherit the property, and an inline union's member keeps the keys it was sent beside its own.
     */
    public function testAKeyOnlyBesideAUnionOfClassesIsCheckedThenDropped(): void
    {
        $member = static fn(string $own): array => [
            'type' => 'object',
            'required' => ['kind'],
            'properties' => ['kind' => ['type' => 'string'], $own => ['type' => 'boolean']],
        ];
        $union = [['$ref' => '#/components/schemas/Cat'], ['$ref' => '#/components/schemas/Dog']];
        $discriminator = ['propertyName' => 'kind', 'mapping' => ['cat' => '#/components/schemas/Cat', 'dog' => '#/components/schemas/Dog']];
        $own = ['type' => 'object', 'properties' => ['value' => ['type' => 'integer']]];
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas'] = [
            'Probe' => ['type' => 'object', 'properties' => [
                'plain' => ['$ref' => '#/components/schemas/Pet'],
                'inline' => [...$own, 'oneOf' => $union, 'discriminator' => $discriminator],
            ]],
            'Pet' => [...$own, 'oneOf' => $union, 'discriminator' => $discriminator],
            'Cat' => $member('purr'),
            'Dog' => $member('bark'),
        ];

        $kept = ['inline' => ['kind' => 'dog', 'bark' => true, 'value' => 5]];
        $dropped = ['inline' => ['kind' => 'dog', 'bark' => true]];
        $this->assertEquals(
            expected: [$kept, $dropped, $dropped],
            actual: $this->writtenBackByTheWritingModes($spec, 'key beside a union', '{"inline":{"kind":"dog","bark":true,"value":5}}'),
        );
        $this->assertEquals(
            expected: [['plain' => ['kind' => 'cat', 'value' => 5]], ['plain' => ['kind' => 'cat']], ['plain' => ['kind' => 'cat']]],
            actual: $this->writtenBackByTheWritingModes($spec, 'key beside a union', '{"plain":{"kind":"cat","value":5}}'),
        );
    }

    /**
     * Laravel asks the raw body whether a `type: object` arrived as a JSON list, at every path in
     * `OPENAPI_OBJECT_PATHS`. The paths stopped one container below the property: an object two or more
     * containers down (`items.items`, `additionalProperties.items`, `additionalProperties.additionalProperties`,
     * `items.additionalProperties`, an item with properties) got none, so `[[[1]]]` was taken as the
     * object and written back keyed by index.
     *
     * @param array<string, bool> $payloads
     */
    #[DataProvider('deepObjectShapeProvider')]
    public function testAnObjectSeveralContainersDownRefusesAJsonList(array $payloads): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'ivies' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => ['type' => 'object']]],
            'reed' => ['type' => 'object', 'additionalProperties' => ['type' => 'array', 'items' => ['type' => 'object']]],
            'pond' => ['type' => 'object', 'additionalProperties' => ['type' => 'object', 'additionalProperties' => ['type' => 'object']]],
            'lily' => ['type' => 'array', 'items' => ['type' => 'object', 'additionalProperties' => ['type' => 'object']]],
            'vine' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => [
                'type' => 'object',
                'required' => ['hue'],
                'properties' => ['hue' => ['type' => 'string'], 'tint' => ['type' => 'object']],
            ]]],
            'moss' => ['type' => 'array', 'items' => ['type' => 'object']],
            'oak' => ['type' => 'object', 'additionalProperties' => ['type' => 'object']],
        ]];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'object several containers down',
                payloads: $payloads,
                // Symfony and yii3 decode the body to PHP arrays before they validate it; their wire
                // shape is not this question.
                diverging: ['symfony' => array_fill_keys(keys: array_keys($payloads), value: null), 'yii3' => array_fill_keys(keys: array_keys($payloads), value: null)],
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, bool>}>
     */
    public static function deepObjectShapeProvider(): iterable
    {
        // Cause: no raw path two containers down.
        yield 'a list where the object is' => [[
            '{"ivies":[[[]]]}' => false,
            '{"ivies":[[[1]]]}' => false,
            '{"reed":{"k":[[1]]}}' => false,
            '{"pond":{"a":{"b":[1]}}}' => false,
            '{"lily":[{"a":[1]}]}' => false,
            '{"vine":[[["x"]]]}' => false,
            '{"vine":[[{"hue":"x","tint":[1]}]]}' => false,
        ]];
        // Neighbours: one container down was refused already, and the objects themselves pass.
        yield 'one level down and the objects' => [[
            '{"moss":[[1]]}' => false,
            '{"oak":{"leaf":[1]}}' => false,
            '{"ivies":[[{}]]}' => true,
            '{"ivies":[[{"a":1}]]}' => true,
            '{"reed":{"k":[{}]}}' => true,
            '{"pond":{"a":{"b":{}}}}' => true,
            '{"lily":[{"a":{}}]}' => true,
            '{"vine":[[{"hue":"x","tint":{}}]]}' => true,
            '{"moss":[{}]}' => true,
        ]];
    }

    /**
     * Laravel spells the properties of an object no class sits under as dotted rules below a wildcard
     * path — an item that is an `allOf` of a `$ref` plus 3.0 `nullable`, an `anyOf` of a `$ref` and
     * `null`, a `$ref` two containers deep. Each such property got its schema's rules without the
     * `nullable` its schema allows, so `[{"colour": null}]` failed `string` in laravel and laravel-data.
     *
     * @param array<string, mixed> $nullWrapped the `items` of `nullWrapped`
     * @param array<string, mixed> $colour the nullable property of `Cat`
     * @param array<string, bool> $payloads
     * @param array<string, array<string, bool|null>> $diverging mode => payloads it answers otherwise
     */
    #[DataProvider('nullablePropertyOfAnInlinedItemProvider')]
    public function testANullablePropertyOfAnInlinedItemTakesNull(
        string $openApiVersion,
        array $nullWrapped,
        array $colour,
        array $payloads,
        array $diverging = [],
    ): void {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => $openApiVersion,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'nullWrapped' => ['type' => 'array', 'items' => $nullWrapped],
                    'grid' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => $ref('Cat')]],
                    'plain' => ['type' => 'array', 'items' => $ref('Cat')],
                    'single' => ['allOf' => [$ref('Cat')]],
                    'pack' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => $ref('Dog')]],
                ]],
                'Cat' => ['type' => 'object', 'properties' => ['colour' => $colour]],
                'Dog' => ['type' => 'object', 'required' => ['hue'], 'properties' => ['hue' => ['type' => 'string']]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'nullable property of an inlined item ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, mixed>, 2: array<string, mixed>, 3: array<string, bool>, 4?: array<string, array<string, bool|null>>}>
     */
    public static function nullablePropertyOfAnInlinedItemProvider(): iterable
    {
        $cat = ['$ref' => '#/components/schemas/Cat'];
        $payloads = [
            // Cause: the inlined property lost its `nullable`.
            '{"nullWrapped":[{"colour":null}]}' => true,
            '{"grid":[[{"colour":null}]]}' => true,
            // Neighbours: a wrong type is still refused there, a valid value passes, and the paths a
            // class answers for already took null.
            '{"nullWrapped":[{"colour":5}]}' => false,
            '{"nullWrapped":[{"colour":"red"}]}' => true,
            '{"nullWrapped":[null]}' => true,
            '{"grid":[[{"colour":5}]]}' => false,
            '{"grid":[[{"colour":"red"}]]}' => true,
            '{"plain":[{"colour":null}]}' => true,
            '{"plain":[{"colour":5}]}' => false,
            '{"single":{"colour":null}}' => true,
            '{"single":{"colour":5}}' => false,
            // A property that does not admit null keeps refusing it, and stays required.
            '{"pack":[[{"hue":null}]]}' => false,
            '{"pack":[[{}]]}' => false,
            '{"pack":[[{"hue":"red"}]]}' => true,
        ];

        yield '3.0 allOf and nullable' => ['3.0.3', ['allOf' => [$cat], 'nullable' => true], ['type' => 'string', 'nullable' => true], $payloads];
        yield '3.1 anyOf with null' => [
            '3.1.0',
            ['anyOf' => [$cat, ['type' => 'null']]],
            ['type' => ['string', 'null']],
            $payloads,
            // README.support-matrix, "a `null` ITEM of a nullable list of DTOs": `#[DataCollectionOf]`.
            ['laravel-data' => ['{"nullWrapped":[null]}' => false]],
        ];
    }

    /**
     * A JSON object keyed 0..n-1 decodes to the PHP list a JSON array does, and passes Laravel's `list`
     * rule. The raw body was asked only about the EMPTY object, so `{"0":1,"1":2}` was taken as the list
     * and written back as `[1,2]` — at the property and at a nested wildcard path.
     *
     * @param array<string, bool> $payloads
     */
    #[DataProvider('denseKeyedObjectForAListProvider')]
    public function testADenseKeyedObjectIsNotAList(array $payloads): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'leaf' => ['type' => 'array', 'items' => ['type' => 'integer']],
            'cell' => ['type' => 'array', 'items' => ['type' => 'array', 'items' => ['type' => 'integer']]],
            'mix' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'integer']], ['type' => 'object']]],
        ]];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'dense keyed object for a list',
                payloads: $payloads,
                // Symfony and yii3 decode the body to PHP arrays before they validate it; their wire
                // shape is not this question.
                diverging: ['symfony' => array_fill_keys(keys: array_keys($payloads), value: null), 'yii3' => array_fill_keys(keys: array_keys($payloads), value: null)],
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, bool>}>
     */
    public static function denseKeyedObjectForAListProvider(): iterable
    {
        // Cause: only an empty `{}` was refused where a `list` rule stands.
        yield 'an object keyed 0..n-1' => [[
            '{"leaf":{"0":1,"1":2}}' => false,
            '{"leaf":{"0":1}}' => false,
            '{"cell":{"0":[1]}}' => false,
            '{"cell":[{"0":1}]}' => false,
        ]];
        // Neighbours: the lists, a sparse object, the empty object, and a union that admits the object.
        yield 'lists and the object member' => [[
            '{"leaf":[1,2]}' => true,
            '{"leaf":{"1":1}}' => false,
            '{"leaf":{}}' => false,
            '{"cell":[[1],[]]}' => true,
            '{"mix":{"0":1}}' => true,
            '{"mix":[1]}' => true,
        ]];
    }

    /**
     * laravel's `toArray()` wrote an empty `type: object` two containers below the property as `[]`:
     * the mapper knew the schema of the first container only and guessed the rest with
     * `array_is_list()`, which an empty array satisfies. laravel-data is a documented divergence.
     */
    public function testAnEmptyObjectTwoContainersDownIsWrittenBackAsAnObject(): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'pond' => ['type' => 'object', 'additionalProperties' => ['type' => 'object', 'additionalProperties' => ['type' => 'object']]],
            'lily' => ['type' => 'array', 'items' => ['type' => 'object', 'additionalProperties' => ['type' => 'object']]],
            'reed' => ['type' => 'object', 'additionalProperties' => ['type' => 'array', 'items' => ['type' => 'object', 'additionalProperties' => ['type' => 'object']]]],
        ]];

        foreach ([
            // Cause: the inner level was guessed.
            '{"pond":{"a":{"b":{}}}}',
            '{"lily":[{"a":{}}]}',
            '{"reed":{"k":[{"a":{}}]}}',
            // Neighbours, written right already.
            '{"pond":{"a":{}}}',
            '{"pond":{}}',
            '{"lily":[{}]}',
            '{"lily":[{"a":{"b":1}}]}',
        ] as $json) {
            $this->assertSame(expected: $json, actual: $this->writtenBack(GenerationMode::Laravel, $spec, 'empty object two containers down', $json));
        }
    }

    /**
     * Inside a free-form value laravel rebuilt every nested JSON object from the decoded PHP array, so a
     * nested `{}` came back as `[]` and `{"0":"x"}` as `["x"]`; an untyped property was written as the
     * PHP value it held. The raw body is what says which arrays were objects. laravel-data is a
     * documented divergence.
     */
    public function testAFreeFormValueIsWrittenBackAsSent(): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'reeds' => ['type' => 'array', 'items' => ['type' => 'object']],
            'fern' => ['type' => 'object'],
            'bush' => ['type' => 'object', 'additionalProperties' => true],
            'tree' => [],
            'bag' => ['type' => 'array'],
            'twig' => ['type' => 'object', 'properties' => ['knot' => ['type' => 'object']]],
            'leaf' => ['type' => 'array', 'items' => ['type' => 'integer']],
        ]];

        foreach ([
            // Cause: nested objects of a free-form value rebuilt from the decoded array.
            '{"reeds":[{"a":{}}]}',
            '{"fern":{"a":{}}}',
            '{"bush":{"a":{"b":{}}}}',
            '{"fern":{"a":[{}]}}',
            '{"fern":{"a":{"0":"x"}}}',
            '{"tree":{}}',
            '{"tree":{"0":"x"}}',
            '{"tree":[{},{"a":{}}]}',
            '{"bag":[{}]}',
            '{"twig":{"knot":{"a":{}}}}',
            // Neighbours, written right already.
            '{"fern":{}}',
            '{"reeds":[{}]}',
            '{"fern":{"a":[1,{"b":2}]}}',
            '{"tree":[1,"x"]}',
            '{"tree":"x"}',
            '{"leaf":[1,2]}',
        ] as $json) {
            $written = $this->writtenBack(GenerationMode::Laravel, $spec, 'free form written back', $json);
            $this->assertSame(expected: $json, actual: $written);
            // The round trip keeps it.
            $this->assertSame(expected: $json, actual: $this->writtenBack(GenerationMode::Laravel, $spec, 'free form written back', $written));
        }
    }

    /**
     * The free-form values of a class that holds itself, at every level the body reaches: written out,
     * the paths stop where the schema refers back to itself.
     */
    public function testAFreeFormValueOfASelfReferringClassIsWrittenBackAsSent(): void
    {
        $spec = self::probeSpec(['type' => 'object']);
        $spec['components']['schemas']['Probe'] = ['type' => 'object', 'properties' => [
            'meta' => ['type' => 'object'],
            'next' => ['$ref' => '#/components/schemas/Probe'],
            'kids' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/Probe']],
        ]];

        foreach ([
            '{"meta":{"a":{}}}',
            '{"next":{"meta":{"a":{}}}}',
            '{"next":{"next":{"meta":{"a":{"0":"x"}}}}}',
            '{"kids":[{"kids":[{"meta":{"a":{}}}]}]}',
            '{"next":{"meta":{}}}',
        ] as $json) {
            $this->assertSame(expected: $json, actual: $this->writtenBack(GenerationMode::Laravel, $spec, 'free form in a self-referring class', $json));
        }
    }

    /**
     * A union component's branch `{allOf: [$ref Amber], nullable: true}` is Amber, or null: the 3.0
     * `nullable` beside the one-member `allOf` is what kept it from being unwrapped, and the branch was
     * then a member of no class — `Olive`'s members were Scarlet alone, so an object only Amber's
     * sibling matched was refused as `Unsupported type: Olive`, and one both members match passed a
     * `oneOf`. The same branch without `nullable` (`Olivine`) already was Amber, and is the neighbour
     * pinned here; `null` is accepted through the branch's `nullable`, as the generator reads 3.0.
     */
    public function testANullableAllOfWrappedRefMemberOfAUnionComponentIsThatMember(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'crane' => $ref('Olive'),
                            'heron' => ['allOf' => [$ref('Olive')]],
                            'egret' => ['type' => 'array', 'items' => $ref('Olive')],
                            'stork' => $ref('Olivine'),
                        ],
                    ],
                    'Amber' => [
                        'type' => 'object',
                        'properties' => ['macaw' => ['type' => 'string'], 'lemur' => ['type' => 'integer']],
                        'required' => ['macaw', 'lemur'],
                    ],
                    'Scarlet' => [
                        'type' => 'object',
                        'properties' => ['macaw' => ['type' => 'string']],
                        'required' => ['macaw'],
                    ],
                    'Olive' => ['oneOf' => [['allOf' => [$ref('Amber')], 'nullable' => true], $ref('Scarlet')]],
                    'Olivine' => ['oneOf' => [['allOf' => [$ref('Amber')]], $ref('Scarlet')]],
                ],
            ],
        ];
        $payloads = [];
        foreach (['crane' => '%s', 'heron' => '%s', 'egret' => '[%s]', 'stork' => '%s'] as $field => $wrap) {
            $payloads += [
                sprintf('{"%s":%s}', $field, sprintf($wrap, '{"macaw":"ab"}')) => true,
                sprintf('{"%s":%s}', $field, sprintf($wrap, '{"macaw":"ab","lemur":3}')) => false,
                sprintf('{"%s":%s}', $field, sprintf($wrap, '{"lemur":3}')) => false,
                sprintf('{"%s":%s}', $field, sprintf($wrap, '{"macaw":1}')) => false,
            ];
        }
        $payloads += ['{"crane":null}' => true, '{"heron":null}' => true, '{"egret":[null]}' => true];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'nullable allOf wrapped ref member', payloads: $payloads),
        );
        // The member built is Scarlet, written back without Amber's `lemur`. Only `crane` is compared:
        // laravel-data writes the absent optional keys back as null.
        $this->assertSame(
            expected: array_fill(0, 3, ['macaw' => 'ab']),
            actual: array_map(
                callback: static fn(mixed $written): mixed => is_array($written) ? $written['crane'] ?? 'absent' : $written,
                array: $this->writtenBackByTheWritingModes($spec, 'nullable allOf wrapped ref member', '{"crane":{"macaw":"ab"}}'),
            ),
        );
    }

    /**
     * A property `$ref Teal` where `Teal` is a union whose member is a `$ref` to a component that admits
     * null — `Maroon: {type: array, nullable: true}`, a list, a map, an object, the 3.1 `[array, null]` —
     * admits null itself. Only a literal `{type: null}` branch of the union was read as null, so laravel,
     * laravel-data, symfony and yii3 refused `{"lynx": null}` (laravel-data with a `TypeError`). The
     * same union inline, and the `$ref` to `Maroon` directly, already took it, and are pinned here.
     */
    public function testAUnionComponentWhoseMemberAdmitsNullTakesNull(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $schemas = [
            'Probe' => [
                'type' => 'object',
                'properties' => [
                    'lynx' => $ref('Teal'),
                    'puma' => $ref('TealOne'),
                    'ibex' => $ref('TealMix'),
                    'mink' => $ref('TealList'),
                    'seal' => $ref('TealMap'),
                    'wolf' => $ref('TealObject'),
                    'hare' => $ref('TealDuo'),
                    'mole' => ['anyOf' => [$ref('Maroon')]],
                    'newt' => $ref('Maroon'),
                ],
            ],
            'Maroon' => ['type' => 'array', 'nullable' => true],
            'MaroonList' => ['type' => 'array', 'items' => ['type' => 'integer'], 'nullable' => true],
            'MaroonMap' => ['type' => 'object', 'additionalProperties' => ['type' => 'integer'], 'nullable' => true],
            'MaroonObject' => ['type' => 'object', 'properties' => ['emu' => ['type' => 'string']], 'nullable' => true],
            'Teal' => ['anyOf' => [$ref('Maroon')]],
            'TealOne' => ['oneOf' => [$ref('Maroon')]],
            'TealMix' => ['anyOf' => [$ref('Maroon'), ['type' => 'integer']]],
            'TealList' => ['anyOf' => [$ref('MaroonList')]],
            'TealMap' => ['anyOf' => [$ref('MaroonMap')]],
            'TealObject' => ['anyOf' => [$ref('MaroonObject')]],
            'TealDuo' => ['anyOf' => [$ref('Maroon'), ['type' => 'object', 'properties' => ['plover' => ['type' => 'string']]]]],
        ];
        $spec = ['openapi' => '3.0.3', 'info' => ['title' => 'T', 'version' => '1.0.0'], 'components' => ['schemas' => $schemas]];
        $payloads = [];
        foreach (['lynx', 'puma', 'ibex', 'mink', 'seal', 'wolf', 'hare', 'mole', 'newt'] as $field) {
            $payloads[sprintf('{"%s":null}', $field)] = true;
            $payloads[sprintf('{"%s":"x"}', $field)] = false;
        }
        $payloads += [
            '{"lynx":[1]}' => true,
            '{"ibex":3}' => true,
            '{"mink":[1]}' => true,
            '{"mink":["a"]}' => false,
            '{"seal":{"a":1}}' => true,
            '{"seal":{"a":"b"}}' => false,
            '{"wolf":{"emu":"s"}}' => true,
            '{"wolf":{"emu":1}}' => false,
            '{"hare":{"plover":"s"}}' => true,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'union component member admits null', payloads: $payloads),
        );
        foreach (['lynx', 'wolf'] as $field) {
            foreach (GenerationMode::cases() as $mode) {
                if ($mode === GenerationMode::Runtime || $mode === GenerationMode::Symfony || $mode === GenerationMode::Yii3) {
                    continue;
                }
                $json = sprintf('{"%s":null}', $field);
                $this->assertSame(
                    expected: [$field => null],
                    actual: array_intersect_key(
                        (array)json_decode($this->writtenBack($mode, $spec, 'union component member admits null', $json), true),
                        [$field => true],
                    ),
                    message: $mode->value . ' ' . $json,
                );
            }
        }

        // The 3.1 spelling of the member.
        $spec31 = self::probeSpec($ref('Teal'));
        $spec31['components']['schemas']['Probe']['required'] = [];
        $spec31['components']['schemas'] += [
            'Teal' => ['anyOf' => [$ref('Maroon')]],
            'Maroon' => ['type' => ['array', 'null']],
        ];
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec31,
                key: 'union component member admits null 3.1',
                payloads: ['{"f":null}' => true, '{"f":[1]}' => true, '{"f":"x"}' => false],
            ),
        );
    }

    /**
     * A property `$ref Shape` where `Shape` is a union whose INLINE branch admits null — the 3.0
     * `{type: object, nullable: true}` or the 3.1 `type: [object, 'null']` — admits null itself: null
     * matches that branch alone, so both `oneOf` and `anyOf` hold. Only a literal `{type: null}` branch
     * or a `$ref` branch was read, so laravel-data crashed with a `TypeError` (a constructor typed
     * `Shape|Optional|array`), a required property was refused by runtime and yii3 and crashed laravel,
     * and under 3.1 laravel and laravel-data refused with `validation.array`. The same union written
     * inline on the property, a `$ref` branch to a nullable component and `nullable: true` on the union
     * component itself already took null, and are pinned here.
     */
    public function testAUnionComponentWithAnInlineNullableBranchTakesNull(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $red = ['type' => 'object', 'nullable' => true, 'properties' => ['red' => ['type' => 'string']], 'required' => ['red']];
        $blue = ['type' => 'object', 'properties' => ['blue' => ['type' => 'string']], 'required' => ['blue']];
        $schemas = [
            'Probe' => [
                'type' => 'object',
                'required' => ['heron'],
                'properties' => [
                    'crane' => $ref('Shape'),
                    'heron' => $ref('Shape'),
                    'egret' => $ref('ShapeAny'),
                    'stork' => ['oneOf' => [$red, $blue]],
                    'ibis' => $ref('ShapeViaRef'),
                    'swan' => $ref('ShapeNullable'),
                ],
            ],
            'Shape' => ['oneOf' => [$red, $blue]],
            'ShapeAny' => ['anyOf' => [$red, $blue]],
            'Circle' => $red,
            'ShapeViaRef' => ['oneOf' => [$ref('Circle'), $blue]],
            'ShapeNullable' => ['oneOf' => [$red, $blue], 'nullable' => true],
        ];
        $spec = ['openapi' => '3.0.3', 'info' => ['title' => 'T', 'version' => '1.0.0'], 'components' => ['schemas' => $schemas]];
        $payloads = ['{"heron":{"blue":"b"}}' => true];
        foreach (['crane', 'heron', 'egret', 'stork', 'ibis', 'swan'] as $field) {
            $others = $field === 'heron' ? '' : ',"heron":{"blue":"b"}';
            $payloads[sprintf('{"%s":null%s}', $field, $others)] = true;
            $payloads[sprintf('{"%s":{"red":"r"}%s}', $field, $others)] = true;
            $payloads[sprintf('{"%s":{"blue":"b"}%s}', $field, $others)] = true;
            $payloads[sprintf('{"%s":"x"%s}', $field, $others)] = false;
        }
        // Symfony builds the inline union's member whose class name sorts first: the framework boundary
        // of README.support-matrix.md, unasserted here.
        $symfonySortsTheMembers = ['symfony' => ['{"stork":{"blue":"b"},"heron":{"blue":"b"}}' => null]];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union component inline nullable branch',
                payloads: $payloads,
                diverging: $symfonySortsTheMembers,
            ),
        );

        // The 3.1 spelling of the branch, on an optional and on a required property.
        $red31 = ['type' => ['object', 'null'], 'properties' => ['red' => ['type' => 'string']], 'required' => ['red']];
        $spec31 = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => [
                    'type' => 'object',
                    'required' => ['heron'],
                    'properties' => ['crane' => $ref('Shape'), 'heron' => $ref('Shape'), 'stork' => ['oneOf' => [$red31, $blue]]],
                ],
                'Shape' => ['oneOf' => [$red31, $blue]],
            ]],
        ];
        $payloads31 = ['{"heron":{"blue":"b"}}' => true];
        foreach (['crane', 'heron', 'stork'] as $field) {
            $others = $field === 'heron' ? '' : ',"heron":{"blue":"b"}';
            $payloads31[sprintf('{"%s":null%s}', $field, $others)] = true;
            $payloads31[sprintf('{"%s":{"red":"r"}%s}', $field, $others)] = true;
            $payloads31[sprintf('{"%s":{"blue":"b"}%s}', $field, $others)] = true;
            $payloads31[sprintf('{"%s":"x"%s}', $field, $others)] = false;
        }
        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec31,
                key: 'union component inline nullable branch 3.1',
                payloads: $payloads31,
                diverging: $symfonySortsTheMembers,
            ),
        );
    }

    /**
     * A property spelled `allOf: [{$ref: Mauve}]` — beside annotations or `nullable` too — where Mauve
     * is an undiscriminated union of an object member built from `allOf` fragments and an `array`
     * member is the bare `$ref: Mauve`. yii3 holds the value as the decoded array, and only the bare
     * reference was spelled out as the component's union: behind the wrapper the object member was cut
     * down to `{type: object}`, so `{"tern": "x"}` passed an integer `tern`, `{"toucan": 31}` passed
     * a member's `required`, and `{"toucan": 1, "llama": "x"}` matched "more than one oneOf branch".
     * The bare reference and the inline union, pinned here, already worked.
     */
    #[DataProvider('openApiVersions')]
    public function testASingleRefAllOfAroundAUnionComponentIsTheReference(string $version): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $wrapped = static fn(string $name): array => ['allOf' => [$ref($name)]];
        $mauvea = [
            'oneOf' => [
                [
                    'type' => 'object',
                    'allOf' => [
                        ['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']],
                        ['type' => 'object', 'properties' => ['toucan' => ['type' => 'integer']], 'required' => ['toucan']],
                    ],
                ],
                ['type' => 'array', 'items' => ['type' => 'string']],
                [
                    'type' => 'object',
                    'properties' => ['toucan' => ['type' => 'integer'], 'llama' => ['type' => 'string']],
                    'required' => ['toucan', 'llama'],
                ],
            ],
        ];
        $mauve = [
            'anyOf' => [
                [
                    'type' => 'object',
                    'allOf' => [['type' => 'object', 'properties' => ['tern' => ['type' => 'integer']], 'required' => ['tern']]],
                ],
                ['type' => 'array', 'items' => ['type' => 'string']],
            ],
        ];
        $anyOfFields = ['jackal' => $wrapped('Mauve'), 'vole' => $ref('Mauve')];
        $oneOfFields = [
            'ibex' => $wrapped('Mauvea'),
            'lynx' => $wrapped('Mauvea') + ['description' => 'A wrapped union.'],
            'puma' => $ref('Mauvea'),
            'mink' => $mauvea,
        ];
        if ($version === '3.0.3') {
            $oneOfFields['otter'] = $wrapped('Mauvea') + ['nullable' => true];
        }
        $spec = [
            'openapi' => $version,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => ['type' => 'object', 'properties' => $anyOfFields + $oneOfFields],
                    'Mauve' => $mauve,
                    'Mauvea' => $mauvea,
                ],
            ],
        ];
        $payloads = [];
        foreach (array_keys($anyOfFields) as $field) {
            foreach (['{"tern":1}' => true, '{"tern":"x"}' => false, '["a"]' => true, '[1]' => false, '"x"' => false] as $value => $expected) {
                $payloads[sprintf('{"%s":%s}', $field, $value)] = $expected;
            }
        }
        foreach (array_keys($oneOfFields) as $field) {
            $values = [
                '{"tern":1.5,"toucan":2}' => true,
                '{"toucan":31}' => false,
                '{"llama":"q"}' => false,
                '{"toucan":1,"llama":"x"}' => true,
                '{"tern":1,"toucan":1,"llama":"x"}' => false,
                '["a"]' => true,
                '"x"' => false,
            ];
            foreach ($values as $value => $expected) {
                $payloads[sprintf('{"%s":%s}', $field, $value)] = $expected;
            }
        }
        if ($version === '3.0.3') {
            $payloads['{"otter":null}'] = true;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'single ref allOf around union ' . $version, payloads: $payloads),
        );
    }

    /**
     * @return iterable<string, array{string}>
     */
    public static function openApiVersions(): iterable
    {
        yield '3.0' => ['3.0.3'];
        yield '3.1' => ['3.1.0'];
    }

    /**
     * A union member that is a `$ref` WITH annotations beside it — `{$ref: Olive, title: Fern}`,
     * `{$ref: Olive, description: …}` — to a component that admits null (`nullable: true`, 3.1
     * `type: [object, "null"]`) admits null as the bare `{$ref: Olive}` does: the 3.0 siblings of a
     * `$ref` are ignored, and in 3.1 a title or a description asserts nothing. Only the bare member
     * passed its null on, so symfony refused `{"tern": null}` (a `not: {type: null}` guard, or a type
     * without null), yii3 refused it, laravel crashed on a required property and laravel-data on every
     * one — on the property and through a union component (`Teal: {anyOf: [{$ref: Olive, title: …}]}`).
     * The bare member, pinned here, already worked. A member with an ASSERTING sibling (3.1 `{$ref:
     * Olive, type: object}`) still refuses the null.
     *
     * @param array<string, mixed> $olive
     */
    #[DataProvider('annotatedNullableRefMemberVersions')]
    public function testAnAnnotatedRefMemberAdmittingNullTakesNull(string $version, array $olive): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $number = ['type' => 'number'];
        $properties = [
            'tern' => ['anyOf' => [$ref('Olive') + ['title' => 'Fern'], $number]],
            'wren' => ['oneOf' => [$ref('Olive') + ['description' => 'An olive.'], $number]],
            'kite' => ['anyOf' => [$ref('Olive') + ['title' => 'Fern'], $number, ['type' => 'object']]],
            'lark' => $ref('Teal'),
            'loon' => $ref('TealOne'),
            'bare' => ['anyOf' => [$ref('Olive'), $number]],
            'rook' => ['anyOf' => [$ref('Olive') + ['title' => 'Fern'], $number]],
            'crow' => ['oneOf' => [$ref('Olive') + ['description' => 'An olive.'], $number]],
        ];
        if ($version === '3.1.0') {
            $properties['gull'] = ['anyOf' => [$ref('Olive') + ['type' => 'object'], $number]];
        }
        $spec = [
            'openapi' => $version,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => ['type' => 'object', 'required' => ['rook', 'crow'], 'properties' => $properties],
                    'Olive' => $olive + ['properties' => ['ibis' => ['type' => 'integer']]],
                    'Teal' => ['anyOf' => [$ref('Olive') + ['title' => 'Object'], $number]],
                    'TealOne' => ['oneOf' => [$ref('Olive') + ['description' => 'An olive.'], $number]],
                ],
            ],
        ];
        $base = '"rook":1,"crow":1';
        $payloads = ['{' . $base . '}' => true];
        foreach (['rook', 'crow'] as $field) {
            $payloads[sprintf('{"%s":%s}', $field, $field === 'rook' ? '"crow":1' : '"rook":1')] = false;
        }
        foreach (array_keys($properties) as $field) {
            $prefix = in_array($field, ['rook', 'crow'], true)
                ? '{' . ($field === 'rook' ? '"crow":1' : '"rook":1') . ','
                : '{' . $base . ',';
            $payloads[sprintf('%s"%s":null}', $prefix, $field)] = $field !== 'gull';
            $payloads[sprintf('%s"%s":{"ibis":1}}', $prefix, $field)] = true;
            $payloads[sprintf('%s"%s":2.5}', $prefix, $field)] = true;
            $payloads[sprintf('%s"%s":"x"}', $prefix, $field)] = false;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'annotated ref member admits null ' . $version, payloads: $payloads),
        );
        // Written back, the annotated member is the bare one: an absent key and a null alike. Laravel
        // wrote an absent annotated `tern` as `{}`, the bare `bare` as the documented null.
        foreach (['{' . $base . '}', '{' . $base . ',"tern":null,"bare":null}'] as $json) {
            foreach ($this->writtenBackByTheWritingModes($spec, 'annotated ref member admits null ' . $version, $json) as $position => $written) {
                $this->assertIsArray($written, $json);
                $this->assertSame(
                    expected: array_key_exists('bare', $written) ? $written['bare'] : 'absent',
                    actual: array_key_exists('tern', $written) ? $written['tern'] : 'absent',
                    message: $position . ' ' . $json,
                );
            }
        }
    }

    /**
     * @return iterable<string, array{string, array<string, mixed>}>
     */
    public static function annotatedNullableRefMemberVersions(): iterable
    {
        yield '3.0 nullable' => ['3.0.3', ['type' => 'object', 'nullable' => true]];
        yield '3.1 type null' => ['3.1.0', ['type' => ['object', 'null']]];
    }

    /**
     * Wherever a union member is read as "the reference" — a discriminated union on a property, in a
     * list or as a component, a nullable item `anyOf: [$ref, null]`, a scalar alias beside null, a
     * union component of classes, a union of classes with `properties` beside it — a `$ref` member
     * with only annotations beside it (`title`, `description`) is that reference too. Read as anything
     * else, a discriminated union matched twice (yii3 refused every pet, symfony took any tag), a list
     * of them dispatched on nothing in every mode, laravel and laravel-data could not build a union
     * component, and symfony dropped the checks beside a union of classes. The bare members already
     * worked; `$nullableMember` also gives a member that admits null.
     */
    #[DataProvider('nullableMemberSwitch')]
    public function testAnAnnotatedRefMemberIsTheReferenceItNames(bool $nullableMember): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'pet' => ['oneOf' => [$ref('Cat') + ['title' => 'A cat'], $ref('Dog') + ['description' => 'A dog']], 'discriminator' => ['propertyName' => 'kind']],
                    'hue' => ['anyOf' => [$ref('Tone') + ['title' => 'Tone'], ['type' => 'boolean']]],
                    'pets' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Cat') + ['title' => 'A cat'], $ref('Dog') + ['description' => 'A dog']], 'discriminator' => ['propertyName' => 'kind']]],
                    'zoo' => $ref('Pet'),
                    'herd' => $ref('Herd'),
                    'cats' => ['type' => 'array', 'items' => ['anyOf' => [$ref('Cat') + ['title' => 'A cat'], ['type' => 'null']]]],
                    'tint' => ['anyOf' => [$ref('Shade') + ['description' => 'A shade'], ['type' => 'null']]],
                    'owner' => ['anyOf' => [$ref('Cat') + ['title' => 'A cat'], $ref('Dog') + ['description' => 'A dog']], 'properties' => ['paw' => ['type' => 'integer', 'minimum' => 0]]],
                ]],
                'Shade' => ['type' => 'string', 'minLength' => 2],
                'Hen' => ['type' => 'object', 'required' => ['egg'], 'properties' => ['egg' => ['type' => 'integer']]] + ($nullableMember ? ['nullable' => true] : []),
                'Ram' => ['type' => 'object', 'required' => ['horn'], 'properties' => ['horn' => ['type' => 'integer']]],
                'Herd' => ['anyOf' => [$ref('Hen') + ['title' => 'A hen'], $ref('Ram') + ['description' => 'A ram']]],
                'Pet' => ['oneOf' => [$ref('Cat') + ['title' => 'A cat'], $ref('Dog') + ['description' => 'A dog']], 'discriminator' => ['propertyName' => 'kind']],
                'Cat' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string'], 'paw' => ['type' => 'integer']]] + ($nullableMember ? ['nullable' => true] : []),
                'Dog' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string'], 'bark' => ['type' => 'integer']]],
                'Tone' => ['anyOf' => [['type' => 'string'], ['type' => 'integer']]],
            ]],
        ];
        $this->assertSame(expected: [], actual: $this->payloadTableMisses(spec: $spec, key: 'annotated ref member is the reference ' . (int)$nullableMember, payloads: [
            '{}' => true,
            '{"pet":{"kind":"Cat","paw":1}}' => true,
            '{"pet":{"kind":"Dog","bark":1}}' => true,
            '{"pet":{"kind":"Cat","paw":"x"}}' => false,
            '{"pet":{"kind":"Dog","bark":"x"}}' => false,
            '{"pet":{"kind":"Owl"}}' => false,
            '{"pet":null}' => $nullableMember,
            '{"pet":5}' => false,
            '{"hue":"a"}' => true,
            '{"hue":1}' => true,
            '{"hue":true}' => true,
            '{"hue":1.5}' => false,
            '{"hue":null}' => false,
            '{"pets":[{"kind":"Cat","paw":1},{"kind":"Dog","bark":1}]}' => true,
            '{"pets":[{"kind":"Dog","bark":"x"}]}' => false,
            '{"pets":[{"kind":"Owl"}]}' => false,
            '{"zoo":{"kind":"Cat","paw":1}}' => true,
            '{"zoo":{"kind":"Dog","bark":1}}' => true,
            '{"zoo":{"kind":"Dog","bark":"x"}}' => false,
            '{"zoo":{"kind":"Owl"}}' => false,
            '{"zoo":null}' => $nullableMember,
            '{"cats":[null,{"kind":"Cat","paw":1}]}' => true,
            '{"cats":[{"kind":"Cat","paw":"x"}]}' => false,
            '{"cats":[5]}' => false,
            '{"tint":null}' => true,
            '{"tint":"ab"}' => true,
            '{"tint":"a"}' => false,
            '{"tint":5}' => false,
            '{"herd":{"egg":1}}' => true,
            '{"herd":{"horn":2}}' => true,
            '{"herd":{"egg":"x"}}' => false,
            '{"herd":5}' => false,
            '{"herd":null}' => $nullableMember,
            '{"owner":{"kind":"Cat","paw":1}}' => true,
            '{"owner":{"kind":"Cat","paw":-1}}' => false,
        ], diverging: [
            // The annotated item reference is the nullable list of DTOs the bare one is, and laravel-data
            // refuses its `null` item as the bare spelling always was — a framework boundary
            // (README.support-matrix, "a `null` ITEM of a nullable list of DTOs").
            'laravel-data' => ['{"cats":[null,{"kind":"Cat","paw":1}]}' => false],
        ]), message: (string)$nullableMember);
    }

    /**
     * @return iterable<string, array{bool}>
     */
    public static function nullableMemberSwitch(): iterable
    {
        yield 'members refuse null' => [false];
        yield 'a member admits null' => [true];
    }

    /**
     * A list whose items are `allOf: [$ref Pet]`, `Pet` a union of classes, is a list of `Pet`, as
     * `items: $ref Pet` is. Symfony held it as a bare `?array` checked for a list only, so an item that
     * was no `Pet` at all — `7`, `null`, a `Cat` without its `paw` — passed. `items: $ref Pet` and a
     * property `allOf: [$ref Pet]` already checked the item, and are pinned here.
     *
     * @param array<string, mixed> $pet
     * @param array<string, bool> $memberPayloads an item => accepted
     */
    #[DataProvider('listOfAnAllOfWrappedUnionCases')]
    public function testAListOfAnAllOfWrappedUnionComponentChecksItsItems(array $pet, array $memberPayloads): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = self::probeSpec(['type' => 'array', 'items' => ['allOf' => [$ref('Pet')]]]);
        $spec['components']['schemas']['Probe']['required'] = [];
        $spec['components']['schemas']['Probe']['properties'] += [
            'vole' => ['type' => 'array', 'items' => $ref('Pet')],
            'mole' => ['allOf' => [$ref('Pet')]],
        ];
        $spec['components']['schemas'] += [
            'Cat' => [
                'type' => 'object',
                'properties' => ['kind' => ['type' => 'string'], 'paw' => ['type' => 'integer']],
                'required' => ['kind', 'paw'],
            ],
            'Dog' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']], 'required' => ['kind']],
            'Pet' => $pet,
        ];
        $payloads = [];
        foreach (['f', 'vole'] as $field) {
            $payloads[sprintf('{"%s":[7]}', $field)] = false;
            $payloads[sprintf('{"%s":[null]}', $field)] = false;
            foreach ($memberPayloads as $item => $accepted) {
                $payloads[sprintf('{"%s":[%s]}', $field, $item)] = $accepted;
            }
        }
        $payloads['{"mole":7}'] = false;
        foreach ($memberPayloads as $item => $accepted) {
            $payloads[sprintf('{"mole":%s}', $item)] = $accepted;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'list of an allOf wrapped union ' . count($pet), payloads: $payloads),
        );
    }

    /**
     * @return iterable<string, array{array<string, mixed>, array<string, bool>}>
     */
    public static function listOfAnAllOfWrappedUnionCases(): iterable
    {
        $members = ['oneOf' => [['$ref' => '#/components/schemas/Cat'], ['$ref' => '#/components/schemas/Dog']]];
        yield 'discriminated' => [
            $members + ['discriminator' => ['propertyName' => 'kind', 'mapping' => [
                'cat' => '#/components/schemas/Cat',
                'dog' => '#/components/schemas/Dog',
            ]]],
            ['{"kind":"cat","paw":1}' => true, '{"kind":"dog"}' => true, '{"kind":"cat"}' => false],
        ];
        yield 'undiscriminated' => [
            $members,
            ['{"kind":"cat"}' => true, '{"kind":"cat","paw":1}' => false, '{"paw":1}' => false],
        ];
    }

    /**
     * A union component whose member is itself a DISCRIMINATED union — `Pet: {anyOf: [{anyOf: [Cobalt,
     * Mauve], discriminator: kind}, integer]}` — builds the member the tag names. Symfony flattened the
     * inner union into `Cobalt|Mauve|int` without its discriminator map, so the serializer tried Cobalt
     * first and refused a `Mauve` for Cobalt's `kind` enum. The same union inline (`heron`) and the
     * discriminated union alone behind a `$ref` (`egret`) already worked, and are pinned here.
     */
    public function testADiscriminatedUnionMemberOfAUnionComponentKeepsItsDiscriminator(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $inner = ['anyOf' => [$ref('Cobalt'), $ref('Mauve')], 'discriminator' => ['propertyName' => 'kind']];
        $spec = self::probeSpec($ref('Pet'));
        $spec['components']['schemas']['Probe']['required'] = [];
        $spec['components']['schemas']['Probe']['properties'] += [
            'heron' => ['anyOf' => [$inner, ['type' => 'integer']]],
            'egret' => $ref('Duo'),
        ];
        $spec['components']['schemas'] += [
            'Cobalt' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['Cobalt']]]],
            'Mauve' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'koala' => ['type' => 'integer']]],
            'Pet' => ['anyOf' => [$inner, ['type' => 'integer']]],
            'Duo' => $inner,
        ];
        $payloads = [];
        foreach (['f', 'heron', 'egret'] as $field) {
            $payloads += [
                sprintf('{"%s":{"kind":"Mauve"}}', $field) => true,
                sprintf('{"%s":{"kind":"Mauve","koala":2}}', $field) => true,
                sprintf('{"%s":{"kind":"Cobalt"}}', $field) => true,
                sprintf('{"%s":{"kind":"Mauve","koala":"x"}}', $field) => false,
            ];
        }
        $payloads += ['{"f":3}' => true, '{"f":"x"}' => false, '{"heron":3}' => true];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'discriminated union member of a union component', payloads: $payloads),
        );
    }

    /**
     * `allOf: [{anyOf: [{type: array}, <object>]}]` is that `anyOf`: the `allOf` around one union and
     * nothing else asserts nothing more. Symfony and yii3 judged it otherwise than the bare `anyOf` —
     * symfony dropped the enum of an object member's property and typed a `$ref` member's property
     * `?array`, so the member class was never built; yii3 checked the object member for `type: object`
     * only — and an object no member describes passed. The bare `anyOf` (`bare`) is the neighbour.
     */
    public function testAnAllOfAroundOneUnionOfAnArrayAndAnObjectIsThatUnion(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $bisonOnly = ['type' => 'object', 'properties' => ['bison' => ['type' => 'integer', 'enum' => [30]]], 'required' => ['bison']];
        $bisonRef = ['type' => 'object', 'properties' => ['bison' => $ref('Crimson')], 'required' => ['bison']];
        $indigoInline = [
            'type' => 'object',
            'properties' => ['bison' => ['type' => 'integer'], 'robin' => ['type' => 'string']],
            'required' => ['bison', 'robin'],
        ];
        $wrapped = static fn(array $member): array => ['allOf' => [['anyOf' => [['type' => 'array'], $member]]]];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'enumed' => $wrapped($bisonOnly),
                            'refenum' => $wrapped($bisonRef),
                            'inline' => $wrapped($indigoInline),
                            'reffed' => $wrapped($ref('Indigo')),
                            'bare' => ['anyOf' => [['type' => 'array'], $ref('Indigo')]],
                        ],
                    ],
                    'Crimson' => ['type' => 'integer', 'enum' => [30]],
                    'Indigo' => $indigoInline,
                ],
            ],
        ];
        $payloads = [];
        foreach (['enumed', 'refenum'] as $field) {
            $payloads += [
                sprintf('{"%s":{"bison":30}}', $field) => true,
                sprintf('{"%s":[1]}', $field) => true,
                sprintf('{"%s":{"bison":25}}', $field) => false,
                sprintf('{"%s":{"bison":"zzq"}}', $field) => false,
                sprintf('{"%s":{"okapi":7}}', $field) => false,
                sprintf('{"%s":"x"}', $field) => false,
            ];
        }
        foreach (['inline', 'reffed', 'bare'] as $field) {
            $payloads += [
                sprintf('{"%s":{"bison":1,"robin":"x"}}', $field) => true,
                sprintf('{"%s":[1]}', $field) => true,
                sprintf('{"%s":{"okapi":7}}', $field) => false,
                sprintf('{"%s":{"bison":"x","robin":""}}', $field) => false,
                sprintf('{"%s":"x"}', $field) => false,
            ];
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'allOf around one union of array and object', payloads: $payloads),
        );
    }

    /**
     * A list component whose items are an alias of an alias of a date — `Ivory: {items: $ref Jade}`,
     * `Jade: $ref Sienna`, `Sienna: {type: string, format: date}` — checks the date. Symfony followed
     * one hop of the alias, typed the items `DateTimeImmutable` without the strict `Y-m-d` reading, and
     * took `"now"`. The list of `$ref Sienna` (`crane`) already refused it, and is pinned here.
     */
    public function testAListComponentOfAnAliasChainOfADateChecksTheDate(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = self::probeSpec($ref('Ivory'));
        $spec['components']['schemas']['Probe']['required'] = [];
        $spec['components']['schemas']['Probe']['properties']['crane'] = $ref('Ivy');
        $spec['components']['schemas'] += [
            'Sienna' => ['type' => 'string', 'format' => 'date'],
            'Jade' => $ref('Sienna'),
            'Ivory' => ['type' => 'array', 'items' => $ref('Jade')],
            'Ivy' => ['type' => 'array', 'items' => $ref('Sienna')],
        ];
        $payloads = [];
        foreach (['f', 'crane'] as $field) {
            $payloads += [
                sprintf('{"%s":["2024-01-02"]}', $field) => true,
                sprintf('{"%s":["now"]}', $field) => false,
                sprintf('{"%s":["2024-01-02T10:00:00Z"]}', $field) => false,
                sprintf('{"%s":[3]}', $field) => false,
            ];
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'list component of an alias chain of a date', payloads: $payloads),
        );
        $this->assertSame(
            expected: array_fill(0, 3, ['f' => ['2024-01-02']]),
            actual: $this->writtenBackByTheWritingModes($spec, 'list component of an alias chain of a date', '{"f":["2024-01-02"]}'),
        );
    }

    /**
     * A `format: date` beside an inline object member (`DateTimeImmutable|ProbeCrane`) is read with the
     * one date pattern in symfony too. It used to be read by PHP's free parser there, the strict context
     * left out because it reaches the class's own properties: `"now"`, `"@0"` and a date-time passed.
     * A class holding a date-time (`ProbeHeron.stamp`) resets the pattern on its own property, so its
     * date-time is still read as one (a loose date-time stays the symfony row of the support matrix).
     */
    public function testADateBesideAnObjectMemberIsParsedStrictly(): void
    {
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'crane' => ['anyOf' => [
                                ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']], 'required' => ['kind']],
                                ['type' => 'string', 'format' => 'date'],
                            ]],
                            'heron' => ['anyOf' => [
                                [
                                    'type' => 'object',
                                    'properties' => ['stamp' => ['type' => 'string', 'format' => 'date-time']],
                                    'required' => ['stamp'],
                                ],
                                ['type' => 'string', 'format' => 'date'],
                            ]],
                        ],
                    ],
                ],
            ],
        ];
        $payloads = [];
        foreach (['crane', 'heron'] as $field) {
            $payloads += [
                sprintf('{"%s":"2024-01-02"}', $field) => true,
                sprintf('{"%s":"now"}', $field) => false,
                sprintf('{"%s":"@0"}', $field) => false,
                sprintf('{"%s":"2024-01-02T10:00:00Z"}', $field) => false,
                sprintf('{"%s":5}', $field) => false,
            ];
        }
        $payloads += [
            '{"crane":{"kind":"x"}}' => true,
            '{"crane":{}}' => false,
            '{"heron":{"stamp":"2024-01-02T10:00:00Z"}}' => true,
            '{"heron":{"stamp":"2024-01-02"}}' => false,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'date beside an object member',
                payloads: $payloads,
                // Symfony reads a date-time with PHP's free parser (the loose date-time row).
                diverging: ['symfony' => ['{"heron":{"stamp":"2024-01-02"}}' => true]],
            ),
        );
    }

    /**
     * A class held beside `array` (`array|Pet`, `array|Indigo`) is judged when the serializer leaves the
     * value raw. Symfony falls back to the array member whenever it cannot build the class — no tag, an
     * unknown or null tag, `[]` — and the branch "is that class" let such a raw object through, so
     * `{"tern": []}` and `{"tern": {"kind": null}}` passed `anyOf: [{type: array, minItems: 1}, $ref
     * Pet]`. The class's schema now judges it, as runtime judges a raw object. A class that takes `{}`
     * (`Loose`) still takes `[]` in symfony, which cannot tell the two apart (the EMPTY JSON container
     * row of the support matrix).
     */
    public function testAClassBesideAListIsJudgedWhenTheSerializerLeavesTheValueRaw(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $list = ['type' => 'array', 'minItems' => 1, 'items' => ['type' => 'string']];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'tern' => ['anyOf' => [$list, $ref('Pet')]],
                            'wren' => ['anyOf' => [$list, $ref('Indigo')]],
                            'lark' => ['anyOf' => [$list, $ref('Loose')]],
                        ],
                    ],
                    'Cat' => [
                        'type' => 'object',
                        'properties' => ['kind' => ['type' => 'string'], 'paw' => ['type' => 'integer']],
                        'required' => ['kind', 'paw'],
                    ],
                    'Dog' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']], 'required' => ['kind']],
                    'Pet' => [
                        'oneOf' => [$ref('Cat'), $ref('Dog')],
                        'discriminator' => [
                            'propertyName' => 'kind',
                            'mapping' => ['cat' => '#/components/schemas/Cat', 'dog' => '#/components/schemas/Dog'],
                        ],
                    ],
                    'Indigo' => [
                        'type' => 'object',
                        'properties' => ['bison' => ['type' => 'integer', 'minimum' => 5]],
                        'required' => ['bison'],
                    ],
                    'Loose' => ['type' => 'object', 'properties' => ['robin' => ['type' => 'integer']]],
                ],
            ],
        ];
        $payloads = [];
        foreach (['tern', 'wren', 'lark'] as $field) {
            $payloads += [
                sprintf('{"%s":["a"]}', $field) => true,
                sprintf('{"%s":[3]}', $field) => false,
                sprintf('{"%s":5}', $field) => false,
            ];
        }
        $payloads += [
            '{"tern":[]}' => false,
            '{"tern":{}}' => false,
            '{"tern":{"kind":null}}' => false,
            '{"tern":{"kind":"zzz"}}' => false,
            '{"tern":{"kind":"cat"}}' => false,
            '{"tern":{"kind":"dog"}}' => true,
            '{"tern":{"kind":"cat","paw":1}}' => true,
            '{"wren":[]}' => false,
            '{"wren":{}}' => false,
            '{"wren":{"bison":1}}' => false,
            '{"wren":{"bison":"q"}}' => false,
            '{"wren":{"bison":7}}' => true,
            '{"lark":{}}' => true,
            '{"lark":{"robin":2}}' => true,
            '{"lark":{"robin":"q"}}' => false,
            '{"lark":[]}' => false,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'class beside a list left raw',
                payloads: $payloads,
                // `[]` and `{}` are one decoded value in symfony and yii3 (the EMPTY JSON container row):
                // symfony takes both as the empty `Loose`, yii3 judges both as the short list.
                diverging: ['symfony' => ['{"lark":[]}' => true], 'yii3' => ['{"lark":{}}' => false]],
            ),
        );
    }

    /**
     * A list branch of null items beside a scalar (`anyOf: [{type: array, items: {type: 'null'}},
     * {type: integer}]`) checks its items in symfony too. `null` has no `Assert\Type` spelling, so the
     * branch was "a list" and `[7]` matched it. The same branch with integer items, and a plain list of
     * null items, are the neighbours pinned here.
     */
    public function testAListBranchOfNullItemsChecksItsItems(): void
    {
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'tern' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'null']], ['type' => 'integer']]],
                            'wren' => ['anyOf' => [['type' => 'array', 'items' => ['type' => 'integer']], ['type' => 'boolean']]],
                            'lark' => ['type' => 'array', 'items' => ['type' => 'null']],
                        ],
                    ],
                ],
            ],
        ];
        $payloads = [
            '{"tern":[null]}' => true,
            '{"tern":[]}' => true,
            '{"tern":7}' => true,
            '{"tern":[7]}' => false,
            '{"tern":["xyz"]}' => false,
            '{"tern":[null,1]}' => false,
            '{"tern":"x"}' => false,
            '{"wren":[1]}' => true,
            '{"wren":true}' => true,
            '{"wren":["x"]}' => false,
            '{"lark":[null]}' => true,
            '{"lark":[7]}' => false,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'list branch of null items', payloads: $payloads),
        );
    }

    /**
     * An item of a list of DTOs that is no object — `"x"`, a `null` the items do not admit, a list — is
     * refused. yii3's `#[Collection]` dropped such an item before any rule ran, so `[{…}, "x"]` arrived
     * as the valid `[{…}]`; the raw `Each` now asks every item whether it is an object, as the
     * interpreter asks the value of a map of them. Pinned beside it: the map, items that admit null, a
     * requirement-free item class (an empty object is one), and the valid lists. Symfony's answer for
     * the requirement-free class depends on the serializer release (see the support matrix).
     */
    public function testANonObjectItemOfAListOfDtosIsRefused(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'emu' => ['type' => 'array', 'items' => $ref('Hare')],
                            'owl' => ['type' => 'object', 'additionalProperties' => $ref('Hare')],
                            'yak' => ['type' => 'array', 'items' => ['anyOf' => [$ref('Hare'), ['type' => 'null']]]],
                            'elk' => ['type' => 'array', 'items' => $ref('Pika')],
                        ],
                    ],
                    'Hare' => ['type' => 'object', 'properties' => ['ka' => ['type' => 'string']], 'required' => ['ka']],
                    'Pika' => ['type' => 'object', 'properties' => ['ka' => ['type' => 'string']]],
                ],
            ],
        ];
        $payloads = [
            '{"emu":["x"]}' => false,
            '{"emu":[null]}' => false,
            '{"emu":[{"ka":"a"},"x"]}' => false,
            '{"emu":[{"ka":"a"},7]}' => false,
            '{"emu":[["a"]]}' => false,
            '{"emu":[{"ka":"a"}]}' => true,
            '{"emu":[]}' => true,
            '{"emu":[{"ka":1}]}' => false,
            '{"emu":{"a":{"ka":"a"}}}' => false,
            '{"owl":{"a":"x"}}' => false,
            '{"owl":{"a":{"ka":"a"}}}' => true,
            '{"yak":["x"]}' => false,
            '{"yak":[{"ka":"a"},null]}' => true,
            '{"elk":["x"]}' => false,
            '{"elk":[null]}' => false,
            '{"elk":[[1]]}' => false,
            '{"elk":[{}]}' => true,
            '{"elk":[{"ka":"a"}]}' => true,
        ];
        $diverging = [
            // A requirement-free item class: the serializer builds a scalar or null into an empty object
            // on older releases (7.4.10), and refuses it on newer ones.
            'symfony' => ['{"elk":["x"]}' => null, '{"elk":[null]}' => null, '{"elk":[[1]]}' => null],
            // A `null` item of a nullable list of DTOs: see the support matrix's row for it.
            'laravel-data' => ['{"yak":[{"ka":"a"},null]}' => null],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'non-object item of a list of dtos', payloads: $payloads, diverging: $diverging),
        );
    }

    /**
     * One `Data` class beside a free-form object member (`oneOf: [{type: object, required: [yak]}, $ref
     * Heron]`, typed `array|Heron`) is built only from the object Heron accepts. laravel-data's cast pipe
     * built Heron from every object first, so `{"yak": 1, "egret": "x"}`, which only the free-form member
     * takes, died on Heron's `int $egret` (a 500), and `{"yak": 1, "llama": 3}` came back as Heron's
     * `{"llama": "3"}`. The same with the branches wrapped in `allOf`, and as an `anyOf`; an object
     * Heron takes is still Heron.
     */
    public function testAClassBesideAFreeFormObjectIsBuiltOnlyFromWhatItAccepts(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $free = ['type' => 'object', 'required' => ['yak']];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'lynx' => ['oneOf' => [$free, $ref('Heron')]],
                            'puma' => ['anyOf' => [$free, $ref('Heron')]],
                            'ibex' => ['oneOf' => [['allOf' => [$free]], ['allOf' => [$ref('Heron')]]]],
                        ],
                    ],
                    'Heron' => ['type' => 'object', 'properties' => ['llama' => ['type' => 'string'], 'egret' => ['type' => 'integer']]],
                ],
            ],
        ];
        $payloads = [];
        $diverging = ['symfony' => []];
        foreach (['lynx', 'puma', 'ibex'] as $field) {
            $payloads += [
                sprintf('{"%s":{"yak":1,"egret":"x"}}', $field) => true,
                sprintf('{"%s":{"yak":1,"llama":3}}', $field) => true,
                sprintf('{"%s":{"llama":"a","egret":1}}', $field) => true,
                sprintf('{"%s":{"egret":"x"}}', $field) => false,
            ];
        }
        // An `allOf`-wrapped `$ref` branch: the serializer builds Heron from the object before any
        // constraint runs, and refuses what Heron's types do not take.
        $diverging['symfony']['{"ibex":{"yak":1,"egret":"x"}}'] = null;
        $diverging['symfony']['{"ibex":{"yak":1,"llama":3}}'] = null;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'class beside a free-form object', payloads: $payloads, diverging: $diverging),
        );
        foreach (['lynx', 'puma', 'ibex'] as $field) {
            $this->assertSame(
                expected: array_fill(0, 3, [$field => ['yak' => 1, 'llama' => 3]]),
                actual: $this->writtenBackByTheWritingModes(
                    spec: $spec,
                    key: 'class beside a free-form object',
                    json: sprintf('{"%s":{"yak":1,"llama":3}}', $field),
                ),
                message: $field,
            );
        }
    }

    /**
     * A single-reference `allOf` whose reference carries an annotation — `allOf: [{$ref: Count,
     * description: d}]` — is that reference, wherever it stands: a union branch, a map value, a
     * nullable property around a list alias, a list alias in a union branch, a union inside a union.
     * Only the bare `allOf: [{$ref: Count}]` was unwrapped, so the property was typed with the alias
     * class Count or Ints, which is never written: runtime refused every value as an unsupported
     * type, yii3 refused a number as no object or string, and symfony, laravel and laravel-data named
     * a class that does not exist. Pinned beside it: the bare spellings, a branch that adds a check
     * beside the annotated reference, and the property-level positions that already worked — a scalar
     * alias, an enum, an object, a map of objects, a map component.
     */
    #[DataProvider('referenceAnnotationSwitch')]
    public function testAnAnnotatedSingleRefAllOfIsTheAliasItNames(bool $annotated): void
    {
        $ref = static fn(string $name): array => $annotated
            ? ['$ref' => '#/components/schemas/' . $name, 'description' => 'd']
            : ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Count' => ['type' => 'integer', 'minimum' => 10],
                    'Ints' => ['type' => 'array', 'items' => ['type' => 'integer', 'maximum' => 5]],
                    'Colour' => ['type' => 'string', 'enum' => ['red', 'blue']],
                    'Pet' => ['type' => 'object', 'required' => ['name'], 'properties' => ['name' => ['type' => 'string']]],
                    'Tallies' => ['type' => 'object', 'additionalProperties' => ['type' => 'integer']],
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'noted' => ['oneOf' => [['allOf' => [$ref('Count')]], ['type' => 'string']]],
                            'mapNoted' => ['type' => 'object', 'additionalProperties' => ['allOf' => [$ref('Count')]]],
                            'pNoted' => ['allOf' => [$ref('Ints')], 'nullable' => true],
                            'uNoted' => ['oneOf' => [['allOf' => [$ref('Ints')]], ['type' => 'string']]],
                            'nested' => ['anyOf' => [['oneOf' => [['allOf' => [$ref('Count')]], ['type' => 'boolean']]], ['type' => 'string']]],
                            'split' => ['oneOf' => [['allOf' => [$ref('Count'), ['maximum' => 30]]], ['type' => 'string']]],
                            'scalar' => ['allOf' => [$ref('Count')]],
                            'colour' => ['allOf' => [$ref('Colour')]],
                            'pet' => ['allOf' => [$ref('Pet')]],
                            'pets' => ['type' => 'object', 'additionalProperties' => ['allOf' => [$ref('Pet')]]],
                            'tallies' => ['allOf' => [$ref('Tallies')]],
                        ],
                    ],
                ],
            ],
        ];
        $payloads = [
            '{"noted":20}' => true,
            '{"noted":"x"}' => true,
            '{"noted":5}' => false,
            '{"mapNoted":{"a":20}}' => true,
            '{"mapNoted":{"a":5}}' => false,
            '{"pNoted":[1]}' => true,
            '{"pNoted":null}' => true,
            '{"pNoted":[9]}' => false,
            '{"uNoted":[1]}' => true,
            '{"uNoted":"x"}' => true,
            '{"uNoted":[9]}' => false,
            '{"nested":20}' => true,
            '{"nested":true}' => true,
            '{"nested":"x"}' => true,
            '{"nested":5}' => false,
            '{"split":20}' => true,
            '{"split":40}' => false,
            '{"split":5}' => false,
            '{"scalar":20}' => true,
            '{"scalar":5}' => false,
            '{"colour":"red"}' => true,
            '{"colour":"green"}' => false,
            '{"pet":{"name":"x"}}' => true,
            '{"pet":{}}' => false,
            '{"pets":{"a":{"name":"x"}}}' => true,
            '{"pets":{"a":{}}}' => false,
            '{"tallies":{"a":1}}' => true,
            '{"tallies":{"a":"x"}}' => false,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'annotated single ref allOf ' . ($annotated ? 'noted' : 'bare'),
                payloads: $payloads,
            ),
        );
    }

    /**
     * @return iterable<string, array{bool}>
     */
    public static function referenceAnnotationSwitch(): iterable
    {
        yield 'bare reference' => [false];
        yield 'annotated reference' => [true];
    }

    /**
     * An `allOf` of a reference to a scalar alias and a keyword-only fragment — `allOf: [{$ref: Num},
     * {multipleOf: 0.5}]` — folds to that scalar, as the inline `allOf: [{type: number}, {multipleOf:
     * 0.5}]` and the bare `allOf: [{$ref: Num}]` always did. A reference was accepted only as the sole
     * fragment, so beside a discriminated union of classes symfony typed the property `mixed` and took
     * `{"walrus": 2.5}`, and yii3 typed it as any value. Pinned: the type every mode gives it is the
     * one it gives the inline spelling, and the payloads agree — for an annotated reference too, and
     * for a union component spelled that way.
     */
    public function testAReferenceToAScalarBesideAKeywordFragmentFoldsToTheScalar(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $shape = static fn(array $second): array => ['anyOf' => [$ref('Shape'), ['allOf' => [$second, ['multipleOf' => 0.5]]]]];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Num' => ['type' => 'number'],
                    'Wrap' => $shape($ref('Num')),
                    'Shape' => [
                        'oneOf' => [$ref('Square'), $ref('Circle')],
                        'discriminator' => [
                            'propertyName' => 'kind',
                            'mapping' => ['square' => '#/components/schemas/Square', 'circle' => '#/components/schemas/Circle'],
                        ],
                    ],
                    'Square' => [
                        'type' => 'object',
                        'required' => ['kind'],
                        'properties' => [
                            'kind' => ['type' => 'string', 'enum' => ['square']],
                            'walrus' => ['type' => 'string'],
                        ],
                    ],
                    'Circle' => [
                        'type' => 'object',
                        'required' => ['kind'],
                        'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']]],
                    ],
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'panda' => $shape($ref('Num')),
                            'koala' => $shape(['type' => 'number']),
                            'lynx' => $shape(['$ref' => '#/components/schemas/Num', 'description' => 'd']),
                            'otter' => $ref('Wrap'),
                        ],
                    ],
                ],
            ],
        ];
        $payloads = [];
        foreach (['panda', 'koala', 'lynx', 'otter'] as $field) {
            $payloads += [
                sprintf('{"%s":2.5}', $field) => true,
                sprintf('{"%s":0.7}', $field) => false,
                sprintf('{"%s":{"kind":"square","walrus":"w"}}', $field) => true,
                sprintf('{"%s":{"kind":"circle"}}', $field) => true,
                sprintf('{"%s":{"walrus":2.5}}', $field) => false,
                sprintf('{"%s":"x"}', $field) => false,
            ];
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'ref beside keyword fragment', payloads: $payloads),
        );
        foreach ([GenerationMode::Symfony, GenerationMode::Yii3] as $mode) {
            $fqcn = $this->generate($spec, $this->namespaceFor($mode, 'ref beside keyword fragment types'), $mode->value);
            foreach (['panda', 'lynx'] as $field) {
                $this->assertSame(
                    expected: (string)(new ReflectionProperty($fqcn, 'koala'))->getType(),
                    actual: (string)(new ReflectionProperty($fqcn, $field))->getType(),
                    message: $mode->value . ' ' . $field,
                );
            }
        }
    }

    /**
     * A union branch naming a union component of classes — `anyOf: [{$ref: Shape}, {not: {type:
     * object}}]`, `Shape: {oneOf: [$ref Square, $ref Circle]}`, with a discriminator or without — under
     * a property no PHP type can spell (`mixed`). Nothing builds the interface there, so the value stays
     * the decoded array, and symfony judged it as "is a Shape": `anyOf` took every object unchecked
     * (`{"walrus": 2.5}` matches no member, `kind` is required), `oneOf` refused every object, the
     * valid ones included. The members are written out for the raw object now, as the other modes do.
     * Pinned beside it: a property typed with the interface, where symfony builds the member and the
     * branch is still "is a Shape".
     */
    #[DataProvider('discriminatorSwitch')]
    public function testAUnionComponentBranchUnderAMixedPropertyJudgesTheRawObject(bool $discriminated): void
    {
        $shape = [
            'oneOf' => [['$ref' => '#/components/schemas/Square'], ['$ref' => '#/components/schemas/Circle']],
        ];
        if ($discriminated) {
            $shape['discriminator'] = [
                'propertyName' => 'kind',
                'mapping' => ['square' => '#/components/schemas/Square', 'circle' => '#/components/schemas/Circle'],
            ];
        }
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Shape' => $shape,
                    'Square' => [
                        'type' => 'object',
                        'required' => ['kind'],
                        'properties' => ['kind' => ['type' => 'string', 'enum' => ['square']], 'walrus' => ['type' => 'string']],
                    ],
                    'Circle' => [
                        'type' => 'object',
                        'required' => ['kind'],
                        'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']]],
                    ],
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'anyPanda' => ['anyOf' => [['$ref' => '#/components/schemas/Shape'], ['not' => ['type' => 'object']]]],
                            'onePanda' => ['oneOf' => [['$ref' => '#/components/schemas/Shape'], ['not' => ['type' => 'object']]]],
                            'typed' => ['oneOf' => [['$ref' => '#/components/schemas/Shape'], ['type' => 'string']]],
                        ],
                    ],
                ],
            ],
        ];
        $payloads = [];
        foreach (['anyPanda', 'onePanda', 'typed'] as $property) {
            $payloads += [
                sprintf('{"%s":{"walrus":2.5}}', $property) => false,
                sprintf('{"%s":{"kind":"square"}}', $property) => true,
                sprintf('{"%s":{"kind":"circle"}}', $property) => true,
                sprintf('{"%s":{"kind":"square","walrus":"x"}}', $property) => true,
                sprintf('{"%s":{"kind":"square","walrus":2.5}}', $property) => false,
                sprintf('{"%s":{"kind":"oval"}}', $property) => false,
            ];
        }
        $payloads += [
            '{"anyPanda":3}' => true,
            '{"onePanda":3}' => true,
            '{"typed":"x"}' => true,
            '{"typed":3}' => false,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union component branch raw object ' . ($discriminated ? 'tagged' : 'untagged'),
                payloads: $payloads,
            ),
        );
    }

    /**
     * @return iterable<string, array{bool}>
     */
    public static function discriminatorSwitch(): iterable
    {
        yield 'with a discriminator' => [true];
        yield 'without a discriminator' => [false];
    }

    /**
     * A union component written out for a raw value (`x-php-raw-object`) keeps the `allOf` of its
     * object members: `stoat: {anyOf: [{not: {type: object}}, $ref Mauve]}` with `Mauve: {oneOf:
     * [{type: object, allOf: [{required: [tern]}]}, {required: [newt]}]}`. Symfony reduced such a
     * member to "the class checks it" — `type: object` alone — though under a `mixed` property no class
     * is ever built, so the member matched every object and `{"stoat": {}}` passed. The same member
     * without the wrapper (`bare`) and the scalar `allOf` branch beside it (`heron`) are the controls.
     * yii3 lost the same `allOf` one property down a class it holds as the decoded array (`kiwi:
     * Umber|array|null`, `Umber.pika`); a class symfony falls back from (`wolf`) and one built by
     * `allOf` (`lynx`) are pinned beside it.
     */
    public function testAnAllOfMemberOfAUnionComponentHeldRawIsJudged(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => [
                        'type' => 'object',
                        'properties' => [
                            'stoat' => ['anyOf' => [['not' => ['type' => 'object']], $ref('Mauve')]],
                            'bare' => ['anyOf' => [['not' => ['type' => 'object']], $ref('Plum')]],
                            'heron' => [
                                'anyOf' => [
                                    ['allOf' => [$ref('Teal'), ['type' => 'integer', 'multipleOf' => 5]]],
                                    $ref('Ochre'),
                                ],
                            ],
                            'kiwi' => ['oneOf' => [['type' => 'array', 'items' => ['type' => 'integer']], $ref('Umber')]],
                            'lynx' => ['oneOf' => [['type' => 'array', 'items' => ['type' => 'integer']], $ref('Sepia')]],
                            'wolf' => ['anyOf' => [['type' => 'array', 'minItems' => 1, 'items' => ['type' => 'string']], $ref('Kit')]],
                            'mink' => ['anyOf' => [['type' => 'array', 'minItems' => 1, 'items' => ['type' => 'string']], $ref('Pet')]],
                        ],
                    ],
                    'Umber' => [
                        'type' => 'object',
                        'properties' => [
                            'pika' => [
                                'oneOf' => [
                                    [
                                        'type' => 'object',
                                        'allOf' => [['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']]],
                                    ],
                                    ['type' => 'object', 'properties' => ['newt' => ['type' => 'string']], 'required' => ['newt']],
                                ],
                            ],
                        ],
                    ],
                    'Pet' => [
                        'oneOf' => [$ref('Cub'), $ref('Dog')],
                        'discriminator' => [
                            'propertyName' => 'kind',
                            'mapping' => ['cub' => '#/components/schemas/Cub', 'dog' => '#/components/schemas/Dog'],
                        ],
                    ],
                    'Cub' => [
                        'type' => 'object',
                        'properties' => [
                            'kind' => ['type' => 'string'],
                            'paw' => [
                                'oneOf' => [
                                    [
                                        'type' => 'object',
                                        'allOf' => [['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']]],
                                    ],
                                    ['type' => 'string'],
                                ],
                            ],
                        ],
                    ],
                    'Dog' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']], 'required' => ['kind']],
                    'Sepia' => [
                        'allOf' => [
                            $ref('Bone'),
                            ['type' => 'object', 'properties' => ['vole' => ['type' => 'string']], 'required' => ['vole']],
                        ],
                    ],
                    'Mauve' => [
                        'oneOf' => [
                            [
                                'type' => 'object',
                                'allOf' => [['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']]],
                            ],
                            ['type' => 'object', 'properties' => ['newt' => ['type' => 'string']], 'required' => ['newt']],
                        ],
                    ],
                    'Plum' => [
                        'oneOf' => [
                            ['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']],
                            ['type' => 'object', 'properties' => ['newt' => ['type' => 'string']], 'required' => ['newt']],
                        ],
                    ],
                    'Kit' => [
                        'type' => 'object',
                        'required' => ['paw'],
                        'properties' => [
                            'paw' => [
                                'oneOf' => [
                                    [
                                        'type' => 'object',
                                        'allOf' => [['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']]],
                                    ],
                                    ['type' => 'string'],
                                ],
                            ],
                        ],
                    ],
                    'Bone' => ['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']],
                    'Teal' => ['type' => 'integer', 'enum' => [45, 60]],
                    'Ochre' => [
                        'oneOf' => [
                            [
                                'type' => 'object',
                                'allOf' => [
                                    ['type' => 'object', 'properties' => ['tern' => ['type' => 'number']], 'required' => ['tern']],
                                    [
                                        'type' => 'object',
                                        'properties' => ['ibis' => ['type' => 'boolean'], 'macaw' => ['type' => 'boolean']],
                                        'required' => ['ibis', 'macaw'],
                                    ],
                                ],
                            ],
                            [
                                'type' => 'object',
                                'properties' => ['newt' => ['type' => 'string'], 'bison' => ['type' => 'boolean']],
                                'required' => ['newt'],
                            ],
                        ],
                    ],
                ],
            ],
        ];
        $payloads = [];
        foreach (['stoat', 'bare'] as $property) {
            $payloads += [
                sprintf('{"%s":{}}', $property) => false,
                sprintf('{"%s":{"tern":"x"}}', $property) => false,
                sprintf('{"%s":{"tern":1}}', $property) => true,
                sprintf('{"%s":{"newt":"a"}}', $property) => true,
                sprintf('{"%s":5}', $property) => true,
                sprintf('{"%s":"x"}', $property) => true,
            ];
        }
        $payloads += [
            '{"heron":{}}' => false,
            '{"heron":{"macaw":false}}' => false,
            '{"heron":{"bison":"zzq"}}' => false,
            '{"heron":{"tern":1}}' => false,
            '{"heron":{"tern":1,"ibis":true,"macaw":false}}' => true,
            '{"heron":{"newt":"a"}}' => true,
            '{"heron":{"newt":"a","bison":"zzq"}}' => false,
            '{"heron":45}' => true,
            '{"heron":50}' => false,
            '{"heron":"x"}' => false,
            '{"kiwi":[1]}' => true,
            '{"kiwi":{}}' => true,
            '{"kiwi":{"pika":{}}}' => false,
            '{"kiwi":{"pika":{"tern":"x"}}}' => false,
            '{"kiwi":{"pika":{"tern":1}}}' => true,
            '{"kiwi":{"pika":{"newt":"a"}}}' => true,
            '{"lynx":[1]}' => true,
            '{"lynx":{"vole":"x"}}' => false,
            '{"lynx":{"tern":1}}' => false,
            '{"lynx":{"tern":1,"vole":"x"}}' => true,
            '{"lynx":{"tern":"x","vole":"x"}}' => false,
            '{"wolf":["a"]}' => true,
            '{"wolf":{"paw":"x"}}' => true,
            '{"wolf":{"paw":{"tern":1}}}' => true,
            '{"wolf":{"paw":{}}}' => false,
            '{"wolf":{"paw":{"tern":"x"}}}' => false,
            '{"wolf":{"paw":1}}' => false,
            '{"mink":{"paw":{}}}' => false,
            '{"mink":{"paw":{"tern":"x"}}}' => false,
            '{"mink":{"kind":"cub","paw":{"tern":1}}}' => true,
            '{"mink":{"kind":"dog"}}' => true,
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'union component raw allOf member',
                payloads: $payloads,
                // Symfony builds `Umber` and, for `pika`, tries the first class of the inline union: the
                // framework boundary of README.support-matrix ("an inline union of classes").
                diverging: [GenerationMode::Symfony->value => ['{"kiwi":{"pika":{"newt":"a"}}}' => null]],
            ),
        );
    }

    /**
     * A property inside an inline `allOf` branch that references a component admitting null —
     * `urchin: {$ref: Amber}` with `Amber: {type: object, nullable: true}` (3.1: `[object, null]`),
     * its items, an array alias reached through a chain, a union with such a branch, the 3.1
     * nullable scalar alias union and the null alias — admits null just like the same property
     * outside the `allOf`. Only a schema's own `properties` had their references normalized, so
     * the branch kept the bare reference: runtime refused the null at deserialization, laravel and
     * laravel-data with `validation.array`, symfony and yii3 in their object type rule. Covered for a
     * top-level `allOf` component (with a nested `allOf`) and for an inline `allOf` property; the list
     * outside any `allOf` is the control.
     */
    #[DataProvider('openApiVersions')]
    public function testAPropertyOfAnAllOfBranchTakesTheNullItsReferenceAdmits(string $version): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $is31 = $version === '3.1.0';
        $branchProperties = [
            'urchin' => $ref('Amber'),
            'heron' => ['type' => 'array', 'items' => $ref('Amber')],
            'sable' => $ref('Pewter'),
            'tapir' => ['anyOf' => [$ref('Amber'), ['type' => 'integer']]],
        ];
        if ($is31) {
            $branchProperties += [
                'ocelot' => ['anyOf' => [$ref('Pebble'), ['type' => 'null']]],
                'pika' => $ref('Hollow'),
            ];
        }
        $schemas = [
            'Probe' => [
                'type' => 'object',
                'properties' => [
                    'zebu' => $ref('Zebu'),
                    'heron' => ['type' => 'array', 'items' => $ref('Amber')],
                    'mole' => [
                        'allOf' => [
                            ['type' => 'object', 'properties' => ['otter' => ['type' => 'integer']]],
                            ['type' => 'object', 'properties' => $branchProperties],
                        ],
                    ],
                ],
            ],
            'Amber' => $is31
                ? ['type' => ['object', 'null'], 'properties' => ['hyena' => ['type' => 'string']]]
                : ['type' => 'object', 'nullable' => true, 'properties' => ['hyena' => ['type' => 'string']]],
            'Pewter' => $ref('PewterBase'),
            'PewterBase' => $is31
                ? ['type' => ['array', 'null'], 'items' => ['type' => 'integer']]
                : ['type' => 'array', 'nullable' => true, 'items' => ['type' => 'integer']],
            'Zebu' => [
                'allOf' => [
                    ['type' => 'object', 'properties' => $branchProperties],
                    ['allOf' => [['type' => 'object', 'properties' => ['wren' => $ref('Amber')]]]],
                ],
            ],
        ];
        if ($is31) {
            $schemas += [
                'Pebble' => ['type' => 'string'],
                'Hollow' => ['type' => 'null'],
            ];
        }
        $spec = ['openapi' => $version, 'info' => ['title' => 'T', 'version' => '1.0.0'], 'components' => ['schemas' => $schemas]];
        $payloads = [];
        foreach (['zebu', 'mole'] as $container) {
            $member = static fn(string $body): string => sprintf('{"%s":{%s}}', $container, $body);
            $payloads += [
                $member('"urchin":null') => true,
                $member('"urchin":{"hyena":"x"}') => true,
                $member('"urchin":{"hyena":1}') => false,
                $member('"urchin":"x"') => false,
                $member('"heron":[null]') => true,
                $member('"heron":[{"hyena":"x"}]') => true,
                $member('"heron":["x"]') => false,
                $member('"sable":null') => true,
                $member('"sable":[1]') => true,
                $member('"sable":["a"]') => false,
                $member('"tapir":null') => true,
                $member('"tapir":3') => true,
                $member('"tapir":"x"') => false,
            ];
            if ($is31) {
                $payloads += [
                    $member('"ocelot":null') => true,
                    $member('"ocelot":"s"') => true,
                    $member('"ocelot":3') => false,
                    $member('"pika":null') => true,
                    $member('"pika":1') => false,
                ];
            }
        }
        $payloads += [
            '{"heron":[null]}' => true,
            '{"heron":["x"]}' => false,
            '{"zebu":{"wren":null}}' => true,
            '{"zebu":{"wren":"x"}}' => false,
            '{"mole":{"otter":1,"urchin":null}}' => true,
            '{"mole":{"otter":"x","urchin":null}}' => false,
        ];

        // Both as outside an `allOf` (README.support-matrix): laravel-data's `#[DataCollectionOf]` has no
        // null item, and symfony's serializer builds a scalar item into an empty object on 7.4.10.
        $diverging = [];
        foreach (['{"heron":%s}', '{"zebu":{"heron":%s}}', '{"mole":{"heron":%s}}'] as $shape) {
            $diverging[GenerationMode::LaravelData->value][sprintf($shape, '[null]')] = false;
            $diverging[GenerationMode::Symfony->value][sprintf($shape, '["x"]')] = null;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'allof branch ref null ' . $version,
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * A `$ref` with an `enum` beside it, on a property of an inline object branch of a union Symfony
     * holds as the decoded array (the `array` member is what keeps it decoded). In OpenAPI 3.1 the
     * sibling asserts. The extraction left the members to the backed enum the property became, which
     * the decoded array never holds: `{"pet": {"colour": "zzq"}}` passed every mode but Symfony refused
     * it. The same branch held as the built class (`plain`, no array member), the `enum` written
     * inline (`inline`), on the component (`hued`) and beside a `$ref` through `allOf` (`wrapped`)
     * are the neighbours pinned here.
     */
    public function testARefWithAnEnumBesideItInAHeldDecodedUnionBranchKeepsTheMembers(): void
    {
        $branch = static fn(array $colour): array => ['oneOf' => [
            ['type' => 'object', 'properties' => ['colour' => $colour]],
            ['type' => 'object', 'properties' => ['shape' => ['type' => 'string']], 'required' => ['shape']],
            ['type' => 'array'],
        ]];
        $hue = ['$ref' => '#/components/schemas/Hue'];
        $members = ['enum' => ['cyan', 'red']];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'pet' => $branch($hue + $members),
                    'plain' => ['oneOf' => [
                        ['type' => 'object', 'properties' => ['colour' => $hue + $members]],
                        ['type' => 'object', 'properties' => ['shape' => ['type' => 'string']], 'required' => ['shape']],
                    ]],
                    'inline' => $branch(['type' => 'string'] + $members),
                    'hued' => $branch(['$ref' => '#/components/schemas/Tint']),
                    'wrapped' => $branch(['allOf' => [$hue]] + $members),
                ]],
                'Hue' => ['type' => 'string'],
                'Tint' => ['type' => 'string'] + $members,
            ]],
        ];
        $payloads = [];
        foreach (['pet', 'plain', 'inline', 'hued', 'wrapped'] as $property) {
            $payloads['{"' . $property . '":{"colour":"cyan"}}'] = true;
            $payloads['{"' . $property . '":{"colour":"zzq"}}'] = false;
            $payloads['{"' . $property . '":{"colour":"zzq","shape":"x"}}'] = true;
        }
        $payloads['{"pet":[]}'] = true;
        $payloads['{"pet":{"colour":5}}'] = false;

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'ref enum sibling held decoded',
                payloads: $payloads,
                // Built, not held: the serializer builds the first member class and reports its enum
                // (README.support-matrix, the row on an object only a later union member accepts).
                diverging: ['symfony' => ['{"plain":{"colour":"zzq","shape":"x"}}' => false]],
            ),
        );
    }

    /**
     * A union COMPONENT of objects whose members are written inline or as an `allOf` — an `allOf` of two
     * objects, of an object and a requirement, the one-member wrapper, a `$ref` with siblings beside it,
     * a plain inline object — is built (laravel, laravel-data) or held decoded (symfony) as a component
     * of `$ref` members is. Its members were not counted as objects: symfony typed the property as the
     * bare interface and refused every object as `must be one of "Pet" ("array" given)`, laravel called
     * the interface's missing `fromValidated()` (allOf members) or threw "a union with no discriminator"
     * (inline members), and laravel-data died on a TypeError. A list of such a component (`herd`), the
     * `$ref` members (`ctl`) and a branch that only requires a key (`bare`, a value) are the neighbours
     * pinned here.
     */
    public function testAUnionComponentOfInlineOrAllOfObjectMembersIsUsable(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $object = static fn(array $properties, array $required = []): array => ['type' => 'object', 'properties' => $properties]
            + ($required === [] ? [] : ['required' => $required]);
        $integer = ['type' => 'integer'];
        $string = ['type' => 'string'];
        $boolean = ['type' => 'boolean'];
        $catOwl = ['allOf' => [$object(['cat' => $integer]), $object(['owl' => $string], ['owl'])]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'pet' => $ref('Pet'),
                    'sib' => $ref('Sib'),
                    'one' => $ref('Uno'),
                    'req' => $ref('Req'),
                    'inl' => $ref('Inl'),
                    'mix' => $ref('Mix'),
                    'wrap' => $ref('Wrap'),
                    'ctl' => $ref('Ctl'),
                    'bare' => $ref('Bare'),
                    'herd' => ['type' => 'array', 'items' => $ref('Pet')],
                ]],
                'Cat' => $object(['purr' => $boolean]),
                'Yak' => $object(['yak' => $integer], ['yak']),
                'Owl' => $object(['owl' => $string], ['owl']),
                'Pet' => ['anyOf' => [
                    ['allOf' => [$object(['fin' => $integer]), $object(['purr' => $boolean])]],
                    ['allOf' => [$object(['wing' => $integer]), $object(['bark' => $string], ['bark'])]],
                ]],
                'Sib' => ['anyOf' => [
                    $ref('Cat') + ['properties' => []],
                    ['allOf' => [$object(['wing' => $integer]), $object(['bark' => $string], ['bark'])]],
                ]],
                'Uno' => ['oneOf' => [
                    $ref('Cat') + ['properties' => []],
                    ['allOf' => [$object(['wing' => $integer]), $object(['bark' => $string], ['bark'])]],
                ]],
                'Req' => ['anyOf' => [['allOf' => [$object(['yak' => $integer]), ['required' => ['yak']]]], $catOwl]],
                'Inl' => ['anyOf' => [$object(['owl' => $boolean]), $object(['cat' => $integer, 'owl' => $boolean])]],
                'Mix' => ['anyOf' => [$ref('Yak'), $object(['owl' => $string], ['owl'])]],
                'Wrap' => ['anyOf' => [['allOf' => [$object(['yak' => $integer], ['yak'])]], $catOwl]],
                'Ctl' => ['anyOf' => [$ref('Yak'), $ref('Owl')]],
                'Bare' => ['anyOf' => [['required' => ['yak']], $catOwl]],
            ]],
        ];
        $payloads = [
            '{"pet":{"purr":true}}' => true,
            '{"pet":{"bark":"x"}}' => true,
            '{"pet":{"purr":1}}' => false,
            '{"pet":{"fin":"x"}}' => false,
            '{"pet":5}' => false,
            '{"sib":{"purr":true}}' => true,
            '{"sib":{"bark":"x"}}' => true,
            '{"sib":{"purr":1}}' => false,
            '{"one":{"purr":true}}' => true,
            '{"one":{"purr":1,"bark":"x"}}' => true,
            '{"one":{"purr":true,"bark":"x"}}' => false,
            '{"one":{"purr":1}}' => false,
            '{"req":{"yak":1}}' => true,
            '{"req":{"owl":"x"}}' => true,
            '{"req":{"yak":"x"}}' => false,
            '{"req":{"cat":1}}' => false,
            '{"inl":{"owl":true}}' => true,
            '{"inl":{"cat":1,"owl":true}}' => true,
            '{"inl":{"owl":1}}' => false,
            '{"mix":{"yak":1}}' => true,
            '{"mix":{"owl":"x"}}' => true,
            '{"mix":{"owl":1}}' => false,
            '{"wrap":{"yak":1}}' => true,
            '{"wrap":{"owl":"x"}}' => true,
            '{"wrap":{"yak":"x"}}' => false,
            '{"wrap":{"cat":1}}' => false,
            '{"ctl":{"yak":1}}' => true,
            '{"ctl":{"owl":"x"}}' => true,
            '{"ctl":{"owl":1}}' => false,
            '{"bare":{"yak":1}}' => true,
            '{"bare":{"owl":"x"}}' => true,
            '{"bare":{"owl":1}}' => false,
            '{"bare":{}}' => false,
            '{"herd":[{"purr":true},{"bark":"x"}]}' => true,
            '{"herd":[{"purr":1}]}' => false,
        ];
        $key = 'union component of inline or allOf object members';

        $this->assertSame(expected: [], actual: $this->payloadTableMisses(spec: $spec, key: $key, payloads: $payloads));
        // Symfony holds the object decoded, beside the interface a DTO built by hand holds — not `mixed`,
        // which an `allOf` member made the union before.
        $namespace = $this->namespaceFor(GenerationMode::Symfony, $key);
        $fqcn = $this->generate(spec: $spec, namespace: $namespace, mode: GenerationMode::Symfony->value);
        foreach (['pet' => 'Pet', 'sib' => 'Sib', 'one' => 'Uno', 'req' => 'Req', 'inl' => 'Inl'] as $property => $interface) {
            $this->assertSame(
                expected: sprintf('%s\%s|array|null', $namespace, $interface),
                actual: (string)(new ReflectionProperty($fqcn, $property))->getType(),
                message: $property,
            );
        }
        // The member the payload matches is the one built: the first under `anyOf`. `bare` — a branch that
        // only requires a key — is a value, which laravel-data writes back as `null` when absent: left out.
        $writeSpec = $spec;
        $writeSpec['components']['schemas']['Probe']['properties'] = array_diff_key(
            $spec['components']['schemas']['Probe']['properties'],
            ['bare' => true],
        );
        foreach (['{"req":{"owl":"x"}}' => ['req' => ['owl' => 'x']], '{"mix":{"owl":"x"}}' => ['mix' => ['owl' => 'x']], '{"inl":{"owl":true}}' => ['inl' => ['owl' => true]]] as $json => $written) {
            $this->assertSame(
                expected: array_fill(start_index: 0, count: 3, value: $written),
                actual: $this->writtenBackByTheWritingModes(spec: $writeSpec, key: $key . ' written back', json: $json),
                message: $json,
            );
        }
    }

    /**
     * A union COMPONENT that inline would be a value — a scalar branch, a map branch, a branch that
     * names no type — is that value wherever it is referenced, with an asserting keyword beside the
     * union (`minimum`, `maxLength`, `maxProperties`, …), with the union wrapped in an `allOf` (and
     * members that only constrain), or with a branch that only requires a key. Kept a class, it was an
     * empty class or an interface whose only members were the object branches: every scalar was refused
     * as no object, a map was refused, crashed or written back `{}`, and the keyword beside the union
     * was checked by nothing. The union of two real objects with a key count stays an interface (`two`),
     * and the union without a sibling (`nomax`) and the list arm (`wd`) are pinned as neighbours.
     *
     * @param array<string, mixed> $teal
     * @param array<string, bool> $payloads
     */
    #[DataProvider('valueUnionComponents')]
    public function testAValueUnionComponentIsTheValueWhereverItIsReferenced(string $key, array $teal, array $payloads): void
    {
        $members = [
            'Olive' => ['type' => 'object', 'properties' => ['k' => ['type' => 'string']], 'required' => ['k']],
            'Amber' => ['type' => 'object', 'properties' => ['m' => ['type' => 'integer']], 'required' => ['m']],
        ];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => [
                'schemas' => [
                    'Probe' => ['type' => 'object', 'properties' => ['lynx' => ['$ref' => '#/components/schemas/Teal']]],
                    'Teal' => $teal,
                    ...$members,
                ],
            ],
        ];
        $wired = [];
        foreach ($payloads as $value => $expected) {
            $wired[sprintf('{"lynx":%s}', $value)] = $expected;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'value union component ' . $key, payloads: $wired),
        );
        if (($payloads['{"a":"x"}'] ?? false) === true) {
            $this->assertSame(
                expected: array_fill(start_index: 0, count: 3, value: ['lynx' => ['a' => 'x']]),
                actual: $this->writtenBackByTheWritingModes(spec: $spec, key: 'value union component ' . $key, json: '{"lynx":{"a":"x"}}'),
            );
        }
    }

    /**
     * @return iterable<string, array{string, array<string, mixed>, array<string, bool>}>
     */
    public static function valueUnionComponents(): iterable
    {
        $map = ['type' => 'object', 'additionalProperties' => ['type' => 'string']];
        $scalars = [['type' => 'string'], ['type' => 'integer']];
        $mapOrInt = ['anyOf' => [$map, ['type' => 'integer']]];
        $fourKeys = '{"a":"x","b":"x","c":"x","d":"x"}';

        yield 'scalars beside minimum' => [
            'mn',
            ['anyOf' => $scalars, 'minimum' => 3],
            ['5' => true, '"s"' => true, '1' => false, '{"a":"x"}' => false, 'true' => false],
        ];
        yield 'scalars beside maxLength' => [
            'ml',
            ['anyOf' => $scalars, 'maxLength' => 2],
            ['5' => true, '"ab"' => true, '"abc"' => false, '{"a":"b"}' => false],
        ];
        yield 'map or integer beside maxProperties' => [
            'mp',
            [...$mapOrInt, 'maxProperties' => 3],
            ['5' => true, '{"a":"x"}' => true, $fourKeys => false, '{"a":1}' => false, '"s"' => false],
        ];
        yield 'object or integer beside maxProperties' => [
            'ob',
            ['anyOf' => [['type' => 'object', 'properties' => array_fill_keys(keys: ['k', 'p', 'q', 'r'], value: ['type' => 'string'])], ['type' => 'integer']], 'maxProperties' => 3],
            ['5' => true, '{"k":"x"}' => true, '{"k":1}' => false, '{"k":"x","p":"x","q":"x","r":"x"}' => false, '"s"' => false],
        ];
        yield 'map or list beside maxProperties' => [
            'ls',
            ['anyOf' => [$map, ['type' => 'array', 'items' => ['type' => 'string']]], 'maxProperties' => 3],
            ['{"a":"x"}' => true, '["x"]' => true, $fourKeys => false, '[1]' => false, '5' => false],
        ];
        yield 'oneOf map or string beside minProperties' => [
            'on',
            ['oneOf' => [$map, ['type' => 'string']], 'minProperties' => 1],
            ['"s"' => true, '{"a":"x"}' => true, '{}' => false, '5' => false],
        ];
        yield 'two objects beside maxProperties' => [
            'tw',
            ['anyOf' => [['$ref' => '#/components/schemas/Olive'], ['$ref' => '#/components/schemas/Amber']], 'maxProperties' => 1],
            ['{"k":"x"}' => true, '{"m":1}' => true, '{"k":"x","m":1}' => false, '5' => false],
        ];
        yield 'map or integer alone' => [
            'nm',
            $mapOrInt,
            ['5' => true, '{"a":"x"}' => true, '{"a":1}' => false, '"s"' => false],
        ];
        yield 'allOf around map or integer' => [
            'wa',
            ['allOf' => [$mapOrInt]],
            ['5' => true, '{"a":"x"}' => true, '{"a":1}' => false, '"s"' => false],
        ];
        yield 'allOf around scalars and a key count' => [
            'wb',
            ['allOf' => [['anyOf' => $scalars], ['maxProperties' => 3]]],
            ['"s"' => true, '5' => true, '{"a":1}' => false],
        ];
        yield 'allOf around map or integer and a minimum' => [
            'wc',
            ['allOf' => [$mapOrInt, ['minimum' => 3]]],
            ['5' => true, '1' => false, '{"a":"x"}' => true, '{"a":1}' => false],
        ];
        yield 'allOf around map or integer and a key count' => [
            'wr',
            ['allOf' => [$mapOrInt, ['maxProperties' => 3]]],
            ['5' => true, '{"a":"x"}' => true, $fourKeys => false, '{"a":1}' => false],
        ];
        yield 'allOf around list or integer and a minimum' => [
            'wd',
            ['allOf' => [['anyOf' => [['type' => 'array', 'items' => ['type' => 'string']], ['type' => 'integer']]], ['minimum' => 3]]],
            ['["x"]' => true, '5' => true, '1' => false, '[1]' => false],
        ];
        yield 'a branch that only requires a key' => [
            'rq',
            ['anyOf' => [['required' => ['yak']], ['type' => 'object', 'properties' => ['owl' => ['type' => 'string']], 'required' => ['owl']]]],
            ['5' => true, '{"yak":1}' => true, '{"owl":"x"}' => true, '{"owl":1}' => false, '{}' => false],
        ];
    }

    /**
     * A class branch judged against the raw object a neighbouring member kept as an array — a map, an
     * inline object of a nested `anyOf` — keeps the rules its property TYPES own: an `enum` (moved into
     * a backed enum), a nested class, a list of classes. Read off the constraints alone, the raw object
     * "matched" the class while breaking them: a wrong accept where no other branch matched, a false
     * "matches more than one" where the map matched too. `format` was checked already, and is pinned.
     * And a key the class declares none for is seen by the map beside it: judged on the built object's
     * declared keys alone, `{"lemur": "x"}` matched the integer map too and was refused twice.
     *
     * @param array<string, mixed> $amber
     * @param array<string, mixed> $macaw
     * @param array<string, bool|null> $payloads the value of `macaw`
     * @param list<GenerationMode> $skippedModes
     */
    #[DataProvider('rawObjectAgainstTypedPropertiesCases')]
    public function testARawObjectIsJudgedByTheRulesItsClassPropertyTypesOwn(array $amber, array $macaw, array $payloads, array $skippedModes = []): void
    {
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => ['macaw' => $macaw]],
                'Amber' => ['type' => 'object', 'properties' => $amber],
                'Teal' => ['type' => 'object', 'properties' => ['crane' => ['type' => 'integer', 'minimum' => 5]], 'required' => ['crane']],
            ]],
        ];
        $wired = [];
        foreach ($payloads as $value => $expected) {
            $wired[sprintf('{"macaw":%s}', $value)] = $expected;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'raw object typed properties ' . md5((string)json_encode($spec)),
                payloads: $wired,
                skippedModes: $skippedModes,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, mixed>, 2: array<string, bool|null>, 3?: list<GenerationMode>}>
     */
    public static function rawObjectAgainstTypedPropertiesCases(): iterable
    {
        $amber = ['$ref' => '#/components/schemas/Amber'];
        $teal = ['$ref' => '#/components/schemas/Teal'];
        $intMap = ['type' => 'object', 'additionalProperties' => ['type' => 'integer']];
        $closedLemur = ['type' => 'object', 'properties' => ['lemur' => ['type' => 'string']], 'additionalProperties' => false];
        $colours = ['type' => 'string', 'enum' => ['violet', 'blue']];

        yield 'enum property beside an integer map' => [
            ['bison' => $colours],
            ['oneOf' => [$amber, $intMap]],
            ['{"bison":"zzq"}' => false, '{"bison":3}' => true, '{"bison":"violet"}' => true, '{"lemur":"x"}' => true, '{"lemur":3}' => false, '{}' => false],
        ];
        yield 'nested class property beside an integer map' => [
            ['bison' => $teal],
            ['oneOf' => [$amber, $intMap]],
            ['{"bison":"zzq"}' => false, '{"bison":{"crane":1}}' => false, '{"bison":{"crane":7}}' => true, '{"bison":3}' => true],
        ];
        yield 'nested class property in an anyOf beside an integer map' => [
            ['bison' => $teal],
            ['oneOf' => [['anyOf' => [$amber, $closedLemur]], $intMap]],
            ['{"bison":3}' => true, '{"bison":{"crane":7}}' => true, '{"bison":{"crane":1}}' => false, '{"lemur":"x"}' => true],
        ];
        yield 'list of classes and enum beside an integer map' => [
            [
                'day' => ['type' => 'string', 'format' => 'date'],
                'pack' => ['type' => 'array', 'items' => $teal],
                'tint' => ['type' => 'string', 'enum' => ['red']],
            ],
            ['oneOf' => [$amber, $intMap]],
            [
                '{"pack":[{"crane":1}]}' => false,
                '{"tint":"blue"}' => false,
                '{"day":"x"}' => false,
                '{"pack":[{"crane":6}],"tint":"red","day":"2024-01-02"}' => true,
                '{"pack":[]}' => true,
            ],
        ];
        yield 'map of classes and list of enum values beside an integer map' => [
            [
                'flock' => ['type' => 'object', 'additionalProperties' => $teal],
                'hues' => ['type' => 'array', 'items' => ['type' => 'string', 'enum' => ['red', 'blue']]],
            ],
            ['oneOf' => [$amber, $intMap]],
            [
                '{"flock":{"k":{"crane":1}}}' => false,
                '{"flock":{"k":{"crane":6}}}' => true,
                '{"hues":["green"]}' => false,
                '{"hues":["red","blue"]}' => true,
            ],
        ];
        // A scalar item where the list holds classes: laravel and laravel-data built the member from the
        // validated array and crashed on it (a TypeError, `CannotCreateData`).
        yield 'scalar item of a list of classes beside an integer map' => [
            ['pack' => ['type' => 'array', 'items' => $teal]],
            ['oneOf' => [$amber, $intMap]],
            ['{"pack":["x"]}' => false, '{"pack":[{"crane":6}]}' => true],
        ];
        yield 'enum property in an anyOf beside a list' => [
            ['bison' => $colours],
            ['oneOf' => [['anyOf' => [$amber, $closedLemur]], ['type' => 'array', 'items' => ['type' => 'integer']]]],
            [
                '{"bison":"zzq","lemur":"red","egret":"bcabcabc"}' => false,
                '{"bison":"violet","lemur":"red"}' => true,
                '{"lemur":"red"}' => true,
                '[1]' => true,
            ],
        ];
    }

    /**
     * A class that is one branch of a union is checked by the emitted interpreter against a spelled-out
     * schema. A list item or map value there that is itself a class (`items: $ref Teal`) was a bare
     * recurse marker with no `type: object`, the recursive fold too: a scalar item matched, the union
     * counted the branch, and laravel / laravel-data crashed building the member (a `TypeError`,
     * `CannotCreateData`). The same class held directly (`plain`) already refused it.
     */
    public function testAClassItemOfAUnionBranchIsAnObject(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'macaw' => ['oneOf' => [$ref('Amber'), ['type' => 'string']]],
                    'deep' => ['oneOf' => [$ref('Coral'), ['type' => 'string']]],
                    'twig' => ['oneOf' => [$ref('Node'), ['type' => 'string']]],
                    'gull' => ['oneOf' => [$ref('Amber'), ['type' => 'object', 'additionalProperties' => ['type' => 'integer']]]],
                    'wren' => ['oneOf' => [$ref('Olive'), ['type' => 'string']]],
                    // Controls: the classes held directly.
                    'plain' => $ref('Amber'),
                    'olive' => $ref('Olive'),
                ]],
                'Amber' => ['type' => 'object', 'properties' => [
                    'pack' => ['type' => 'array', 'items' => $ref('Teal')],
                    'bag' => ['type' => 'object', 'additionalProperties' => $ref('Teal')],
                    'one' => $ref('Teal'),
                ]],
                'Coral' => ['type' => 'object', 'properties' => ['inner' => $ref('Amber')]],
                'Node' => ['type' => 'object', 'properties' => ['kids' => ['type' => 'array', 'items' => $ref('Node')]], 'required' => ['kids']],
                // Items that admit null: a null item still passes.
                'Olive' => ['type' => 'object', 'properties' => [
                    'pack' => ['type' => 'array', 'items' => ['oneOf' => [$ref('Teal'), ['type' => 'null']]]],
                ]],
                'Teal' => ['type' => 'object', 'properties' => ['hue' => ['type' => 'string']], 'required' => ['hue']],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'class item of a union branch',
                payloads: [
                    '{"macaw":{"pack":["x"]}}' => false,
                    '{"macaw":{"pack":[1]}}' => false,
                    '{"macaw":{"bag":{"k":"x"}}}' => false,
                    '{"macaw":{"pack":[{"hue":"red"}],"bag":{"k":{"hue":"red"}}}}' => true,
                    '{"macaw":"x"}' => true,
                    '{"macaw":{"one":"x"}}' => false,
                    '{"deep":{"inner":{"pack":["x"]}}}' => false,
                    '{"deep":{"inner":{"pack":[{"hue":"red"}]}}}' => true,
                    '{"twig":{"kids":[1]}}' => false,
                    '{"twig":{"kids":[{"kids":[]}]}}' => true,
                    '{"gull":{"pack":["x"]}}' => false,
                    '{"gull":{"pack":[{"hue":"red"}]}}' => true,
                    '{"wren":{"pack":["x"]}}' => false,
                    '{"wren":{"pack":[null,{"hue":"red"}]}}' => true,
                    '{"plain":{"pack":["x"]}}' => false,
                    '{"plain":{"pack":[{"hue":"red"}]}}' => true,
                    '{"olive":{"pack":["x"]}}' => false,
                    '{"olive":{"pack":[null,{"hue":"red"}]}}' => true,
                ],
                // A boundary (support matrix, a `null` ITEM of a nullable list of DTOs): laravel-data's
                // `#[DataCollectionOf]` has no null case, and the guard refuses the null first.
                diverging: [
                    GenerationMode::LaravelData->value => [
                        '{"wren":{"pack":[null,{"hue":"red"}]}}' => false,
                        '{"olive":{"pack":[null,{"hue":"red"}]}}' => false,
                    ],
                ],
            ),
        );
    }

    /**
     * `not` laid beside a generated class — a `$ref`, an `allOf: [$ref]` with and without `required`, an
     * inline object — is asked of the class's property values. The DTO-owned property rules were left
     * out of the `not` subschema as they are out of the class's own: the emptied subschema matched every
     * object, and every value was refused.
     *
     * @param array<string, mixed> $macaw
     * @param array<string, bool> $payloads the value of `macaw`
     */
    #[DataProvider('notBesideAClassCases')]
    public function testANotBesideAClassIsAskedOfItsPropertyValues(array $macaw, array $payloads): void
    {
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => ['macaw' => $macaw]],
                'Amber' => ['type' => 'object', 'properties' => ['bison' => ['type' => 'string'], 'crane' => ['type' => 'integer']]],
            ]],
        ];
        $wired = [];
        foreach ($payloads as $value => $expected) {
            $wired[sprintf('{"macaw":%s}', $value)] = $expected;
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'not beside a class ' . md5((string)json_encode($spec)),
                payloads: $wired,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool>}>
     */
    public static function notBesideAClassCases(): iterable
    {
        $amber = ['$ref' => '#/components/schemas/Amber'];
        $notBlue = ['properties' => ['bison' => ['enum' => ['blue']]]];

        yield 'not beside a ref' => [
            [...$amber, 'not' => $notBlue],
            ['{"bison":"violet"}' => true, '{"bison":"blue"}' => false, '{"crane":1}' => false],
        ];
        yield 'not beside an allOf ref' => [
            ['allOf' => [$amber], 'not' => [...$notBlue, 'required' => ['bison']]],
            ['{"bison":"violet"}' => true, '{"bison":"blue"}' => false, '{"crane":1}' => true],
        ];
        yield 'not beside an allOf ref without required' => [
            ['allOf' => [$amber], 'not' => $notBlue],
            ['{"bison":"violet"}' => true, '{"bison":"blue"}' => false, '{"crane":1}' => false],
        ];
        yield 'not beside an inline object' => [
            ['type' => 'object', 'properties' => ['bison' => ['type' => 'string']], 'not' => ['properties' => ['bison' => ['minLength' => 4]]]],
            ['{"bison":"ab"}' => true, '{"bison":"abcd"}' => false, '{}' => false],
        ];
        yield 'not beside an inline object with required' => [
            ['type' => 'object', 'properties' => ['bison' => ['type' => 'string']], 'not' => ['properties' => ['bison' => ['const' => 'blue']], 'required' => ['bison']]],
            ['{"bison":"violet"}' => true, '{"bison":"blue"}' => false, '{}' => true],
        ];
        // Neighbours: the same `$ref` under anyOf and dependentSchemas, the latter beside `allOf` too.
        yield 'anyOf beside a ref' => [
            [...$amber, 'anyOf' => [['properties' => ['bison' => ['enum' => ['violet']]]], ['required' => ['crane']]]],
            ['{"bison":"violet"}' => true, '{"crane":1}' => true, '{"bison":"blue"}' => false],
        ];
        yield 'dependentSchemas beside a ref' => [
            [...$amber, 'dependentSchemas' => ['crane' => ['properties' => ['bison' => ['enum' => ['violet']]]]]],
            ['{"bison":"blue"}' => true, '{"crane":1,"bison":"violet"}' => true, '{"crane":1,"bison":"blue"}' => false],
        ];
        yield 'dependentSchemas beside an allOf ref' => [
            ['allOf' => [$amber], 'dependentSchemas' => ['crane' => ['properties' => ['bison' => ['enum' => ['violet']]]]]],
            ['{"bison":"blue"}' => true, '{"crane":1,"bison":"violet"}' => true, '{"crane":1,"bison":"blue"}' => false],
        ];
    }

    /**
     * What runtime, laravel and laravel-data write a payload back as — the modes that write one, so the
     * member that was BUILT shows, not just the verdict. Decoded, so the order of the keys is not
     * asserted: laravel-data writes a member's keys in its own order.
     *
     * @param array<string, mixed> $spec
     * @return list<mixed>
     */
    private function writtenBackByTheWritingModes(array $spec, string $key, string $json): array
    {
        $decoded = static fn(string $written): mixed => json_decode($written, true) ?? $written;

        return [
            $decoded($this->runtimeRoundTrip($spec, $key, $json)),
            $decoded($this->writtenBack(GenerationMode::Laravel, $spec, $key, $json)),
            $decoded($this->writtenBack(GenerationMode::LaravelData, $spec, $key, $json)),
        ];
    }

    /**
     * `allOf: [$ref Indigo]` is the same reference as `$ref: Indigo`. Indigo wraps a discriminated `oneOf`
     * in an `anyOf`, and the wrapped spelling lifted its members into the PHP type (`Jade|Ivory`) without
     * the discriminator: symfony tried Ivory first, its `kind` enum a collected error under
     * `#[MapRequestPayload]`, and refused a valid Jade. Held as the decoded array now, as the bare `$ref`
     * already was, and the member its tag names judges it.
     */
    public function testAnAllOfWrappedReferenceToANestedDiscriminatedUnionKeepsItsDiscriminator(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $discriminated = [
            'oneOf' => [$ref('Jade'), $ref('Ivory')],
            'discriminator' => ['propertyName' => 'kind', 'mapping' => ['square' => '#/components/schemas/Jade', 'oval' => '#/components/schemas/Ivory']],
        ];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Jade' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string']]],
                'Ivory' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string', 'enum' => ['oval']]]],
                'Indigo' => ['anyOf' => [$discriminated]],
                'Indigob' => ['anyOf' => [$discriminated, ['type' => 'integer']]],
                'Probe' => ['type' => 'object', 'properties' => [
                    'ibis' => ['allOf' => [$ref('Indigo')]],
                    'ibex' => ['allOf' => [$ref('Indigob')]],
                    // Controls that already held it: the bare reference, the union written inline, and the
                    // discriminated `oneOf` on the property itself.
                    'bare' => $ref('Indigo'),
                    'inl' => ['allOf' => [['anyOf' => [$discriminated]]]],
                    'own' => $discriminated,
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'allOf-wrapped reference to a nested discriminated union',
                payloads: [
                    '{"ibis":{"kind":"square"}}' => true,
                    '{"ibis":{"kind":"oval"}}' => true,
                    '{"ibis":{"kind":"round"}}' => false,
                    '{"ibis":5}' => false,
                    '{"ibex":{"kind":"square"}}' => true,
                    '{"ibex":{"kind":"oval"}}' => true,
                    '{"ibex":5}' => true,
                    '{"ibex":{"kind":"round"}}' => false,
                    '{"bare":{"kind":"square"}}' => true,
                    '{"bare":{"kind":"round"}}' => false,
                    '{"inl":{"kind":"square"}}' => true,
                    '{"inl":{"kind":"round"}}' => false,
                    '{"own":{"kind":"square"}}' => true,
                    '{"own":{"kind":"oval"}}' => true,
                    '{"own":{"kind":"round"}}' => false,
                ],
            ),
        );
    }

    /**
     * A list item naming an alias of an empty object (`Amber: {$ref: Azure}`, `Azure: {type: object}`)
     * is an object. Inside a union component held as the decoded array, symfony read the component RAW,
     * the item still named Amber — no class, no schema of its own — and the item was written out as
     * nothing: `{"plover": [true]}` passed. The alias is followed to Azure now, as everywhere else.
     */
    public function testAListItemNamingAnAliasOfAnEmptyObjectIsAnObject(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $list = static fn(string $item): array => ['oneOf' => [['type' => 'array', 'items' => $ref($item)]]];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'components' => ['schemas' => [
                'Azure' => ['type' => 'object'],
                'Amber' => $ref('Azure'),
                'Indigo' => $list('Amber'),
                'Indigoz' => $list('Azure'),
                'Probe' => ['type' => 'object', 'properties' => [
                    'plover' => $ref('Indigo'),
                    // Controls that already refused: the item naming Azure itself, the union inline, and
                    // the list without a union.
                    'direct' => $ref('Indigoz'),
                    'inl' => $list('Amber'),
                    'flat' => ['type' => 'array', 'items' => $ref('Amber')],
                ]],
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'list item naming an alias of an empty object',
                payloads: [
                    '{"plover":[{}]}' => true,
                    '{"plover":[{"a":1}]}' => true,
                    '{"plover":[true]}' => false,
                    '{"plover":[1]}' => false,
                    '{"direct":[{}]}' => true,
                    '{"direct":[true]}' => false,
                    '{"inl":[{}]}' => true,
                    '{"inl":[1]}' => false,
                    '{"flat":[{}]}' => true,
                    '{"flat":[1]}' => false,
                ],
            ),
        );
    }

    /**
     * A member of a discriminated union that is a class of another document, placed by `--ref` where that
     * document's own run writes it, may not name the union: that run knows nothing of it, and the two runs
     * wrote two classes into one file — laravel `implements Pet`, laravel-data `extends Pet`, symfony
     * `implements Pet` against a plain DTO. With the plain one in place, `{"pet":{"kind":"dog",…}}` was a
     * `TypeError` in laravel and laravel-data and a 500 in symfony: the holder typed `?Pet` could not take
     * the `Dog`. Both runs now write the same Dog; the holder is typed by the members and dispatched by
     * the tag (runtime, laravel, laravel-data) or held as the decoded array the tag's member judges
     * (symfony) — a list of them too. yii3 left the member of another document unchecked: `then: []`.
     */
    public function testAUnionMemberAnotherDocumentWritesIsHeldByItsMembers(): void
    {
        $ref = static fn(string $target): array => ['$ref' => $target];
        $document = static fn(array $schemas): array => ['openapi' => '3.0.3', 'info' => ['title' => 'T', 'version' => '1'], 'paths' => [], 'components' => ['schemas' => $schemas]];
        $ext = $document([
            'Dog' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string'], 'bark' => ['type' => 'integer']]],
        ]);
        $main = $document([
            'Probe' => ['type' => 'object', 'properties' => [
                'pet' => $ref('#/components/schemas/Pet'),
                'pets' => ['type' => 'array', 'items' => $ref('#/components/schemas/Pet')],
            ]],
            'Pet' => [
                'oneOf' => [$ref('#/components/schemas/Cat'), $ref('ext.json#/components/schemas/Dog')],
                'discriminator' => ['propertyName' => 'kind', 'mapping' => ['cat' => '#/components/schemas/Cat', 'dog' => 'ext.json#/components/schemas/Dog']],
            ],
            'Cat' => ['type' => 'object', 'required' => ['kind'], 'properties' => ['kind' => ['type' => 'string'], 'purr' => ['type' => 'boolean']]],
        ]);
        $payloads = [
            '{"pet":{"kind":"dog","bark":2}}' => true,
            '{"pet":{"kind":"cat","purr":true}}' => true,
            '{"pets":[{"kind":"dog","bark":2},{"kind":"cat","purr":false}]}' => true,
            '{"pet":{"kind":"dog","bark":"x"}}' => false,
            '{"pets":[{"kind":"dog","bark":"x"}]}' => false,
            '{"pet":{"kind":"cow"}}' => false,
        ];

        $workingDirectory = (string)getcwd();
        $misses = [];
        try {
            foreach (GenerationMode::cases() as $mode) {
                $namespace = $this->namespaceFor($mode, 'union member another document writes');
                $root = $this->outputDirectory . '/' . $namespace;
                mkdir($root . '/documents', 0o755, true);
                file_put_contents($root . '/documents/ext.json', json_encode($ext, JSON_THROW_ON_ERROR));
                file_put_contents($root . '/documents/main.json', json_encode($main, JSON_THROW_ON_ERROR));
                chdir($root);
                $this->runGenerateCommand([
                    '--file' => 'documents/main.json',
                    '--directory' => 'Main',
                    '--namespace' => $namespace . '\Main',
                    '--attributes' => $mode->value,
                    '--ref' => ['documents/ext.json=Ext=' . $namespace . '\Ext'],
                ]);
                $writtenForTheUnion = (string)file_get_contents($root . '/Ext/Dog.php');
                $this->runGenerateCommand([
                    '--file' => 'documents/ext.json',
                    '--directory' => 'Ext',
                    '--namespace' => $namespace . '\Ext',
                    '--attributes' => $mode->value,
                ]);
                $written = (string)file_get_contents($root . '/Ext/Dog.php');
                if ($writtenForTheUnion !== $written) {
                    $misses[] = $mode->value . ': the two runs write two Dogs';
                }
                $this->registerGeneratedAutoloader(namespace: $namespace . '\Main', target: $root . '/Main');
                $this->registerGeneratedAutoloader(namespace: $namespace . '\Ext', target: $root . '/Ext');
                if ($mode === GenerationMode::LaravelData) {
                    LaravelDataContainer::boot();
                }
                foreach ($payloads as $json => $expected) {
                    $outcome = $this->payloadOutcome($mode, $namespace . '\Main\Probe', (string)$json);
                    $wanted = $expected ? PayloadVerdict::Accepted : PayloadVerdict::Refused;
                    if ($outcome->verdict !== $wanted) {
                        $misses[] = sprintf('%s: %s %s (%s: %s)', $mode->value, $json, $outcome->verdict->value, $outcome->stage, $outcome->detail);
                    }
                }
            }
        } finally {
            chdir($workingDirectory);
        }

        $this->assertSame(expected: [], actual: $misses);
    }

    /**
     * The keywords an `allOf` branch states about the KEYS of the object — `additionalProperties`
     * `false` or a schema, `minProperties` / `maxProperties` — judge a class spelled as that `allOf`
     * the way they judge the plain spelling: a one-member wrapper (a component or inline), a second
     * branch beside it, a closed branch beside a `$ref` parent. Runtime emitted no object constraints
     * for such a class and both Laravel modes no closure, so `{"crane": "a", "stray": "x"}` was
     * accepted with the stray key dropped, where the plain spelling refused it.
     *
     * A branch's closure counts the names its sibling branches declare (the inherited properties are
     * not extra ones beside a parent — `testInheritedPropertiesAreNotExtraOnesBesideAParent`), but not
     * the ones the class declares beside its `allOf`: those reach no branch. Symfony and yii3 drop an
     * undeclared key before any constraint runs, and judge the branch's closure on the class they
     * merge it into (README.support-matrix, the closed-object rows), so their answer to a key a
     * closure refuses is not asserted.
     *
     * @param array<string, mixed> $schemas
     * @param array<string, bool|null> $payloads
     * @param list<string> $closureOnlyRefusals payloads only the closure refuses, beside the ones with a `stray` key
     */
    #[DataProvider('allOfBranchObjectKeywordCases')]
    public function testObjectKeywordsInsideAnAllOfBranchJudgeTheClass(array $schemas, array $payloads, array $closureOnlyRefusals = []): void
    {
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => $schemas],
        ];
        $undeclaredKeyUnseen = [];
        foreach ($payloads as $json => $expected) {
            if ($expected === false && (str_contains((string)$json, '"stray"') || in_array($json, $closureOnlyRefusals, true))) {
                $undeclaredKeyUnseen[(string)$json] = null;
            }
        }

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'allOf branch object keywords ' . md5((string)json_encode($schemas)),
                payloads: $payloads,
                diverging: ['symfony' => $undeclaredKeyUnseen, 'yii3' => $undeclaredKeyUnseen],
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, bool|null>, 2?: list<string>}>
     */
    public static function allOfBranchObjectKeywordCases(): iterable
    {
        $probe = ['type' => 'object', 'properties' => ['urchin' => ['$ref' => '#/components/schemas/Cobalt']]];
        $crane = ['crane' => ['type' => 'string']];
        $closed = ['type' => 'object', 'properties' => $crane, 'additionalProperties' => false];
        $closedPayloads = [
            '{"urchin":{"crane":"a"}}' => true,
            '{"urchin":{}}' => true,
            '{"urchin":{"crane":"a","stray":"x"}}' => false,
            '{"urchin":{"crane":5}}' => false,
        ];

        // Pinned: the plain spelling, and a one-member `allOf` of a `$ref` parent.
        yield 'closed, plain' => [['Probe' => $probe, 'Cobalt' => $closed], $closedPayloads];
        yield 'closed parent of a one-member allOf' => [
            ['Probe' => $probe, 'Cobalt' => ['allOf' => [['$ref' => '#/components/schemas/Base']]], 'Base' => $closed],
            $closedPayloads,
        ];
        yield 'closed one-member allOf component' => [['Probe' => $probe, 'Cobalt' => ['allOf' => [$closed]]], $closedPayloads];
        yield 'closed one-member allOf, nested once more' => [['Probe' => $probe, 'Cobalt' => ['allOf' => [['allOf' => [$closed]]]]], $closedPayloads];
        yield 'closed one-member allOf inline' => [
            ['Probe' => ['type' => 'object', 'properties' => ['urchin' => ['allOf' => [$closed]]]]],
            $closedPayloads,
        ];
        yield 'closed branch of a two-branch allOf' => [
            ['Probe' => $probe, 'Cobalt' => ['allOf' => [$closed, ['type' => 'object', 'properties' => ['crane' => ['minLength' => 1]]]]]],
            [...$closedPayloads, '{"urchin":{"crane":""}}' => false],
        ];
        yield 'closed branch beside a $ref parent' => [
            [
                'Probe' => $probe,
                'Cobalt' => ['allOf' => [['$ref' => '#/components/schemas/Base'], $closed]],
                'Base' => ['type' => 'object', 'properties' => ['heron' => ['type' => 'string']]],
            ],
            [...$closedPayloads, '{"urchin":{"crane":"a","heron":"b"}}' => true],
        ];
        yield 'closed branch beside an open sibling branch' => [
            ['Probe' => $probe, 'Cobalt' => ['allOf' => [$closed, ['type' => 'object', 'properties' => ['heron' => ['type' => 'string']]]]]],
            [...$closedPayloads, '{"urchin":{"crane":"a","heron":"b"}}' => true],
        ];
        yield 'closed branch, a property declared beside the allOf' => [
            ['Probe' => $probe, 'Cobalt' => ['type' => 'object', 'properties' => ['heron' => ['type' => 'string']], 'allOf' => [$closed]]],
            [...$closedPayloads, '{"urchin":{"crane":"a","heron":"b"}}' => false, '{"urchin":{"heron":"b"}}' => false],
            ['{"urchin":{"crane":"a","heron":"b"}}', '{"urchin":{"heron":"b"}}'],
        ];

        // The class extends Mid, whose own branch closure it inherits beside its own branch's bound.
        yield 'closed branch of a parent beside a bounded branch' => [
            [
                'Probe' => $probe,
                'Cobalt' => ['allOf' => [['$ref' => '#/components/schemas/Mid'], ['type' => 'object', 'properties' => ['egret' => ['type' => 'string']], 'maxProperties' => 2]]],
                'Mid' => ['allOf' => [$closed, ['type' => 'object', 'properties' => ['heron' => ['type' => 'string']]]]],
            ],
            [
                '{"urchin":{"crane":"a","heron":"b"}}' => true,
                '{"urchin":{"crane":"a","stray":"x"}}' => false,
                '{"urchin":{"crane":5}}' => false,
            ],
        ];

        $typed = ['type' => 'object', 'properties' => $crane, 'additionalProperties' => ['type' => 'boolean']];
        $typedPayloads = [
            '{"urchin":{"crane":"a","egret":true}}' => true,
            '{"urchin":{"crane":"a","stray":{"zz":1}}}' => false,
            '{"urchin":{"crane":"a","stray":"y"}}' => false,
        ];
        yield 'additionalProperties schema, plain' => [['Probe' => $probe, 'Cobalt' => $typed], $typedPayloads];
        yield 'additionalProperties schema in a one-member allOf' => [['Probe' => $probe, 'Cobalt' => ['allOf' => [$typed]]], $typedPayloads];
        yield 'additionalProperties schema in a branch of two' => [
            ['Probe' => $probe, 'Cobalt' => ['allOf' => [$typed, ['type' => 'object', 'properties' => ['crane' => ['minLength' => 1]]]]]],
            $typedPayloads,
        ];

        $bounded = ['type' => 'object', 'properties' => [...$crane, 'heron' => ['type' => 'string']], 'maxProperties' => 1];
        $boundedPayloads = [
            '{"urchin":{"crane":"a"}}' => true,
            '{"urchin":{"crane":"a","heron":"b"}}' => false,
        ];
        yield 'maxProperties, plain' => [['Probe' => $probe, 'Cobalt' => $bounded], $boundedPayloads];
        yield 'maxProperties in a one-member allOf' => [['Probe' => $probe, 'Cobalt' => ['allOf' => [$bounded]]], $boundedPayloads];
        yield 'maxProperties in a branch of two' => [
            ['Probe' => $probe, 'Cobalt' => ['allOf' => [$bounded, ['type' => 'object', 'properties' => ['crane' => ['minLength' => 1]]]]]],
            $boundedPayloads,
        ];
    }

    /**
     * A union member that is a class of another document (`--ref`, its own namespace) is the class it
     * names in every mode. Symfony's interpreter resolved the short marker against the holder's own
     * namespace, so `oneOf: [{type: string, nullable: true}, {$ref: other.json#/…/Jadea}]` refused every
     * valid Jadea as "does not match any oneOf branch"; and a discriminated union with such a member, its
     * mapping left implicit, was typed `?array` with nothing checking it — `{"kind": "zzq"}` passed,
     * as did a member missing what it requires. The same shapes within one document are pinned beside.
     *
     * @param array<string, mixed> $main
     * @param array<string, mixed> $ext
     * @param array<string, bool|null> $payloads
     */
    #[DataProvider('unionMemberOfAnotherDocumentCases')]
    public function testAUnionMemberOfAnotherDocumentIsItsOwnClass(array $main, array $ext, array $payloads): void
    {
        $this->assertSame(
            expected: [],
            actual: $this->externalDocumentPayloadMisses(
                main: $main,
                ext: $ext,
                key: 'union member of another document ' . md5((string)json_encode([$main, $ext])),
                payloads: $payloads,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, mixed>, 2: array<string, bool|null>}>
     */
    public static function unionMemberOfAnotherDocumentCases(): iterable
    {
        $document = static fn(string $version, array $schemas): array => [
            'openapi' => $version,
            'info' => ['title' => 'T', 'version' => '1'],
            'paths' => [],
            'components' => ['schemas' => $schemas],
        ];
        $probe = static fn(array $properties): array => ['type' => 'object', 'properties' => $properties];
        $jadeaDocument = $document('3.0.3', [
            'Siennaa' => ['type' => 'boolean'],
            'Jadea' => ['type' => 'object', 'properties' => ['robin' => ['$ref' => '#/components/schemas/Siennaa']]],
        ]);
        $jadeaPayloads = [
            '{"sable":{"robin":false}}' => true,
            '{"sable":{}}' => true,
            '{"sable":"x"}' => true,
            '{"sable":null}' => true,
            '{"sable":5}' => false,
            '{"sable":{"robin":3}}' => false,
        ];
        $external = ['$ref' => 'ext.json#/components/schemas/Jadea'];

        yield 'string or a class of another document' => [
            $document('3.0.3', ['Probe' => $probe(['sable' => ['oneOf' => [['type' => 'string', 'nullable' => true], $external]]])]),
            $jadeaDocument,
            $jadeaPayloads,
        ];
        yield 'string or a class of another document, wrapped in allOf' => [
            $document('3.0.3', ['Probe' => $probe(['sable' => ['oneOf' => [['type' => 'string', 'nullable' => true], ['allOf' => [$external]]]]])]),
            $jadeaDocument,
            $jadeaPayloads,
        ];

        $azureDocument = $document('3.1.0', [
            'Azure' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'newt' => ['type' => 'integer']], 'required' => ['kind', 'newt']],
        ]);
        $amber = ['type' => 'object', 'properties' => ['kind' => ['type' => 'string'], 'tapir' => ['type' => 'integer']], 'required' => ['kind', 'tapir']];
        $members = [['$ref' => 'ext.json#/components/schemas/Azure'], ['$ref' => '#/components/schemas/Amber']];
        $taggedPayloads = [
            '{"bison":{"kind":"Amber","tapir":1}}' => true,
            '{"bison":{"kind":"Azure","newt":1}}' => true,
            '{"bison":{"kind":"zzq","tapir":2}}' => false,
            '{"bison":{"kind":"Azure"}}' => false,
            '{"bison":{"kind":"Amber","tapir":"x"}}' => false,
            '{"bison":{"kind":"Azure","tapir":1}}' => false,
        ];
        foreach (['anyOf', 'oneOf'] as $keyword) {
            yield 'discriminated ' . $keyword . ' with a member of another document' => [
                $document('3.1.0', [
                    'Probe' => $probe(['bison' => [$keyword => $members, 'discriminator' => ['propertyName' => 'kind']]]),
                    'Amber' => $amber,
                ]),
                $azureDocument,
                $taggedPayloads,
            ];
            yield 'discriminated ' . $keyword . ' component with a member of another document' => [
                $document('3.1.0', [
                    'Probe' => $probe(['bison' => ['$ref' => '#/components/schemas/Pet']]),
                    'Pet' => [$keyword => $members, 'discriminator' => ['propertyName' => 'kind']],
                    'Amber' => $amber,
                ]),
                $azureDocument,
                $taggedPayloads,
            ];
        }
        // Pinned: the same shapes within one document.
        yield 'string or a class of the same document' => [
            $document('3.0.3', [
                'Probe' => $probe(['sable' => ['oneOf' => [['type' => 'string', 'nullable' => true], ['$ref' => '#/components/schemas/Jadea']]]]),
                ...$jadeaDocument['components']['schemas'],
            ]),
            $jadeaDocument,
            $jadeaPayloads,
        ];
        yield 'discriminated anyOf within one document' => [
            $document('3.1.0', [
                'Probe' => $probe(['bison' => ['anyOf' => [['$ref' => '#/components/schemas/Azure'], ['$ref' => '#/components/schemas/Amber']], 'discriminator' => ['propertyName' => 'kind']]]),
                'Amber' => $amber,
                ...$azureDocument['components']['schemas'],
            ]),
            $azureDocument,
            $taggedPayloads,
        ];

        // A component union of this document mapping a member of the other one, which `--ref` places
        // where its own run writes it too: the member may not extend the union, so a holder is typed by
        // the members. Only the bare `$ref` was; the reference wrapped in `allOf` or beside a null kept
        // the base — runtime refused every Scarlet ("must extend or implement Teal"), laravel and
        // laravel-data died on a TypeError, and symfony typed the property by an interface Scarlet
        // does not implement.
        $scarletDocument = $document('3.1.0', [
            'Scarlet' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['hexagon']], 'kiwi' => ['type' => 'integer']], 'required' => ['kind']],
        ]);
        $teal = [
            'oneOf' => [['$ref' => 'ext.json#/components/schemas/Scarlet'], ['$ref' => '#/components/schemas/Olive']],
            'discriminator' => ['propertyName' => 'kind', 'mapping' => ['hexagon' => 'ext.json#/components/schemas/Scarlet', 'square' => '#/components/schemas/Olive']],
        ];
        $olive = ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['square']]], 'required' => ['kind']];
        $tealRef = ['$ref' => '#/components/schemas/Teal'];
        $tealPayloads = [
            '{"toucan":{"kind":"hexagon","kiwi":1}}' => true,
            '{"toucan":{"kind":"square"}}' => true,
            '{"toucan":{"kind":"hexagon","kiwi":"x"}}' => false,
            '{"toucan":{"kind":"zzq"}}' => false,
            '{"toucan":5}' => false,
        ];
        $tealSpellings = [
            'a bare reference' => [$tealRef, false],
            'a reference in a one-member allOf' => [['allOf' => [$tealRef]], false],
            'a reference beside a null in anyOf' => [['anyOf' => [$tealRef, ['type' => 'null']]], true],
            'a reference beside a null in oneOf' => [['oneOf' => [$tealRef, ['type' => 'null']]], true],
        ];
        foreach ($tealSpellings as $spelling => [$toucan, $admitsNull]) {
            yield 'discriminated union mapping a member of another document, held by ' . $spelling => [
                $document('3.1.0', ['Probe' => $probe(['toucan' => $toucan]), 'Teal' => $teal, 'Olive' => $olive]),
                $scarletDocument,
                [...$tealPayloads, '{"toucan":null}' => $admitsNull],
            ];
        }
        yield 'list of a discriminated union mapping a member of another document, beside a null' => [
            $document('3.1.0', [
                'Probe' => $probe(['toucan' => ['type' => 'array', 'items' => ['anyOf' => [$tealRef, ['type' => 'null']]]]]),
                'Teal' => $teal,
                'Olive' => $olive,
            ]),
            $scarletDocument,
            [
                '{"toucan":[{"kind":"hexagon","kiwi":1},{"kind":"square"}]}' => true,
                '{"toucan":[{"kind":"hexagon","kiwi":"x"}]}' => false,
                '{"toucan":[{"kind":"zzq"}]}' => false,
            ],
        ];
        yield 'list of a discriminated union mapping a member of another document, in a one-member allOf' => [
            $document('3.1.0', [
                'Probe' => $probe(['toucan' => ['type' => 'array', 'items' => ['allOf' => [$tealRef]]]]),
                'Teal' => $teal,
                'Olive' => $olive,
            ]),
            $scarletDocument,
            [
                '{"toucan":[{"kind":"hexagon","kiwi":1},{"kind":"square"}]}' => true,
                '{"toucan":[{"kind":"hexagon","kiwi":"x"}]}' => false,
                '{"toucan":[{"kind":"zzq"}]}' => false,
            ],
        ];
        yield 'map of a discriminated union mapping a member of another document, beside a null' => [
            $document('3.1.0', [
                'Probe' => $probe(['toucan' => ['type' => 'object', 'additionalProperties' => ['anyOf' => [$tealRef, ['type' => 'null']]]]]),
                'Teal' => $teal,
                'Olive' => $olive,
            ]),
            $scarletDocument,
            [
                '{"toucan":{"a":{"kind":"hexagon","kiwi":1},"b":{"kind":"square"}}}' => true,
                '{"toucan":{"a":{"kind":"hexagon","kiwi":"x"}}}' => false,
                '{"toucan":{"a":{"kind":"zzq"}}}' => false,
            ],
        ];

        // A discriminated union of the other document beside a scalar: laravel built its members by short
        // names it never imported — `Class "…\Azure" not found` for every valid tag.
        $crimsonDocument = $document('3.1.0', [
            'Crimson' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']]], 'required' => ['kind']],
            'Azure' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['hexagon']], 'kiwi' => ['type' => 'integer']], 'required' => ['kind']],
            'Scarlet' => [
                'oneOf' => [['$ref' => '#/components/schemas/Crimson'], ['$ref' => '#/components/schemas/Azure']],
                'discriminator' => ['propertyName' => 'kind', 'mapping' => ['circle' => '#/components/schemas/Crimson', 'hexagon' => '#/components/schemas/Azure']],
            ],
        ]);
        $scarletRef = ['$ref' => 'ext.json#/components/schemas/Scarlet'];
        $urchinPayloads = [
            '{"urchin":{"kind":"hexagon","kiwi":-45}}' => true,
            '{"urchin":{"kind":"circle"}}' => true,
            '{"urchin":"x"}' => true,
            '{"urchin":{"kind":"hexagon","kiwi":"y"}}' => false,
            '{"urchin":{"kind":"zzq"}}' => false,
            '{"urchin":5}' => false,
        ];
        yield 'string or a discriminated union of another document' => [
            $document('3.1.0', ['Probe' => $probe(['urchin' => ['oneOf' => [['type' => 'string'], $scarletRef]]])]),
            $crimsonDocument,
            $urchinPayloads,
        ];
        yield 'string or a discriminated union of another document, wrapped in allOf' => [
            $document('3.1.0', ['Probe' => $probe(['urchin' => ['oneOf' => [['type' => 'string'], ['allOf' => [$scarletRef]]]]])]),
            $crimsonDocument,
            $urchinPayloads,
        ];
        // Pinned: the union of the other document held on its own.
        yield 'a discriminated union of another document' => [
            $document('3.1.0', ['Probe' => $probe(['urchin' => $scarletRef])]),
            $crimsonDocument,
            [
                '{"urchin":{"kind":"hexagon","kiwi":-45}}' => true,
                '{"urchin":{"kind":"circle"}}' => true,
                '{"urchin":{"kind":"zzq"}}' => false,
            ],
        ];
    }

    /**
     * A discriminated union nested in an undiscriminated one more than one level down — `anyOf:
     * [{anyOf: [{type: string}, <discriminated oneOf>]}, {type: null}]` — is held as the decoded array
     * in symfony as the one-level spelling is. Typed `string|Amber|Indigo|null`, the serializer built
     * Amber for a valid `{"kind": "circle"}` and refused it for Amber's `kind` enum.
     */
    public function testADiscriminatedUnionTwoUnionsDownKeepsItsDiscriminator(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $discriminated = [
            'oneOf' => [$ref('Amber'), $ref('Indigo')],
            'discriminator' => ['propertyName' => 'kind', 'mapping' => ['square' => '#/components/schemas/Amber', 'circle' => '#/components/schemas/Indigo']],
        ];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'bison' => ['anyOf' => [['anyOf' => [['type' => 'string'], $discriminated]], ['type' => 'null']]],
                    'heron' => ['anyOf' => [['anyOf' => [['type' => 'string'], $discriminated, ['type' => 'integer', 'exclusiveMaximum' => -12]]], ['type' => 'null']]],
                    // Pinned: the one-level spelling.
                    'egret' => ['anyOf' => [['type' => 'string'], $discriminated, ['type' => 'null']]],
                ]],
                'Amber' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['square']]], 'required' => ['kind']],
                'Indigo' => ['type' => 'object', 'properties' => ['kind' => ['type' => 'string', 'enum' => ['circle']]], 'required' => ['kind']],
            ]],
        ];
        $payloads = [];
        foreach (['bison', 'heron', 'egret'] as $name) {
            $payloads += [
                '{"' . $name . '":{"kind":"circle"}}' => true,
                '{"' . $name . '":{"kind":"square"}}' => true,
                '{"' . $name . '":"x"}' => true,
                '{"' . $name . '":null}' => true,
                '{"' . $name . '":{"kind":"oval"}}' => false,
                '{"' . $name . '":true}' => false,
            ];
        }
        $payloads += ['{"heron":-20}' => true, '{"heron":5}' => false];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(spec: $spec, key: 'discriminated union two unions down', payloads: $payloads),
        );
    }

    /**
     * A list item or map value that is a string enum or null — a `$ref` made nullable by 3.0's `nullable`,
     * by an `allOf` wrapper, by `anyOf` / `oneOf` beside `{type: null}`, or the inline enum with
     * `nullable` — accepts its null in symfony: typed `?Nonnull`, `BackedEnumNormalizer` refused it
     * ("neither an integer nor a string"). It is held as the string it arrives as, the callback checking
     * the enum, as the inline enum that lists `null` itself always was.
     *
     * @param array<string, mixed> $member
     * @param array<string, mixed> $schemas
     * @param array<string, bool> $payloads the string enum's when empty
     */
    #[DataProvider('nullableEnumContainerMemberCases')]
    public function testANullableEnumListItemOrMapValueAcceptsNull(string $version, array $member, array $schemas = [], array $payloads = []): void
    {
        $spec = [
            'openapi' => $version,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'otter' => ['type' => 'object', 'additionalProperties' => $member],
                    'lynx' => ['type' => 'array', 'items' => $member],
                ]],
                'Nonnull' => ['type' => 'string', 'enum' => ['violet', 'cyan']],
                ...$schemas,
            ]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'nullable enum container member ' . md5((string)json_encode($spec)),
                payloads: $payloads !== [] ? $payloads : [
                    '{"otter":{"ka":null}}' => true,
                    '{"otter":{"ka":"cyan","kb":null}}' => true,
                    '{"otter":{"ka":"blue"}}' => false,
                    '{"otter":{"ka":3}}' => false,
                    '{"lynx":[null]}' => true,
                    '{"lynx":["violet",null]}' => true,
                    '{"lynx":["blue"]}' => false,
                    '{"lynx":[true]}' => false,
                ],
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, mixed>, 2?: array<string, mixed>, 3?: array<string, bool>}>
     */
    public static function nullableEnumContainerMemberCases(): iterable
    {
        $nonnull = ['$ref' => '#/components/schemas/Nonnull'];

        yield '3.0 nullable beside the reference' => ['3.0.3', [...$nonnull, 'nullable' => true]];
        yield 'nullable allOf wrapper component' => [
            '3.0.3',
            ['$ref' => '#/components/schemas/Coral'],
            ['Coral' => ['allOf' => [$nonnull], 'nullable' => true]],
        ];
        yield 'nullable allOf wrapper inline' => ['3.0.3', ['allOf' => [$nonnull], 'nullable' => true]];
        yield 'anyOf beside null' => ['3.1.0', ['anyOf' => [$nonnull, ['type' => 'null']]]];
        yield 'oneOf beside null' => ['3.1.0', ['oneOf' => [$nonnull, ['type' => 'null']]]];
        yield 'inline nullable enum' => ['3.0.3', ['type' => 'string', 'enum' => ['violet', 'cyan'], 'nullable' => true]];
        yield 'integer enum beside null' => [
            '3.1.0',
            ['anyOf' => [$nonnull, ['type' => 'null']]],
            ['Nonnull' => ['type' => 'integer', 'enum' => [4, 7]]],
            [
                '{"otter":{"ka":null}}' => true,
                '{"otter":{"ka":7}}' => true,
                '{"otter":{"ka":5}}' => false,
                '{"lynx":[4,null]}' => true,
                '{"lynx":[5]}' => false,
                '{"lynx":["x"]}' => false,
            ],
        ];
        // Pinned: the enum that lists `null` itself.
        yield 'enum listing null' => [
            '3.0.3',
            ['$ref' => '#/components/schemas/Coral'],
            ['Coral' => ['type' => 'string', 'enum' => ['violet', 'cyan', null], 'nullable' => true]],
        ];
    }

    /**
     * An `allOf` of scalar fragments is that scalar wherever it sits — with an `enum` or `const`
     * fragment (`allOf: [{type: integer}, {enum: [6, 9, 0]}]`), around a `$ref` to a scalar with value
     * keywords beside it (`allOf: [{$ref: Mauve, multipleOf: 2}]`), around a scalar component that is
     * itself a one-member `allOf`, and as 3.0 list items `{allOf: [{$ref: X}], nullable: true}`. Read as
     * no scalar, a union of such branches became an empty class that refused every value, the wrapped
     * reference named a class that was never written, and the list items lost their class.
     *
     * @param array<string, mixed> $schemas
     * @param array<string, bool|null> $payloads
     * @param array<string, array<string, bool|null>> $diverging
     */
    #[DataProvider('scalarAllOfFoldCases')]
    public function testAScalarAllOfFoldsWhereverItSits(string $version, array $schemas, array $payloads, array $diverging = []): void
    {
        $spec = [
            'openapi' => $version,
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => $schemas],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'scalar allOf fold ' . md5((string)json_encode($spec)),
                payloads: $payloads,
                diverging: $diverging,
            ),
        );
    }

    /**
     * @return iterable<string, array{0: string, 1: array<string, mixed>, 2: array<string, bool|null>, 3?: array<string, array<string, bool|null>>}>
     */
    public static function scalarAllOfFoldCases(): iterable
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $probe = static fn(array $properties): array => ['type' => 'object', 'properties' => $properties];
        $crimson = ['oneOf' => [['allOf' => [['type' => 'integer'], ['enum' => [6, 9, 0]]]], ['type' => 'null']]];
        $mauve = ['type' => 'number'];
        // README.support-matrix: laravel-data and yii3 take a numeric string for a number.
        $numericString = static fn(string $json): array => ['laravel-data' => [$json => null], 'yii3' => [$json => null]];

        yield 'enum fragment or null' => [
            '3.1.0',
            [
                'Probe' => $probe(['robin' => $ref('Ivory')]),
                'Ivory' => ['oneOf' => [['allOf' => [['type' => 'string'], ['enum' => ['violet']]]], ['type' => 'null']]],
            ],
            ['{"robin":"violet"}' => true, '{"robin":null}' => true, '{"robin":"red"}' => false, '{"robin":5}' => false, '{"robin":{"a":1}}' => false],
        ];
        yield 'enum fragments of two types' => [
            '3.0.3',
            [
                'Probe' => $probe(['robin' => $ref('Ivory')]),
                'Ivory' => ['oneOf' => [
                    ['allOf' => [['type' => 'string'], ['enum' => ['violet']]]],
                    ['allOf' => [[], ['type' => 'integer', 'enum' => [5, 8], 'minimum' => 5]]],
                ]],
            ],
            ['{"robin":"violet"}' => true, '{"robin":5}' => true, '{"robin":8}' => true, '{"robin":6}' => false, '{"robin":"red"}' => false],
        ];
        yield 'const fragment' => [
            '3.1.0',
            [
                'Probe' => $probe(['robin' => $ref('Ivory')]),
                'Ivory' => ['oneOf' => [['allOf' => [['type' => 'string'], ['const' => 'violet']]], ['type' => 'null']]],
            ],
            ['{"robin":"violet"}' => true, '{"robin":null}' => true, '{"robin":"red"}' => false],
        ];
        yield 'enum fragment union referenced' => [
            '3.1.0',
            ['Probe' => $probe(['stoat' => $ref('Crimson')]), 'Crimson' => $crimson],
            ['{"stoat":6}' => true, '{"stoat":null}' => true, '{"stoat":-15}' => false, '{"stoat":"6"}' => false],
            // README.support-matrix: a numeric string for an integer `enum` builds the backed enum.
            ['symfony' => ['{"stoat":"6"}' => null], 'laravel-data' => ['{"stoat":"6"}' => null]],
        ];
        // Its canonical spelling, inline: yii3 held it as `?int` and its lenient raw `Integer` rule took
        // `"6"`, the enum then checked on the cast value — now the raw value is checked against the list.
        yield 'enum fragment union, the type-list spelling inline' => [
            '3.1.0',
            ['Probe' => $probe(['stoat' => ['type' => ['integer', 'null'], 'enum' => [6, 9, 0, null]]])],
            ['{"stoat":6}' => true, '{"stoat":null}' => true, '{"stoat":-15}' => false, '{"stoat":"6"}' => false],
        ];
        yield 'enum fragment union as list items' => [
            '3.1.0',
            ['Probe' => $probe(['stoat' => ['type' => 'array', 'items' => $ref('Crimson')]]), 'Crimson' => $crimson],
            ['{"stoat":[0]}' => true, '{"stoat":[6,null]}' => true, '{"stoat":[-15]}' => false, '{"stoat":[{}]}' => false],
        ];
        yield 'enum fragment union in a map of lists' => [
            '3.1.0',
            [
                'Probe' => $probe(['stoat' => ['type' => 'object', 'additionalProperties' => ['type' => 'array', 'items' => $ref('Crimson')]]]),
                'Crimson' => $crimson,
            ],
            ['{"stoat":{"ka":[0]}}' => true, '{"stoat":{"ka":[6,null]}}' => true, '{"stoat":{"ka":[-15]}}' => false],
        ];
        yield 'reference with multipleOf wrapped, or null' => [
            '3.1.0',
            ['Probe' => $probe(['yak' => ['oneOf' => [['allOf' => [[...$ref('Mauve'), 'multipleOf' => 2]]], ['type' => 'null']]]]), 'Mauve' => $mauve],
            ['{"yak":4}' => true, '{"yak":-14}' => true, '{"yak":null}' => true, '{"yak":3}' => false, '{"yak":{"zz":1}}' => false],
        ];
        yield 'reference with enum wrapped, or null' => [
            '3.1.0',
            ['Probe' => $probe(['yak' => ['oneOf' => [['allOf' => [[...$ref('Mauve'), 'enum' => [4]]]], ['type' => 'null']]]]), 'Mauve' => $mauve],
            ['{"yak":4}' => true, '{"yak":null}' => true, '{"yak":5}' => false, '{"yak":"4"}' => false],
            $numericString('{"yak":"4"}'),
        ];
        yield 'reference with multipleOf wrapped, or string' => [
            '3.1.0',
            ['Probe' => $probe(['yak' => ['anyOf' => [['allOf' => [[...$ref('Mauve'), 'multipleOf' => 2]]], ['type' => 'string']]]]), 'Mauve' => $mauve],
            ['{"yak":4}' => true, '{"yak":"s"}' => true, '{"yak":3}' => false, '{"yak":true}' => false],
        ];
        yield 'reference with multipleOf wrapped alone' => [
            '3.1.0',
            ['Probe' => $probe(['yak' => ['allOf' => [[...$ref('Mauve'), 'multipleOf' => 2]]]]), 'Mauve' => $mauve],
            ['{"yak":4}' => true, '{"yak":3}' => false, '{"yak":"4"}' => false],
            $numericString('{"yak":"4"}'),
        ];
        yield 'reference with multipleOf wrapped, 3.0 nullable' => [
            '3.0.3',
            ['Probe' => $probe(['yak' => ['allOf' => [[...$ref('Mauve'), 'multipleOf' => 2]], 'nullable' => true]]), 'Mauve' => $mauve],
            ['{"yak":4}' => true, '{"yak":null}' => true, '{"yak":3}' => false],
        ];
        yield 'reference with multipleOf wrapped as map values' => [
            '3.1.0',
            ['Probe' => $probe(['yak' => ['type' => 'object', 'additionalProperties' => ['allOf' => [[...$ref('Mauve'), 'multipleOf' => 2]]]]]), 'Mauve' => $mauve],
            ['{"yak":{"k":4}}' => true, '{"yak":{"k":3}}' => false, '{"yak":{"k":{}}}' => false],
        ];
        yield 'bare reference with multipleOf' => [
            '3.1.0',
            ['Probe' => $probe(['yak' => [...$ref('Mauve'), 'multipleOf' => 2]]), 'Mauve' => $mauve],
            ['{"yak":4}' => true, '{"yak":3}' => false, '{"yak":"4"}' => false],
            $numericString('{"yak":"4"}'),
        ];
        yield 'date beside a one-member allOf string component' => [
            '3.0.3',
            ['Probe' => $probe(['panda' => ['allOf' => [['format' => 'date'], $ref('Ambera')]]]), 'Ambera' => ['allOf' => [['type' => 'string']]]],
            ['{"panda":"2026-02-03"}' => true, '{"panda":"nope"}' => false, '{"panda":5}' => false],
        ];
        yield 'date beside a string component' => [
            '3.0.3',
            ['Probe' => $probe(['panda' => ['allOf' => [['format' => 'date'], $ref('Ambera')]]]), 'Ambera' => ['type' => 'string']],
            ['{"panda":"2026-02-03"}' => true, '{"panda":"nope"}' => false, '{"panda":5}' => false],
        ];
        $nonnull = ['type' => 'object', 'properties' => ['wombat' => ['type' => 'string']], 'additionalProperties' => false];
        yield '3.0 nullable allOf-wrapped list items' => [
            '3.0.3',
            ['Probe' => $probe(['newt' => ['type' => 'array', 'items' => ['allOf' => [$ref('Nonnull')], 'nullable' => true]]]), 'Nonnull' => $nonnull],
            ['{"newt":[{"wombat":"x"},null]}' => true, '{"newt":[{"wombat":1}]}' => false],
        ];
        yield 'allOf-wrapped list items' => [
            '3.0.3',
            ['Probe' => $probe(['newt' => ['type' => 'array', 'items' => ['allOf' => [$ref('Nonnull')]]]]), 'Nonnull' => $nonnull],
            ['{"newt":[{"wombat":"x"}]}' => true, '{"newt":[{"wombat":1}]}' => false],
        ];
    }

    /**
     * The typed shapes behind `testAScalarAllOfFoldsWhereverItSits()`: a date beside a component that is a
     * one-member `allOf` of a string is the date its plain spelling is, and 3.0 nullable list items
     * wrapped in an `allOf` are their class or null.
     */
    public function testAScalarAllOfFoldKeepsItsPhpType(): void
    {
        $ref = static fn(string $name): array => ['$ref' => '#/components/schemas/' . $name];
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => [
                'Probe' => ['type' => 'object', 'properties' => [
                    'panda' => ['allOf' => [['format' => 'date'], $ref('Ambera')]],
                    'newt' => ['type' => 'array', 'items' => ['allOf' => [$ref('Nonnull')], 'nullable' => true]],
                ]],
                'Ambera' => ['allOf' => [['type' => 'string']]],
                'Nonnull' => ['type' => 'object', 'properties' => ['wombat' => ['type' => 'string']]],
            ]],
        ];
        foreach ([GenerationMode::Runtime, GenerationMode::Symfony, GenerationMode::Yii3] as $mode) {
            $fqcn = $this->generate($spec, $this->namespaceFor($mode, 'scalar allOf fold php type'), $mode->value);
            $panda = (new ReflectionProperty($fqcn, 'panda'))->getType();
            $this->assertStringStartsWith(prefix: 'DateTimeImmutable', string: ltrim((string)$panda, '?'), message: $mode->value);
        }
        $request = Request::create(
            uri: '/',
            method: 'POST',
            server: ['CONTENT_TYPE' => 'application/json'],
            content: '{"newt":[{"wombat":"x"},null]}',
        );
        $dto = (new DtoDeserializer())->deserialize(
            request: $request,
            dtoClass: $this->generate($spec, $this->namespaceFor(GenerationMode::Runtime, 'scalar allOf fold php type'), 'runtime'),
        );
        $newt = (new ReflectionProperty($dto, 'newt'))->getValue($dto);
        $this->assertIsArray($newt);
        $this->assertInstanceOf(expected: substr($dto::class, 0, -strlen('Probe')) . 'Nonnull', actual: $newt[0]);
        $this->assertNull($newt[1]);
    }

    /**
     * An `allOf` naming an ENUM component of another document — `[{type: string}, {$ref:
     * other.json#/…/Amber}]` — is that enum, as its local spelling is. Taken as a parent class, the
     * property's class extended the final enum and PHP refused to load it.
     *
     * @param array<string, mixed> $kind
     */
    #[DataProvider('externalEnumInAllOfCases')]
    public function testAnExternalEnumInAnAllOfIsTheEnum(array $kind): void
    {
        $this->siblingDocuments = ['other.json' => [
            'openapi' => '3.1.0',
            'info' => ['title' => 'O', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => ['Amber' => ['type' => 'string', 'enum' => ['circle', 'square']]]],
        ]];
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => ['Probe' => ['type' => 'object', 'properties' => ['kind' => $kind]]]],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'external enum in allOf ' . md5((string)json_encode($kind)),
                payloads: ['{"kind":"circle"}' => true, '{"kind":"square"}' => true, '{"kind":"tri"}' => false, '{"kind":5}' => false],
            ),
        );
    }

    /**
     * @return iterable<string, array{array<string, mixed>}>
     */
    public static function externalEnumInAllOfCases(): iterable
    {
        $amber = ['$ref' => 'other.json#/components/schemas/Amber'];

        yield 'type beside the reference' => [['allOf' => [['type' => 'string'], $amber]]];
        yield 'minLength beside the reference' => [['allOf' => [$amber, ['minLength' => 1]]]];
        yield 'the reference alone' => [['allOf' => [$amber]]];
    }

    /**
     * An enum component of ANOTHER document as a map value or a list item — `additionalProperties:
     * {$ref: other.json#/…/Crimson}` — keeps its members, as the local spelling does. Only local
     * pointers were read for the members, so yii3 accepted `{"ka": 5}` and `{"ka": null}` where the
     * enum is `[-6]`.
     *
     * @param array<string, mixed> $ocelot
     * @param array<string, bool> $payloads
     */
    #[DataProvider('externalEnumAsContainerValueCases')]
    public function testAnExternalEnumAsAMapValueOrListItemIsChecked(array $ocelot, array $payloads): void
    {
        $crimson = ['Crimson' => ['type' => 'integer', 'enum' => [-6]]];
        $external = str_contains((string)json_encode($ocelot), 'other.json');
        if ($external) {
            $this->siblingDocuments = ['other.json' => [
                'openapi' => '3.0.3',
                'info' => ['title' => 'O', 'version' => '1.0.0'],
                'paths' => [],
                'components' => ['schemas' => $crimson],
            ]];
        }
        $spec = [
            'openapi' => '3.0.3',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => ['Probe' => ['type' => 'object', 'properties' => ['ocelot' => $ocelot]]] + ($external ? [] : $crimson)],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'external enum container value ' . md5((string)json_encode($ocelot)),
                payloads: $payloads,
            ),
        );
    }

    /**
     * Every container twice: the reference into another document under test, and the local one that
     * already worked.
     *
     * @return iterable<string, array{array<string, mixed>, array<string, bool>}>
     */
    public static function externalEnumAsContainerValueCases(): iterable
    {
        $map = ['{"ocelot":{"ka":-6}}' => true, '{"ocelot":{"ka":5}}' => false, '{"ocelot":{"ka":null}}' => false];
        $list = ['{"ocelot":[-6]}' => true, '{"ocelot":[5]}' => false, '{"ocelot":[null]}' => false];
        foreach (['other document' => 'other.json#/components/schemas/Crimson', 'local' => '#/components/schemas/Crimson'] as $where => $ref) {
            yield 'map value / ' . $where => [['type' => 'object', 'additionalProperties' => ['$ref' => $ref]], $map];
            yield 'list item / ' . $where => [['type' => 'array', 'items' => ['$ref' => $ref]], $list];
        }
    }

    /**
     * `{$ref: other.json#/…/Fox, properties: {egret: …}}` — a reference into ANOTHER document with keys
     * beside it — is both the class and the keys, as the local spelling is. Only a local pointer was
     * merged into the `allOf`, so symfony and yii3 typed the bare `Fox` and accepted an `egret` item
     * outside its enum.
     *
     * @param array<string, mixed> $marten
     */
    #[DataProvider('externalReferenceWithSiblingsCases')]
    public function testAnExternalReferenceKeepsTheKeysBesideIt(array $marten): void
    {
        $fox = ['Fox' => ['type' => 'object', 'properties' => ['tail' => ['type' => 'string']], 'required' => ['tail']]];
        $external = str_contains((string)json_encode($marten), 'other.json');
        if ($external) {
            $this->siblingDocuments = ['other.json' => [
                'openapi' => '3.1.0',
                'info' => ['title' => 'O', 'version' => '1.0.0'],
                'paths' => [],
                'components' => ['schemas' => $fox],
            ]];
        }
        $spec = [
            'openapi' => '3.1.0',
            'info' => ['title' => 'T', 'version' => '1.0.0'],
            'paths' => [],
            'components' => ['schemas' => ['Probe' => ['type' => 'object', 'properties' => ['marten' => $marten]]] + ($external ? [] : $fox)],
        ];

        $this->assertSame(
            expected: [],
            actual: $this->payloadTableMisses(
                spec: $spec,
                key: 'external reference with siblings ' . md5((string)json_encode($marten)),
                payloads: [
                    '{"marten":{"egret":["violet"],"tail":"x"}}' => true,
                    '{"marten":{"egret":[2.5],"tail":"x"}}' => false,
                    '{"marten":{"egret":["violet"]}}' => false,
                ],
            ),
        );
